// Safe safeLocalStorage wrapper to prevent SecurityErrors under file:// protocol on iOS WKWebView
const safeLocalStorage = (function() {
    const memoryStore = {};
    let hasLocalStorage = false;
    try {
        hasLocalStorage = typeof window !== 'undefined' && 'localStorage' in window && window.localStorage !== null;
    } catch (e) {
        hasLocalStorage = false;
    }
    return {
        getItem(key) {
            try {
                return hasLocalStorage ? window.localStorage.getItem(key) : memoryStore[key] || null;
            } catch (e) {
                return memoryStore[key] || null;
            }
        },
        setItem(key, value) {
            try {
                if (hasLocalStorage) {
                    window.localStorage.setItem(key, value);
                } else {
                    memoryStore[key] = String(value);
                }
            } catch (e) {
                memoryStore[key] = String(value);
            }
        },
        removeItem(key) {
            try {
                if (hasLocalStorage) {
                    window.localStorage.removeItem(key);
                } else {
                    delete memoryStore[key];
                }
            } catch (e) {
                delete memoryStore[key];
            }
        },
        clear() {
            try {
                if (hasLocalStorage) {
                    window.localStorage.clear();
                } else {
                    for (const key in memoryStore) {
                        delete memoryStore[key];
                    }
                }
            } catch (e) {
                for (const key in memoryStore) {
                    delete memoryStore[key];
                }
            }
        }
    };
})();

