// LocalStorage Synchronization
function saveState() {
    if (state && state.conversations) {
        state.conversations.forEach(conv => {
            conv.messages.forEach(msg => {
                if (!msg.timestamp) {
                    msg.timestamp = Date.now();
                }
            });
        });
    }

    // Safety fallback: if adminAuthenticated is true but no login event took place, reset it
    if (state && state.adminAuthenticated && !safeSessionStorage.getItem('admin_login_verified')) {
        state.adminAuthenticated = false;
    }

    try {
        const serialized = JSON.stringify(state);
        safeLocalStorage.setItem('barterland_state', serialized);
        
        // Compute checksum of the serialized string using sampling for large strings to make it extremely fast
        let hash = 0;
        const len = serialized.length;
        hash = (hash << 5) - hash + len;
        hash |= 0;
        
        const step = len > 10000 ? Math.ceil(len / 500) : 1;
        for (let i = 0; i < len; i += step) {
            hash = (hash << 5) - hash + serialized.charCodeAt(i);
            hash |= 0;
        }
        safeLocalStorage.setItem('barterland_state_sig', hash.toString());
    } catch (e) {
        console.error("State save failed:", e.message || e);
        if (e.name === 'QuotaExceededError' || e.code === 22) {
            alert("Storage limit exceeded. This image might be too large! Try uploading a smaller image.");
        }
    }
    if (typeof updateChatNotificationBadge === 'function') {
        updateChatNotificationBadge();
    }
}

