function renderHomeDashboard() {
    const user = state.currentUser || { firstName: 'Lily', lastName: 'Kaufmann', displayName: 'Lily Kaufmann', location: 'Mount Pleasant', avatar: DEFAULT_AVATAR };
    
    // Update user info
    const welcomeEl = document.getElementById('home-welcome-name');
    if (welcomeEl) welcomeEl.innerText = (user.displayName || `${user.firstName} ${user.lastName}`).toUpperCase();
    
    const avatarEl = document.getElementById('home-user-avatar');
    if (avatarEl) avatarEl.src = user.avatar || DEFAULT_AVATAR;
    
    // Calculate completed swaps count
    const completedSwapsCount = (state.conversations ? state.conversations.filter(c => c.negotiation && c.negotiation.status === 'completed').length : 0);
    const totalKarma = ((state.level || 1) - 1) * 100 + (state.xp || 50);
    
    const vouchesEl = document.getElementById('user-vouches-count');
    const vouchesCount = state.userVouches !== undefined ? state.userVouches : 75;
    if (vouchesEl) vouchesEl.innerText = vouchesCount;

    const karmaScoreEl = document.getElementById('user-karma-score');
    if (karmaScoreEl) karmaScoreEl.innerText = totalKarma;
    
    const tradesMadeEl = document.getElementById('user-trades-made');
    if (tradesMadeEl) tradesMadeEl.innerText = completedSwapsCount;

    // Update circular progress tracks (circumference = 289)
    const vouchCircle = document.getElementById('vouch-progress-circle');
    const vouchText = document.getElementById('vouch-progress-text');
    if (vouchCircle && vouchText) {
        const targetVouches = 100; // standard milestone for reliability tokens
        const pct = Math.min((vouchesCount / targetVouches) * 100, 100);
        vouchCircle.style.strokeDashoffset = 289 - (pct / 100) * 289;
        vouchText.innerText = `${vouchesCount}/${targetVouches}`;
    }

    // Update the combined card progress bar and text inside widget-badges-section
    const vouchBarCard = document.getElementById('vouch-progress-bar-card');
    const vouchTextCard = document.getElementById('vouch-level-text-card');
    if (vouchBarCard && vouchTextCard) {
        const pct = Math.min((vouchesCount / 100) * 100, 100);
        vouchBarCard.style.width = `${pct}%`;
        vouchTextCard.innerText = `${vouchesCount}/100 Karma`;
    }

    const karmaCircle = document.getElementById('karma-progress-circle');
    const karmaText = document.getElementById('karma-progress-text');
    const karmaLevelText = document.getElementById('karma-level-text');
    if (karmaCircle && karmaText) {
        const lvl = state.level || 1;
        const xp = state.xp || 50;
        karmaCircle.style.strokeDashoffset = 289 - (xp / 100) * 289;
        karmaText.innerText = `${xp}/100 XP`;
        if (karmaLevelText) karmaLevelText.innerText = `Level ${lvl}`;
    }

    const karmaBarCard = document.getElementById('karma-progress-bar-card');
    const karmaTextCard = document.getElementById('karma-level-text-card');
    if (karmaBarCard && karmaTextCard) {
        const lvl = state.level || 1;
        const xp = state.xp || 50;
        karmaBarCard.style.width = `${xp}%`;
        karmaTextCard.innerText = `Lvl ${lvl} (${xp}/100)`;
    }

    const tradesCircle = document.getElementById('trades-progress-circle');
    const tradesText = document.getElementById('trades-progress-text');
    if (tradesCircle && tradesText) {
        const targetTrades = 20; // standard milestone
        const pct = Math.min((completedSwapsCount / targetTrades) * 100, 100);
        tradesCircle.style.strokeDashoffset = 289 - (pct / 100) * 289;
        tradesText.innerText = `${completedSwapsCount}/${targetTrades}`;
    }

    const tradesBarCard = document.getElementById('trades-progress-bar-card');
    const tradesTextCard = document.getElementById('trades-level-text-card');
    if (tradesBarCard && tradesTextCard) {
        const targetTrades = 20;
        const pct = Math.min((completedSwapsCount / targetTrades) * 100, 100);
        tradesBarCard.style.width = `${pct}%`;
        tradesTextCard.innerText = `${completedSwapsCount} Swap${completedSwapsCount !== 1 ? 's' : ''}`;
    }

    const responseCircle = document.getElementById('response-progress-circle');
    if (responseCircle) {
        responseCircle.style.strokeDashoffset = 289 - (98 / 100) * 289;
    }

    const impactCircle = document.getElementById('impact-progress-circle');
    if (impactCircle) {
        impactCircle.style.strokeDashoffset = 289 - (15 / 20) * 289;
    }
    
    // Daily Community Quote
    const now = new Date();
    const start = new Date(now.getFullYear(), 0, 0);
    const diff = now - start;
    const oneDay = 1000 * 60 * 60 * 24;
    const dayOfYear = Math.floor(diff / oneDay);
    const quoteIndex = dayOfYear % COMMUNITY_QUOTES.length;
    const quote = COMMUNITY_QUOTES[quoteIndex];
    
    const quoteTextEl = document.getElementById('home-quote-text');
    const quoteAuthorEl = document.getElementById('home-quote-author');
    if (quoteTextEl) quoteTextEl.innerText = `"${quote.text}"`;
    if (quoteAuthorEl) quoteAuthorEl.innerText = `— ${quote.author}`;
    
    // Render 2 trending offerings
    const featuredContainer = document.getElementById('home-trending-offerings-container');
    if (featuredContainer) {
        featuredContainer.innerHTML = "";
        
        // Take first 2 neighbors (filtering blocked/suspended)
        const allowedNames = Object.keys(state.neighbors).filter(name => {
            if (state.blockedUsers && state.blockedUsers.includes(name)) return false;
            if (state.suspendedUsers && state.suspendedUsers.includes(name)) return false;
            if (state.neighbors[name] && state.neighbors[name].suspended) return false;
            if (state.neighbors[name] && state.neighbors[name].shadowBanned) return false;
            return true;
        });
        const neighborNames = allowedNames.slice(0, 2);
        neighborNames.forEach(name => {
            const neighbor = state.neighbors[name];
            if (!neighbor) return;
            const card = document.createElement('div');
            card.className = "bg-white p-4 rounded-xl border border-outline-variant/30 shadow-sm flex items-start gap-3 cursor-pointer active:scale-98 transition-transform";
            card.onclick = () => {
                showView('village');
                switchVillageSegment('map');
                openMapItemDetail(neighbor.name);
            };
            card.innerHTML = `
                <img src="${neighbor.offerImg || PLACEHOLDER_IMAGE}" class="w-12 h-12 rounded-xl object-cover border border-outline-variant/20 flex-shrink-0">
                <div class="flex-grow min-w-0">
                    <div class="flex justify-between items-start">
                        <h4 class="font-bold text-black dark:text-white text-xs truncate">${neighbor.offerTitle}</h4>
                        <span class="text-[9px] text-on-surface-variant font-medium ml-2">${neighbor.location}</span>
                    </div>
                    <p class="text-[10px] text-on-surface-variant line-clamp-2 mt-0.5">${neighbor.offerDesc}</p>
                    <div class="flex items-center gap-1.5 mt-2 text-[9px] text-black/60 dark:text-white/60 font-bold uppercase tracking-wider">
                        <span class="material-symbols-outlined text-[10px]">person</span>
                        <span>${neighbor.name} · ${neighbor.vouches} ❤️</span>
                    </div>
                </div>
            `;
            featuredContainer.appendChild(card);
        });
    }
}

window.showVouchesDetails = function() {
    triggerBadgeUnlockModal('Reliability', 'Reliability represents your trustworthiness score based on thumbs up and down after completed swaps. It goes from 1 to 100.', 'gpp_maybe', 'gold');
};

window.triggerBadgeUnlockModal = function(title, desc, iconName, themeColor, isUnlocked = true, badgeObj = null) {
    if (typeof playSound === 'function') playSound('success');
    
    const modal = document.getElementById('achievement-detail-modal');
    if (!modal) return;

    const card = document.getElementById('achievement-modal-card');
    const modalIconBox = document.getElementById('achievement-modal-icon-box');
    const modalIcon = document.getElementById('achievement-modal-icon');
    const modalTitle = document.getElementById('achievement-modal-title');
    const modalBadge = document.getElementById('achievement-modal-badge');
    const modalDesc = document.getElementById('achievement-modal-desc');
    const modalProgressHeader = document.getElementById('achievement-modal-progress-header');
    const modalProgressTrack = document.getElementById('achievement-modal-progress-track');
    const modalReward = document.getElementById('achievement-modal-reward');

    if (modalTitle) {
        modalTitle.innerText = title;
        modalTitle.className = "font-headline text-lg font-bold text-forest-green dark:text-[#308A5E] mb-2 leading-tight";
    }
    if (modalDesc) {
        modalDesc.innerText = desc;
        modalDesc.className = "text-[13.5px] text-black dark:text-warm-cream/90 mb-6 leading-relaxed";
    }
    if (modalIcon) {
        modalIcon.innerText = iconName;
    }

    // Hide progress and levels since badges do not have levels
    if (modalProgressHeader) modalProgressHeader.style.display = 'none';
    if (modalProgressTrack) modalProgressTrack.style.display = 'none';
    if (modalReward) modalReward.style.display = 'none';

    if (modalBadge) {
        modalBadge.classList.add('hidden');
    }

    if (card) {
        card.className = "relative bg-white dark:bg-[#18201a] border border-outline-variant/30 w-full max-w-xs p-6 rounded-3xl shadow-2xl text-center flex flex-col items-center animate-slide-up";
    }

    if (modalIconBox) {
        let colorClass = "bg-forest-green/10 text-forest-green";
        if (themeColor === 'gold' || themeColor === 'amber') {
            colorClass = "bg-amber-500/10 text-[#f59e0b]";
        } else if (themeColor === 'green' || themeColor === 'emerald') {
            colorClass = "bg-emerald-500/10 text-[#22c55e]";
        } else if (themeColor === 'blue') {
            colorClass = "bg-blue-500/10 text-[#3b82f6]";
        } else if (themeColor === 'red' || themeColor === 'rose') {
            colorClass = "bg-red-500/10 text-[#ef4444]";
        }
        modalIconBox.className = `w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4 ${colorClass}`;
        if (modalIcon) {
            modalIcon.style.color = '';
        }
    }

    const actionContainer = document.getElementById('achievement-modal-action-container');
    const actionBtn = document.getElementById('achievement-modal-action-btn');
    const actionText = document.getElementById('achievement-modal-action-text');

    if (actionContainer) {
        if (badgeObj && badgeObj.linkUrl) {
            actionContainer.classList.remove('hidden');
            if (actionText) {
                if (isUnlocked) {
                    actionText.innerText = "Visit GoFundMe Page";
                } else {
                    actionText.innerText = "Support GoFundMe Campaign";
                }
            }
            if (actionBtn) {
                actionBtn.onclick = (e) => {
                    if (e) e.stopPropagation();
                    window.open(badgeObj.linkUrl, '_blank');
                    
                    if (!isUnlocked && badgeObj.id === 'gofundme_supporter') {
                        state.gofundmeSupporter = true;
                        saveState();
                        alert("Thank you for your support! You have unlocked the GoFundMe Backer badge!");
                        closeAchievementModal();
                        if (window.renderProfileSettings) window.renderProfileSettings();
                        if (window.renderBadgesList) {
                            const name = state.currentUser ? state.currentUser.displayName : 'Lily Kaufmann';
                            window.renderBadgesList(name);
                        }
                    }
                };
            }
        } else {
            actionContainer.classList.add('hidden');
        }
    }

    const closeContainer = document.getElementById('achievement-modal-close-container');
    if (closeContainer) {
        if (badgeObj && badgeObj.id === 'gofundme_supporter') {
            closeContainer.classList.add('hidden');
        } else {
            closeContainer.classList.remove('hidden');
        }
    }

    modal.classList.remove('hidden');
};

window.handleHomeFeedbackSubmit = function(event) {
    if (event) event.preventDefault();
    const input = document.getElementById('home-suggestion-input');
    if (!input) return;
    const val = input.value.trim();
    if (!val) return;
    
    if (!state.suggestions) state.suggestions = [];
    state.suggestions.push({
        id: 'suggest-' + Date.now(),
        text: val,
        time: new Date().toLocaleString()
    });
    saveState();
    
    input.value = "";
    openProfileStatExplanation('feedback-submitted');
    if (typeof playSound === 'function') playSound('success');
    
    renderAdminPanel();
};

