function handleOfferPhotoSlotUpload(input, index) {
    if (input.files && input.files[0]) {
        playSound('success');
        compressImage(input.files[0], 800, 800, function(dataUrl) {
            if (!state.selectedOfferPhotos) {
                state.selectedOfferPhotos = ["", "", ""];
            }
            state.selectedOfferPhotos[index] = dataUrl;
            state.selectedOfferHeroImage = state.selectedOfferPhotos.filter(Boolean).join('|||');
            saveState();
            renderOfferPhotosList();
            input.value = "";
        });
    }
}
