function updateOfferPhotoCounter() {
    const counterText = document.getElementById('offer-photo-counter-text');
    if (counterText) {
        const count = state.selectedOfferPhotos ? state.selectedOfferPhotos.filter(Boolean).length : 0;
        counterText.innerText = `${count} of 3 photos added`;
    }
}

function renderOfferPhotosList() {
    if (!state.selectedOfferPhotos) {
        state.selectedOfferPhotos = ["", "", ""];
    }
    while (state.selectedOfferPhotos.length < 3) {
        state.selectedOfferPhotos.push("");
    }
    for (let i = 0; i < 3; i++) {
        const preview = document.getElementById(`offer-photo-preview-${i}`);
        const placeholder = document.getElementById(`offer-photo-placeholder-${i}`);
        const removeBtn = document.getElementById(`offer-photo-remove-${i}`);
        const input = document.getElementById(`offer-photo-input-${i}`);
        const dataUrl = state.selectedOfferPhotos[i];
        
        if (preview && placeholder && removeBtn) {
            if (dataUrl) {
                preview.src = dataUrl;
                preview.classList.remove('hidden');
                placeholder.classList.add('hidden');
                removeBtn.classList.remove('hidden');
            } else {
                preview.src = "";
                preview.classList.add('hidden');
                placeholder.classList.remove('hidden');
                removeBtn.classList.add('hidden');
            }
        }
        if (input) {
            input.value = "";
        }
    }
    updateOfferPhotoCounter();
    updateEventPhotoPlaceholder();
}
window.renderOfferPhotosList = renderOfferPhotosList;

