function getEventIconDetails(type) {
    const t = (type || '').toLowerCase();
    if (t.includes('workshop')) {
        return { icon: 'school', color: '#3b82f6', bgColor: '#eff6ff', darkColor: '#60a5fa', darkBgColor: '#172554' };
    }
    if (t.includes('meetup')) {
        return { icon: 'groups', color: '#f97316', bgColor: '#fff7ed', darkColor: '#fb923c', darkBgColor: '#7c2d12' };
    }
    if (t.includes('clean')) {
        return { icon: 'cleaning_services', color: '#10b981', bgColor: '#ecfdf5', darkColor: '#34d399', darkBgColor: '#064e3b' };
    }
    if (t.includes('swap') || t.includes('book')) {
        return { icon: 'menu_book', color: '#f59e0b', bgColor: '#fffbeb', darkColor: '#fbbf24', darkBgColor: '#78350f' };
    }
    if (t.includes('playdate')) {
        return { icon: 'child_care', color: '#ec4899', bgColor: '#fdf2f8', darkColor: '#f472b6', darkBgColor: '#831843' };
    }
    if (t.includes('garden')) {
        return { icon: 'yard', color: '#84cc16', bgColor: '#f7fee7', darkColor: '#a3e635', darkBgColor: '#365314' };
    }
    if (t.includes('repair') || t.includes('tool')) {
        return { icon: 'handyman', color: '#6366f1', bgColor: '#eef2ff', darkColor: '#818cf8', darkBgColor: '#1e1b4b' };
    }
    if (t.includes('clothing') || t.includes('apparel')) {
        return { icon: 'checkroom', color: '#a855f7', bgColor: '#faf5ff', darkColor: '#c084fc', darkBgColor: '#581c87' };
    }
    return { icon: 'campaign', color: '#3b82f6', bgColor: '#eff6ff', darkColor: '#60a5fa', darkBgColor: '#172554' };
}
window.getEventIconDetails = getEventIconDetails;

function getEventIconClasses(type) {
    const t = (type || '').toLowerCase();
    if (t.includes('workshop')) {
        return 'bg-blue-50 text-blue-600 dark:bg-blue-950/40 dark:text-blue-400';
    }
    if (t.includes('meetup')) {
        return 'bg-orange-50 text-orange-600 dark:bg-orange-950/40 dark:text-orange-400';
    }
    if (t.includes('clean')) {
        return 'bg-emerald-50 text-emerald-600 dark:bg-emerald-950/40 dark:text-emerald-400';
    }
    if (t.includes('swap') || t.includes('book')) {
        return 'bg-amber-50 text-amber-600 dark:bg-amber-950/40 dark:text-amber-400';
    }
    if (t.includes('playdate')) {
        return 'bg-pink-50 text-pink-600 dark:bg-pink-950/40 dark:text-pink-400';
    }
    if (t.includes('garden')) {
        return 'bg-lime-50 text-lime-600 dark:bg-lime-950/40 dark:text-lime-400';
    }
    if (t.includes('repair') || t.includes('tool')) {
        return 'bg-indigo-50 text-indigo-600 dark:bg-indigo-950/40 dark:text-indigo-400';
    }
    if (t.includes('clothing') || t.includes('apparel')) {
        return 'bg-purple-50 text-purple-600 dark:bg-purple-950/40 dark:text-purple-400';
    }
    return 'bg-blue-50 text-blue-600 dark:bg-blue-950/40 dark:text-blue-400';
}
window.getEventIconClasses = getEventIconClasses;

function getEventCardThumbnailHTML(evt, extraClasses = "") {
    const firstImg = evt.image ? evt.image.split('|||').filter(Boolean)[0] : null;
    const imgUrl = firstImg || getEventPresetImage(evt.type);
    return `<img src="${imgUrl}" class="absolute inset-0 w-full h-full object-cover ${extraClasses}">`;
}
window.getEventCardThumbnailHTML = getEventCardThumbnailHTML;

function getEventThumbnailHTML(type, additionalClasses = '', iconSize = 'text-[48px]') {
    const details = getEventIconDetails(type);
    return `
        <div class="w-full h-full flex items-center justify-center event-stock-thumbnail ${additionalClasses}" style="--bg-light: ${details.bgColor}; --bg-dark: ${details.darkBgColor}; --color-light: ${details.color}; --color-dark: ${details.darkColor}; background-color: var(--bg-light); color: var(--color-light);">
            <span class="material-symbols-outlined ${iconSize}" style="font-variation-settings: 'FILL' 1;">${details.icon}</span>
        </div>
    `;
}
window.getEventThumbnailHTML = getEventThumbnailHTML;

function updateEventPhotoPlaceholder() {
    const preview = document.getElementById('offer-photo-preview-0');
    const placeholder = document.getElementById('offer-photo-placeholder-0');
    if (!placeholder) return;
    
    const parent = placeholder.parentElement;
    if (!parent) return;

    const dataUrl = state.selectedOfferPhotos ? state.selectedOfferPhotos[0] : "";
    const eventTypeSelect = document.getElementById('offer-event-type-select');
    const eventType = eventTypeSelect ? eventTypeSelect.value : "";

    if (state.currentOfferMode === 'event' && eventType && !dataUrl) {
        const details = getEventIconDetails(eventType);
        
        parent.className = "relative w-[84px] h-[84px] rounded-xl flex flex-col items-center justify-center cursor-pointer select-none overflow-hidden hover:opacity-90 active:scale-95 transition-all shadow-sm group event-stock-thumbnail";
        parent.style.setProperty('--bg-light', details.bgColor);
        parent.style.setProperty('--bg-dark', details.darkBgColor);
        parent.style.setProperty('--color-light', details.color);
        parent.style.setProperty('--color-dark', details.darkColor);
        parent.style.borderColor = 'transparent';
        
        placeholder.innerHTML = `<span class="material-symbols-outlined text-2xl" style="font-variation-settings: 'FILL' 1;">${details.icon}</span>`;
        if (preview) preview.classList.add('hidden');
    } else {
        parent.className = "relative w-[84px] h-[84px] rounded-xl bg-white dark:bg-[#18201a] border border-outline-variant/40 flex flex-col items-center justify-center cursor-pointer select-none overflow-hidden hover:bg-forest-green/5 active:scale-95 transition-all shadow-sm group";
        parent.style.removeProperty('--bg-light');
        parent.style.removeProperty('--bg-dark');
        parent.style.removeProperty('--color-light');
        parent.style.removeProperty('--color-dark');
        parent.style.borderColor = '';
        parent.style.backgroundColor = '';
        
        placeholder.innerHTML = `<span class="material-symbols-outlined text-black dark:text-white text-2xl group-hover:scale-110 transition-transform">add_a_photo</span>`;
    }
}
window.updateEventPhotoPlaceholder = updateEventPhotoPlaceholder;

