let currentStockCategoryPhotos = [];

function showEventPhotoOptionsModal() {
    const modal = document.getElementById('event-photo-options-modal');
    if (modal) modal.classList.remove('hidden');
}
window.showEventPhotoOptionsModal = showEventPhotoOptionsModal;

function closeEventPhotoOptionsModal() {
    const modal = document.getElementById('event-photo-options-modal');
    if (modal) modal.classList.add('hidden');
}
window.closeEventPhotoOptionsModal = closeEventPhotoOptionsModal;

function handleEventPhotoOption(option) {
    closeEventPhotoOptionsModal();
    if (option === 'library' || option === 'camera') {
        const input = document.getElementById('offer-photo-input-0');
        if (input) input.click();
    } else if (option === 'stock') {
        showStockPhotoModal();
    }
}
window.handleEventPhotoOption = handleEventPhotoOption;

function showStockPhotoModal() {
    const modal = document.getElementById('stock-photo-modal');
    if (modal) {
        modal.classList.remove('hidden');
        showStockCategories();
    }
}
window.showStockPhotoModal = showStockPhotoModal;

function closeStockPhotoModal() {
    const modal = document.getElementById('stock-photo-modal');
    if (modal) modal.classList.add('hidden');
}
window.closeStockPhotoModal = closeStockPhotoModal;

function showStockCategories() {
    const categoriesView = document.getElementById('stock-categories-view');
    const photosView = document.getElementById('stock-photos-view');
    const backBtn = document.getElementById('stock-back-btn');
    const title = document.getElementById('stock-photo-modal-title');
    const spacer = document.getElementById('stock-title-spacer');

    if (categoriesView) categoriesView.classList.remove('hidden');
    if (photosView) photosView.classList.add('hidden');
    if (backBtn) backBtn.classList.add('hidden');
    if (spacer) spacer.classList.remove('hidden');
    if (title) title.innerText = "Select Stock Category";
}
window.showStockCategories = showStockCategories;

function selectStockCategory(category) {
    if (typeof playSound === 'function') playSound('click');
    const categoriesView = document.getElementById('stock-categories-view');
    const photosView = document.getElementById('stock-photos-view');
    const backBtn = document.getElementById('stock-back-btn');
    const title = document.getElementById('stock-photo-modal-title');
    const spacer = document.getElementById('stock-title-spacer');

    currentStockCategoryPhotos = EVENT_STOCK_PHOTOS[category] || [];

    // Load images into selectors
    for (let i = 0; i < 3; i++) {
        const img = document.getElementById(`stock-img-${i}`);
        if (img) {
            img.src = currentStockCategoryPhotos[i] || "";
        }
    }

    if (categoriesView) categoriesView.classList.add('hidden');
    if (photosView) photosView.classList.remove('hidden');
    if (backBtn) backBtn.classList.remove('hidden');
    if (spacer) spacer.classList.add('hidden');
    if (title) title.innerText = category;
}
window.selectStockCategory = selectStockCategory;

function chooseStockPhoto(index) {
    if (typeof playSound === 'function') playSound('success');
    const url = currentStockCategoryPhotos[index];
    if (url) {
        if (!state.selectedOfferPhotos) {
            state.selectedOfferPhotos = ["", "", ""];
        }
        state.selectedOfferPhotos[0] = url;
        state.selectedOfferHeroImage = state.selectedOfferPhotos.filter(Boolean).join('|||');
        saveState();
        renderOfferPhotosList();
        closeStockPhotoModal();
    }
}
window.chooseStockPhoto = chooseStockPhoto;
window.handleCustomAvatarUpload = handleCustomAvatarUpload;
window.handleWizardPhotoUpload = handleWizardPhotoUpload;

function handleSignUpStep1(e) {
    if (e) e.preventDefault();
    const firstName = document.getElementById('su-first-name').value.trim();
    const lastName = document.getElementById('su-last-name').value.trim();
    const displayName = document.getElementById('su-display-name').value.trim();

    if (!firstName || !lastName || !displayName) {
        alert("Please fill in all fields.");
        return;
    }

    playSound('click');
    showView('create_account_credentials');
}
window.handleSignUpStep1 = handleSignUpStep1;

function handleSignUpStep2(e) {
    if (e) e.preventDefault();
    const email = document.getElementById('su-email').value.trim();
    const password = document.getElementById('su-password').value.trim();

    if (!email || !password) {
        alert("Please fill in all fields.");
        return;
    }

    if (password.length < 8) {
        alert("Password must be at least 8 characters.");
        return;
    }

    playSound('click');
    showView('create_account_social');
}
window.handleSignUpStep2 = handleSignUpStep2;

function handleSignUpStep3(e) {
    if (e) e.preventDefault();
    const firstName = document.getElementById('su-first-name').value.trim();
    const lastName = document.getElementById('su-last-name').value.trim();
    const displayName = document.getElementById('su-display-name').value.trim();
    const email = document.getElementById('su-email').value.trim();
    const password = document.getElementById('su-password').value.trim();

    if (!firstName || !lastName || !displayName || !email || !password) {
        alert("Registration state is incomplete. Please restart registration.");
        showView('create_account');
        return;
    }

    if (state.suspendedUsers && (state.suspendedUsers.includes(displayName) || state.suspendedUsers.includes(email))) {
        alert("Your account has been suspended for repeated unreliability (5 no-show strikes). Please contact support.");
        return;
    }

    const instagram = document.getElementById('su-instagram') ? document.getElementById('su-instagram').value.trim() : "";
    const facebook = document.getElementById('su-facebook') ? document.getElementById('su-facebook').value.trim() : "";
    const tiktok = document.getElementById('su-tiktok') ? document.getElementById('su-tiktok').value.trim() : "";

    state.currentUser = {
        firstName,
        lastName,
        displayName,
        email,
        avatar: signupAvatarUrl || DEFAULT_AVATAR,
        location: '',
        skills: [],
        needs: [],
        instagram,
        facebook,
        tiktok
    };
    state.isGuest = false;
    state.loggedOut = false;
    saveState();
    playSound('click');
    showView('profile_consent');
}
window.handleSignUpStep3 = handleSignUpStep3;

function togglePasswordVisibility(inputId, buttonEl) {
    const input = document.getElementById(inputId);
    if (!input) return;
    const icon = buttonEl.querySelector('.material-symbols-outlined');
    if (input.type === 'password') {
        input.type = 'text';
        if (icon) icon.innerText = 'visibility_off';
    } else {
        input.type = 'password';
        if (icon) icon.innerText = 'visibility';
    }
}
window.togglePasswordVisibility = togglePasswordVisibility;

