function toggleTagSelection(el) {
    el.classList.toggle('selected');
    playSound('click');
    if (el.classList.contains('selected')) {
        el.classList.remove('bg-white', 'text-forest-green', 'border-outline-variant/30');
        el.classList.add('bg-forest-green', 'text-white', 'border-transparent');
    } else {
        el.classList.add('bg-white', 'text-forest-green', 'border-outline-variant/30');
        el.classList.remove('bg-forest-green', 'text-white', 'border-transparent');
    }
}

