// EXPRESS ONBOARDING HANDLERS (OPTION 2)
// ====================================================

window.tempExpressUser = null;
window.expressPostType = 'offering';

window.handleExpressNeighborhoodChange = function(value) {
    const customContainer = document.getElementById('express-custom-location-container');
    if (customContainer) {
        if (value === 'custom') {
            customContainer.classList.remove('hidden');
            const input = document.getElementById('express-custom-location');
            if (input) input.required = true;
        } else {
            customContainer.classList.add('hidden');
            const input = document.getElementById('express-custom-location');
            if (input) input.required = false;
        }
    }
};

window.toggleExpressSubmitButton = function() {
    const consentCheck = document.getElementById('express-consent-check');
    const submitBtn = document.getElementById('express-step1-submit');
    if (consentCheck && submitBtn) {
        const consentChecked = consentCheck.checked;
        if (consentChecked) {
            submitBtn.disabled = false;
            submitBtn.classList.remove('bg-forest-green/45', 'cursor-not-allowed');
            submitBtn.classList.add('bg-forest-green');
        } else {
            submitBtn.disabled = true;
            submitBtn.classList.remove('bg-forest-green');
            submitBtn.classList.add('bg-forest-green/45', 'cursor-not-allowed');
        }
    }
};

window.openExpressPolicyModal = function(e, type) {
    if (e) {
        e.preventDefault();
        e.stopPropagation();
    }
    const modal = document.getElementById('express-policy-modal');
    const titleEl = document.getElementById('express-policy-title');
    const bodyEl = document.getElementById('express-policy-body');
    
    if (!modal || !titleEl || !bodyEl) return;
    
    let title = "";
    let body = "";
    
    if (type === 'conduct') {
        title = "Code of Conduct";
        body = "Corner Swaps is built on trust, respect, and mutual aid. Members are expected to be kind, respectful, and reliable when arranging swaps. Repeated no-shows (5 strikes), harassment, commercial listings, or spamming will lead to immediate account suspension.";
    } else if (type === 'safety') {
        title = "Safety Rules";
        body = "Always arrange exchanges in safe, public, and well-lit locations (such as local parks, cafes, or community centers). Only share cross-streets or general vicinities; never share your exact home address or apartment number. Trust your instincts and report suspicious behavior.";
    } else if (type === 'liability') {
        title = "Liability Disclaimer";
        body = "Corner Swaps acts solely as a passive facilitator to connect community members. We do not inspect, verify, or guarantee the safety, legality, quality, or existence of any listings, items, or skills exchanged. By using this platform, you explicitly acknowledge and agree that all exchanges are conducted entirely at your own risk. You hereby release Corner Swaps and its affiliates from any and all liability, claims, disputes, damages, or losses arising from or in connection with user exchanges, transactions, or communications.";
    } else if (type === 'privacy') {
        title = "Privacy Policy";
        body = "We collect basic account details (name, email) and location information (neighborhood or neighborhood center) to connect you with other users. We do not sell your personal data. You can delete your account at any time in Account Settings.";
    }
    
    titleEl.textContent = title;
    bodyEl.textContent = body;
    modal.classList.remove('hidden');
};

window.closeExpressPolicyModal = function() {
    const modal = document.getElementById('express-policy-modal');
    if (modal) {
        modal.classList.add('hidden');
    }
};

window.handleExpressSignupStep1 = function(event) {
    if (event) event.preventDefault();
    
    const firstName = document.getElementById('express-first-name').value.trim();
    const displayName = document.getElementById('express-display-name').value.trim();
    const email = document.getElementById('express-email').value.trim();
    const password = document.getElementById('express-password').value.trim();
    const locationSelect = document.getElementById('express-location-select').value;
    const customLocation = document.getElementById('express-custom-location').value.trim();
    const consentCheck = document.getElementById('express-consent-check');
    const consentChecked = consentCheck ? consentCheck.checked : false;
    
    if (!firstName || !displayName || !email || !password || !locationSelect) {
        alert("Please fill in all required fields.");
        return;
    }
    
    if (locationSelect === 'custom' && !customLocation) {
        alert("Please type your neighborhood name.");
        return;
    }
    
    if (password.length < 8) {
        alert("Password must be at least 8 characters.");
        return;
    }
    
    if (!consentChecked) {
        alert("You must agree to the policies to proceed.");
        return;
    }
    
    if (state.suspendedUsers && (state.suspendedUsers.includes(displayName) || state.suspendedUsers.includes(email))) {
        alert("Your account has been suspended for repeated unreliability (5 no-show strikes). Please contact support.");
        return;
    }
    
    let resolvedLocation = locationSelect;
    let resolvedLat = 49.2608;
    let resolvedLng = -123.1368;
    
    if (locationSelect === 'custom') {
        resolvedLocation = customLocation;
    } else {
        const coords = NEIGHBORHOOD_COORDS[locationSelect];
        if (coords) {
            resolvedLat = coords.lat;
            resolvedLng = coords.lng;
        }
    }
    
    window.tempExpressUser = {
        firstName: firstName,
        lastName: '',
        displayName: displayName,
        email: email,
        password: password,
        location: resolvedLocation,
        lat: resolvedLat,
        lng: resolvedLng
    };
    
    if (typeof playSound === 'function') playSound('click');
    showView('express_signup_step2');
    window.setExpressPostType('offering');
};

window.setExpressPostType = function(type) {
    if (typeof playSound === 'function') playSound('click');
    window.expressPostType = type;
    
    const tabs = ['offering', 'need', 'skip'];
    tabs.forEach(t => {
        const btn = document.getElementById(`express-post-tab-${t}`);
        if (btn) {
            if (t === type) {
                btn.className = "p-2.5 bg-forest-green text-white border border-forest-green rounded-xl font-bold text-[11px] flex items-center justify-center gap-1.5 active:scale-95 transition-all select-none";
            } else {
                btn.className = "p-2.5 bg-white border border-outline-variant/30 text-forest-green rounded-xl font-bold text-[11px] flex items-center justify-center gap-1.5 active:scale-95 transition-all select-none";
            }
        }
    });
    
    const formContainer = document.getElementById('express-post-form-container');
    if (formContainer) {
        if (type === 'skip') {
            formContainer.classList.add('hidden');
        } else {
            formContainer.classList.remove('hidden');
        }
    }
};

window.handleExpressSignupSubmit = function() {
    if (!window.tempExpressUser) {
        alert("Sign up details missing. Please restart registration.");
        showView('village');
        return;
    }
    
    const postType = window.expressPostType || 'offering';
    let hasListing = false;
    let listingTitle = "";
    let listingDesc = "";
    let listingCategory = "Other";
    
    if (postType !== 'skip') {
        listingTitle = document.getElementById('express-post-title').value.trim();
        listingDesc = document.getElementById('express-post-desc').value.trim();
        const catSelect = document.getElementById('express-post-category');
        listingCategory = catSelect ? catSelect.value : "Other";
        
        if (!listingTitle || !listingDesc) {
            alert("Please enter a title and description for your post, or choose 'Skip Post'.");
            return;
        }
        
        if (typeof checkSafetyPolicy === 'function' && (checkSafetyPolicy(listingTitle) || checkSafetyPolicy(listingDesc))) {
            showSafetyContentViolation();
            return;
        }
        if (typeof checkCashlessPolicy === 'function' && (checkCashlessPolicy(listingTitle) || checkCashlessPolicy(listingDesc))) {
            showSafetyMoneyWarning();
            return;
        }
        
        hasListing = true;
    }
    
    state.currentUser = {
        firstName: window.tempExpressUser.firstName,
        lastName: window.tempExpressUser.lastName,
        displayName: window.tempExpressUser.displayName,
        email: window.tempExpressUser.email,
        avatar: DEFAULT_AVATAR,
        location: window.tempExpressUser.location,
        lat: window.tempExpressUser.lat,
        lng: window.tempExpressUser.lng,
        skills: [],
        needs: []
    };
    state.isGuest = false;
    state.loggedOut = false;
    
    if (hasListing) {
        const id = postType + '-' + Date.now() + '-' + Math.random().toString(36).substr(2, 9);
        if (postType === 'offering') {
            state.userOfferings.push({
                id: id,
                title: listingTitle,
                category: listingCategory,
                desc: listingDesc,
                icon: 'info',
                image: null,
                lat: window.tempExpressUser.lat,
                lng: window.tempExpressUser.lng
            });
        } else if (postType === 'need') {
            if (!state.userNeeds) state.userNeeds = [];
            state.userNeeds.push({
                id: id,
                title: listingTitle,
                category: listingCategory,
                desc: listingDesc,
                icon: 'info',
                lat: window.tempExpressUser.lat,
                lng: window.tempExpressUser.lng
            });
        }
    }
    
    saveState();
    window.tempExpressUser = null;
    
    if (typeof playSound === 'function') playSound('click');
    showView('village');
    if (typeof triggerSuccessConfetti === 'function') triggerSuccessConfetti();
    if (typeof refreshAllLayouts === 'function') refreshAllLayouts();
};
window.goToMapFromCelebration = goToMapFromCelebration;

// Profile Step 4: Host Event (Optional) Handlers
function handleProfileStep4Skip() {
    playSound('click');
    showView('village');
}

function handleProfileStep4Submit() {
    const title = document.getElementById('wizard-event-title').value.trim();
    const type = document.getElementById('wizard-event-type').value;
    const datetime = document.getElementById('wizard-event-datetime').value;
    const location = document.getElementById('wizard-event-location').value.trim();
    const desc = document.getElementById('wizard-event-desc').value.trim();

    if (!title || !type || !datetime || !location || !desc) {
        alert("Please fill out all fields to host an event, or click Skip.");
        return;
    }

    if (desc.trim().length < 80) {
        alert("Please write a more detailed description (at least a paragraph, minimum 80 characters) so neighbors know what to expect!");
        return;
    }

    // Safety checks
    if (checkSafetyPolicy(title) || checkSafetyPolicy(desc)) {
        showSafetyContentViolation();
        return;
    }
    // Cashless checks
    if (checkCashlessPolicy(title) || checkCashlessPolicy(desc)) {
        showSafetyMoneyWarning();
        return;
    }

    // Address check (strict blocker)
    if (checkExactAddress(location)) {
        showSafetyAddressWarning();
        return;
    }

    submitWizardEvent(title, type, datetime, location, desc);
}

function submitWizardEvent(title, type, datetime, location, desc) {
    createEventAndSave(title, type, datetime, '', location, desc);
    playSound('click');
    showView('village');
}

function createEventAndSave(title, type, datetime, endDatetime, location, desc) {
    title = escapeHTML(title);
    location = escapeHTML(location);
    desc = escapeHTML(desc);
    
    const lat = 49.2827 + (Math.random() - 0.5) * 0.015;
    const lng = -123.1207 + (Math.random() - 0.5) * 0.015;
    
    const newEvent = {
        id: Date.now().toString(),
        title: title,
        type: type,
        datetime: datetime,
        endDatetime: endDatetime || '',
        location: location,
        desc: desc,
        lat: lat,
        lng: lng,
        image: state.selectedOfferHeroImage || "",
        icon: state.selectedOfferIcon || getEventIcon(type),
        host: state.currentUser ? `${state.currentUser.firstName} ${state.currentUser.lastName}` : 'Lily Kaufmann'
    };

    if (!state.events) state.events = [];
    state.events.push(newEvent);
    addKarmaXP(10);
    saveState();

    // Dynamically add marker on Leaflet map for the new event!
    if (leafletMap) {
        const color = getCategoryColor('Event or Meetup');
        const imgUrl = getEventPresetImage(newEvent.type);

        const iconName = getEventIcon(newEvent.type);
        const avatarUrl = (state.currentUser && state.currentUser.avatar) ? state.currentUser.avatar : DEFAULT_AVATAR;
        const customIcon = L.divIcon({
            className: 'custom-div-icon',
            html: `<div class="pin-icon relative flex items-center justify-center rounded-full" style="border: 2px solid #2563eb !important; background-color: ${color} !important; width: 38px; height: 38px; border-radius: 50% !important; box-shadow: 0 3px 8px rgba(0,0,0,0.2) !important; display: flex !important; align-items: center !important; justify-content: center !important;">
                    <span class="material-symbols-outlined text-[20px]" style="color: white !important; font-variation-settings: 'FILL' 1, 'wght' 600;">${iconName}</span>
                    
                   </div>`,
            iconSize: [38, 38],
            iconAnchor: [19, 19]
        });

        const marker = L.marker([lat, lng], { icon: customIcon }).addTo(leafletMap);
        marker.on('click', () => {
            if (typeof playSound === 'function') playSound('click');
            openEventDetail(newEvent.id);
        });
        mapMarkers.push({ marker, name: 'evt_' + newEvent.id });
    }
}

function getEventPresetImage(type) {
    if (!type) return 'https://images.unsplash.com/photo-1511632765486-a01980e01a18?q=60&w=400&auto=format&fit=crop';
    const t = type.toLowerCase();
    if (t.includes('garden')) return 'https://images.unsplash.com/photo-1466692476868-aef1dfb1e735?q=60&w=400&auto=format&fit=crop';
    if (t.includes('repair') || t.includes('tool')) return 'https://images.unsplash.com/photo-1581092160607-ee22621dd758?q=60&w=400&auto=format&fit=crop';
    if (t.includes('clothing') || t.includes('clothes') || t.includes('apparel')) return 'https://images.unsplash.com/photo-1489987707025-afc232f7ea0f?q=60&w=400&auto=format&fit=crop';
    if (t.includes('workshop')) return 'https://images.unsplash.com/photo-1531482615713-2afd69097998?q=60&w=400&auto=format&fit=crop';
    if (t.includes('meetup')) return 'https://images.unsplash.com/photo-1511632765486-a01980e01a18?q=60&w=400&auto=format&fit=crop';
    if (t.includes('clean')) return 'https://images.unsplash.com/photo-1618477388954-7852f32655ec?q=60&w=400&auto=format&fit=crop';
    if (t.includes('swap') || t.includes('book')) return 'https://images.unsplash.com/photo-1481627834876-b7833e8f5570?q=60&w=400&auto=format&fit=crop';
    if (t.includes('playdate')) return 'https://images.unsplash.com/photo-1485546246426-74dc88dec4d9?q=60&w=400&auto=format&fit=crop';
    return 'https://images.unsplash.com/photo-1511632765486-a01980e01a18?q=60&w=400&auto=format&fit=crop';
}

function renderEventsList() {
    // Sync label only — do not reset slider.value to avoid interrupting user drag
    let radiusVal = (state.stats && state.stats.radius !== undefined) ? state.stats.radius : 5;
    if (radiusVal > 5) radiusVal = 5;
    if (radiusVal < 0.5) radiusVal = 0.5;
    const eventsLabel = document.getElementById('village-events-distance-display');
    if (eventsLabel) eventsLabel.innerText = formatRadiusValue(radiusVal);

    const containers = [
        document.getElementById('events-list-container'),
        document.getElementById('village-events-list')
    ].filter(el => el !== null);
    
    if (containers.length === 0) return;

    const searchInput = document.getElementById('village-events-search-input') || document.getElementById('village-search-input');
    const query = searchInput ? searchInput.value.toLowerCase().trim() : "";
    
    containers.forEach(container => {
        container.innerHTML = "";

        // Render music guidance banner if query is musical
        renderMusicGuidanceBanner(container, query);

        if (!state.events || state.events.length === 0) {
            container.innerHTML += `
                <div class="text-center py-12 bg-white rounded-2xl border border-outline-variant/20 p-6">
                    <span class="material-symbols-outlined text-4xl text-forest-green/40 mb-2 font-light">event_busy</span>
                    <p class="text-xs text-on-surface-variant">No community events hosted yet.</p>
                    <p class="text-[10px] text-outline mt-1">Be the first to kickstart an event in your neighborhood!</p>
                </div>
            `;
            return;
        }

        let maxRadius = radiusVal;
        let userLat = 49.2827;
        let userLng = -123.1207;
        if (state.currentUser && state.currentUser.lat && state.currentUser.lng) {
            userLat = state.currentUser.lat;
            userLng = state.currentUser.lng;
        }

        const sortedEvents = [...state.events].sort((a, b) => new Date(a.datetime) - new Date(b.datetime));
        const eventsWithDistance = sortedEvents.map(evt => {
            let coords = [evt.lat, evt.lng];
            if (!evt.lat || !evt.lng) {
                const hostObj = state.neighbors[evt.host];
                if (hostObj) {
                    coords = getNeighborCoordinates(hostObj);
                } else {
                    coords = [49.2827, -123.1207];
                }
            }
            const distance = (evt.host === 'me' || evt.host === 'Lily Kaufmann' || (state.currentUser && evt.host === (state.currentUser.displayName || `${state.currentUser.firstName} ${state.currentUser.lastName}`))) ? 0.0 : getDistance(userLat, userLng, coords[0], coords[1]);
            return {
                ...evt,
                distance: distance
            };
        });

        const filteredEvents = eventsWithDistance.filter(evt => {
            const currentUser = state.currentUser ? (state.currentUser.displayName || `${state.currentUser.firstName} ${state.currentUser.lastName}`) : 'Lily Kaufmann';
            const isUserEvent = evt.host === 'me' || 
                                evt.host === 'Lily Kaufmann' || 
                                evt.host === 'Lily Kaufmann (You)' ||
                                evt.host.includes('(You)') ||
                                evt.host === currentUser ||
                                (state.currentUser && (evt.host === state.currentUser.displayName || evt.host === `${state.currentUser.firstName} ${state.currentUser.lastName}`));
            if (isUserEvent) return false;

            if (state.blockedUsers && state.blockedUsers.includes(evt.host)) return false;
            if (state.suspendedUsers && state.suspendedUsers.includes(evt.host)) return false;
            const hostObj = state.neighbors[evt.host];
            if (hostObj && hostObj.suspended) return false;
            
            // Distance filter check
            if (evt.distance > maxRadius) return false;

            // Category filter check
            if (state.activeMapFilters && state.activeMapFilters.length > 0) {
                const matchesCategory = state.activeMapFilters.some(filter => isCategoryMatchHelper(evt.type, filter) || isCategoryMatchHelper(evt.category, filter));
                if (!matchesCategory) return false;
            }

            // Search filter check
            return fuzzySearchMatch(query, evt.title, evt.desc, evt.type, evt.location, evt.host);
        });

        if (filteredEvents.length === 0) {
            // Note: Use container.insertAdjacentHTML or innerHTML addition to preserve the music banner if present
            const emptyDiv = document.createElement('div');
            emptyDiv.className = "text-center py-12 bg-white rounded-2xl border border-outline-variant/20 p-6";
            emptyDiv.innerHTML = `
                <span class="material-symbols-outlined text-4xl text-forest-green/40 mb-2 font-light">event_busy</span>
                <p class="text-xs text-on-surface-variant">No matching events found.</p>
            `;
            container.appendChild(emptyDiv);
            return;
        }

        filteredEvents.forEach(evt => {
            const firstImg = evt.image ? evt.image.split('|||').filter(Boolean)[0] : null;
            const img = firstImg || getEventPresetImage(evt.type);
            const times = formatEventTimes(evt.datetime, evt.endDatetime);

            const hostNeighbor = state.neighbors[evt.host];
            const hostAvatar = hostNeighbor ? hostNeighbor.avatar : 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?q=60&w=80';
            
            const isCurrentlyExpanded = window.activeExpandedCardId === 'evt_' + evt.id;
            const card = document.createElement('div');
            card.setAttribute('data-id', evt.id);
            card.className = "list-card-container bg-white dark:bg-[#18201a] rounded-2xl border border-outline-variant/30 dark:border-outline-variant/15 shadow-sm flex flex-col cursor-pointer active:scale-[0.99] hover:border-forest-green/60 hover:shadow-md transition-all relative overflow-hidden" + (isCurrentlyExpanded ? " expanded" : "");
            
            card.onclick = (e) => {
                if (e.target.closest('button') || e.target.closest('a') || e.target.closest('.profile-avatar-ring') || e.target.closest('.profile-avatar-no-ring') || e.target.closest('.inline-save-btn')) {
                    return;
                }
                window.toggleListCardExpand(card, 'event', 'evt_' + evt.id);
            };

            const isUserHost = evt.host === 'me' || evt.host === 'Lily Kaufmann' || (state.currentUser && evt.host === (state.displayName || `${state.currentUser.firstName} ${state.currentUser.lastName}`));
            const distanceDisplay = isUserHost ? '0 km' : `${formatRadiusValue(evt.distance)} away`;

            const evtImages = evt.image ? evt.image.split('|||').filter(Boolean) : [];
            const presetImg = getEventPresetImage(evt.type);
            const img1 = evtImages[0] || presetImg;

            const rawCategory = evt.type || evt.category || 'Event';
            const formattedCategory = rawCategory.replace(/\b\w/g, c => c.toUpperCase());
            const isFree = (evt.category && evt.category.toLowerCase() === 'gifts') || (evt.type && evt.type.toLowerCase() === 'gifts');

            if (!evt.rsvps) {
                evt.rsvps = ['Sarah Chen', 'David Kim'];
            }
            const currentUser = state.currentUser ? (state.currentUser.displayName || `${state.currentUser.firstName} ${state.currentUser.lastName}`) : 'Lily Kaufmann';
            const isUserRsvped = evt.rsvps.includes(currentUser);
            const rsvpsCount = evt.rsvps.length;

            let rsvpAvatarsHtml = '';
            evt.rsvps.forEach(name => {
                let avatarUrl = RSVP_AVATARS[name] || 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?q=60&w=80&auto=format&fit=crop';
                if (state.currentUser && (name === currentUser || name === state.currentUser.displayName || name === (state.currentUser.firstName + ' ' + state.currentUser.lastName).trim())) {
                    if (state.currentUser.avatar) {
                        avatarUrl = state.currentUser.avatar;
                    }
                }
                rsvpAvatarsHtml += `
                    <div class="profile-avatar-no-ring inline-block h-7 w-7 flex-shrink-0 border border-white dark:border-[#18201a] rounded-full overflow-hidden">
                        <img class="w-full h-full object-cover rounded-full" src="${avatarUrl}" title="${name}" alt="${name}">
                    </div>
                `;
            });

            card.innerHTML = `
                <!-- Top Image Portion -->
                <div class="list-card-image-wrapper w-full relative overflow-hidden flex-shrink-0 bg-gray-100 dark:bg-gray-800 border-b border-outline-variant/30 dark:border-outline-variant/15">
                    <img src="${img1}" class="w-full h-full object-cover">
                    ${isFree ? `<div class="absolute top-2.5 right-2.5 px-2 py-0.5 rounded border border-white bg-black/40 text-white text-[9px] font-bold uppercase tracking-wider">Free</div>` : ''}
                </div>
                <!-- Bottom Details Portion -->
                <div class="list-card-text-wrapper p-4 flex-grow flex flex-col justify-between self-stretch min-w-0 w-full">
                    <div>
                        <div class="flex items-center justify-between gap-2">
                            <div class="flex items-center min-w-0 flex-grow">
                                ${getCategoryIconHtml(evt.type || evt.category)}
                                <h4 class="list-card-title truncate leading-tight">${evt.title}</h4>
                            </div>
                        </div>
                        <p class="list-card-description">${evt.desc}</p>
                    </div>

                    <div class="flex items-center justify-between gap-1.5 mt-2">
                        <div class="flex items-center gap-1.5 min-w-0">
                            <!-- Host details with circular avatar bubble -->
                            <div class="profile-avatar-ring w-4 h-4 flex-shrink-0" onclick="event.stopPropagation(); ${isUserHost ? "showView('profile_settings')" : `openNeighborProfileModal('${evt.host}')`}"><img src="${hostAvatar}" class="w-full h-full object-cover rounded-full"></div>
                            <span class="text-[10.5px] text-black dark:text-white font-semibold truncate" onclick="event.stopPropagation(); ${isUserHost ? "showView('profile_settings')" : `openNeighborProfileModal('${evt.host}')`}">${evt.host || 'Member'}</span>
                        </div>
                        <span class="text-[10.5px] text-black dark:text-white font-medium flex-shrink-0">${times.timeDisplay} · ${distanceDisplay}</span>
                    </div>
                </div>
                <!-- Expandable wrapper -->
                <div class="list-card-expandable ${isCurrentlyExpanded ? 'expanded' : ''}">
                    <div class="list-card-expandable-content bg-white dark:bg-[#18201a] px-4 pb-6 space-y-4 border-t border-outline-variant/10 text-xs text-black dark:text-white pt-3">
                        <div class="space-y-3">
                            <!-- Date & Time -->
                            <div class="flex items-start gap-2.5">
                                <span class="material-symbols-outlined text-amber-500 dark:text-amber-400 text-lg mt-0.5">schedule</span>
                                <div>
                                    <h5 class="text-[10px] font-bold uppercase tracking-wider text-outline/80">Date & Time</h5>
                                    <p class="mt-0.5">${times.fullDisplay}</p>
                                </div>
                            </div>
                            <!-- Location/Neighbourhood -->
                            <div class="flex items-start gap-2.5">
                                <span class="material-symbols-outlined text-blue-600 dark:text-blue-400 text-lg mt-0.5">location_on</span>
                                <div>
                                    <h5 class="text-[10px] font-bold uppercase tracking-wider text-outline/80">Neighbourhood</h5>
                                    <p class="mt-0.5">${evt.location} · ${distanceDisplay}</p>
                                </div>
                            </div>
                            
                            <!-- Attendees -->
                            <div class="flex items-start gap-2.5 pt-1">
                                <span class="material-symbols-outlined text-purple-600 dark:text-purple-400 text-lg mt-0.5">group</span>
                                <div class="flex-grow">
                                    <div class="flex justify-between items-center mb-1.5">
                                        <h5 class="text-[10px] font-bold uppercase tracking-wider text-outline/80">Attendees</h5>
                                        <span class="text-[10px] font-medium text-gray-500 dark:text-gray-400 attendee-count-el">${rsvpsCount} ${rsvpsCount === 1 ? 'neighbor is' : 'neighbors are'} going</span>
                                    </div>
                                    <div class="flex gap-1.5 overflow-hidden py-1 attendee-avatars-container">
                                        ${rsvpAvatarsHtml}
                                    </div>
                                </div>
                            </div>
                        </div>
                        
                        <!-- Actions Row -->
                        <div class="flex flex-col gap-2 pt-1.5 bg-white dark:bg-[#18201a] rounded-b-2xl">
                            ${isUserHost ? `
                                <button class="w-full bg-white dark:bg-[#18201a] border border-black/20 dark:border-white/20 text-black dark:text-white py-1.5 rounded-lg font-bold text-[10px] tracking-wide active:scale-[0.98] transition-transform flex items-center justify-center gap-1.5 hover:bg-black/5 dark:hover:bg-white/5 lowercase" onclick="event.stopPropagation(); showView('profile_settings');">
                                    <span class="material-symbols-outlined text-xs">person</span> view profile
                                </button>
                            ` : `
                                <!-- RSVP Button -->
                                <button class="inline-rsvp-btn w-full py-1.5 rounded-lg font-bold text-[10px] tracking-wide active:scale-[0.98] transition-transform flex items-center justify-center gap-1.5 lowercase ${isUserRsvped ? 'bg-black text-white hover:bg-black/90 dark:bg-white dark:text-black dark:hover:bg-white/90' : 'bg-white border border-black/20 text-black hover:bg-black/5 dark:bg-[#18201a] dark:border-white/20 dark:text-white dark:hover:bg-white/5'}" onclick="window.handleEventRSVPToggleFromList('${evt.id}', event)">
                                    <span class="material-symbols-outlined text-xs inline-rsvp-icon">${isUserRsvped ? 'cancel' : 'check_circle'}</span>
                                    <span class="inline-rsvp-text">${isUserRsvped ? 'cancel rsvp' : 'rsvp to event'}</span>
                                </button>
                                
                                <!-- Save Button -->
                                <button class="inline-save-btn w-full bg-white dark:bg-[#18201a] border border-black/20 dark:border-white/20 text-black dark:text-white py-1.5 rounded-lg font-bold text-[10px] tracking-wide active:scale-[0.98] transition-transform flex items-center justify-center gap-1.5 hover:bg-black/5 dark:hover:bg-white/5 lowercase ${state.savedEvents && state.savedEvents.includes(evt.id) ? 'active-green-white' : ''}" onclick="window.handleInlineSaveEvent(event, '${evt.id}')">
                                    <span class="material-symbols-outlined text-xs inline-save-icon" style="font-variation-settings: 'FILL' ${state.savedEvents && state.savedEvents.includes(evt.id) ? '1' : '0'};">bookmark</span>
                                    <span class="inline-save-text">${state.savedEvents && state.savedEvents.includes(evt.id) ? 'saved to profile' : 'save event'}</span>
                                </button>
                                
                                <!-- View Host Profile Button -->
                                <button class="w-full bg-white dark:bg-[#18201a] border border-black/20 dark:border-white/20 text-black dark:text-white py-1.5 rounded-lg font-bold text-[10px] tracking-wide active:scale-[0.98] transition-transform flex items-center justify-center gap-1.5 hover:bg-black/5 dark:hover:bg-white/5 lowercase" onclick="event.stopPropagation(); openNeighborProfileModal('${evt.host}');">
                                    <span class="material-symbols-outlined text-xs">person</span> view host profile
                                </button>
                                
                                <!-- Report Button -->
                                <button class="w-full bg-transparent text-error border border-error/20 py-1.5 rounded-lg font-bold flex items-center justify-center gap-1.5 active:scale-[0.98] transition-transform text-[10px] tracking-wide hover:bg-red-50 lowercase" onclick="event.stopPropagation(); openReportModal('event', '${evt.id}');">
                                    <span class="material-symbols-outlined text-xs">flag</span> report event
                                </button>
                            `}
                        </div>
                    </div>
                </div>
            `;
            container.appendChild(card);
        });
    });
}

function getBulletinTypeBadgeClass(type) {
    if (type === 'Alert') return 'bg-rose-50 text-rose-600 border border-rose-200/50 animate-pulse';
    if (type === 'Notice') return 'bg-blue-50 text-blue-600 border border-blue-200/50';
    if (type === 'Info') return 'bg-teal-50 text-teal-600 border border-teal-200/50';
    return 'bg-amber-50 text-amber-600 border border-amber-200/50'; // Lost & Found
}

function renderBulletinsList() {
    const container = document.getElementById('village-bulletins-list');
    if (!container) return;
    
    container.innerHTML = "";

    const searchInput = document.getElementById('village-bulletins-search-input');
    const query = searchInput ? searchInput.value.toLowerCase().trim() : "";

    // Prepend music guidance banner if query is musical
    renderMusicGuidanceBanner(container, query);

    if (!state.bulletins || state.bulletins.length === 0) {
        container.innerHTML += `
            <div class="text-center py-12 bg-white rounded-2xl border border-outline-variant/20 p-6">
                <span class="material-symbols-outlined text-4xl text-forest-green/40 mb-2 font-light">campaign</span>
                <p class="text-xs text-on-surface-variant">No announcements posted yet.</p>
                <p class="text-[10px] text-outline mt-1">Be the first to share neighborhood news!</p>
            </div>
        `;
        return;
    }

    const filteredBulletins = state.bulletins.filter(bulletin => {
        return fuzzySearchMatch(query, bulletin.title, bulletin.desc, bulletin.type, bulletin.author);
    });

    if (filteredBulletins.length === 0) {
        const emptyDiv = document.createElement('div');
        emptyDiv.className = "text-center py-12 bg-white rounded-2xl border border-outline-variant/20 p-6";
        emptyDiv.innerHTML = `
            <span class="material-symbols-outlined text-4xl text-forest-green/40 mb-2 font-light">campaign</span>
            <p class="text-xs text-on-surface-variant">No matching announcements found.</p>
        `;
        container.appendChild(emptyDiv);
        return;
    }

    filteredBulletins.forEach(bulletin => {
        const card = document.createElement('div');
        card.className = "bg-white border border-outline-variant/30 hover:border-forest-green cursor-pointer transition-all duration-200 rounded-2xl p-4.5 shadow-sm space-y-3 relative text-left active:scale-[0.99]";
        card.onclick = () => openBulletinDetailModal(bulletin.id);
        
        card.innerHTML = `
            <div class="flex justify-between items-start">
                <h4 class="font-headline font-bold text-sm text-black dark:text-white">${bulletin.title}</h4>
                <span class="px-2 py-0.5 rounded-full text-[9px] font-bold uppercase tracking-wider ${getBulletinTypeBadgeClass(bulletin.type)}">${bulletin.type}</span>
            </div>
            <p class="text-xs text-on-surface-variant leading-relaxed text-left line-clamp-3">${bulletin.desc}</p>
            <div class="flex justify-between items-center text-[10px] text-outline border-t border-outline-variant/10 pt-3">
                <div class="flex items-center gap-1.5">
                    <span class="material-symbols-outlined text-xs">person</span>
                    <span class="font-medium">${bulletin.author}</span>
                    <span>•</span>
                    <span>${bulletin.date}</span>
                </div>
                <button class="flex items-center gap-1 text-black dark:text-white hover:opacity-80 active:scale-90 transition-transform font-bold" onclick="event.stopPropagation(); likeBulletin('${bulletin.id}')">
                    <span class="material-symbols-outlined text-xs text-rose-500" style="font-variation-settings: 'FILL' 1;">favorite</span>
                    <span id="bulletin-likes-${bulletin.id}">${bulletin.likes}</span>
                </button>
            </div>
        `;
        container.appendChild(card);
    });
}

function likeBulletin(id) {
    playSound('pop');
    const bulletin = state.bulletins.find(b => b.id === id);
    if (bulletin) {
        bulletin.likes = (bulletin.likes || 0) + 1;
        const el = document.getElementById(`bulletin-likes-${id}`);
        if (el) {
            el.innerText = bulletin.likes;
            el.classList.add('scale-125', 'text-rose-600');
            setTimeout(() => {
                el.classList.remove('scale-125', 'text-rose-600');
            }, 300);
        }
    }
}

window.openBulletinDetailModal = function(id) {
    playSound('click');
    const bulletin = state.bulletins.find(b => b.id === id);
    if (!bulletin) return;
    
    const modal = document.getElementById('bulletin-detail-modal');
    if (!modal) return;
    
    const titleEl = document.getElementById('bulletin-modal-title');
    const descEl = document.getElementById('bulletin-modal-desc');
    const badgeEl = document.getElementById('bulletin-modal-badge');
    const dateEl = document.getElementById('bulletin-modal-date');
    const authorAvatarEl = document.getElementById('bulletin-modal-author-avatar');
    const authorNameEl = document.getElementById('bulletin-modal-author-name');
    const likesCountEl = document.getElementById('bulletin-modal-likes-count');
    const likeBtn = document.getElementById('bulletin-modal-like-btn');
    const messageBtn = document.getElementById('bulletin-modal-message-btn');
    
    if (titleEl) titleEl.textContent = bulletin.title;
    if (descEl) descEl.innerHTML = (bulletin.desc || "").replace(/\n/g, '<br>');
    if (badgeEl) {
        badgeEl.textContent = bulletin.type;
        badgeEl.className = `px-2 py-0.5 rounded-full text-[9px] font-bold uppercase tracking-wider ${getBulletinTypeBadgeClass(bulletin.type)}`;
    }
    if (dateEl) dateEl.textContent = bulletin.date;
    
    const rawAuthor = bulletin.author || "Sarah Chen";
    const authorName = rawAuthor.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(' ');
    if (authorNameEl) authorNameEl.textContent = authorName;
    const neighbor = state.neighbors[authorName];
    if (authorAvatarEl) {
        authorAvatarEl.src = neighbor && neighbor.avatar ? neighbor.avatar : "https://images.unsplash.com/photo-1544005313-94ddf0286df2?q=60&w=80&auto=format&fit=crop";
    }
    
    if (likesCountEl) likesCountEl.textContent = bulletin.likes || 0;
    
    if (likeBtn) {
        likeBtn.onclick = (e) => {
            e.stopPropagation();
            likeBulletin(id);
            if (likesCountEl) likesCountEl.textContent = bulletin.likes;
        };
    }
    
    if (messageBtn) {
        messageBtn.onclick = (e) => {
            e.stopPropagation();
            closeBulletinDetailModal();
            const currentUserName = state.currentUser ? (state.currentUser.displayName || `${state.currentUser.firstName} ${state.currentUser.lastName}`) : 'Lily Kaufmann';
            if (authorName === currentUserName) {
                alert("This is your own bulletin!");
                return;
            }
            startChatConversation(authorName);
        };
    }
    
    modal.classList.remove('hidden');
};

window.closeBulletinDetailModal = function() {
    playSound('click');
    const modal = document.getElementById('bulletin-detail-modal');
    if (modal) {
        modal.classList.add('hidden');
    }
};

function openNewBulletinModal() {
    playSound('click');
    showView('create_bulletin');
}

function handleCreateBulletinSubmit(event) {
    event.preventDefault();
    if (state.lockdownMode) {
        alert("Posting is temporarily disabled due to global administrator security lockdown.");
        return;
    }
    playSound('success');

    const titleInput = document.getElementById('bulletin-title-input');
    const typeSelect = document.getElementById('bulletin-type-select');
    const descInput = document.getElementById('bulletin-desc-input');

    if (!titleInput || !typeSelect || !descInput) return;

    const newBulletin = {
        id: 'b_' + Date.now(),
        title: escapeHTML(titleInput.value.trim()),
        type: typeSelect.value,
        desc: escapeHTML(descInput.value.trim()),
        author: state.currentUser ? escapeHTML(`${state.currentUser.firstName} ${state.currentUser.lastName}`) : 'Lily Kaufmann',
        date: 'Just now',
        likes: 0
    };

    if (!state.bulletins) state.bulletins = [];
    state.bulletins.unshift(newBulletin);

    // Reset form
    document.getElementById('create-bulletin-form').reset();

    // Go back to village view and switch to bulletins segment
    showView('village');
    switchVillageSegment('bulletins');
}

function handleCreateEventSubmit(e) {
    if (e) e.preventDefault();
    submitCreateEvent();
}

function submitCreateEvent() {
    const titleInput = document.getElementById('event-title-input');
    const typeSelect = document.getElementById('event-type-select');
    const datetimeInput = document.getElementById('event-datetime-input');
    const endDatetimeInput = document.getElementById('event-end-datetime-input');
    const locationInput = document.getElementById('event-location-input');
    const descInput = document.getElementById('event-desc-input');

    const title = titleInput ? titleInput.value.trim() : '';
    const type = typeSelect ? typeSelect.value : '';
    const datetime = datetimeInput ? datetimeInput.value : '';
    const endDatetime = endDatetimeInput ? endDatetimeInput.value : '';
    const location = locationInput ? locationInput.value.trim() : '';
    const desc = descInput ? descInput.value.trim() : '';

    let hasErrors = false;
    let firstErrorEl = null;

    const markInvalid = (el) => {
        if (el) {
            el.classList.add('border-red-500', 'ring-1', 'ring-red-500');
            hasErrors = true;
            if (!firstErrorEl) firstErrorEl = el;
        }
    };

    const markValid = (el) => {
        if (el) {
            el.classList.remove('border-red-500', 'ring-1', 'ring-red-500');
        }
    };

    if (!title) markInvalid(titleInput); else markValid(titleInput);
    if (!type) markInvalid(typeSelect); else markValid(typeSelect);
    if (!datetime) markInvalid(datetimeInput); else markValid(datetimeInput);
    if (!location) markInvalid(locationInput); else markValid(locationInput);

    if (datetime && endDatetime && new Date(endDatetime) <= new Date(datetime)) {
        markInvalid(endDatetimeInput);
        alert("End time must be after the start time.");
    } else {
        markValid(endDatetimeInput);
    }

    if (hasErrors) {
        if (firstErrorEl) {
            firstErrorEl.focus();
            firstErrorEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
        return;
    }

    // Safety checks
    if (checkSafetyPolicy(title) || checkSafetyPolicy(desc)) {
        showSafetyContentViolation();
        return;
    }
    // Cashless checks
    if (checkCashlessPolicy(title) || checkCashlessPolicy(desc)) {
        showSafetyMoneyWarning();
        return;
    }

    // Address check (strict blocker)
    if (checkExactAddress(location)) {
        showSafetyAddressWarning();
        return;
    }

    executeCreateEvent(title, type, datetime, endDatetime, location, desc);
}

function executeCreateEvent(title, type, datetime, endDatetime, location, desc) {
    if (state.lockdownMode) {
        alert("Posting is temporarily disabled due to global administrator security lockdown.");
        return;
    }
    createEventAndSave(title, type, datetime, endDatetime, location, desc);

    // Trigger Success Confetti & sound
    if (typeof triggerSuccessConfetti === 'function') {
        triggerSuccessConfetti();
    } else {
        playSound('success');
    }

    // Show congratulations modal
    showCongratsEventModal(title);
}

function showCongratsEventModal(eventTitle) {
    const modal = document.getElementById('congrats-event-modal');
    const textEl = document.getElementById('congrats-event-text');
    if (textEl) {
        textEl.innerHTML = `Congratulations! You've successfully scheduled <strong>"${escapeHTML(eventTitle)}"</strong>. Neighbors will be notified to RSVP! 🎉`;
    }
    if (modal) {
        modal.classList.remove('hidden');
    }
}
window.showCongratsEventModal = showCongratsEventModal;

function closeCongratsEventModal() {
    if (typeof playSound === 'function') playSound('click');
    const modal = document.getElementById('congrats-event-modal');
    if (modal) {
        modal.classList.add('hidden');
    }

    // Clear event form fields
    const titleInput = document.getElementById('event-title-input');
    const typeSelect = document.getElementById('event-type-select');
    const datetimeInput = document.getElementById('event-datetime-input');
    const endDatetimeInput = document.getElementById('event-end-datetime-input');
    const locationInput = document.getElementById('event-location-input');
    const descInput = document.getElementById('event-desc-input');
    if (titleInput) titleInput.value = '';
    if (typeSelect) typeSelect.value = '';
    if (datetimeInput) datetimeInput.value = '';
    if (endDatetimeInput) endDatetimeInput.value = '';
    if (locationInput) locationInput.value = '';
    if (descInput) descInput.value = '';

    // Only redirect to page after closing the congrats popup
    exitCreateEvent();
}
window.closeCongratsEventModal = closeCongratsEventModal;

// ----------------------------------------------------
// 4. Immersive Discovery Map (Leaflet)
// ----------------------------------------------------
function getCategoryColor(category) {
    if (!category) return '#546E7A'; // Default gray for other (non-green)
    const catLower = category.toLowerCase();
    if (catLower.includes('karma')) return '#f59e0b';
    if (catLower.includes('donation')) return '#ec4899';
    
    // Find matching category in MAP_FILTER_CATEGORIES
    const match = MAP_FILTER_CATEGORIES.find(c => {
        const nameLower = c.name.toLowerCase();
        return nameLower.includes(catLower) || catLower.includes(nameLower) ||
               (catLower.includes('outdoor') && nameLower.includes('outdoor')) ||
               (catLower.includes('service') && nameLower.includes('service')) ||
               (catLower.includes('art') && nameLower.includes('art')) ||
               (catLower.includes('apparel') && nameLower.includes('apparel')) ||
               (catLower.includes('entertainment') && nameLower.includes('entertainment')) ||
               (catLower.includes('maternity') && nameLower.includes('maternity')) ||
               (catLower.includes('exchange') && nameLower.includes('exchange'));
    });
    if (match) {
        return match.color;
    }
    
    // Fallback logic to match MAP_FILTER_CATEGORIES colors
    if (catLower.includes('food') || catLower.includes('drink')) return '#EF5350';
    if (catLower.includes('home') || catLower.includes('living') || catLower.includes('gear')) return '#AB47BC';
    if (catLower.includes('garden') || catLower.includes('outdoor')) return '#66BB6A';
    if (catLower.includes('skills') || catLower.includes('education')) return '#42A5F5';
    if (catLower.includes('handyman') || catLower.includes('service')) return '#FF7043';
    if (catLower.includes('creative') || catLower.includes('art')) return '#EC407A';
    if (catLower.includes('health') || catLower.includes('wellness')) return '#26A69A';
    if (catLower.includes('clothing') || catLower.includes('apparel')) return '#FFB300';
    if (catLower.includes('books') || catLower.includes('games') || catLower.includes('entertainment')) return '#5C6BC0';
    if (catLower.includes('kids') || catLower.includes('maternity')) return '#F06292';
    if (catLower.includes('event') || catLower.includes('meetup')) return '#8D6E63';
    if (catLower.includes('language') || catLower.includes('info') || catLower.includes('exchange')) return '#00ACC1';
    
    return '#546E7A'; // Gray for Other
}

function getCategoryIcon(category) {
    if (!category) return 'handshake';
    const cat = category.toLowerCase();
    if (cat.includes('karma')) return 'favorite';
    if (cat.includes('donation')) return 'volunteer_activism';
    if (cat.includes('food') || cat.includes('drink')) return 'restaurant';
    if (cat.includes('home') || cat.includes('living')) return 'home';
    if (cat.includes('garden') || cat.includes('outdoor')) return 'yard';
    if (cat.includes('skills') || cat.includes('education')) return 'school';
    if (cat.includes('handyman') || cat.includes('service')) return 'handyman';
    if (cat.includes('creative') || cat.includes('art')) return 'palette';
    if (cat.includes('health') || cat.includes('wellness')) return 'spa';
    if (cat.includes('clothing') || cat.includes('apparel')) return 'checkroom';
    if (cat.includes('books') || cat.includes('games') || cat.includes('entertainment')) return 'sports_esports';
    if (cat.includes('kids') || cat.includes('maternity')) return 'stroller';
    if (cat.includes('event') || cat.includes('meetup')) return 'groups';
    if (cat.includes('language') || cat.includes('info') || cat.includes('exchange')) return 'translate';
    if (cat.includes('sex') || cat.includes('escort')) return 'warning';
    if (cat.includes('money') || cat.includes('cash')) return 'attach_money';
    if (cat.includes('drugs') || cat.includes('substances')) return 'medication';
    return 'apps';
}

// Global variable for Karma gift state
let giftKarmaActive = false;
let karmaXPClaimedForCurrentOffer = false;

function handleKarmaCheckboxChange(checkbox) {
    giftKarmaActive = checkbox.checked;
    const wishlistInput = document.getElementById('offer-wishlist-input');
    const unifiedCard = document.getElementById('karma-unified-card');
    
    if (!wishlistInput || !unifiedCard) return;
    
    if (giftKarmaActive) {
        wishlistInput.value = "Free / Sharing Karma Only";
        wishlistInput.disabled = true;
        wishlistInput.classList.add('bg-gray-100/55', 'dark:bg-emerald-950/10', 'opacity-85');
        unifiedCard.classList.remove('border-outline-variant/30');
        unifiedCard.classList.add('border-[#308A5E]', 'bg-[#308A5E]/5', 'dark:bg-emerald-950/15');
        
        // Trigger the animation and add XP only if NOT already claimed in this offering session
        if (!karmaXPClaimedForCurrentOffer) {
            karmaXPClaimedForCurrentOffer = true;
            triggerKarmaBoostAnimation(null);
        } else {
            const subPanel = document.getElementById('karma-animation-sub-panel');
            if (subPanel) {
                subPanel.classList.remove('hidden');
            }
            if (typeof playSound === 'function') {
                playSound('click');
            }
        }
    } else {
        wishlistInput.value = "";
        wishlistInput.disabled = false;
        wishlistInput.classList.remove('bg-gray-100/55', 'dark:bg-emerald-950/10', 'opacity-85');
        unifiedCard.classList.add('border-outline-variant/30');
        unifiedCard.classList.remove('border-[#308A5E]', 'bg-[#308A5E]/5', 'dark:bg-emerald-950/15');
        
        // Hide the sub-panel
        const subPanel = document.getElementById('karma-animation-sub-panel');
        if (subPanel) {
            subPanel.classList.add('hidden');
        }
        
        if (typeof playSound === 'function') {
            playSound('click');
        }
    }
}

window.handleKarmaCardClick = function(event) {
    // Avoid double trigger if they clicked the checkbox directly or elements inside it
    if (event.target.id === 'karma-checkbox' || event.target.closest('label') || event.target.closest('input')) return;
    const checkbox = document.getElementById('karma-checkbox');
    if (checkbox) {
        checkbox.checked = !checkbox.checked;
        handleKarmaCheckboxChange(checkbox);
    }
};

window.triggerKarmaBoostAnimation = function(event) {
    if (typeof playSound === 'function') {
        playSound('success');
    }

    const subPanel = document.getElementById('karma-animation-sub-panel');
    if (!subPanel) return;

    // Remove hidden class to expand panel
    subPanel.classList.remove('hidden');

    // Read current stats before adding XP
    const startLevel = state.level || 1;
    const startXp = state.xp === undefined ? 50 : state.xp;
    const prevScore = (startLevel - 1) * 100 + startXp;

    // Initialize UI state
    const prevScoreEl = document.getElementById('karma-anim-prev-score');
    const progressBar = document.getElementById('karma-anim-progress-bar');
    const levelLabel = document.getElementById('karma-anim-level-label');

    if (prevScoreEl) prevScoreEl.innerText = `${prevScore} Karma`;
    if (progressBar) {
        progressBar.style.transition = 'none';
        progressBar.style.width = `${startXp}%`;
        // Force reflow
        progressBar.offsetHeight;
        progressBar.style.transition = 'all 1000ms ease-out';
    }
    if (levelLabel) {
        levelLabel.innerText = `Level ${startLevel}: ${typeof getLevelTitle === 'function' ? getLevelTitle(startLevel) : 'Resident'}`;
    }

    // No XP awarded here per new karma points rules

    const endLevel = state.level || 1;
    const endXp = state.xp === undefined ? 50 : state.xp;
    const newScore = (endLevel - 1) * 100 + endXp;

    // Animate progress bar width
    if (progressBar) {
        if (endLevel > startLevel) {
            // Level Up scenario
            progressBar.style.width = '100%';
            setTimeout(() => {
                progressBar.style.transition = 'none';
                progressBar.style.width = '0%';
                progressBar.offsetHeight; // reflow
                progressBar.style.transition = 'all 1000ms ease-out';
                progressBar.style.width = `${endXp}%`;
                if (levelLabel) {
                    levelLabel.innerText = `Level ${endLevel}: ${typeof getLevelTitle === 'function' ? getLevelTitle(endLevel) : 'Resident'}`;
                }
            }, 600);
        } else {
            // Normal increment
            progressBar.style.width = `${endXp}%`;
        }
    }

    // Animate numeric score count up
    if (prevScoreEl) {
        let startScore = prevScore;
        let endScore = newScore;
        let animDuration = 1000;
        let startTime = null;
        function step(timestamp) {
            if (!startTime) startTime = timestamp;
            let progress = Math.min((timestamp - startTime) / animDuration, 1);
            let currentVal = Math.floor(startScore + progress * (endScore - startScore));
            prevScoreEl.innerText = `${currentVal} Karma`;
            if (progress < 1) {
                window.requestAnimationFrame(step);
            } else {
                prevScoreEl.innerText = `${endScore} Karma`;
            }
        }
        window.requestAnimationFrame(step);
    }

    // Create floating score boost bubble animation
    const container = document.getElementById('view-offer');
    if (container) {
        const bubble = document.createElement('div');
        bubble.className = 'karma-boost-bubble';
        bubble.innerText = '+50 Karma Points Added';
        
        const rect = container.getBoundingClientRect();
        const card = document.getElementById('karma-unified-card');
        let x = rect.width / 2;
        let y = rect.height / 2;
        
        if (event && event.clientX && event.clientY) {
            x = event.clientX - rect.left;
            y = event.clientY - rect.top;
        } else if (card) {
            const cardRect = card.getBoundingClientRect();
            x = (cardRect.left + cardRect.width / 2) - rect.left;
            y = (cardRect.top + cardRect.height / 2) - rect.top - 20;
        }
        
        bubble.style.left = `${x}px`;
        bubble.style.top = `${y}px`;
        
        container.appendChild(bubble);
        setTimeout(() => {
            bubble.remove();
        }, 1200);
    }
};

