function getEventIcon(type) {
    if (!type) return 'campaign';
    const t = type.toLowerCase();
    if (t.includes('workshop')) return 'school';
    if (t.includes('meetup')) return 'groups';
    if (t.includes('clean')) return 'cleaning_services';
    if (t.includes('swap') || t.includes('book')) return 'menu_book';
    if (t.includes('playdate')) return 'child_care';
    if (t.includes('garden')) return 'yard';
    if (t.includes('repair') || t.includes('tool')) return 'handyman';
    if (t.includes('clothing') || t.includes('apparel')) return 'checkroom';
    return 'campaign';
}

function getBarterItemStatus(idOrName) {
    if (!idOrName) return 'Available';
    if (idOrName.startsWith('evt_')) {
        return 'Available';
    }
    let neighborName = idOrName;
    if (idOrName.startsWith('off_') || idOrName === '1' || idOrName === '2') {
        const offer = state.userOfferings.find(o => o.id === idOrName);
        if (!offer) return 'Available';
        const title = offer.title;
        const conv = state.conversations && state.conversations.find(c => c.negotiation && c.negotiation.offeredItem === title);
        if (conv && conv.negotiation) {
            if (conv.negotiation.status === 'completed') return 'Traded';
            if (conv.negotiation.status === 'accepted' || conv.negotiation.status === 'pending' || conv.negotiation.status === 'received') return 'Negotiating';
        }
        return 'Available';
    }
    const conv = state.conversations && state.conversations.find(c => c.neighborName === neighborName);
    if (conv && conv.negotiation) {
        if (conv.negotiation.status === 'completed') return 'Traded';
        if (conv.negotiation.status === 'accepted' || conv.negotiation.status === 'pending' || conv.negotiation.status === 'received') return 'Negotiating';
    }
    return 'Available';
}

function updateStatusDots(containerId, status) {
    const dotsContainer = document.getElementById(containerId);
    if (!dotsContainer) return;
    
    const availableDot = dotsContainer.querySelector('[id$="dot-available"]');
    const negotiatingDot = dotsContainer.querySelector('[id$="dot-negotiating"]');
    const tradedDot = dotsContainer.querySelector('[id$="dot-traded"]');
    
    if (!availableDot || !negotiatingDot || !tradedDot) return;
    
    const dotSizeClass = "w-2.5 h-2.5";
    
    // Reset styles
    availableDot.className = `${dotSizeClass} rounded-full bg-[#00FF66] transition-all duration-300`;
    negotiatingDot.className = `${dotSizeClass} rounded-full bg-[#f59e0b] transition-all duration-300`;
    tradedDot.className = `${dotSizeClass} rounded-full bg-[#ef4444] transition-all duration-300`;
    
    // Apply status-specific highlights
    if (status === 'Available') {
        availableDot.classList.add('glow-dot-green');
        negotiatingDot.classList.add('opacity-25');
        tradedDot.classList.add('opacity-25');
    } else if (status === 'Negotiating') {
        negotiatingDot.classList.add('glow-dot-amber');
        availableDot.classList.add('opacity-25');
        tradedDot.classList.add('opacity-25');
    } else if (status === 'Traded') {
        tradedDot.classList.add('glow-dot-red');
        availableDot.classList.add('opacity-25');
        negotiatingDot.classList.add('opacity-25');
    }
}

function initLeafletMap() {
    if (leafletMap) {
        setTimeout(() => {
            const mapEl = document.getElementById('map');
            if (leafletMap && mapEl && mapEl.offsetParent !== null) {
                leafletMap.invalidateSize();
            }
        }, 150);
        return;
    }

    console.log("Constructing Map...");
    const mapContainer = document.getElementById('map');
    if (!mapContainer) return;

    const vancouverBounds = L.latLngBounds([49.0, -123.5], [49.4, -122.5]);
    let centerCoords = [49.2608, -123.1368]; // Default to Fairview
    let zoomLevel = 15; // Zoom in to your area!
    if (state.currentUser && state.currentUser.lat && state.currentUser.lng) {
        centerCoords = [state.currentUser.lat, state.currentUser.lng];
    }

    leafletMap = L.map('map', {
        zoomControl: false,
        attributionControl: false,
        maxBounds: vancouverBounds,
        maxBoundsViscosity: 1.0,
        minZoom: 10,
        tap: false,
        bounceAtZoomLimits: false,
        wheelDebounceTime: 150,
        preferCanvas: true,
        fadeAnimation: true,
        zoomAnimation: true,
        markerZoomAnimation: true,
        inertia: true,
        inertiaDeceleration: 3000,
        inertiaMaxSpeed: 1500
    }).setView(centerCoords, zoomLevel);

    const retinaSuffix = '';
    const isDark = state.preferences && state.preferences.darkMode;
    const tileUrl = isDark
        ? 'https://{s}.basemaps.cartocdn.com/rastertiles/dark_all/{z}/{x}/{y}' + retinaSuffix + '.png'
        : 'https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}' + retinaSuffix + '.png';
    
    mapTileLayer = L.tileLayer(tileUrl, {
        maxZoom: 19,
        subdomains: 'abcd',
        keepBuffer: 2,
        updateWhenPanning: true,
        updateWhenIdle: false
    }).addTo(leafletMap);

    // Setup ResizeObserver to automatically handle size changes smoothly (fixes simulator/notch size transitions)
    try {
        const resizeObserver = new ResizeObserver(() => {
            if (leafletMap) {
                leafletMap.invalidateSize();
            }
        });
        const mapEl = document.getElementById('map');
        if (mapEl) {
            resizeObserver.observe(mapEl);
        }
    } catch (e) {
        console.error("ResizeObserver not supported or failed:", e);
    }

    leafletMap.on('click', (e) => {
        closeMapItemDetail();
        closeMapItemPeek();
        // Keep map category dropdown open as requested
    });

    leafletMap.on('popupopen', function(e) {
        const popupEl = e.popup.getElement();
        if (!popupEl) return;
        
        const wrapper = popupEl.querySelector('.map-popup-card-wrapper');
        if (wrapper) {
            const targetId = wrapper.getAttribute('data-target-id');
            const isEvent = wrapper.getAttribute('data-is-event') === 'true';
            const isNeed = wrapper.getAttribute('data-is-need') === 'true';
            
            const handleInteraction = (evt) => {
                evt.preventDefault();
                evt.stopPropagation();
                
                leafletMap.closePopup();
                
                if (isEvent) {
                    openMapItemDetail('evt_' + targetId);
                } else if (isNeed) {
                    openMapItemDetail('need_' + targetId);
                } else {
                    openMapItemDetail(targetId);
                }
            };
            
            wrapper.addEventListener('click', (evt) => {
                evt.stopPropagation();
            });
            wrapper.addEventListener('touchend', (evt) => {
                evt.stopPropagation();
            });
            
            const button = wrapper.querySelector('button');
            if (button) {
                button.addEventListener('click', handleInteraction);
                button.addEventListener('touchend', handleInteraction);
            }
        }
    });

    const updateLocationBtnColor = (btn, distance) => {
        if (!btn) return;
        btn.classList.remove(
            'bg-amber-500', 'border-amber-500', 'hover:bg-amber-600', 'pulse-amber-light',
            'bg-forest-green', 'border-forest-green', 'hover:bg-forest-green/90', 'pulse-green-light',
            'bg-blue-600', 'border-blue-600', 'hover:bg-blue-700', 'pulse-blue-light',
            'dark:bg-[#308A5E]', 'dark:border-[#308A5E]', 'dark:text-[#18201a]'
        );
        if (distance <= 200) {
            btn.classList.add('bg-blue-600', 'border-blue-600', 'hover:bg-blue-700', 'pulse-blue-light', 'text-white');
        } else {
            btn.classList.add('bg-amber-500', 'border-amber-500', 'hover:bg-amber-600', 'pulse-amber-light', 'text-white');
        }
    };

    leafletMap.on('moveend', () => {
        if (state.currentUser && state.currentUser.lat && state.currentUser.lng) {
            const center = leafletMap.getCenter();
            const userLoc = L.latLng(state.currentUser.lat, state.currentUser.lng);
            const distance = center.distanceTo(userLoc); // Distance in meters
            const btn = document.getElementById('snap-to-neighborhood-btn');
            if (btn) {
                const overlay = document.getElementById('map-detail-overlay');
                const isDetailActive = (overlay && overlay.classList.contains('active')) || (state.currentView === 'event_detail');
                if (isDetailActive) {
                    btn.style.display = 'none';
                } else {
                    btn.style.display = 'flex';
                }
                updateLocationBtnColor(btn, distance);
            }
            const meetupBtn = document.getElementById('meetup-snap-btn');
            if (meetupBtn) {
                updateLocationBtnColor(meetupBtn, distance);
            }
        }
    });

    // Run initial snap button evaluation
    if (state.currentUser && state.currentUser.lat && state.currentUser.lng && leafletMap) {
        const center = leafletMap.getCenter();
        const userLoc = L.latLng(state.currentUser.lat, state.currentUser.lng);
        const distance = center.distanceTo(userLoc);
        const btn = document.getElementById('snap-to-neighborhood-btn');
        if (btn) {
            const overlay = document.getElementById('map-detail-overlay');
            const isDetailActive = (overlay && overlay.classList.contains('active')) || (state.currentView === 'event_detail');
            if (isDetailActive) {
                btn.style.display = 'none';
            } else {
                btn.style.display = 'flex';
            }
            updateLocationBtnColor(btn, distance);
        }
        const meetupBtn = document.getElementById('meetup-snap-btn');
        if (meetupBtn) {
            updateLocationBtnColor(meetupBtn, distance);
        }
    }

    leafletMap.on('move', throttle(() => {
        const center = leafletMap.getCenter();
        const bounds = leafletMap.getBounds();
        const boundsKey = `${bounds.getSouthWest().lat.toFixed(3)},${bounds.getSouthWest().lng.toFixed(3)}-${bounds.getNorthEast().lat.toFixed(3)},${bounds.getNorthEast().lng.toFixed(3)}`;
        
        const cached = MapCache.getCachedPins(center.lat, center.lng);
        if (cached) {
            console.log("[MAP API] Viewport moved slightly. Serving map pins from client-side cache.");
        } else {
            console.log("[MAP API] Map moved to a new region. Making expensive API call to download pins from server...");
            MapCache.cachePins(center.lat, center.lng, boundsKey);
        }
    }, 1200));

    mapMarkers = [];
    plotMapMarkersOnly();

    state.mapInitialized = true;
    saveState();
    applyMapFiltering();
}

function disableMapGestures() {
    if (leafletMap) {
        if (leafletMap.dragging) leafletMap.dragging.disable();
        if (leafletMap.touchZoom) leafletMap.touchZoom.disable();
        if (leafletMap.doubleClickZoom) leafletMap.doubleClickZoom.disable();
        if (leafletMap.scrollWheelZoom) leafletMap.scrollWheelZoom.disable();
        if (leafletMap.boxZoom) leafletMap.boxZoom.disable();
        if (leafletMap.keyboard) leafletMap.keyboard.disable();
        if (leafletMap.tap) leafletMap.tap.disable();
    }
}

function enableMapGestures() {
    const mapDetailActive = document.getElementById('map-detail-overlay')?.classList.contains('active');
    const eventDetailActive = document.getElementById('map-event-detail-overlay')?.classList.contains('active');
    const profileModalActive = !document.getElementById('neighbor-profile-modal')?.classList.contains('hidden');
    
    if (mapDetailActive || eventDetailActive || profileModalActive) return;

    if (leafletMap) {
        if (leafletMap.dragging) leafletMap.dragging.enable();
        if (leafletMap.touchZoom) leafletMap.touchZoom.enable();
        if (leafletMap.doubleClickZoom) leafletMap.doubleClickZoom.enable();
        if (leafletMap.scrollWheelZoom) leafletMap.scrollWheelZoom.enable();
        if (leafletMap.boxZoom) leafletMap.boxZoom.enable();
        if (leafletMap.keyboard) leafletMap.keyboard.enable();
        if (leafletMap.tap) leafletMap.tap.enable();
    }
}

