function openCategoryView(categoryName) {
    playSound('click');
    const overlay = document.getElementById('category-list-overlay');
    const container = document.getElementById('category-items-container');
    document.getElementById('category-list-title').innerText = categoryName;
    container.innerHTML = "";

    let hasResults = false;

    // Also filter map in background
    if (categoryName === 'All') {
        activeCategoryFilter = null;
    } else {
        activeCategoryFilter = categoryName;
    }
    const banner = document.getElementById('active-filter-banner');
    const filterText = document.getElementById('active-filter-text');
    const filterIcon = document.getElementById('active-filter-icon');
    if (banner && activeCategoryFilter) {
        if (filterText) filterText.innerText = `Category: ${activeCategoryFilter}`;
        if (filterIcon) filterIcon.innerText = getCategoryIcon(activeCategoryFilter);
        banner.classList.remove('hidden');
    } else {
        if (banner) banner.classList.add('hidden');
    }
    applyMapFiltering();

    // Helper to match categories flexibly
    function isCategoryMatch(itemCategory, filterCategory) {
        if (!itemCategory || !filterCategory) return false;
        const itemCat = itemCategory.toLowerCase();
        const filterCat = filterCategory.toLowerCase();
        if (filterCat === 'all' || filterCat === 'show all') return true;
        if (itemCat === filterCat) return true;
        
        // Services mappings
        if (filterCat === 'services') {
            return itemCat.includes('services') || 
                   itemCat.includes('handyman') || 
                   itemCat.includes('wellness') || 
                   itemCat.includes('health') || 
                   itemCat.includes('art') || 
                   itemCat.includes('creative') ||
                   itemCat.includes('other');
        }
        
        // Skills mappings
        if (filterCat === 'skills') {
            return itemCat.includes('skills') || 
                   itemCat.includes('education') || 
                   itemCat.includes('art') || 
                   itemCat.includes('creative') || 
                   itemCat.includes('wellness') ||
                   itemCat.includes('health');
        }
        
        // Home & Gear mappings
        if (filterCat === 'home and living' || filterCat === 'home, living & gear' || filterCat === 'home & gear') {
            return itemCat.includes('home') || 
                   itemCat.includes('gear') || 
                   itemCat.includes('living') || 
                   itemCat.includes('tool') || 
                   itemCat.includes('garden') || 
                   itemCat.includes('outdoor') || 
                   itemCat.includes('clothing') || 
                   itemCat.includes('apparel') ||
                   itemCat.includes('other');
        }
        
        // Food & Drink mappings
        if (filterCat === 'food & drink' || filterCat === 'food') {
            return itemCat.includes('food') || itemCat.includes('drink') || itemCat.includes('kitchen');
        }
        
        // Books & Games mappings
        if (filterCat === 'books, games, entertainment' || filterCat === 'kids, puzzles & books' || filterCat === 'kids & puzzles' || filterCat.includes('books') || filterCat.includes('games')) {
            return itemCat.includes('book') || itemCat.includes('game') || itemCat.includes('puzzle') || itemCat.includes('entertainment');
        }

        // Kids & Maternity mappings
        if (filterCat === 'kids and maternity' || filterCat.includes('kids') || filterCat.includes('maternity')) {
            return itemCat.includes('kids') || itemCat.includes('maternity') || itemCat.includes('stroller') || itemCat.includes('child');
        }

        // Event or Meetup
        if (filterCat === 'event or meetup' || filterCat.includes('event') || filterCat.includes('meetup')) {
            return itemCat.includes('event') || itemCat.includes('meetup') || itemCat.includes('group');
        }

        // Language / Info Exchange
        if (filterCat === 'language or info exchange' || filterCat.includes('language') || filterCat.includes('info') || filterCat.includes('exchange')) {
            return itemCat.includes('language') || itemCat.includes('info') || itemCat.includes('exchange') || itemCat.includes('translate');
        }

        if (itemCat.includes(filterCat) || filterCat.includes(itemCat)) return true;
        return false;
    }

    // 1. Render neighbor postings
    Object.keys(state.neighbors).forEach(name => {
        const neighbor = state.neighbors[name];
        if (isCategoryMatch(neighbor.category, categoryName)) {
            hasResults = true;
            const card = document.createElement('div');
            card.className = "flex items-center gap-4 py-3 border-b border-outline-variant/10 dark:border-white/5 cursor-pointer active:opacity-75 transition-all";
            card.onclick = () => {
                window.categoryOverlayReferrer = categoryName;
                overlay.classList.remove('active');
                openMapItemDetail(neighbor.name);
            };
            card.innerHTML = `
                <div class="w-11 h-11 rounded-full overflow-hidden flex-shrink-0 bg-white dark:bg-[#202c22] border border-outline-variant/20 dark:border-white/10 flex items-center justify-center shadow-sm">
                    <img src="${neighbor.offerImg || PLACEHOLDER_IMAGE}" class="w-full h-full object-cover rounded-full">
                </div>
                <div class="flex-grow min-w-0 text-left">
                    <h4 class="font-bold text-[#1c2d24] dark:text-[#f1f5f9] truncate text-[13.5px]">${neighbor.offerTitle}</h4>
                    <p class="text-xs text-on-surface-variant/80 dark:text-warm-cream/60 truncate mt-0.5">${neighbor.name} · ${neighbor.category}</p>
                </div>
                <div class="flex flex-col items-end flex-shrink-0 select-none text-right">
                    <span class="text-[10px] font-bold text-black dark:text-white uppercase tracking-wider">${neighbor.location.split(' ')[0]}</span>
                    <span class="text-[9px] text-on-surface-variant/50 dark:text-warm-cream/40 mt-0.5">${neighbor.vouches || 0} ❤️</span>
                </div>
            `;
            container.appendChild(card);
        }
    });

    // 2. Render user postings
    state.userOfferings.forEach(offer => {
        if (isCategoryMatch(offer.category, categoryName)) {
            hasResults = true;
            const card = document.createElement('div');
            card.className = "flex items-center gap-4 py-3 border-b border-outline-variant/10 dark:border-white/5 cursor-pointer active:opacity-75 transition-all";
            card.onclick = () => {
                window.categoryOverlayReferrer = categoryName;
                overlay.classList.remove('active');
                openMapItemDetail(offer.id);
            };
            card.innerHTML = `
                <div class="w-11 h-11 rounded-full overflow-hidden flex-shrink-0 bg-white dark:bg-[#202c22] border border-outline-variant/20 dark:border-white/10 flex items-center justify-center shadow-sm">
                    <img src="${offer.image || PLACEHOLDER_IMAGE}" class="w-full h-full object-cover rounded-full">
                </div>
                <div class="flex-grow min-w-0 text-left">
                    <h4 class="font-bold text-[#1c2d24] dark:text-[#f1f5f9] truncate text-[13.5px]">${offer.title} <span class="text-[8px] text-[#D99036] font-bold bg-[#D99036]/10 dark:bg-[#D99036]/20 px-1.5 py-0.5 rounded ml-1 uppercase tracking-wide">You</span></h4>
                    <p class="text-xs text-on-surface-variant/80 dark:text-warm-cream/60 truncate mt-0.5">Lily K. · ${offer.category}</p>
                </div>
                <div class="flex flex-col items-end flex-shrink-0 select-none text-right">
                    <span class="text-[10px] font-bold text-black dark:text-white uppercase tracking-wider">${(offer.location || 'Oakwood').split(' ')[0]}</span>
                    <span class="text-[9px] text-on-surface-variant/50 dark:text-warm-cream/40 mt-0.5">Active</span>
                </div>
            `;
            container.appendChild(card);
        }
    });

    if (!hasResults) {
        container.innerHTML = `<div class="text-center py-10 text-xs text-on-surface-variant">No nearby postings listed in this category.</div>`;
    }

    overlay.classList.add('active');
    
    // Auto collapse tray
    const tray = document.getElementById('category-tray');
    const chevron = document.getElementById('tray-chevron');
    if (tray) {
        tray.classList.remove('expanded');
        
        const triggerIcon = document.getElementById('segment-trigger-icon');
        const blueBtn = document.getElementById('snap-to-neighborhood-btn');
        const floatingContainer = document.getElementById('village-segment-floating-buttons');
        if (triggerIcon) {
            updateTriggerIconState(triggerIcon, false);
            if (floatingContainer) floatingContainer.classList.remove('detail-active-trigger');
        }
        if (blueBtn) {
            const isMapSegment = currentVillageSegment === 'map' || currentVillageSegment === 'needs_map' || currentVillageSegment === 'gifts_map' || currentVillageSegment === 'events_map';
            if (!isMapSegment) {
                blueBtn.style.display = 'none';
            } else {
                blueBtn.style.display = 'flex';
            }
        }
    }
    if (chevron) {
        chevron.textContent = 'expand_less';
    }
}

function closeCategoryView() {
    playSound('click');
    document.getElementById('category-list-overlay').classList.remove('active');
    // Restore floating buttons after category overlay is dismissed
    const floatingContainer = document.getElementById('village-segment-floating-buttons');
    if (floatingContainer && state.currentView === 'village') {
        floatingContainer.style.display = 'flex';
    }
}

// ----------------------------------------------------
// 5. Accordion category choices for Creating Offers
// ----------------------------------------------------
function initOfferCategoriesAccordion() {
    document.querySelectorAll('.sub-chip').forEach(chip => {
        chip.classList.remove('chip-active');
    });
    
    const items = document.querySelectorAll('.accordion-item');
    items.forEach(item => {
        const header = item.querySelector('.category-header');
        const newHeader = header.cloneNode(true);
        header.parentNode.replaceChild(newHeader, header);
        
        newHeader.addEventListener('click', () => {
            playSound('click');
            const isActive = item.classList.contains('active');
            
            // Close all
            items.forEach(i => {
                i.classList.remove('active');
                i.querySelector('.category-header').setAttribute('data-active', 'false');
                i.querySelector('.category-header .material-symbols-outlined:last-child').style.transform = 'rotate(0deg)';
            });

            // Toggle selected
            if (!isActive) {
                item.classList.add('active');
                newHeader.setAttribute('data-active', 'true');
                newHeader.querySelector('.material-symbols-outlined:last-child').style.transform = 'rotate(180deg)';
            }
        });
    });

    // Subchips selection toggles
    document.querySelectorAll('.sub-chip').forEach(chip => {
        const newChip = chip.cloneNode(true);
        chip.parentNode.replaceChild(newChip, chip);
        
        newChip.addEventListener('click', (e) => {
            playSound('click');
            e.stopPropagation();
            
            const panel = newChip.closest('.accordion-content');
            panel.querySelectorAll('.sub-chip').forEach(c => c.classList.remove('chip-active'));
            newChip.classList.add('chip-active');
        });
    });

    // Current location mock detection
    const locationBtn = document.getElementById('btn-current-location');
    const locationInput = document.getElementById('neighborhood-input');
    if (locationBtn && locationInput) {
        locationBtn.onclick = (e) => {
            e.preventDefault();
            playSound('click');
            locationInput.value = "Mount Pleasant";
            locationInput.focus();
        };
    }

    // Meeting Preferences selection toggle
    document.querySelectorAll('.preference-card').forEach(card => {
        const newCard = card.cloneNode(true);
        card.parentNode.replaceChild(newCard, card);
        
        newCard.addEventListener('click', () => {
            playSound('click');
            document.querySelectorAll('.preference-card').forEach(c => {
                c.classList.remove('border-forest-green', 'bg-forest-green/5');
                c.classList.add('border-outline-variant/20', 'bg-white');
                c.removeAttribute('data-selected');
            });
            newCard.classList.add('border-forest-green', 'bg-forest-green/5');
            newCard.classList.remove('border-outline-variant/20', 'bg-white');
            newCard.setAttribute('data-selected', 'true');

            // Sync card selection to dropdown
            const locationPrefSelect = document.getElementById('offer-location-pref-select');
            const cardText = newCard.querySelector('span:last-child').innerText.trim().toUpperCase();
            if (locationPrefSelect) {
                if (cardText === 'CROSS STREET') {
                    locationPrefSelect.value = 'Coffee Shop';
                } else if (cardText === 'DOORSTEP') {
                    locationPrefSelect.value = 'Doorstep';
                } else if (cardText === 'PUBLIC SPACE') {
                    locationPrefSelect.value = 'Public Park';
                }
                locationPrefSelect.classList.remove('border-red-500', 'ring-1', 'ring-red-500');
            }
        });
    });

    // Bidirectional sync: select dropdown changes card highlights
    const locationPrefSelect = document.getElementById('offer-location-pref-select');
    if (locationPrefSelect) {
        locationPrefSelect.addEventListener('change', () => {
            locationPrefSelect.classList.remove('border-red-500', 'ring-1', 'ring-red-500');
            const val = locationPrefSelect.value;
            let targetCardText = '';
            if (val === 'Coffee Shop' || val === 'Rented Studio Space') {
                targetCardText = 'CROSS STREET';
            } else if (val === 'Doorstep') {
                targetCardText = 'DOORSTEP';
            } else if (val === 'Public Park') {
                targetCardText = 'PUBLIC SPACE';
            }
            
            document.querySelectorAll('.preference-card').forEach(c => {
                const txt = c.querySelector('span:last-child').innerText.trim().toUpperCase();
                if (txt === targetCardText) {
                    c.classList.add('border-forest-green', 'bg-forest-green/5');
                    c.classList.remove('border-outline-variant/20', 'bg-white');
                    c.setAttribute('data-selected', 'true');
                } else {
                    c.classList.remove('border-forest-green', 'bg-forest-green/5');
                    c.classList.add('border-outline-variant/20', 'bg-white');
                    c.removeAttribute('data-selected');
                }
            });
        });
    }

    // Dynamic highlight removal hooks for inputs
    const offerTitleInput = document.getElementById('offer-title');
    if (offerTitleInput) {
        const checkEl = document.getElementById('offer-title-check');
        const updateCheck = () => {
            if (checkEl) {
                if (offerTitleInput.value.trim().length > 0) {
                    checkEl.classList.remove('hidden');
                } else {
                    checkEl.classList.add('hidden');
                }
            }
        };
        offerTitleInput.addEventListener('input', function() {
            this.classList.remove('border-red-500', 'ring-1', 'ring-red-500');
            const label = document.getElementById('offer-title-label');
            if (label) {
                label.classList.remove('text-red-500');
                label.classList.add('text-forest-green');
            }
            updateCheck();
        });
        offerTitleInput.addEventListener('change', updateCheck);
        offerTitleInput.addEventListener('blur', updateCheck);
    }
    const offerDescInput = document.getElementById('offer-desc');
    if (offerDescInput) {
        offerDescInput.addEventListener('input', function() {
            if (this.value.trim().length >= 80) {
                this.classList.remove('border-red-500', 'ring-1', 'ring-red-500');
            }
        });
    }
    const offerDurationSelect = document.getElementById('offer-duration-select');
    if (offerDurationSelect) {
        offerDurationSelect.addEventListener('change', function() {
            this.classList.remove('border-red-500', 'ring-1', 'ring-red-500');
        });
    }



    // Dynamic offer radius slider updates
    const offerRadiusSlider = document.getElementById('offer-radius-slider');
    if (offerRadiusSlider) {
        offerRadiusSlider.oninput = (e) => {
            document.getElementById('offer-radius-value').innerText = `${e.target.value} km`;
        };
    }
}

function checkOfferFormValidity() {
    if (state.currentOfferMode === 'event') {
        const titleInput = document.getElementById('offer-title');
        const typeSelect = document.getElementById('offer-event-type-select');
        const datetimeInput = document.getElementById('offer-event-datetime-input');
        const locationInput = document.getElementById('offer-event-location-input');
        const submitBtn = document.getElementById('btn-list-offering');
        
        if (!titleInput || !typeSelect || !datetimeInput || !locationInput || !submitBtn) return;
        
        const title = titleInput.value.trim();
        const type = typeSelect.value;
        const datetime = datetimeInput.value;
        const location = locationInput.value.trim();
        
        submitBtn.classList.remove('hidden');
        
        if (offerFormValidated) {
            if (title) {
                titleInput.classList.remove('border-red-500', 'ring-1', 'ring-red-500');
            } else {
                titleInput.classList.add('border-red-500', 'ring-1', 'ring-red-500');
            }
            if (type) {
                typeSelect.classList.remove('border-red-500', 'ring-1', 'ring-red-500');
                const eventGrid = document.getElementById('offer-event-type-grid');
                if (eventGrid) eventGrid.classList.remove('border', 'border-red-500', 'ring-1', 'ring-red-500', 'rounded-xl');
            } else {
                typeSelect.classList.add('border-red-500', 'ring-1', 'ring-red-500');
                const eventGrid = document.getElementById('offer-event-type-grid');
                if (eventGrid) eventGrid.classList.add('border', 'border-red-500', 'ring-1', 'ring-red-500', 'rounded-xl');
            }
            if (datetime) {
                datetimeInput.classList.remove('border-red-500', 'ring-1', 'ring-red-500');
            } else {
                datetimeInput.classList.add('border-red-500', 'ring-1', 'ring-red-500');
            }
            if (location) {
                locationInput.classList.remove('border-red-500', 'ring-1', 'ring-red-500');
            } else {
                locationInput.classList.add('border-red-500', 'ring-1', 'ring-red-500');
            }
        }
        return;
    }

    const titleInput = document.getElementById('offer-title');
    const descInput = document.getElementById('offer-desc') || document.querySelector('#view-offer textarea');
    const categorySelect = document.getElementById('offer-category-select');
    const submitBtn = document.getElementById('btn-list-offering');
    
    if (!titleInput || !descInput || !categorySelect || !submitBtn) return;
    
    const title = titleInput.value.trim();
    const desc = descInput.value.trim();
    const category = categorySelect.value;
    
    // Always keep submit button visible so users can submit and see errors
    submitBtn.classList.remove('hidden');
    
    if (offerFormValidated) {
        if (title) {
            titleInput.classList.remove('border-red-500', 'ring-1', 'ring-red-500');
            const label = document.getElementById('offer-title-label');
            if (label) {
                label.classList.remove('text-red-500');
                label.classList.add('text-forest-green');
            }
        } else {
            titleInput.classList.add('border-red-500', 'ring-1', 'ring-red-500');
            const label = document.getElementById('offer-title-label');
            if (label) {
                label.classList.add('text-red-500');
                label.classList.remove('text-forest-green');
            }
        }
        if (category) {
            const grid = document.getElementById('offer-categories-grid');
            if (grid) grid.classList.remove('border', 'border-red-500', 'ring-1', 'ring-red-500', 'rounded-xl');
            const catLabel = document.getElementById('offer-category-header-label');
            if (catLabel) {
                catLabel.classList.remove('text-red-500');
                catLabel.classList.add('text-forest-green');
            }
        } else {
            const grid = document.getElementById('offer-categories-grid');
            if (grid) grid.classList.add('border', 'border-red-500', 'ring-1', 'ring-red-500', 'rounded-xl');
            const catLabel = document.getElementById('offer-category-header-label');
            if (catLabel) {
                catLabel.classList.add('text-red-500');
                catLabel.classList.remove('text-forest-green');
            }
        }
        if (desc) {
            descInput.classList.remove('border-red-500', 'ring-1', 'ring-red-500');
            const descLabel = document.getElementById('offer-desc-label');
            if (descLabel) {
                descLabel.classList.remove('text-red-500');
                descLabel.classList.add('text-forest-green');
            }
        } else {
            descInput.classList.add('border-red-500', 'ring-1', 'ring-red-500');
            const descLabel = document.getElementById('offer-desc-label');
            if (descLabel) {
                descLabel.classList.add('text-red-500');
                descLabel.classList.remove('text-forest-green');
            }
        }
    }
}
window.checkOfferFormValidity = checkOfferFormValidity;

