// Group Chat Creation functions
function openCreateGroupModal() {
    playSound('click');
    const listContainer = document.getElementById('group-friends-checkbox-list');
    if (!listContainer) return;
    
    listContainer.innerHTML = "";
    
    // Reset search query input
    const searchIn = document.getElementById('group-friends-search');
    if (searchIn) searchIn.value = "";

    // Reset selected friends count badge
    const countBadge = document.getElementById('group-friends-count-badge');
    if (countBadge) countBadge.classList.add('hidden');

    // Seed default friends list if empty or less than 10
    if (ensureFriendsList()) {
        saveState();
    }
    
    const friends = state.friends || [];
    if (friends.length === 0) {
        listContainer.innerHTML = `
            <div class="col-span-2 flex flex-col items-center justify-center p-6 bg-white dark:bg-[#101612] border border-dashed border-outline-variant/30 rounded-2xl text-center w-full">
                <span class="material-symbols-outlined text-3xl text-outline-variant mb-2">person_add</span>
                <p class="text-xs text-outline italic mb-3">No friends available to add yet.</p>
                <button type="button" class="px-3.5 py-1.5 bg-forest-green/10 border border-forest-green text-forest-green dark:text-[#308A5E] hover:bg-forest-green/20 dark:hover:bg-[#308A5E]/20 font-bold text-[10px] rounded-lg active:scale-95 transition-transform cursor-pointer border-solid" onclick="handleInviteFriend()">
                    Invite Friends
                </button>
            </div>
        `;
    } else {
        friends.forEach(friend => {
            const name = friend.name;
            const avatar = friend.avatar || DEFAULT_AVATAR;
            const item = document.createElement('label');
            item.className = "friend-select-btn flex items-center gap-2.5 p-2 bg-white dark:bg-[#101612] border border-outline-variant/30 dark:border-outline-variant/15 rounded-xl hover:border-forest-green dark:hover:border-[#308A5E] hover:bg-forest-green/5 dark:hover:bg-[#308A5E]/5 cursor-pointer transition-all select-none w-full relative text-left h-12 shadow-sm";
            item.innerHTML = `
                <input type="checkbox" name="group-members" value="${escapeHTML(name)}" class="hidden" />
                <div class="w-7 h-7 rounded-full overflow-hidden flex-shrink-0 bg-gray-200">
                    <img src="${avatar}" class="w-full h-full object-cover" />
                </div>
                <div class="flex-grow min-w-0">
                    <span class="friend-name text-[13px] font-bold text-on-surface dark:text-[#FDFBF7]/90 truncate block">${escapeHTML(name)}</span>
                </div>
                <div class="checkbox-indicator w-4 h-4 rounded-full border border-outline-variant/50 flex items-center justify-center text-white bg-transparent shrink-0">
                    <span class="material-symbols-outlined text-[10px] font-black hidden">check</span>
                </div>
            `;
            
            // Sync checked styles
            const chk = item.querySelector('input[type="checkbox"]');
            const indicator = item.querySelector('.checkbox-indicator');
            const checkIcon = indicator.querySelector('.material-symbols-outlined');
            
            chk.addEventListener('change', () => {
                if (chk.checked) {
                    item.classList.add('bg-forest-green/10', 'dark:bg-emerald-600/10', 'border-forest-green', 'dark:border-emerald-500', 'ring-1', 'ring-forest-green', 'dark:ring-emerald-500');
                    indicator.classList.remove('bg-transparent', 'border-outline-variant/50');
                    indicator.classList.add('bg-forest-green', 'dark:bg-emerald-500', 'border-forest-green', 'dark:border-emerald-500');
                    checkIcon.classList.remove('hidden');
                } else {
                    item.classList.remove('bg-forest-green/10', 'dark:bg-emerald-600/10', 'border-forest-green', 'dark:border-emerald-500', 'ring-1', 'ring-forest-green', 'dark:ring-emerald-500');
                    indicator.classList.add('bg-transparent', 'border-outline-variant/50');
                    indicator.classList.remove('bg-forest-green', 'dark:bg-emerald-500', 'border-forest-green', 'dark:border-emerald-500');
                    checkIcon.classList.add('hidden');
                }
                
                // Check count of selected friends
                const checkedCount = listContainer.querySelectorAll('input[name="group-members"]:checked').length;
                if (countBadge) {
                    if (checkedCount >= 1) {
                        countBadge.innerText = `${checkedCount} Selected`;
                        countBadge.classList.remove('hidden');
                    } else {
                        countBadge.classList.add('hidden');
                    }
                }
            });
            
            listContainer.appendChild(item);
        });
    }
    
    const nameInput = document.getElementById('group-name-input');
    if (nameInput) nameInput.value = "";

    const descInput = document.getElementById('group-desc-input');
    if (descInput) descInput.value = "";
    
    const preview = document.getElementById('group-photo-preview');
    if (preview) {
        preview.src = "";
        preview.classList.add('hidden');
    }
    const placeholder = document.getElementById('group-photo-placeholder');
    if (placeholder) {
        placeholder.classList.remove('hidden');
    }
    const removeBtn = document.getElementById('group-photo-remove');
    if (removeBtn) {
        removeBtn.classList.add('hidden');
    }
    const fileInput = document.getElementById('group-avatar-file');
    if (fileInput) fileInput.value = "";
    createGroupAvatarUrl = "";
    
    showView('create_group');
}

function closeCreateGroupModal() {
    playSound('click');
    showView('chat_hub');
}

function filterGroupFriends(query) {
    const listContainer = document.getElementById('group-friends-checkbox-list');
    if (!listContainer) return;
    
    const items = listContainer.querySelectorAll('.friend-select-btn');
    const cleanQuery = query.trim().toLowerCase();
    
    items.forEach(item => {
        const nameText = item.querySelector('.friend-name').innerText.toLowerCase();
        if (nameText.includes(cleanQuery)) {
            item.classList.remove('hidden');
        } else {
            item.classList.add('hidden');
        }
    });
}
window.filterGroupFriends = filterGroupFriends;

window.handleChatHeaderClick = function() {
    const conv = state.conversations.find(c => c.id === state.currentConversationId);
    if (!conv) return;
    if (conv.isGroup) {
        openGroupSettingsModal(conv.id);
    } else {
        openNeighborProfileModal(conv.neighborName);
    }
};

let clickTimeout = null;
window.handleMessageClick = function(event, index) {
    event.stopPropagation();
    if (clickTimeout) {
        clearTimeout(clickTimeout);
        clickTimeout = null;
        // Handle double click
        handleMessageDblClick(event, index);
        return;
    }
    
    clickTimeout = setTimeout(() => {
        clickTimeout = null;
        // Handle single click
        openMessageActionsSheet(index);
    }, 250);
};

window.handleMessageDblClick = function(event, index) {
    if (event && event.stopPropagation) event.stopPropagation();
    const conv = state.conversations.find(c => c.id === state.currentConversationId);
    if (!conv || !conv.messages || !conv.messages[index]) return;
    
    const msg = conv.messages[index];
    if (msg.text) {
        navigator.clipboard.writeText(msg.text).then(() => {
            showToast('Message copied to clipboard!');
            playSound('success');
        }).catch(err => {
            // Fallback for WebViews
            const textArea = document.createElement("textarea");
            textArea.value = msg.text;
            document.body.appendChild(textArea);
            textArea.select();
            document.execCommand("copy");
            document.body.removeChild(textArea);
            showToast('Message copied to clipboard!');
            playSound('success');
        });
    }
};

window.openMessageActionsSheet = function(index) {
    const conv = state.conversations.find(c => c.id === state.currentConversationId);
    if (!conv || !conv.messages || !conv.messages[index]) return;
    
    state.selectedMessageIndex = index;
    const msg = conv.messages[index];
    
    // Remove selection highlighting from all bubbles
    document.querySelectorAll('.chat-bubble-me, .chat-bubble-other').forEach(el => {
        el.classList.remove('ring-4', 'ring-forest-green/40', 'dark:ring-[#308A5E]/40');
    });
    
    // Find and highlight this bubble
    const targetBubble = document.getElementById(`msg-bubble-${index}`);
    if (targetBubble) {
        targetBubble.classList.add('ring-4', 'ring-forest-green/40', 'dark:ring-[#308A5E]/40');
    }
    
    // Toggle edit option depending on if it's sent by 'me'
    const editBtn = document.getElementById('message-actions-edit-btn');
    if (editBtn) {
        if (msg.sender === 'me' && !msg.isLocationSuggestion && !msg.isCheckIn) {
            editBtn.style.display = 'flex';
        } else {
            editBtn.style.display = 'none';
        }
    }
    
    const sheet = document.getElementById('message-actions-sheet');
    if (sheet) {
        playSound('click');
        sheet.classList.remove('hidden');
    }
};

window.closeMessageActionsSheet = function() {
    const sheet = document.getElementById('message-actions-sheet');
    if (sheet) {
        sheet.classList.add('hidden');
    }
    // Remove highlighting
    document.querySelectorAll('.chat-bubble-me, .chat-bubble-other').forEach(el => {
        el.classList.remove('ring-4', 'ring-forest-green/40', 'dark:ring-[#308A5E]/40');
    });
};

window.handleEditMessageOption = function() {
    closeMessageActionsSheet();
    const conv = state.conversations.find(c => c.id === state.currentConversationId);
    if (!conv || state.selectedMessageIndex === undefined) return;
    const msg = conv.messages[state.selectedMessageIndex];
    if (!msg || msg.sender !== 'me' || msg.isLocationSuggestion || msg.isCheckIn) return;
    
    const textarea = document.getElementById('edit-message-textarea');
    if (textarea) {
        textarea.value = msg.text || "";
    }
    
    const modal = document.getElementById('edit-message-modal');
    if (modal) {
        playSound('click');
        modal.classList.remove('hidden');
    }
};

window.closeEditMessageModal = function() {
    const modal = document.getElementById('edit-message-modal');
    if (modal) {
        playSound('click');
        modal.classList.add('hidden');
    }
};

window.saveEditedMessage = function() {
    const conv = state.conversations.find(c => c.id === state.currentConversationId);
    if (!conv || state.selectedMessageIndex === undefined) return;
    
    const msg = conv.messages[state.selectedMessageIndex];
    if (!msg || msg.sender !== 'me' || msg.isLocationSuggestion || msg.isCheckIn) return;
    
    const textarea = document.getElementById('edit-message-textarea');
    const newText = textarea ? textarea.value.trim() : "";
    if (!newText) {
        alert("Message cannot be empty.");
        return;
    }
    
    if (msg) {
        msg.text = newText;
        msg.edited = true;
        
        saveState();
        playSound('success');
        
        closeEditMessageModal();
        renderChatDetail(conv);
        renderConversationsList(); // to update last message preview in list
    }
};

window.handleCopyMessageOption = function() {
    closeMessageActionsSheet();
    if (state.selectedMessageIndex === undefined) return;
    handleMessageDblClick(null, state.selectedMessageIndex);
};

window.showToast = function(message) {
    let container = document.getElementById('toast-container');
    if (!container) {
        container = document.createElement('div');
        container.id = 'toast-container';
        container.className = 'fixed bottom-24 left-1/2 transform -translate-x-1/2 z-[9999] flex flex-col gap-2 pointer-events-none w-full max-w-[280px]';
        document.body.appendChild(container);
    }
    const toast = document.createElement('div');
    toast.className = 'bg-[#18201a]/90 text-warm-cream dark:bg-warm-cream/90 dark:text-[#18201a] px-4 py-2.5 rounded-full text-xs font-bold text-center shadow-lg border border-outline-variant/20 backdrop-blur-md animate-fade-in opacity-0 transition-opacity duration-300 flex items-center justify-center gap-1.5';
    toast.innerHTML = `<span class="material-symbols-outlined text-sm font-bold">check_circle</span> ${escapeHTML(message)}`;
    container.appendChild(toast);
    
    // Fade in
    setTimeout(() => {
        toast.classList.remove('opacity-0');
        toast.classList.add('opacity-100');
    }, 10);
    
    // Fade out and remove
    setTimeout(() => {
        toast.classList.remove('opacity-100');
        toast.classList.add('opacity-0');
        setTimeout(() => {
            toast.remove();
        }, 300);
    }, 2000);
};

window.openGroupSettingsModal = function(convId) {
    if (!convId) convId = state.currentConversationId;
    const conv = state.conversations.find(c => c.id === convId);
    if (!conv) return;
    
    // Populate details
    const avatarEl = document.getElementById('group-settings-avatar');
    if (avatarEl) {
        avatarEl.src = conv.avatar || "https://images.unsplash.com/photo-1582213782179-e0d53f98f2ca?q=60&w=80&auto=format&fit=crop";
    }
    const nameEl = document.getElementById('group-settings-name');
    if (nameEl) {
        nameEl.innerText = conv.neighborName;
    }
    const descEl = document.getElementById('group-settings-desc');
    if (descEl) {
        if (conv.description) {
            descEl.innerText = conv.description;
            descEl.classList.remove('hidden');
        } else {
            descEl.classList.add('hidden');
        }
    }
    
    const currentUserDisplayName = state.currentUser ? (state.currentUser.displayName || `${state.currentUser.firstName} ${state.currentUser.lastName}`) : 'Lily Kaufmann';
    const isAdmin = conv.groupAdmins && conv.groupAdmins.includes(currentUserDisplayName);
    renderGroupMembersList(conv, isAdmin, currentUserDisplayName);
    
    const modal = document.getElementById('group-settings-modal');
    if (modal) {
        playSound('click');
        modal.classList.remove('hidden');
    }
};

window.closeGroupSettingsModal = function() {
    const modal = document.getElementById('group-settings-modal');
    if (modal) {
        playSound('click');
        modal.classList.add('hidden');
    }
};

function renderGroupMembersList(conv, isCurrentUserAdmin, currentUserDisplayName) {
    const listContainer = document.getElementById('group-settings-members-list');
    if (!listContainer) return;
    listContainer.innerHTML = "";
    
    const members = [currentUserDisplayName, ...(conv.groupMembers || [])];
    
    const countEl = document.getElementById('group-settings-member-count');
    if (countEl) countEl.innerText = `${members.length} Members`;
    
    members.forEach(name => {
        const memberIsAdmin = conv.groupAdmins && conv.groupAdmins.includes(name);
        const isSelf = name === currentUserDisplayName;
        
        const neighbor = state.neighbors[name];
        const avatar = isSelf 
            ? (state.currentUser ? state.currentUser.avatar : "https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?q=60&w=80")
            : (neighbor ? neighbor.avatar : "https://images.unsplash.com/photo-1544005313-94ddf0286df2?q=60&w=80&auto=format&fit=crop");
            
        const memberRow = document.createElement('div');
        memberRow.className = "flex items-center justify-between p-2.5 bg-white dark:bg-[#101612] border border-outline-variant/15 rounded-xl shadow-sm";
        
        let actionBtnsHTML = "";
        if (isCurrentUserAdmin && !isSelf) {
            actionBtnsHTML = `
                <div class="flex items-center gap-1.5">
                    ${!memberIsAdmin ? `
                        <button class="px-2 py-1 bg-forest-green/10 border border-forest-green/20 text-forest-green hover:bg-forest-green/20 font-bold text-[9px] rounded-lg active:scale-95 transition-transform border-solid cursor-pointer" onclick="promoteToAdmin('${conv.id}', '${name.replace(/'/g, "\\'")}')">
                            Make Admin
                        </button>
                    ` : ''}
                    <button class="p-1 text-error hover:bg-error/5 rounded-lg active:scale-95 transition-all border-0 bg-transparent cursor-pointer" onclick="removeGroupMember('${conv.id}', '${name.replace(/'/g, "\\'")}')">
                        <span class="material-symbols-outlined text-sm font-bold">person_remove</span>
                    </button>
                </div>
            `;
        }
        
        memberRow.innerHTML = `
            <div class="flex items-center gap-2.5 cursor-pointer" onclick="${isSelf ? `showView('profile_settings')` : `openNeighborProfileModal('${escapeHTML(name)}')`}">
                <div class="profile-avatar-ring w-8 h-8 flex-shrink-0"><img src="${avatar}" class="w-full h-full object-cover rounded-full"></div>
                <div class="flex flex-col text-left">
                    <span class="text-xs font-bold text-on-surface dark:text-[#FDFBF7]">${escapeHTML(name)}${isSelf ? ' (You)' : ''}</span>
                    ${memberIsAdmin ? '<span class="text-[8px] font-extrabold uppercase tracking-wide text-forest-green dark:text-[#308A5E]">Admin</span>' : ''}
                </div>
            </div>
            ${actionBtnsHTML}
        `;
        
        listContainer.appendChild(memberRow);
    });
}

window.promoteToAdmin = function(convId, name) {
    const conv = state.conversations.find(c => c.id === convId);
    if (!conv) return;
    if (!conv.groupAdmins) conv.groupAdmins = [];
    if (!conv.groupAdmins.includes(name)) {
        conv.groupAdmins.push(name);
        
        const currentUserDisplayName = state.currentUser ? (state.currentUser.displayName || `${state.currentUser.firstName} ${state.currentUser.lastName}`) : 'Lily Kaufmann';
        conv.messages.push({
            sender: 'System',
            text: `${currentUserDisplayName} made ${name} an admin.`,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        });
        
        saveState();
        playSound('success');
        
        openGroupSettingsModal(convId);
        renderChatDetail(conv);
    }
};

window.removeGroupMember = function(convId, name) {
    const conv = state.conversations.find(c => c.id === convId);
    if (!conv) return;
    
    if (confirm(`Are you sure you want to remove ${name} from the group?`)) {
        conv.groupMembers = (conv.groupMembers || []).filter(m => m !== name);
        if (conv.groupAdmins) {
            conv.groupAdmins = conv.groupAdmins.filter(a => a !== name);
        }
        
        const currentUserDisplayName = state.currentUser ? (state.currentUser.displayName || `${state.currentUser.firstName} ${state.currentUser.lastName}`) : 'Lily Kaufmann';
        conv.messages.push({
            sender: 'System',
            text: `${currentUserDisplayName} removed ${name} from the group.`,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        });
        
        saveState();
        playSound('success');
        
        openGroupSettingsModal(convId);
        renderChatDetail(conv);
    }
};

window.openAddMemberSubModal = function() {
    const conv = state.conversations.find(c => c.id === state.currentConversationId);
    if (!conv) return;
    
    const friendsListContainer = document.getElementById('add-member-friends-list');
    if (!friendsListContainer) return;
    friendsListContainer.innerHTML = "";
    
    const currentUserDisplayName = state.currentUser ? (state.currentUser.displayName || `${state.currentUser.firstName} ${state.currentUser.lastName}`) : 'Lily Kaufmann';
    
    const groupMembersSet = new Set(conv.groupMembers || []);
    groupMembersSet.add(currentUserDisplayName);
    
    const eligibleFriends = (state.friends || []).filter(f => !groupMembersSet.has(f.name));
    
    if (eligibleFriends.length === 0) {
        friendsListContainer.innerHTML = `<p class="text-[10px] text-center text-outline/60 dark:text-warm-cream/50 py-4 font-semibold">No available friends to add.</p>`;
    } else {
        eligibleFriends.forEach(friend => {
            const name = friend.name;
            const avatar = friend.avatar || "https://images.unsplash.com/photo-1544005313-94ddf0286df2?q=60&w=80&auto=format&fit=crop";
            
            const friendRow = document.createElement('div');
            friendRow.className = "flex items-center justify-between p-2 bg-white dark:bg-[#101612] border border-outline-variant/10 rounded-xl";
            friendRow.innerHTML = `
                <div class="flex items-center gap-2 cursor-pointer" onclick="openNeighborProfileModal('${escapeHTML(name)}')">
                    <div class="profile-avatar-ring w-7 h-7 flex-shrink-0"><img src="${avatar}" class="w-full h-full object-cover rounded-full"></div>
                    <span class="text-xs font-bold text-on-surface dark:text-[#FDFBF7]">${escapeHTML(name)}</span>
                </div>
                <button class="px-2.5 py-1.5 bg-forest-green text-warm-cream font-bold text-[9px] rounded-lg active:scale-95 transition-transform border-0 cursor-pointer" onclick="handleAddMemberToGroup('${conv.id}', '${name.replace(/'/g, "\\'")}')">
                    Add
                </button>
            `;
            friendsListContainer.appendChild(friendRow);
        });
    }
    
    const modal = document.getElementById('add-member-modal');
    if (modal) {
        playSound('click');
        modal.classList.remove('hidden');
    }
};

window.closeAddMemberSubModal = function() {
    const modal = document.getElementById('add-member-modal');
    if (modal) {
        playSound('click');
        modal.classList.add('hidden');
    }
};

window.handleAddMemberToGroup = function(convId, name) {
    const conv = state.conversations.find(c => c.id === convId);
    if (!conv) return;
    
    if (!conv.groupMembers) conv.groupMembers = [];
    if (!conv.groupMembers.includes(name)) {
        conv.groupMembers.push(name);
        
        const currentUserDisplayName = state.currentUser ? (state.currentUser.displayName || `${state.currentUser.firstName} ${state.currentUser.lastName}`) : 'Lily Kaufmann';
        conv.messages.push({
            sender: 'System',
            text: `${currentUserDisplayName} added ${name} to the group.`,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        });
        
        saveState();
        playSound('success');
        
        closeAddMemberSubModal();
        openGroupSettingsModal(convId);
        renderChatDetail(conv);
    }
};

window.handleExitGroupClick = function() {
    const conv = state.conversations.find(c => c.id === state.currentConversationId);
    if (!conv) return;
    
    if (confirm(`Are you sure you want to exit the group "${conv.neighborName}"?`)) {
        const currentUserDisplayName = state.currentUser ? (state.currentUser.displayName || `${state.currentUser.firstName} ${state.currentUser.lastName}`) : 'Lily Kaufmann';
        
        if (conv.groupAdmins) {
            conv.groupAdmins = conv.groupAdmins.filter(a => a !== currentUserDisplayName);
        }
        
        conv.messages.push({
            sender: 'System',
            text: `${currentUserDisplayName} has left the group.`,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        });
        
        state.conversations = state.conversations.filter(c => c.id !== conv.id);
        
        saveState();
        playSound('success');
        
        closeGroupSettingsModal();
        showView('chat_hub');
        renderConversationsList();
    }
};

function handleCreateGroup() {
    const nameInput = document.getElementById('group-name-input');
    const groupName = nameInput ? nameInput.value.trim() : "";
    
    if (!groupName) {
        alert("Please enter a group name.");
        return;
    }
    
    const descInput = document.getElementById('group-desc-input');
    const groupDesc = descInput ? descInput.value.trim() : "";
    
    if (!groupDesc) {
        alert("Please enter a group description.");
        return;
    }
    
    const checkboxes = document.querySelectorAll('input[name="group-members"]:checked');
    const selectedMembers = Array.from(checkboxes).map(cb => cb.value);
    
    if (selectedMembers.length < 1) {
        alert("Please select at least one neighbor to add to the group.");
        return;
    }
    
    const groupConvId = 'group_' + Date.now();
    const groupAvatar = createGroupAvatarUrl || "https://images.unsplash.com/photo-1582213782179-e0d53f98f2ca?q=60&w=80&auto=format&fit=crop";
    
    const currentUserDisplayName = state.currentUser ? (state.currentUser.displayName || `${state.currentUser.firstName} ${state.currentUser.lastName}`) : 'Lily Kaufmann';
    
    const newGroupConv = {
        id: groupConvId,
        neighborName: groupName,
        isGroup: true,
        unread: false,
        timeLeft: '',
        avatar: groupAvatar,
        description: groupDesc,
        groupMembers: selectedMembers,
        groupAdmins: [currentUserDisplayName],
        messages: [
            {
                sender: 'System',
                text: `Group chat "${groupName}" created with ${selectedMembers.join(', ')}.`,
                time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
            }
        ],
        negotiation: {
            status: 'none'
        }
    };
    
    state.conversations.unshift(newGroupConv);
    saveState();
    playSound('success');
    
    showView('chat_hub');
    renderConversationsList();
    startChatConversation(groupConvId);
}

