function handleSendProposal() {
    if (state.chatLockdownMode) {
        alert("The community chat network is temporarily muted under administrative lockdown.");
        return;
    }
    const conv = state.conversations.find(c => c.id === state.currentConversationId);
    if (!conv) return;

    let selected = "";
    const customText = document.getElementById('custom-offer-input')?.value.trim() || "";
    if (customText) {
        selected = customText;
    } else {
        const checked = document.querySelector('input[name="proposal_offer"]:checked');
        if (!checked) {
            alert("Please pick an offering or type custom trade details.");
            return;
        }
        selected = checked.value;
    }

    // Safety checks
    if (checkSafetyPolicy(selected)) {
        showSafetyContentViolation();
        return;
    }

    // Cashless checks
    if (checkCashlessPolicy(selected)) {
        showSafetyMoneyWarning();
        return;
    }
    // Address check
    if (checkExactAddress(selected)) {
        showSafetyAddressWarning();
        return;
    }

    submitSendProposal(conv, selected);
}

function submitSendProposal(conv, selected) {
    closeBarterProposalModal();

    conv.negotiation.status = 'pending';
    conv.negotiation.offeredItem = selected;
    conv.negotiation.isFromOfferSwapModal = false;
    saveState();

    const feed = document.getElementById('chat-message-feed');
    const systemCard = document.createElement('div');
    systemCard.className = 'flex justify-center my-1 w-full';
    systemCard.innerHTML = `<span class="px-4 py-2 rounded-xl bg-forest-green/5 text-forest-green font-semibold text-xs border border-forest-green/10">Offer sent · Awaiting ${conv.neighborName}'s reply</span>`;
    if (feed) {
        feed.appendChild(systemCard);
        feed.scrollTop = feed.scrollHeight;
    }

    renderNegotiationControl(conv);
    triggerMockAccept(conv);
    playSound('message');
}

function triggerMockAccept(conv) {
    if (conv.mockAcceptTimer) {
        clearTimeout(conv.mockAcceptTimer);
    }
    conv.mockAcceptTimer = setTimeout(() => {
        window.simulatePartnerAccept(conv.id);
    }, 4000);
}

window.simulatePartnerAccept = function(convId) {
    const active = state.conversations.find(c => c.id === convId);
    if (active && active.negotiation.status === 'pending') {
        active.negotiation.status = 'accepted';
        
        const isKarma = active.negotiation.isKarmaSwap || 
                        active.negotiation.offeredItem === "Karma Points" || 
                        active.negotiation.offeredItem === "Karma" ||
                        (active.negotiation.offeredItem && active.negotiation.offeredItem.toLowerCase().includes("karma"));
        
        const acceptMsg = isKarma 
            ? `I'd love to help you out! Earning Karma points is a great way to improve my standing here. Let's arrange a time to meet and location.`
            : `Sounds great. Let's arrange a time to meet and location.`;
            
        active.messages.push({
            sender: active.neighborName,
            text: acceptMsg,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        });
        active.messages.push({
            sender: 'App admin',
            text: 'Click this message to set up a meeting location',
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
            isMeetupPrompt: true,
            isAdminMeetupClick: true
        });
        
        if (isKarma) {
            active.messages.push({
                sender: 'System',
                text: `Reward: ${active.neighborName} will gain +50 Karma points for good standing in the community upon completion.`,
                time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
            });
        }
        
        if (active.mockAcceptTimer) {
            clearTimeout(active.mockAcceptTimer);
            delete active.mockAcceptTimer;
        }
        
        saveState();

        if (typeof queueTradeCheckIn === 'function') {
            queueTradeCheckIn(active.id);
        }

        if (state.currentConversationId === active.id) {
            playSound('message');
            renderChatDetail(active);
            triggerSuccessConfetti();
        }
    }
};

function triggerSuccessConfetti() {
    playSound('success');
    if (typeof confetti === 'function') {
        confetti({
            particleCount: 160,
            spread: 90,
            origin: { y: 0.65 },
            colors: ['#308A5E', '#ffffff', '#86ab83', '#D99036']
        });
    }
}

function handleAcceptProposal() {
    const conv = state.conversations.find(c => c.id === state.currentConversationId);
    if (!conv) return;

    conv.isRequest = false; // Move to active!
    conv.negotiation.status = 'accepted';
    conv.messages.push({
        sender: 'me',
        text: 'Proposal accepted! Sounds great.',
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    });
    conv.messages.push({
        sender: 'App admin',
        text: 'Click this message to set up a meeting location',
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        isMeetupPrompt: true,
        isAdminMeetupClick: true
    });
    saveState();
    
    if (typeof queueTradeCheckIn === 'function') {
        queueTradeCheckIn(conv.id);
    }
    
    if (typeof showToast === 'function') {
        showToast("Swap request accepted!");
    }
    
    renderChatDetail(conv);
    triggerSuccessConfetti();
}

function handleCompleteTrade() {
    const conv = state.conversations.find(c => c.id === state.currentConversationId);
    if (!conv) return;
    
    conv.negotiation.status = 'completed';
    
    // Record in swapHistory
    if (!state.swapHistory) state.swapHistory = [];
    state.swapHistory.unshift({
        neighborName: conv.neighborName,
        offeredItem: conv.negotiation.offeredItem || 'Tutoring',
        requestedItem: conv.negotiation.requestedItem || 'Swap',
        date: 'Just now'
    });
    
    // Increment neighbor vouches if it is a Karma swap
    if (conv.negotiation.isKarmaSwap) {
        const neighbor = state.neighbors ? state.neighbors[conv.neighborName] : null;
        if (neighbor) {
            neighbor.vouches = (neighbor.vouches || 0) + 1;
        }
    }
    
    // Delete the chat (Disabled per request)
    // state.conversations = state.conversations.filter(c => c.id !== conv.id);
    
    state.stats.tradesMade += 1;
    const pts = conv.negotiation.isKarmaSwap ? 10 : 5;
    addKarmaXP(pts);
    saveState();
    
    showTradeCelebrationOverlay(conv);
    showView('chat_hub');
    renderConversationsList();
    triggerSuccessConfetti();

    // Trigger push notification after 5s
    setTimeout(() => {
        triggerPushNotification(
            "Review Reminder",
            `Your swap with ${conv.neighborName} is complete. Leave a review to share your experience!`,
            "rate_review",
            "chat_hub"
        );
    }, 5000);
}

function showTradeCelebrationOverlay(conv) {
    const overlay = document.getElementById('trade-success-overlay');
    document.getElementById('celebration-title').innerText = `Trade with ${conv.neighborName} Complete!`;
    if (conv.negotiation.isKarmaSwap) {
        document.getElementById('celebration-detail').innerHTML = `You requested <span class="font-bold text-[#D99036]">${conv.negotiation.requestedItem || 'requested item'}</span> for free.<br>In exchange, ${conv.neighborName} earned <span class="font-bold text-[#D99036]">Karma Points</span>!`;
    } else {
        document.getElementById('celebration-detail').innerHTML = `You bartered <span class="font-bold text-[#D99036]">${conv.negotiation.offeredItem || 'offered item'}</span><br>for ${conv.neighborName}'s <span class="font-bold text-[#D99036]">${conv.negotiation.requestedItem || 'requested item'}</span>.`;
    }
    const karmaPtsEl = document.getElementById('celebration-karma-pts');
    if (karmaPtsEl) {
        karmaPtsEl.innerText = conv.negotiation.isKarmaSwap ? "+10" : "+5";
    }
    
    overlay.classList.remove('hidden');
    triggerSuccessConfetti();
}

