function handleConfirmDecline() {
    const conv = state.conversations.find(c => c.id === state.currentConversationId);
    if (!conv) return;

    const selectedReason = document.querySelector('input[name="decline_reason"]:checked')?.value || "Friendly decline";

    closeDeclineFeedbackModal();

    conv.isRequest = false; // Move out of swap requests!
    conv.isOld = true; // Move to archived!
    conv.negotiation.status = 'declined';
    conv.negotiation.declineReason = selectedReason;
    
    if (!state.declineLogs) state.declineLogs = [];
    state.declineLogs.push({
        id: 'decline-' + Date.now(),
        neighborName: conv.neighborName,
        reason: selectedReason,
        time: new Date().toLocaleString()
    });

    conv.messages.push({
        sender: 'me',
        text: `I have declined this trade request. Reason: ${selectedReason}.`,
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    });
    saveState();

    if (typeof showToast === 'function') {
        showToast("Swap request declined.");
    }

    // Return to Requests tab in chat hub
    switchChatSegment('requests');
    showView('chat_hub');
}

let lastMessageSentTime = 0;

function handleSendTextMessage() {
    if (state.chatLockdownMode) {
        alert("The community chat network is temporarily muted under administrative lockdown.");
        return;
    }
    const now = Date.now();
    if (now - lastMessageSentTime < 500) {
        alert("Please do not send messages too quickly.");
        return;
    }
    lastMessageSentTime = now;

    const input = document.getElementById('chat-text-input');
    const text = input.value.trim();
    if (!text) return;

    // Safety checks first
    if (checkSafetyPolicy(text)) {
        showSafetyContentViolation();
        return;
    }

    // Cashless check
    if (checkCashlessPolicy(text)) {
        showSafetyMoneyWarning();
        return;
    }

    // Address check
    if (checkExactAddress(text)) {
        showSafetyAddressWarning();
        return;
    }

    submitSendTextMessage(text);
    input.value = "";
}

function submitSendTextMessage(text) {
    const conv = state.conversations.find(c => c.id === state.currentConversationId);
    if (!conv) return;

    const time = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    const msgObj = { sender: 'me', text, time, status: 'delivered' };
    conv.messages.push(msgObj);
    saveState();

    renderChatDetail(conv);
    playSound('message');

    // Scan for contact details
    if (typeof scanMessageForPrivacy === 'function') {
        scanMessageForPrivacy(text);
    }

    // Simulate read receipt delay after 1.5s
    if (!conv.isGroup) {
        setTimeout(() => {
            msgObj.status = 'read';
            saveState();
            if (state.currentConversationId === conv.id) {
                renderChatDetail(conv);
            }
        }, 1500);
    }

    // Show typing indicator in message feed
    const feed = document.getElementById('chat-message-feed');
    if (!feed) return;

    const typingBubble = document.createElement('div');
    typingBubble.className = 'flex items-end gap-2 max-w-[85%] self-start typing-indicator-bubble my-1';
    typingBubble.innerHTML = `
        <div class="bg-[#f3f4f6] text-gray-400 p-3 rounded-2xl shadow-sm border border-gray-200 flex items-center gap-1.5">
            <span class="text-[11px] text-gray-400">${conv.isGroup ? 'Someone' : conv.neighborName} is typing</span>
            <div class="typing-dots flex gap-0.5 items-center">
                <span class="typing-dot"></span>
                <span class="typing-dot"></span>
                <span class="typing-dot"></span>
            </div>
        </div>
    `;
    feed.appendChild(typingBubble);
    feed.scrollTop = feed.scrollHeight;

    // Simulate neighbor response with delay
    setTimeout(() => {
        const current = state.conversations.find(c => c.id === conv.id);
        if (current) {
            // Remove typing bubble
            const bubble = feed.querySelector('.typing-indicator-bubble');
            if (bubble) bubble.remove();

            playSound('message');
            
            // Generate contextual response based on message content
            let replyText = `Got it! Let's arrange a trade offer when you're ready.`;
            let replier = current.isGroup ? (current.groupMembers[Math.floor(Math.random() * current.groupMembers.length)] || 'Neighbor') : current.neighborName;

            if (text.toLowerCase().includes('produce') || text.toLowerCase().includes('veggie')) {
                replyText = `Absolutely, my crops are very fresh right now! What would you like to swap?`;
            } else if (text.toLowerCase().includes('bread') || text.toLowerCase().includes('sourdough')) {
                replyText = `Mmm, fresh sourdough sounds wonderful. I'd love to make a swap.`;
            } else if (text.toLowerCase().includes('guitar') || text.toLowerCase().includes('music') || text.toLowerCase().includes('lesson')) {
                replyText = `Yes! I've been wanting to learn guitar chords. That's a perfect barter.`;
            } else if (text.toLowerCase().includes('meet') || text.toLowerCase().includes('where') || text.toLowerCase().includes('park')) {
                replyText = `Let's meet at the park entrance on Main & 14th. Safety first!`;
            } else if (current.isGroup) {
                const groupReplies = [
                    "Sounds good to me!",
                    "I might have something to swap for that.",
                    "Count me in!",
                    "Let's figure out a day to meet up.",
                    "Thanks for starting this group!",
                    "I can bring some sourdough!"
                ];
                replyText = groupReplies[Math.floor(Math.random() * groupReplies.length)];
            }
            
            current.messages.push({
                sender: replier,
                text: replyText,
                time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
            });
            if (state.currentConversationId === current.id) {
                current.unread = false;
                current.unreadCount = 0;
            } else {
                current.unread = true;
                current.unreadCount = (current.unreadCount || 0) + 1;
            }
            saveState();
            if (typeof scanMessageForPrivacy === 'function') {
                scanMessageForPrivacy(replyText);
            }
            if (state.currentConversationId === current.id) {
                renderChatDetail(current);
            }
            updateChatNotificationBadge();
        }
    }, 4000);
}

function openSocialAppOrWeb(platform, value) {
    if (!value) {
        if (platform === 'instagram') window.open('https://instagram.com', '_blank');
        if (platform === 'facebook') window.open('https://facebook.com', '_blank');
        if (platform === 'tiktok') window.open('https://tiktok.com', '_blank');
        return;
    }

    // Clean value: if it's a full URL, extract the handle
    let handle = value.trim();
    if (handle.startsWith('http://') || handle.startsWith('https://')) {
        try {
            const url = new URL(handle);
            const path = url.pathname.replace(/^\/+|\/+$/g, ''); // strip leading/trailing slashes
            if (platform === 'tiktok') {
                handle = path.replace(/^@/, '');
            } else {
                handle = path;
            }
        } catch(e) {
            handle = value;
        }
    }

    // If it's a placeholder or not set up
    const isPlaceholder = !handle || 
                          handle.toLowerCase() === 'instagram' || 
                          handle.toLowerCase() === 'facebook' || 
                          handle.toLowerCase() === 'tiktok' ||
                          handle.toLowerCase() === 'neighbor';

    if (isPlaceholder) {
        if (platform === 'instagram') window.open('https://instagram.com', '_blank');
        if (platform === 'facebook') window.open('https://facebook.com', '_blank');
        if (platform === 'tiktok') window.open('https://tiktok.com', '_blank');
        return;
    }

    let webUrl = '';

    if (platform === 'instagram') {
        webUrl = `https://instagram.com/${handle}`;
    } else if (platform === 'facebook') {
        webUrl = `https://facebook.com/${handle}`;
    } else if (platform === 'tiktok') {
        webUrl = `https://tiktok.com/@${handle}`;
    }

    if (webUrl) {
        window.open(webUrl, '_blank');
    }
}
window.openSocialAppOrWeb = openSocialAppOrWeb;

