function setupOfferCategoryChangeListener() {
    const select = document.getElementById('offer-category-select');
    if (!select) return;
    select.addEventListener('change', () => {
        const category = select.value;
        if (category) {
            openSubcategoryModal(category);
        }
    });
}

function setupEventValidationListeners() {
    ['event-title-input', 'event-location-input'].forEach(id => {
        const el = document.getElementById(id);
        if (el) {
            el.addEventListener('input', () => {
                if (el.value.trim()) {
                    el.classList.remove('border-red-500', 'ring-1', 'ring-red-500');
                }
            });
        }
    });

    ['event-type-select', 'event-datetime-input'].forEach(id => {
        const el = document.getElementById(id);
        if (el) {
            el.addEventListener('change', () => {
                if (el.value) {
                    el.classList.remove('border-red-500', 'ring-1', 'ring-red-500');
                }
            });
        }
    });
}

let selectedPresetValue = '';

function selectOfferPresetItem(val, btnElement) {
    if (typeof playSound === 'function') playSound('click');
    selectedPresetValue = val;
    
    const container = document.getElementById('offer-preset-buttons-container');
    if (container) {
        container.querySelectorAll('.preset-opt-btn').forEach(btn => {
            btn.classList.remove('bg-forest-green', 'text-warm-cream', 'border-forest-green');
            btn.classList.add('bg-white', 'dark:bg-[#18201a]', 'text-black', 'dark:text-black', 'border-outline-variant/30', 'dark:border-outline-variant/15');
        });
    }
    if (btnElement) {
        btnElement.classList.add('bg-forest-green', 'text-warm-cream', 'border-forest-green');
        btnElement.classList.remove('bg-white', 'dark:bg-[#18201a]', 'text-black', 'dark:text-black', 'border-outline-variant/30', 'dark:border-outline-variant/15');
    }
}

function openOfferPresetModal(category) {
    const modal = document.getElementById('offer-preset-modal');
    const buttonsContainer = document.getElementById('offer-preset-buttons-container');
    if (!modal || !buttonsContainer) return;

    buttonsContainer.innerHTML = "";
    selectedPresetValue = ""; // reset selection
    
    // Get presets for this category
    const presets = OFFER_PRESET_ITEMS[category] || [];
    
    // Create preset buttons
    presets.forEach(item => {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'preset-opt-btn p-3 bg-white dark:bg-[#18201a] border border-outline-variant/30 dark:border-outline-variant/15 rounded-xl text-black font-semibold text-xs flex items-center justify-center text-center hover:bg-forest-green/5 active:scale-95 transition-all w-full select-none shadow-sm h-auto';
        btn.innerText = item;
        btn.onclick = () => selectOfferPresetItem(item, btn);
        buttonsContainer.appendChild(btn);
    });

    // Add Other option button at the end
    const otherBtn = document.createElement('button');
    otherBtn.type = 'button';
    otherBtn.className = 'preset-opt-btn p-3 bg-white dark:bg-[#18201a] border border-outline-variant/30 dark:border-outline-variant/15 rounded-xl text-black font-semibold text-xs flex items-center justify-center text-center hover:bg-forest-green/5 active:scale-95 transition-all w-full select-none shadow-sm h-auto';
    otherBtn.innerText = "Other (Custom)";
    otherBtn.onclick = () => selectOfferPresetItem("Other", otherBtn);
    buttonsContainer.appendChild(otherBtn);

    modal.classList.remove('hidden');
    if (typeof playSound === 'function') playSound('click');
}

function closeOfferPresetModal() {
    const modal = document.getElementById('offer-preset-modal');
    if (modal) {
        modal.classList.add('hidden');
        if (typeof playSound === 'function') playSound('click');
    }
}

function submitOfferPresetSelection() {
    const titleInput = document.getElementById('offer-title');
    if (titleInput) {
        if (!selectedPresetValue) {
            alert('Please select a specific item preset.');
            return;
        }
        if (selectedPresetValue !== "Other") {
            titleInput.value = selectedPresetValue;
        } else {
            titleInput.value = "";
            titleInput.focus();
        }
    }
    closeOfferPresetModal();
}

