window.setMood = function(themeName) {
    const theme = MOOD_THEMES[themeName];
    if (!theme) return;
    
    playSound('click');
    safeLocalStorage.setItem('barterland_mood', themeName);
    state.currentMood = themeName;
    
    // Apply CSS Variables
    const root = document.documentElement;
    root.style.setProperty('--forest-green', theme.forestGreen);
    root.style.setProperty('--forest-green-val', theme.forestGreen);
    root.style.setProperty('--warm-cream', theme.warmCream);
    root.style.setProperty('--warm-cream-val', theme.warmCream);
    root.style.setProperty('--outline', theme.outline);
    
    closeMoodMenus();
};

window.toggleGlobalMoodMenu = function(event) {
    if (event) event.stopPropagation();
    playSound('click');
    const dropdown = document.getElementById('global-mood-dropdown');
    if (dropdown) {
        dropdown.classList.toggle('hidden');
    }
};

