function selectChatFilter(filterMode, muteSound = false, skipRender = false) {
    if (!muteSound) playSound('click');
    state.chatFilter = filterMode;
    saveState();
    
    // Update active UI circular chips in the horizontal bar
    const chips = document.querySelectorAll('.chat-filter-chip');
    chips.forEach(chip => {
        const circle = chip.querySelector('.filter-circle');
        const text = chip.querySelector('.filter-text');
        if (chip.getAttribute('data-filter') === filterMode) {
            chip.classList.add('active');
            if (circle) {
                circle.className = "filter-circle w-12 h-12 rounded-full flex items-center justify-center transition-all bg-forest-green text-warm-cream shadow-md outline-none";
            }
            if (text) {
                text.className = "filter-text text-[10px] font-bold text-forest-green dark:text-warm-cream mt-1";
            }
        } else {
            chip.classList.remove('active');
            if (circle) {
                circle.className = "filter-circle w-12 h-12 rounded-full flex items-center justify-center transition-all bg-white border border-outline-variant/35 text-forest-green dark:bg-[#202a22] dark:text-[#308A5E] hover:bg-forest-green/5 active:scale-95 shadow-sm outline-none";
            }
            if (text) {
                text.className = "filter-text text-[10px] font-bold text-on-surface-variant mt-1";
            }
        }
    });

    // Update active banner
    const banner = document.getElementById('active-chat-filter-banner');
    const textLabel = document.getElementById('active-chat-filter-text');
    if (banner && textLabel) {
        if (filterMode === 'all') {
            banner.classList.add('hidden');
        } else {
            let modeText = 'All';
            if (filterMode === 'unread') modeText = 'Unread Only';
            if (filterMode === 'pending') modeText = 'Pending Swaps';
            if (filterMode === 'completed') modeText = 'Completed Swaps';
            
            textLabel.innerText = 'Filter: ' + modeText;
            banner.classList.remove('hidden');
        }
    }

    if (!skipRender) {
        renderConversationsList();
    }
}

function clearChatFilter() {
    selectChatFilter('all');
}

