function handleShareCurrentLocation() {
    playSound('click');
    const conv = state.conversations.find(c => c.id === state.currentConversationId);
    if (!conv) return;

    if (navigator.geolocation) {
        navigator.geolocation.getCurrentPosition(
            (position) => {
                const lat = position.coords.latitude;
                const lng = position.coords.longitude;
                submitShareLocation(lat, lng, "Exact GPS Location", "Shared real-time coordinate");
            },
            (error) => {
                console.warn("Geolocation failed or denied, using fallback user location.", error);
                const lat = (state.currentUser && state.currentUser.lat) ? state.currentUser.lat : 49.2608;
                const lng = (state.currentUser && state.currentUser.lng) ? state.currentUser.lng : -123.1368;
                const neighborhood = (state.currentUser && state.currentUser.neighborhood) ? state.currentUser.neighborhood : "Fairview";
                submitShareLocation(lat, lng, `${neighborhood} area (approximate)`, "Approximate location shared (GPS permission denied)");
            },
            { enableHighAccuracy: true, timeout: 5000, maximumAge: 0 }
        );
    } else {
        const lat = (state.currentUser && state.currentUser.lat) ? state.currentUser.lat : 49.2608;
        const lng = (state.currentUser && state.currentUser.lng) ? state.currentUser.lng : -123.1368;
        const neighborhood = (state.currentUser && state.currentUser.neighborhood) ? state.currentUser.neighborhood : "Fairview";
        submitShareLocation(lat, lng, `${neighborhood} area (approximate)`, "Approximate location shared (browser Geolocation unsupported)");
    }
}

function submitShareLocation(lat, lng, name, address) {
    const conv = state.conversations.find(c => c.id === state.currentConversationId);
    if (!conv) return;

    const time = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    const msgObj = {
        sender: 'me',
        time: time,
        status: 'delivered',
        isLocationSuggestion: true,
        isLiveLocation: true,
        locationData: {
            lat: lat,
            lng: lng,
            name: name,
            address: address
        }
    };
    conv.messages.push(msgObj);
    saveState();

    renderChatDetail(conv);
    playSound('message');

    // Simulate read receipt delay after 1.5s
    if (!conv.isGroup) {
        setTimeout(() => {
            msgObj.status = 'read';
            saveState();
            if (state.currentConversationId === conv.id) {
                renderChatDetail(conv);
            }
        }, 1500);
    }

    // Simulate response with typing indicator
    const feed = document.getElementById('chat-message-feed');
    if (feed) {
        const typingBubble = document.createElement('div');
        typingBubble.className = 'flex items-end gap-2 max-w-[85%] self-start typing-indicator-bubble my-1';
        typingBubble.innerHTML = `
            <div class="bg-[#f3f4f6] text-gray-400 p-3 rounded-2xl shadow-sm border border-gray-200 flex items-center gap-1.5">
                <span class="text-[11px] text-gray-400">${conv.isGroup ? 'Someone' : conv.neighborName} is typing</span>
                <div class="typing-dots flex gap-0.5 items-center">
                    <span class="typing-dot"></span>
                    <span class="typing-dot"></span>
                    <span class="typing-dot"></span>
                </div>
            </div>
        `;
        feed.appendChild(typingBubble);
        feed.scrollTop = feed.scrollHeight;
    }

    setTimeout(() => {
        const current = state.conversations.find(c => c.id === conv.id);
        if (current) {
            const feed = document.getElementById('chat-message-feed');
            const bubble = feed ? feed.querySelector('.typing-indicator-bubble') : null;
            if (bubble) bubble.remove();

            playSound('message');
            
            let replyText = `Thanks for sharing your location! On my way.`;
            let replier = current.isGroup ? (current.groupMembers[Math.floor(Math.random() * current.groupMembers.length)] || 'Neighbor') : current.neighborName;
            
            current.messages.push({
                sender: replier,
                text: replyText,
                time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
            });
            saveState();
            if (state.currentConversationId === current.id) {
                renderChatDetail(current);
            }
        }
    }, 4000);
}

