// Map Category Filtering Utility & Interface Functions
function isCategoryMatchHelper(itemCategory, filterCategory) {
    if (!itemCategory || !filterCategory) return false;
    const itemCat = itemCategory.toLowerCase();
    const filterCat = filterCategory.toLowerCase();
    if (filterCat === 'all') return true;
    if (itemCat === filterCat) return true;
    
    // Flexible substring/mapping matching
    if ((filterCat === 'food & drink' || filterCat === 'food') && (itemCat.includes('food') || itemCat.includes('drink') || itemCat.includes('produce') || itemCat.includes('garden') || itemCat.includes('bake') || itemCat.includes('cook') || itemCat.includes('sourdough') || itemCat.includes('jam') || itemCat.includes('preserve'))) return true;
    if ((filterCat === 'services' || filterCat === 'handyman & services') && (itemCat.includes('service') || itemCat.includes('handyman') || itemCat.includes('repair') || itemCat.includes('maintenance') || itemCat.includes('tech') || itemCat.includes('tuning') || itemCat.includes('wiring'))) return true;
    if (filterCat === 'skills' && (itemCat.includes('skill') || itemCat.includes('education') || itemCat.includes('workshop'))) return true;
    if ((filterCat === 'home and living' || filterCat === 'home, living & gear') && (itemCat.includes('home') || itemCat.includes('gear') || itemCat.includes('living'))) return true;
    if (filterCat === 'garden & outdoors' && (itemCat.includes('garden') || itemCat.includes('outdoor') || itemCat.includes('yard'))) return true;
    if (filterCat === 'creative & art' && (itemCat.includes('creative') || itemCat.includes('art') || itemCat.includes('brush') || itemCat.includes('workshop') || itemCat.includes('sketch') || itemCat.includes('potter') || itemCat.includes('macrame') || itemCat.includes('clay'))) return true;
    if ((filterCat === 'health' || filterCat === 'health & wellness') && (itemCat.includes('health') || itemCat.includes('wellness') || itemCat.includes('spa') || itemCat.includes('self'))) return true;
    if (filterCat === 'clothing & apparel' && (itemCat.includes('clothing') || itemCat.includes('apparel') || itemCat.includes('checkroom'))) return true;
    if ((filterCat === 'books, games, entertainment' || filterCat === 'kids, puzzles & books') && (itemCat.includes('book') || itemCat.includes('game') || itemCat.includes('puzzle') || itemCat.includes('entertainment'))) return true;
    if (filterCat === 'kids and maternity' && (itemCat.includes('kids') || itemCat.includes('maternity') || itemCat.includes('stroller') || itemCat.includes('child'))) return true;
    if (filterCat === 'event or meetup' && (itemCat.includes('event') || itemCat.includes('meetup') || itemCat.includes('group'))) return true;
    if (filterCat === 'language or info exchange' && (itemCat.includes('language') || itemCat.includes('info') || itemCat.includes('exchange') || itemCat.includes('translate'))) return true;
    
    return itemCat.includes(filterCat) || filterCat.includes(itemCat);
}

function filterMapByCategory(categoryName) {
    playSound('click');
    
    if (!state.activeMapFilters) {
        state.activeMapFilters = [];
    }
    
    if (categoryName === 'All' || activeCategoryFilter === categoryName) {
        activeCategoryFilter = null;
        state.activeMapFilters = [];
    } else {
        activeCategoryFilter = categoryName;
        state.activeMapFilters = [categoryName];
    }
    
    // Show/hide banner
    const banner = document.getElementById('active-filter-banner');
    const filterText = document.getElementById('active-filter-text');
    const filterIcon = document.getElementById('active-filter-icon');
    
    if (banner && activeCategoryFilter) {
        if (filterText) filterText.innerText = `Category: ${activeCategoryFilter}`;
        if (filterIcon) filterIcon.innerText = getCategoryIcon(activeCategoryFilter);
        banner.classList.remove('hidden');
    } else {
        if (banner) banner.classList.add('hidden');
    }
    
    // Switch back to map view as the active segment
    if (categoryName === 'Needs List') {
        switchVillageSegment('needs_map');
    } else {
        switchVillageSegment('map');
    }
    
    // Auto collapse the drawer
    const tray = document.getElementById('category-tray');
    if (tray) {
        tray.classList.remove('expanded');
        const chevron = document.getElementById('tray-chevron');
        if (chevron) chevron.textContent = 'expand_less';
    }
    
    // Update map marker pins visibility and pulsing
    applyMapFiltering();
    
    // Highlight category tray cards
    updateCategoryTrayUI();
}

function clearCategoryFilter() {
    playSound('click');
    activeCategoryFilter = null;
    if (state) {
        state.activeMapFilters = [];
    }
    
    // Hide filter banner
    const banner = document.getElementById('active-filter-banner');
    if (banner) {
        banner.classList.add('hidden');
    }
    
    // Switch to Map view
    switchVillageSegment('map');
    
    // Update map marker pins and lists
    applyMapFiltering();
    updateCategoryTrayUI();
}
window.clearCategoryFilter = clearCategoryFilter;

function clearVillageSearch() {
    playSound('click');
    syncVillageSearch("");
}
window.clearVillageSearch = clearVillageSearch;

function applyMapFiltering() {
    if (!leafletMap) return;
    if (state.meetupMapMode) return;

    const maxRadius = (state.stats && state.stats.radius !== undefined) ? state.stats.radius : 5;
    let userLat = 49.2827;
    let userLng = -123.1207;
    if (state.currentUser && state.currentUser.lat && state.currentUser.lng) {
        userLat = state.currentUser.lat;
        userLng = state.currentUser.lng;
    }

    // Sync banner visibility and text to state.activeMapFilters or activeCategoryFilter
    const banner = document.getElementById('active-filter-banner');
    const filterText = document.getElementById('active-filter-text');
    const filterIcon = document.getElementById('active-filter-icon');
    
    if (banner) {
        if (state && state.activeMapFilters && state.activeMapFilters.length > 0) {
            if (filterText) {
                if (state.activeMapFilters.length === 1) {
                    filterText.innerText = `Category: ${state.activeMapFilters[0]}`;
                } else {
                    filterText.innerText = `Filters: ${state.activeMapFilters.length} categories`;
                }
            }
            if (filterIcon) filterIcon.innerText = 'filter_alt';
            banner.classList.remove('hidden');
        } else if (activeCategoryFilter) {
            if (filterText) filterText.innerText = `Category: ${activeCategoryFilter}`;
            if (filterIcon) filterIcon.innerText = getCategoryIcon(activeCategoryFilter);
            banner.classList.remove('hidden');
        } else {
            banner.classList.add('hidden');
        }
    }

    const searchInput = document.getElementById('village-search-input');
    let query = searchInput ? searchInput.value.toLowerCase().trim() : "";

    if (query && checkDrugsPolicy(query)) {
        alert("Safety Notice: Corner Swaps is a cashless, neighborly platform. Transactions or searches involving drugs or illicit substances are strictly prohibited.");
        if (searchInput) searchInput.value = "";
        const subInputs = [
            'village-list-search-input',
            'village-needs-search-input',
            'village-events-search-input',
            'village-bulletins-search-input'
        ];
        subInputs.forEach(id => {
            const el = document.getElementById(id);
            if (el) el.value = "";
        });
        setTimeout(() => {
            applyMapFiltering();
            renderVillageListView();
            renderNeedsBoardView();
        }, 10);
        return;
    }

    const listClearButtons = [
        'btn-clear-village-list-search',
        'btn-clear-village-needs-search',
        'btn-clear-village-events-search',
        'btn-clear-village-bulletins-search'
    ];
    listClearButtons.forEach(id => {
        const btn = document.getElementById(id);
        if (btn) {
            if (query) {
                btn.classList.remove('hidden');
            } else {
                btn.classList.add('hidden');
            }
        }
    });

    mapMarkers.forEach(m => {
        if (m.name === 'user_location' || m.name === 'user_privacy_circle') {
            m.marker.addTo(leafletMap);
            return;
        }

        let matchSearch = false;
        let matchCategory = false;
        let itemCategory = "";
        let itemType = ""; // 'offer', 'event', 'need'

        if (!m.name || typeof m.name !== 'string') return;

        if (m.name.startsWith('evt_')) {
            itemType = 'event';
            const eventId = m.name.replace('evt_', '');
            const event = state.events ? state.events.find(e => e.id === eventId) : null;
            if (event) {
                matchSearch = fuzzySearchMatch(query, event.title, event.desc, event.type, event.location, event.host);
                itemCategory = event.type;
            }
        } else if (m.name.startsWith('need_')) {
            itemType = 'need';
            const needId = m.name.replace('need_', '');
            const need = state.needsBoard ? state.needsBoard.find(n => n.id === needId) : null;
            if (need) {
                matchSearch = fuzzySearchMatch(query, need.needTitle, need.needDesc, need.category, need.neighborName);
                itemCategory = need.category;
            }
        } else if (m.name.startsWith('off_') || m.name === '1' || m.name === '2') {
            itemType = 'offer';
            const offer = state.userOfferings.find(o => o.id === m.name);
            if (offer) {
                matchSearch = fuzzySearchMatch(query, offer.title, offer.desc, offer.category);
                itemCategory = offer.category;
            }
        } else {
            // Neighbor listing
            itemType = 'offer';
            if (state.neighbors && state.neighbors.hasOwnProperty && state.neighbors.hasOwnProperty(m.name)) {
                const neighbor = state.neighbors[m.name];
                if (neighbor) {
                    matchSearch = fuzzySearchMatch(query, neighbor.name, neighbor.offerTitle, neighbor.offerDesc, neighbor.category);
                    itemCategory = neighbor.category;
                }
            }
        }

        // Apply category / type filters
        if (state && state.activeMapFilters && state.activeMapFilters.length > 0) {
            matchCategory = state.activeMapFilters.some(filter => {
                if (filter === 'Karma Swap') {
                    if (m.name.startsWith('evt_') || m.name.startsWith('need_') || m.name.startsWith('off_') || m.name === '1' || m.name === '2') {
                        return false;
                    }
                    const neighbor = state.neighbors[m.name];
                    return !!(neighbor && neighbor.isKarma);
                }
                if (filter === 'Skills & Swaps') return (itemType === 'offer');
                if (filter === 'Needs List') return (itemType === 'need');
                if (filter === 'Community Events') return (itemType === 'event');
                return isCategoryMatchHelper(itemCategory, filter);
            });
        } else {
            if (!activeCategoryFilter) {
                matchCategory = true;
            } else if (activeCategoryFilter === 'Karma Swap') {
                if (m.name.startsWith('evt_') || m.name.startsWith('need_') || m.name.startsWith('off_') || m.name === '1' || m.name === '2') {
                    matchCategory = false;
                } else {
                    const neighbor = state.neighbors[m.name];
                    matchCategory = !!(neighbor && neighbor.isKarma);
                }
            } else if (activeCategoryFilter === 'Skills & Swaps') {
                matchCategory = (itemType === 'offer');
            } else if (activeCategoryFilter === 'Needs List') {
                matchCategory = (itemType === 'need');
            } else if (activeCategoryFilter === 'Community Events') {
                matchCategory = (itemType === 'event');
            } else {
                matchCategory = isCategoryMatchHelper(itemCategory, activeCategoryFilter);
            }
        }

        let coords = null;
        if (m.name.startsWith('evt_')) {
            const eventId = m.name.replace('evt_', '');
            const event = state.events ? state.events.find(e => e.id === eventId) : null;
            if (event) {
                if (event.lat && event.lng) {
                    coords = [event.lat, event.lng];
                } else {
                    const hostObj = state.neighbors[event.host];
                    if (hostObj) coords = getNeighborCoordinates(hostObj);
                }
            }
        } else if (m.name.startsWith('need_')) {
            const needId = m.name.replace('need_', '');
            const need = state.needsBoard ? state.needsBoard.find(n => n.id === needId) : null;
            if (need) {
                if (need.lat && need.lng) {
                    coords = [need.lat, need.lng];
                } else {
                    const neighbor = state.neighbors[need.neighborName];
                    if (neighbor) coords = getNeighborCoordinates(neighbor);
                }
            }
        } else if (m.name.startsWith('off_') || m.name === '1' || m.name === '2') {
            coords = [userLat, userLng];
        } else {
            const neighbor = state.neighbors[m.name];
            if (neighbor) coords = getNeighborCoordinates(neighbor);
        }

        let matchesRadius = true;
        if (coords) {
            const distance = (m.name.startsWith('off_') || m.name === '1' || m.name === '2') ? 0.0 : getDistance(userLat, userLng, coords[0], coords[1]);
            matchesRadius = distance <= maxRadius;
        }

        if (matchSearch && matchCategory && matchesRadius) {
            m.marker.addTo(leafletMap);
            
            // Add pulse-pin class to inner pin wrapper
            const el = m.marker.getElement();
            if (el) {
                const pinIcon = el.querySelector('.pin-icon');
                if (pinIcon) {
                    if (activeCategoryFilter || (state && state.activeMapFilters && state.activeMapFilters.length > 0)) {
                        pinIcon.classList.add('pulse-pin');
                    } else {
                        pinIcon.classList.remove('pulse-pin');
                    }
                }
            }
        } else {
            leafletMap.removeLayer(m.marker);
        }
    });

    // Sync circle markers (meetup radius) visibility to match their parent markers
    mapMarkers.forEach(m => {
        if (m.name && m.name.endsWith('_circle')) {
            const parentName = m.name.replace('_circle', '');
            const parentMarker = mapMarkers.find(pm => pm.name === parentName);
            if (parentMarker && leafletMap.hasLayer(parentMarker.marker)) {
                m.marker.addTo(leafletMap);
            } else {
                leafletMap.removeLayer(m.marker);
            }
        }
    });

    updateCategoryTrayUI();

    if (currentVillageSegment === 'list') {
        renderVillageListView();
    } else if (currentVillageSegment === 'needs') {
        renderNeedsBoardView();
    }
}

function updateCategoryTrayUI() {
    const cards = document.querySelectorAll('#category-bento-grid .bento-card');
    cards.forEach(card => {
        const cat = card.getAttribute('data-category');
        if (activeCategoryFilter && cat === activeCategoryFilter) {
            card.classList.add('active-filter');
        } else if (!activeCategoryFilter && cat === 'All') {
            card.classList.add('active-filter');
        } else {
            card.classList.remove('active-filter');
        }
    });

    const btnFilter = document.getElementById('btn-segment-filter');
    if (btnFilter) {
        if (activeCategoryFilter) {
            btnFilter.classList.add('has-active-filter');
        } else {
            btnFilter.classList.remove('has-active-filter');
        }
    }
}

function getItemImageByTitle(title) {
    if (!title) return OFFER_IMAGES[0];
    const cleanTitle = title.toLowerCase().trim();
    
    if (cleanTitle.includes('karma') || cleanTitle.includes('standing') || cleanTitle.includes('free') || cleanTitle.includes('points')) {
        return 'https://images.unsplash.com/photo-1532629345422-7515f3d16bb6?q=60&w=400&auto=format&fit=crop';
    }
    
    if (state && state.userOfferings) {
        const userOffer = state.userOfferings.find(o => o && o.title && (o.title.toLowerCase().includes(cleanTitle) || cleanTitle.includes(o.title.toLowerCase())));
        if (userOffer && userOffer.image) return userOffer.image;
    }
    
    if (state && state.neighbors) {
        for (const name in state.neighbors) {
            const n = state.neighbors[name];
            if (n && n.offerTitle && (n.offerTitle.toLowerCase().includes(cleanTitle) || cleanTitle.includes(n.offerTitle.toLowerCase()))) {
                return n.offerImg || n.avatar;
            }
        }
    }
    
    if (cleanTitle.includes('guitar') || cleanTitle.includes('music')) return OFFER_IMAGES[6];
    if (cleanTitle.includes('weed') || cleanTitle.includes('garden') || cleanTitle.includes('yard')) return OFFER_IMAGES[3];
    if (cleanTitle.includes('sourdough') || cleanTitle.includes('bread') || cleanTitle.includes('bake')) return OFFER_IMAGES[0];
    if (cleanTitle.includes('produce') || cleanTitle.includes('tomato') || cleanTitle.includes('veggie') || cleanTitle.includes('kale')) return OFFER_IMAGES[1];
    if (cleanTitle.includes('yoga') || cleanTitle.includes('mindful')) return OFFER_IMAGES[4];
    if (cleanTitle.includes('tech') || cleanTitle.includes('router') || cleanTitle.includes('code')) return OFFER_IMAGES[5];
    if (cleanTitle.includes('maintenance') || cleanTitle.includes('tool') || cleanTitle.includes('drill')) return OFFER_IMAGES[2];
    
    return OFFER_IMAGES[0];
}

window.getItemImageByTitle = getItemImageByTitle;
window.isCategoryMatchHelper = isCategoryMatchHelper;
window.filterMapByCategory = filterMapByCategory;
window.applyMapFiltering = applyMapFiltering;
window.updateCategoryTrayUI = updateCategoryTrayUI;
window.clearCategoryFilter = clearCategoryFilter;

