function selectReportReason(reasonVal) {
    playSound('click');
    const label = document.getElementById('report-reason-label');
    if (label) {
        label.classList.remove('text-red-500', 'dark:text-red-400');
        label.classList.add('text-slate-500', 'dark:text-slate-400');
    }
    const grid = document.getElementById('report-reasons-grid');
    if (grid) {
        grid.querySelectorAll('button').forEach(btn => {
            const icon = btn.querySelector('.material-symbols-outlined');
            const iconColorClass = btn.getAttribute('data-icon-color') || 'text-slate-500';
            btn.classList.remove('border-red-500', 'ring-1', 'ring-red-500');
            if (btn.getAttribute('data-reason') === reasonVal) {
                btn.classList.add('bg-forest-green', 'text-white', 'border-forest-green');
                btn.classList.remove('bg-slate-50', 'dark:bg-[#101612]', 'text-slate-700', 'dark:text-slate-300', 'border-slate-200/60', 'dark:border-slate-800');
                if (icon) {
                    icon.classList.remove(iconColorClass);
                    icon.classList.add('text-white');
                }
            } else {
                btn.classList.remove('bg-forest-green', 'text-white', 'border-forest-green');
                btn.classList.add('bg-slate-50', 'dark:bg-[#101612]', 'text-slate-700', 'dark:text-slate-300', 'border-slate-200/60', 'dark:border-slate-800');
                if (icon) {
                    icon.classList.remove('text-white');
                    icon.classList.add(iconColorClass);
                }
            }
        });
    }
    const select = document.getElementById('report-reason-select');
    if (select) {
        select.value = reasonVal;
    }
}

