function getNeighborNameForTarget(type, target) {
    if (type === 'user' || type === 'chat') return target;
    if (type === 'event') {
        const event = state.events.find(e => e.id === target);
        return event ? (event.host || 'Community Member') : 'Community Member';
    }
    if (type === 'post') {
        if (state.neighbors[target]) return target;
        const offer = state.userOfferings.find(o => o.id === target);
        if (offer) return state.currentUser ? (state.currentUser.displayName || 'Lily Kaufmann') : 'Lily Kaufmann';
        
        for (const name in state.neighbors) {
            const n = state.neighbors[name];
            if (n && (n.offerTitle === target || name === target)) {
                return name;
            }
        }
    }
    return target || 'Community Member';
}

function executeReportSubmission(type, target, reason, details) {
    if (!state.reportedAccounts) state.reportedAccounts = [];
    
    const targetName = getNeighborNameForTarget(type, target);
    
    state.reportedAccounts.push({
        id: 'report-' + Date.now(),
        neighborName: targetName,
        reasons: [reason],
        explanation: details,
        time: new Date().toLocaleString(),
        targetType: type,
        targetId: target,
        status: 'pending'
    });
    saveState();
    playSound('success');
    
    closeReportModal();
    renderAdminPanel();
    
    // If report was triggered from the neighbor profile, just return to profile — no extra popup
    if (type === 'user' && state.activeProfileNeighborName) {
        // Profile modal stays open, report silently submitted
        return;
    }
    
    // For reports from other contexts, show confirmation and optionally prompt to block
    alert(`Thank you for helping keep our community safe. Our moderation team will review your feedback.`);
    
    const currentUserDisplayName = state.currentUser ? (state.currentUser.displayName || `${state.currentUser.firstName} ${state.currentUser.lastName}`) : 'Lily Kaufmann';
    if (targetName && targetName !== currentUserDisplayName && targetName !== 'Community Member' && targetName !== 'Lily Kaufmann') {
        showBlockUserConfirmModal(`Would you like to block ${targetName} as well? You will no longer see their listings, map pins, or messages.`, () => {
            blockNeighbor(targetName);
        });
    }
}

function blockNeighbor(neighborName) {
    if (!state.blockedUsers) state.blockedUsers = [];
    if (!state.blockedUsers.includes(neighborName)) {
        state.blockedUsers.push(neighborName);
        saveState();
        playSound('success');
        
        closeNeighborProfileModal();
        closeMapItemDetail();
        
        if (state.currentView === 'chat_detail') {
            state.currentConversationId = null;
            showView('chat_hub');
        } else if (state.currentView === 'event_detail') {
            showView(state.lastEventView || 'events_hub');
        }
        
        refreshAllLayouts();
        renderBlockedList();
    }
}

function unblockNeighbor(neighborName) {
    if (!state.blockedUsers) return;
    const index = state.blockedUsers.indexOf(neighborName);
    if (index > -1) {
        state.blockedUsers.splice(index, 1);
        saveState();
        playSound('success');
        alert(`${neighborName} has been unblocked.`);
        
        refreshAllLayouts();
        renderBlockedList();
    }
}

function refreshAllLayouts() {
    try {
        renderConversationsList();
        renderListings();
        renderNeedsBoardView();
        renderEventsList();
        renderProfileSettings();
        renderHomeDashboard();
        if (window.syncUserNavbarInfo) {
            window.syncUserNavbarInfo();
        }
        if (leafletMap) {
            leafletMap.eachLayer(layer => {
                if (layer instanceof L.Marker || layer instanceof L.Circle) {
                    leafletMap.removeLayer(layer);
                }
            });
            mapMarkers = [];
            plotMapMarkersOnly();
        }
        renderBlockedList();
    } catch (err) {
        console.warn("Layout refresh deferred or failed during onboarding:", err);
    }
}

function getCategoryIconHtml(category) {
    const cat = (category || '').toLowerCase().trim();
    let icon = 'tag';
    let color = '#308A5E'; // default forest green
    if (cat.includes('garden') || cat.includes('plant') || cat.includes('seed')) {
        icon = 'potted_plant';
        color = '#10B981'; // green
    } else if (cat.includes('tool') || cat.includes('diy') || cat.includes('hardware') || cat.includes('handyman')) {
        icon = 'build';
        color = '#F59E0B'; // amber/orange
    } else if (cat.includes('kitchen') || cat.includes('food') || cat.includes('cook') || cat.includes('bake') || cat.includes('produce')) {
        icon = 'restaurant';
        color = '#EF4444'; // red
    } else if (cat.includes('household') || cat.includes('home') || cat.includes('furniture') || cat.includes('living')) {
        icon = 'home';
        color = '#3B82F6'; // blue
    } else if (cat.includes('book') || cat.includes('media') || cat.includes('study') || cat.includes('education') || cat.includes('skills')) {
        icon = 'menu_book';
        color = '#8B5CF6'; // purple
    } else if (cat.includes('clothing') || cat.includes('apparel') || cat.includes('shoes')) {
        icon = 'checkroom';
        color = '#EC4899'; // pink
    } else if (cat.includes('toy') || cat.includes('baby') || cat.includes('kid')) {
        icon = 'smart_toy';
        color = '#06B6D4'; // cyan
    } else if (cat.includes('event') || cat.includes('meet') || cat.includes('gathering')) {
        icon = 'event';
        color = '#8B5CF6'; // purple
    } else if (cat.includes('need') || cat.includes('request') || cat.includes('help')) {
        icon = 'handshake';
        color = '#F59E0B'; // amber
    }
    return `<span class="material-symbols-outlined text-sm flex-shrink-0" style="color: ${color} !important; font-variation-settings: 'FILL' 1 !important; margin-right: 4px; vertical-align: middle;">${icon}</span>`;
}

