function toggleSecurityLockdown(checked) {
    playSound('click');
    state.lockdownMode = checked;
    saveState();
    if (!state.moderationLogs) state.moderationLogs = [];
    state.moderationLogs.unshift({
        time: 'Just now',
        action: checked ? 'Security Lockdown Enabled' : 'Security Lockdown Disabled',
        detail: checked ? 'Global posting lockdown activated by Administrator.' : 'Global posting lockdown deactivated.',
        type: 'security'
    });
    saveState();
    alert(checked ? "Global security lockdown enabled. New uploads are suspended." : "Global security lockdown disabled.");
    renderAdminPanel();
}
window.toggleSecurityLockdown = toggleSecurityLockdown;

function handleUnsuspendUser(name) {
    playSound('click');
    if (confirm(`Are you sure you want to unsuspend ${name}?`)) {
        const myName = state.currentUser ? state.currentUser.displayName : 'Lily Kaufmann';
        const myEmail = state.currentUser ? state.currentUser.email : 'lily@community.com';
        
        const isSelf = (name === myName || name === myEmail || name === 'Lily Kaufmann' || name === 'lily@community.com');
        
        if (state.suspendedUsers) {
            if (isSelf) {
                state.suspendedUsers = state.suspendedUsers.filter(u => u !== myName && u !== myEmail && u !== 'Lily Kaufmann' && u !== 'lily@community.com');
            } else {
                state.suspendedUsers = state.suspendedUsers.filter(u => u !== name);
            }
        }
        
        if (isSelf && state.currentUser) {
            state.currentUser.suspended = false;
            state.currentUser.strikes = 0;
            state.currentUser.shadowBanned = false;
        }
        
        if (state.neighbors && state.neighbors[name]) {
            state.neighbors[name].suspended = false;
            state.neighbors[name].strikes = 0;
            state.neighbors[name].shadowBanned = false;
        }
        
        if (isSelf && state.neighbors) {
            ['Lily Kaufmann', myName, myEmail].forEach(nKey => {
                if (state.neighbors[nKey]) {
                    state.neighbors[nKey].suspended = false;
                    state.neighbors[nKey].strikes = 0;
                    state.neighbors[nKey].shadowBanned = false;
                }
            });
        }

        if (!state.moderationLogs) state.moderationLogs = [];
        state.moderationLogs.unshift({
            time: 'Just now',
            action: 'Suspension Revoked',
            detail: `Revoked suspension on user: ${name}.`,
            type: 'security'
        });
        saveState();
        refreshAllLayouts();
        alert(`${name} has been unsuspended.`);
        renderAdminPanel();
    }
}
window.handleUnsuspendUser = handleUnsuspendUser;

function switchAdminTab(tabName) {
    playSound('click');
    const tabs = ['reports', 'users', 'listings', 'suspended', 'reviews', 'logs'];
    tabs.forEach(t => {
        const btn = document.getElementById(`admin-tab-${t}`);
        const panel = document.getElementById(`admin-panel-${t}`);
        if (btn && panel) {
            if (t === tabName) {
                panel.classList.remove('hidden');
                btn.className = "flex items-center gap-1.5 px-4 py-2 text-xs font-bold rounded-full transition-all border border-forest-green bg-forest-green text-warm-cream cursor-pointer shadow-sm whitespace-nowrap";
            } else {
                panel.classList.add('hidden');
                btn.className = "flex items-center gap-1.5 px-4 py-2 text-xs font-bold rounded-full transition-all border border-outline-variant/30 bg-white dark:bg-[#18201a] text-outline hover:text-forest-green hover:bg-forest-green/5 cursor-pointer shadow-sm whitespace-nowrap";
            }
        }
    });
}
window.switchAdminTab = switchAdminTab;

function toggleAdminDiagnostics() {
    playSound('click');
    const content = document.getElementById('admin-diagnostics-content');
    const chevron = document.getElementById('admin-diag-chevron');
    if (content && chevron) {
        const isHidden = content.classList.contains('hidden');
        if (isHidden) {
            content.classList.remove('hidden');
            chevron.style.transform = 'rotate(180deg)';
        } else {
            content.classList.add('hidden');
            chevron.style.transform = 'rotate(0deg)';
        }
    }
}
window.toggleAdminDiagnostics = toggleAdminDiagnostics;



window.searchAdminUsers = function() {
    const input = document.getElementById('admin-user-search-input');
    const list = document.getElementById('admin-users-list');
    if (!list) return;
    
    const query = input ? input.value.trim().toLowerCase() : "";
    list.innerHTML = "";
    
    const users = [];
    
    // Add current user
    if (state.currentUser) {
        users.push({
            name: state.currentUser.displayName || 'Lily Kaufmann',
            avatar: state.currentUser.avatar || DEFAULT_AVATAR,
            location: state.currentUser.location || 'Fairview',
            karma: state.currentUser.karmaPoints !== undefined ? state.currentUser.karmaPoints : 120,
            isMe: true,
            suspended: false
        });
    }
    
    // Add mock neighbors
    Object.keys(state.neighbors).forEach(name => {
        const n = state.neighbors[name];
        const isSuspended = state.suspendedUsers && state.suspendedUsers.includes(name);
        users.push({
            name: name,
            avatar: n.avatar || DEFAULT_AVATAR,
            location: n.location || 'Unknown',
            karma: n.karmaPoints !== undefined ? n.karmaPoints : (n.vouches ? n.vouches * 10 : 50),
            isMe: false,
            suspended: isSuspended || !!n.suspended
        });
    });
    
    const filtered = users.filter(u => u.name.toLowerCase().includes(query));
    
    if (filtered.length === 0) {
        list.innerHTML = `<p class="text-xs text-outline italic">No neighbors found matching "${escapeHTML(query)}".</p>`;
        return;
    }
    
    const limit = 2;
    let displayedUsers = filtered;
    let isTruncated = false;
    window.adminShowAll = window.adminShowAll || {};
    if (!window.adminShowAll.users && filtered.length > limit) {
        displayedUsers = filtered.slice(0, limit);
        isTruncated = true;
    }
    
    displayedUsers.forEach(u => {
        const item = document.createElement('div');
        item.className = "p-3 bg-white dark:bg-[#18201a] border border-outline-variant/30 rounded-xl flex items-center justify-between text-xs mb-3";
        
        const suspendBtn = u.isMe ? "" : (u.suspended ? `
            <button class="py-1.5 px-3 bg-forest-green hover:bg-forest-green/90 text-warm-cream font-bold text-[10px] rounded-xl active:scale-[0.98] transition-transform cursor-pointer border-0 shadow-sm" onclick="handleUnsuspendUser('${escapeHTML(u.name.replace(/'/g, "\\'"))}')">
                Unsuspend
            </button>
        ` : `
            <button class="py-1.5 px-3 bg-red-600 hover:bg-red-700 text-white font-bold text-[10px] rounded-xl active:scale-[0.98] transition-transform cursor-pointer border-0 shadow-sm" onclick="suspendUserFromDirectory('${escapeHTML(u.name.replace(/'/g, "\\'"))}')">
                Suspend
            </button>
        `);
        
        item.innerHTML = `
            <div class="flex items-center gap-3 min-w-0">
                <div class="profile-avatar-ring w-9 h-9 flex-shrink-0"><img src="${u.avatar}" class="w-full h-full object-cover rounded-full"></div>
                <div class="min-w-0 text-left">
                    <p class="font-bold text-forest-green truncate flex items-center gap-1">
                        ${escapeHTML(u.name)} 
                        ${u.isMe ? '<span class="text-[8px] bg-forest-green/10 text-forest-green px-1 py-0.5 rounded font-extrabold">YOU</span>' : ''}
                    </p>
                    <p class="text-[9px] text-outline font-medium truncate">${escapeHTML(u.location)}</p>
                    <p class="text-[9px] text-[#424840] font-bold mt-0.5 flex items-center gap-1 select-none">
                        Karma: <span class="text-forest-green">${u.karma} pts</span>
                        ${!u.isMe ? `
                            <button class="w-4 h-4 bg-outline-variant/20 hover:bg-forest-green/10 text-forest-green rounded flex items-center justify-center font-black active:scale-90 transition-transform cursor-pointer border-0" onclick="adjustUserKarma('${escapeHTML(u.name.replace(/'/g, "\\'"))}', 10)">+</button>
                            <button class="w-4 h-4 bg-outline-variant/20 hover:bg-error/10 text-error rounded flex items-center justify-center font-black active:scale-90 transition-transform cursor-pointer border-0" onclick="adjustUserKarma('${escapeHTML(u.name.replace(/'/g, "\\'"))}', -10)">-</button>
                        ` : ''}
                    </p>
                </div>
            </div>
            <div class="flex items-center gap-1.5 flex-shrink-0">
                ${suspendBtn}
            </div>
        `;
        list.appendChild(item);
    });
    
    if (isTruncated) {
        const moreBtn = document.createElement('button');
        moreBtn.className = "w-full py-2 bg-forest-green/5 dark:bg-white/5 hover:bg-forest-green/10 text-forest-green dark:text-[#308A5E] text-[11px] font-bold rounded-xl border border-outline-variant/20 mt-1 cursor-pointer active:scale-95 transition-all text-center";
        moreBtn.innerText = "Show more information";
        moreBtn.onclick = function() {
            window.adminShowAll.users = true;
            searchAdminUsers();
        };
        list.appendChild(moreBtn);
    } else if (window.adminShowAll.users && filtered.length > limit) {
        const lessBtn = document.createElement('button');
        lessBtn.className = "w-full py-2 bg-forest-green/5 dark:bg-white/5 hover:bg-forest-green/10 text-forest-green dark:text-[#308A5E] text-[11px] font-bold rounded-xl border border-outline-variant/20 mt-1 cursor-pointer active:scale-95 transition-all text-center";
        lessBtn.innerText = "Show Less";
        lessBtn.onclick = function() {
            window.adminShowAll.users = false;
            searchAdminUsers();
        };
        list.appendChild(lessBtn);
    }
};

window.adjustUserKarma = function(name, amount) {
    playSound('click');
    if (state.neighbors[name]) {
        if (state.neighbors[name].karmaPoints === undefined) {
            state.neighbors[name].karmaPoints = state.neighbors[name].vouches ? state.neighbors[name].vouches * 10 : 50;
        }
        state.neighbors[name].karmaPoints = Math.max(0, state.neighbors[name].karmaPoints + amount);
        
        if (!state.moderationLogs) state.moderationLogs = [];
        state.moderationLogs.unshift({
            time: new Date().toLocaleString(),
            action: 'Karma Adjusted',
            detail: `Adjusted karma for ${name} by ${amount > 0 ? '+' : ''}${amount} points.`,
            type: 'info'
        });
        saveState();
        searchAdminUsers();
        refreshAllLayouts();
    }
};

window.suspendUserFromDirectory = function(name) {
    playSound('click');
    if (!state.suspendedUsers) state.suspendedUsers = [];
    if (!state.suspendedUsers.includes(name)) {
        state.suspendedUsers.push(name);
        
        if (state.neighbors && state.neighbors[name]) {
            state.neighbors[name].suspended = true;
            state.neighbors[name].strikes = 5;
        }
        
        if (!state.moderationLogs) state.moderationLogs = [];
        state.moderationLogs.unshift({
            time: new Date().toLocaleString(),
            action: 'User Suspended',
            detail: `Administrator suspended user: ${name}.`,
            type: 'warning'
        });
        saveState();
        searchAdminUsers();
        refreshAllLayouts();
        alert(`${name} has been suspended.`);
    }
};

window.renderAdminListings = function() {
    const list = document.getElementById('admin-listings-list');
    if (!list) return;
    
    list.innerHTML = "";
    
    const items = [];
    
    // Add user offerings
    if (state.userOfferings) {
        state.userOfferings.forEach(off => {
            if (getBarterItemStatus(off.id) !== 'Traded') {
                items.push({
                    id: off.id,
                    title: off.title,
                    desc: off.description || "",
                    category: off.category,
                    owner: 'You (Lily Kaufmann)',
                    isUser: true
                });
            }
        });
    }
    
    // Add neighbor offerings
    Object.keys(state.neighbors).forEach(name => {
        const n = state.neighbors[name];
        if (n && n.offerTitle && getBarterItemStatus(name) !== 'Traded' && (!state.suspendedUsers || !state.suspendedUsers.includes(name))) {
            items.push({
                id: name,
                title: n.offerTitle,
                desc: n.offerDesc || "",
                category: n.category,
                owner: name,
                isUser: false
            });
        }
    });
    if (items.length === 0) {
        list.innerHTML = `<p class="text-xs text-outline italic">No active listings available on the map.</p>`;
        return;
    }
    
    const limit = 2;
    let displayedItems = items;
    let isTruncated = false;
    window.adminShowAll = window.adminShowAll || {};
    if (!window.adminShowAll.listings && items.length > limit) {
        displayedItems = items.slice(0, limit);
        isTruncated = true;
    }
    
    displayedItems.forEach(item => {
        const div = document.createElement('div');
        div.className = "p-3 bg-white dark:bg-[#18201a] border border-outline-variant/30 rounded-xl text-xs space-y-1.5 flex flex-col text-left mb-3";
        
        div.innerHTML = `
            <div class="flex justify-between items-start">
                <div class="text-left">
                    <span class="text-[8px] font-bold text-white uppercase px-1.5 py-0.5 rounded-full bg-forest-green select-none">${escapeHTML(item.category)}</span>
                    <h4 class="font-bold text-forest-green text-[11px] mt-1.5">${escapeHTML(item.title)}</h4>
                </div>
                <button class="py-1.5 px-3 bg-red-600 hover:bg-red-700 text-white font-bold text-[10px] rounded-xl active:scale-[0.98] transition-transform cursor-pointer border-0 flex items-center gap-0.5 shadow-sm" onclick="deleteListingFromAdmin('${escapeHTML(item.id)}', ${item.isUser})">
                    <span class="material-symbols-outlined text-[10px]">delete</span> Delete
                </button>
            </div>
            <p class="text-[9.5px] text-on-surface-variant font-medium leading-relaxed text-left">${escapeHTML(item.desc)}</p>
            <p class="text-[9px] text-outline font-bold text-left">Owner: <span class="text-forest-green">${escapeHTML(item.owner)}</span></p>
        `;
        list.appendChild(div);
    });
    
    if (isTruncated) {
        const moreBtn = document.createElement('button');
        moreBtn.className = "w-full h-10 bg-forest-green hover:bg-forest-green/90 text-warm-cream font-bold text-xs rounded-xl active:scale-[0.98] transition-transform border-0 cursor-pointer text-center mt-2 shadow-sm";
        moreBtn.innerText = "Show more information";
        moreBtn.onclick = function() {
            window.adminShowAll.listings = true;
            renderAdminListings();
        };
        list.appendChild(moreBtn);
    } else if (window.adminShowAll.listings && items.length > limit) {
        const lessBtn = document.createElement('button');
        lessBtn.className = "w-full h-10 bg-forest-green hover:bg-forest-green/90 text-warm-cream font-bold text-xs rounded-xl active:scale-[0.98] transition-transform border-0 cursor-pointer text-center mt-2 shadow-sm";
        lessBtn.innerText = "Show Less";
        lessBtn.onclick = function() {
            window.adminShowAll.listings = false;
            renderAdminListings();
        };
        list.appendChild(lessBtn);
    }
};

window.deleteListingFromAdmin = function(id, isUser) {
    playSound('click');
    if (isUser) {
        state.userOfferings = state.userOfferings.filter(o => o.id !== id);
        if (state.savedListings) {
            state.savedListings = state.savedListings.filter(savedId => savedId !== id);
        }
        if (!state.moderationLogs) state.moderationLogs = [];
        state.moderationLogs.unshift({
            time: new Date().toLocaleString(),
            action: 'Listing Deleted',
            detail: `Admin deleted user offering (ID: ${id}).`,
            type: 'warning'
        });
        saveState();
        renderAdminListings();
        refreshAllLayouts();
        alert("Your offering has been deleted by Administrator.");
    } else {
        const n = state.neighbors[id];
        if (n) {
            const oldTitle = n.offerTitle;
            n.offerTitle = "";
            n.offerDesc = "";
            if (state.savedListings) {
                state.savedListings = state.savedListings.filter(savedId => savedId !== id);
            }
            
            if (!state.moderationLogs) state.moderationLogs = [];
            state.moderationLogs.unshift({
                time: new Date().toLocaleString(),
                action: 'Listing Deleted',
                detail: `Admin deleted neighbor listing from ${id}: "${oldTitle}".`,
                type: 'warning'
            });
            saveState();
            renderAdminListings();
            refreshAllLayouts();
            alert(`Listing "${oldTitle}" by ${id} has been deleted.`);
        }
    }
};

