function handleClearAuditLogs() {
    playSound('click');
    if (confirm("Are you sure you want to clear all security audit logs?")) {
        state.moderationLogs = [{
            time: new Date().toLocaleString(),
            action: 'Logs Cleared',
            detail: 'Administrator cleared the system security audit log history.',
            type: 'security'
        }];
        saveState();
        renderAdminPanel();
    }
}
window.handleClearAuditLogs = handleClearAuditLogs;

function handleExportAuditLogs() {
    playSound('click');
    const logs = state.moderationLogs || [];
    const blob = new Blob([JSON.stringify(logs, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `cornerswaps_audit_logs_${Date.now()}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
}
window.handleExportAuditLogs = handleExportAuditLogs;


