function toggleAddNeedForm() {
    playSound('click');
    const formContainer = document.getElementById('add-need-form-container');
    if (!formContainer) return;
    formContainer.classList.toggle('hidden');
    
    // Clear inputs if toggled
    const titleInput = document.getElementById('new-need-title');
    const descInput = document.getElementById('new-need-desc');
    const categorySelect = document.getElementById('new-need-category');
    if (titleInput) titleInput.value = "";
    if (descInput) descInput.value = "";
    if (categorySelect) categorySelect.value = "";
}

function handleAddNeedSubmit() {
    if (state.lockdownMode) {
        alert("Posting is temporarily disabled due to global administrator security lockdown.");
        return;
    }
    const titleInput = document.getElementById('new-need-title');
    const descInput = document.getElementById('new-need-desc');
    const categorySelect = document.getElementById('new-need-category');
    if (!titleInput || !descInput) return;

    const title = titleInput.value.trim();
    const desc = descInput.value.trim();
    const category = categorySelect ? categorySelect.value : 'Home and Living';

    if (!title) {
        alert("Please enter what you need.");
        return;
    }
    if (!category) {
        alert("Please choose a category.");
        return;
    }

    // Safety checks first
    if (checkSafetyPolicy(title) || checkSafetyPolicy(desc)) {
        showSafetyContentViolation();
        return;
    }

    const id = 'need-' + Date.now();
    const newNeed = {
        id: id,
        title: title,
        desc: desc,
        category: category,
        icon: getCategoryIcon(category)
    };

    if (!state.userNeeds) {
        state.userNeeds = [];
    }
    state.userNeeds.push(newNeed);

    // Also populate state.needsBoard so it shows up in the Village Needs Board
    const user = state.currentUser || {};
    const displayName = user.displayName || `${user.firstName || 'Lily'} ${user.lastName || 'Kaufmann'}`;
    const avatar = user.avatar || DEFAULT_AVATAR;
    const location = user.location || 'Mount Pleasant';

    if (!state.needsBoard) {
        state.needsBoard = [];
    }
    const needObj = {
        id: id,
        neighborName: displayName,
        avatar: avatar,
        time: 'Just now',
        location: location,
        needTitle: title,
        needDesc: desc,
        category: category
    };
    state.needsBoard.unshift(needObj);

    saveState();
    playSound('success');

    // Clear inputs and toggle form
    titleInput.value = "";
    descInput.value = "";
    toggleAddNeedForm();

    // Rerender profile page needs list and village needs board view
    renderProfileSettings();
    renderNeedsBoardView();

    if (leafletMap) {
        leafletMap.eachLayer(layer => {
            if (layer instanceof L.Marker || layer instanceof L.Circle) {
                leafletMap.removeLayer(layer);
            }
        });
        mapMarkers = [];
        plotMapMarkersOnly();
    }

    runTagMatchingAlgorithm(needObj, false);
    alert("Your need has been successfully added to your profile and the Village Needs List!");
}

function handleDeleteNeed(id) {
    if (confirm("Are you sure you want to delete this need?")) {
        if (state.userNeeds) {
            state.userNeeds = state.userNeeds.filter(n => n.id !== id);
        }
        if (state.needsBoard) {
            state.needsBoard = state.needsBoard.filter(n => n.id !== id);
        }
        if (state.savedListings) {
            state.savedListings = state.savedListings.filter(savedId => !savedId.endsWith(id));
        }
        saveState();
        playSound('click');
        renderProfileSettings();
        renderNeedsBoardView();
    }
}

// Friends List functions
function handleAddFriendSubmit() {
    const inputEl = document.getElementById('add-friend-input');
    if (!inputEl) return;
    const query = inputEl.value.trim();
    if (!query) {
        alert("Please enter a username or phone number to search.");
        return;
    }

    if (ensureFriendsList()) {
        saveState();
    }

    // Check if already friends
    const exists = state.friends.some(f => f.name.toLowerCase() === query.toLowerCase() || (f.phone && f.phone.includes(query)));
    if (exists) {
        alert("This neighbor is already in your friends list!");
        return;
    }

    // Try to find a matching neighbor in the platform database
    let foundNeighbor = null;
    for (const name in state.neighbors) {
        const n = state.neighbors[name];
        if (n && (n.name.toLowerCase() === query.toLowerCase() || (n.phone && n.phone.includes(query)))) {
            foundNeighbor = n;
            break;
        }
    }

    if (foundNeighbor) {
        state.friends.push({
            name: foundNeighbor.name,
            avatar: foundNeighbor.avatar,
            phone: foundNeighbor.phone || '+1 (604) 555-0199'
        });
        saveState();
        playSound('success');
        inputEl.value = "";
        renderProfileSettings();
        alert(`${foundNeighbor.name} has been added to your friends list!`);
    } else {
        // Fallback: invite mock friend
        const mockFriendName = query.charAt(0).toUpperCase() + query.slice(1);
        state.friends.push({
            name: mockFriendName,
            avatar: DEFAULT_AVATAR,
            phone: query.includes('+') ? query : '+1 (604) 555-0211'
        });
        saveState();
        playSound('success');
        inputEl.value = "";
        renderProfileSettings();
        alert(`Invitation sent! ${mockFriendName} has been added to your friends list.`);
    }
}

function handleRemoveFriend(name) {
    if (confirm(`Remove ${name} from your friends list?`)) {
        if (state.friends) {
            state.friends = state.friends.filter(f => f.name !== name);
        }
        saveState();
        playSound('click');
        renderProfileSettings();
    }
}

function handleInviteFriendFromProfile() {
    const query = state.activeProfileNeighborName;
    if (!query) return;

    if (ensureFriendsList()) {
        saveState();
    }

    // Check if already friends — if so, un-add them
    const existingIndex = state.friends.findIndex(f => f.name.toLowerCase() === query.toLowerCase());
    if (existingIndex !== -1) {
        // Un-add friend
        state.friends.splice(existingIndex, 1);
        saveState();
        playSound('click');
        renderProfileSettings();

        // Update button back to "Become Friend"
        const btn = document.getElementById('neighbor-profile-add-friend-btn');
        if (btn) {
            btn.innerHTML = `<span class="material-symbols-outlined text-xs text-white">person_add</span> Become Friend`;
            btn.className = "flex-grow bg-forest-green text-white dark:bg-[#308A5E] dark:text-white py-3.5 rounded-xl font-bold flex items-center justify-center gap-1 active:scale-[0.98] transition-transform text-xs cursor-pointer border-none";
        }
        return;
    }

    // Set message details dynamically
    const msgEl = document.getElementById('friend-confirm-message');
    if (msgEl) {
        msgEl.innerText = `Would you like to add ${query} to your friends list? You will be able to easily coordinate swaps and share contact details.`;
    }

    // Show friend confirmation modal
    const modal = document.getElementById('friend-confirm-modal');
    if (modal) {
        playSound('click');
        modal.classList.remove('hidden');
    }
}
