function shareInvite(platform) {
    playSound('click');
    const inviteUrl = window.location.origin + '?invite=' + (state.currentUser ? (state.currentUser.firstName || 'Lily') : 'Lily');
    const message = `Hey! Join me on Corner Swaps to swap goods and skills cashlessly: ${inviteUrl}`;
    
    if (platform === 'whatsapp') {
        const nativeUrl = `whatsapp://send?text=${encodeURIComponent(message)}`;
        const webUrl = `https://api.whatsapp.com/send?text=${encodeURIComponent(message)}`;
        window.location.href = nativeUrl;
        setTimeout(() => {
            window.open(webUrl, '_blank');
        }, 500);
        closeInviteModal();
    } else if (platform === 'imessage' || platform === 'text') {
        const separator = (navigator.userAgent.match(/iPhone|iPad|iPod/i) ? '&' : '?');
        const url = `sms:${separator}body=${encodeURIComponent(message)}`;
        window.location.href = url;
        closeInviteModal();
    } else if (platform === 'instagram') {
        navigator.clipboard.writeText(message).then(() => {
            window.location.href = 'instagram://app';
            setTimeout(() => {
                window.open('https://www.instagram.com', '_blank');
            }, 800);
        }).catch(() => {
            console.error("Failed to copy link. Share this URL: " + inviteUrl);
        });
        closeInviteModal();
    } else if (platform === 'tiktok') {
        navigator.clipboard.writeText(message).then(() => {
            window.location.href = 'tiktok://';
            setTimeout(() => {
                window.open('https://www.tiktok.com', '_blank');
            }, 800);
        }).catch(() => {
            console.error("Failed to copy link. Share this URL: " + inviteUrl);
        });
        closeInviteModal();
    } else if (platform === 'email') {
        const url = `mailto:?subject=${encodeURIComponent('Join me on Corner Swaps')}&body=${encodeURIComponent(message)}`;
        window.location.href = url;
        closeInviteModal();
    } else if (platform === 'copy') {
        navigator.clipboard.writeText(inviteUrl).catch(() => {
            console.error("Failed to copy link. Share this URL: " + inviteUrl);
        });
        closeInviteModal();
    } else if (platform === 'system') {
        if (navigator.share) {
            navigator.share({
                title: 'Join Corner Swaps!',
                text: message,
                url: inviteUrl
            }).catch(err => {
                console.log("Share failed", err);
            });
        } else {
            navigator.clipboard.writeText(inviteUrl);
        }
        closeInviteModal();
    } else {
        closeInviteModal();
    }
}

