// Push notification drawer controllers
let currentNotificationActionView = null;
let currentNotificationCallback = null;
let notificationTimeoutId = null;

function triggerPushNotification(title, body, icon = 'notifications', actionView = null, clickCallback = null) {
    const el = document.getElementById('mock-push-notification');
    const titleEl = document.getElementById('notification-title');
    const bodyEl = document.getElementById('notification-body');
    const iconEl = document.getElementById('notification-icon');
    
    if (el && titleEl) {
        let cleanTitle = title;
        if (cleanTitle) {
            cleanTitle = cleanTitle.replace(/Corner Swaps\s*/gi, '').trim();
            if (cleanTitle === 'Match! ⚡') {
                cleanTitle = 'Match Found! ⚡';
            }
        }
        titleEl.innerText = cleanTitle;
        if (bodyEl && body) bodyEl.innerText = body;
        if (iconEl && icon) iconEl.innerText = icon;
        
        currentNotificationActionView = actionView;
        currentNotificationCallback = clickCallback;
        
        if (typeof playSound === 'function') {
            playSound('message');
        }
        
        el.classList.remove('hidden');
        
        if (notificationTimeoutId) clearTimeout(notificationTimeoutId);
        notificationTimeoutId = setTimeout(() => {
            dismissNotification();
        }, 6000);
    }
}

