function dismissNotification() {
    const el = document.getElementById('mock-push-notification');
    if (!el) return;

    el.classList.add('hidden');

    if (notificationTimeoutId) {
        clearTimeout(notificationTimeoutId);
        notificationTimeoutId = null;
    }
}

function handleNotificationClick() {
    if (currentNotificationCallback) {
        currentNotificationCallback();
    } else if (currentNotificationActionView) {
        showView(currentNotificationActionView);
    }
    dismissNotification();
}

function initHomepageWidgets() {
    let hidden = [];
    const stored = safeLocalStorage.getItem('barterland_hidden_widgets');
    if (stored !== null) {
        try {
            hidden = JSON.parse(stored);
        } catch(e) {}
    } else {
        // Setup initial default hidden widgets
        hidden = [
            'widget-trending-swaps',
            'widget-browse-by-category',
            'widget-daily-quote',
            'widget-value-statement',
            'widget-community-events'
        ];
        safeLocalStorage.setItem('barterland_hidden_widgets', JSON.stringify(hidden));
    }
    
    const ids = [
        'widget-badges-section',
        'widget-trending-swaps',
        'widget-browse-by-category',
        'widget-ideas-offer',
        'widget-daily-quote',
        'widget-value-statement',
        'widget-lead-by-giving',
        'widget-community-events',
        'widget-safety-tips',
        'widget-my-offerings',
        'widget-my-needs',
        'widget-friends-list',
        'widget-swaps-history',
        'widget-suggestion-box'
    ];
    
    ids.forEach(id => {
        const el = document.getElementById(id);
        if (el) {
            // Remove inline display none styles, manage entirely through class 'hidden'
            if (el.style.display === 'none') {
                el.style.display = '';
            }
            if (hidden.includes(id)) {
                el.classList.add('hidden');
            } else {
                el.classList.remove('hidden');
            }
        }
    });
    updateResetWidgetsButton();
}

function hideHomepageWidget(event, id) {
    if (event) {
        event.stopPropagation();
        event.preventDefault();
    }
    const el = document.getElementById(id);
    if (el) {
        el.classList.add('hidden');
    }
    let hidden = [];
    try {
        const stored = safeLocalStorage.getItem('barterland_hidden_widgets');
        if (stored) hidden = JSON.parse(stored);
    } catch(e) {}
    if (!hidden.includes(id)) {
        hidden.push(id);
    }
    safeLocalStorage.setItem('barterland_hidden_widgets', JSON.stringify(hidden));
    updateResetWidgetsButton();
}

function showHomepageWidget(id) {
    const el = document.getElementById(id);
    if (el) {
        el.classList.remove('hidden');
        if (el.style.display === 'none') {
            el.style.display = '';
        }
    }
    let hidden = [];
    try {
        const stored = safeLocalStorage.getItem('barterland_hidden_widgets');
        if (stored) hidden = JSON.parse(stored);
    } catch(e) {}
    hidden = hidden.filter(x => x !== id);
    safeLocalStorage.setItem('barterland_hidden_widgets', JSON.stringify(hidden));
    updateResetWidgetsButton();
    renderAdjustHomepage(); // re-render adjust view
}

function resetHomepageWidgets() {
    safeLocalStorage.removeItem('barterland_hidden_widgets');
    initHomepageWidgets();
    if (document.getElementById('view-adjust_homepage').classList.contains('active')) {
        renderAdjustHomepage();
    }
}

function updateResetWidgetsButton() {
    const container = document.getElementById('reset-widgets-btn-container');
    if (container) {
        container.classList.remove('hidden');
    }
}

function renderAdjustHomepage() {
    // Populate profile details
    const user = state.currentUser || { firstName: 'Lily', lastName: 'Kaufmann', email: 'lily@community.com', location: 'Oakwood Village', avatar: DEFAULT_AVATAR };
    
    const nameEl = document.getElementById('adjust-profile-name');
    if (nameEl) {
        const baseName = user.displayName || `${user.firstName} ${user.lastName}`;
        if (state.currentUser && state.currentUser.verified) {
            nameEl.innerHTML = `${baseName} <span class="material-symbols-outlined text-[14px] text-blue-500 align-middle ml-1 inline-flex items-center" style="color: #3b82f6; vertical-align: middle;">verified</span>`;
        } else {
            nameEl.innerText = baseName;
        }
    }
    
    const locEl = document.getElementById('adjust-profile-location');
    if (locEl) locEl.innerText = user.location || "Oakwood Village Community";
    
    const avatarEl = document.getElementById('adjust-profile-avatar');
    if (avatarEl) avatarEl.src = user.avatar || DEFAULT_AVATAR;

    const adjustBadgeIcon = document.getElementById('adjust-profile-badge-icon');
    const adjustBadgeText = document.getElementById('adjust-profile-badge-text');
    const isSelfVerified = state.currentUser && state.currentUser.verified;
    const selfKarma = ((state.level || 1) - 1) * 100 + (state.xp || 50);
    if (adjustBadgeIcon) {
        adjustBadgeIcon.textContent = isSelfVerified ? 'verified_user' : 'person';
    }
    if (adjustBadgeText) {
        adjustBadgeText.textContent = getUserBadgeText(selfKarma);
    }

    const container = document.getElementById('adjust-homepage-widgets-container');
    if (!container) return;
    container.innerHTML = "";

    const widgetIds = [
        'widget-badges-section',
        'widget-my-offerings',
        'widget-my-needs',
        'widget-friends-list',
        'widget-swaps-history',
        'widget-lead-by-giving',
        'widget-ideas-offer',
        'widget-safety-tips',
        'widget-suggestion-box'
    ];

    let hidden = [];
    try {
        const stored = safeLocalStorage.getItem('barterland_hidden_widgets');
        if (stored) hidden = JSON.parse(stored);
    } catch(e) {}

    widgetIds.forEach(id => {
        const originalWidget = document.getElementById(id);
        if (!originalWidget) return;

        const isCurrentlyHidden = hidden.includes(id);

        // Create container wrapper: relative w-full with optional opacity for hidden widgets
        const wrapper = document.createElement('div');
        wrapper.className = "relative w-full" + (isCurrentlyHidden ? " opacity-60" : "");

        // Clone the widget
        const clone = originalWidget.cloneNode(true);
        // Ensure relative positioning for child absolute layout toggle
        clone.classList.add('relative');
        // Ensure it is visible for customization list
        clone.classList.remove('hidden');
        // Rename ID to avoid collisions
        clone.id = 'adjust-' + id;
        
        // Remove navigation or action click handlers on clone and sub-elements
        clone.removeAttribute('onclick');
        clone.querySelectorAll('[onclick]').forEach(el => el.removeAttribute('onclick'));

        // Ensure no duplicated buttons exist in clone
        const existingBtn = clone.querySelector('button[title*="Hide"], button[title*="Restore"]');
        if (existingBtn) existingBtn.remove();
        
        // Clean up interactive/overlapping elements in the top right
        clone.querySelectorAll('.btn-increase-size, button, a, [id$="-body-icon"], #badges-unlocked-count').forEach(el => {
            if (!el.querySelector('input')) {
                el.style.display = 'none';
            }
        });

        // Add customizable slide-to-green toggle switch container inside the box to the right
        const toggleWrapper = document.createElement('div');
        toggleWrapper.className = "absolute top-3.5 right-3.5 z-30 flex items-center gap-1.5 select-none bg-warm-cream/95 dark:bg-[#101612]/95 border border-outline-variant/30 px-2.5 py-1 rounded-full shadow-md transition-all";
        
        const statusLabel = document.createElement('span');
        statusLabel.className = "text-[9px] font-bold tracking-wider uppercase " + (isCurrentlyHidden ? "text-[#424840]/60 dark:text-[#FDFBF7]/60" : "text-forest-green");
        statusLabel.innerText = isCurrentlyHidden ? "Off" : "On";
        
        const label = document.createElement('label');
        label.className = "relative inline-flex items-center cursor-pointer";
        
        const input = document.createElement('input');
        input.type = 'checkbox';
        input.className = 'sr-only peer';
        input.checked = !isCurrentlyHidden;
        input.onchange = (e) => {
            if (input.checked) {
                showHomepageWidget(id);
            } else {
                hideHomepageWidget(null, id);
                renderAdjustHomepage();
            }
        };
        
        const toggleDiv = document.createElement('div');
        toggleDiv.className = "w-10 h-6 bg-outline-variant/40 rounded-full peer peer-checked:after:translate-x-[16px] after:content-[''] after:absolute after:top-0.5 after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-forest-green";
        
        label.appendChild(input);
        label.appendChild(toggleDiv);
        
        toggleWrapper.appendChild(statusLabel);
        toggleWrapper.appendChild(label);
        
        clone.appendChild(toggleWrapper);
        wrapper.appendChild(clone);
        container.appendChild(wrapper);
    });
}

window.qrScanTimeout = null;

function openQRHandshake() {
    const modal = document.getElementById('chat-qr-handshake-modal');
    if (!modal) return;
    
    if (typeof playSound === 'function') playSound('click');
    
    // Set neighbor name dynamically
    const conv = state.conversations.find(c => c.id === state.currentConversationId);
    const neighborLabel = document.getElementById('qr-code-neighbor-name');
    if (neighborLabel && conv) {
        neighborLabel.innerText = `${conv.neighborName.toUpperCase()} - HANDSHAKE`;
    }
    
    modal.classList.remove('hidden');
    switchQRMode('show');
}

function closeQRHandshake() {
    const modal = document.getElementById('chat-qr-handshake-modal');
    if (!modal) return;
    
    modal.classList.add('hidden');
    if (window.qrScanTimeout) {
        clearTimeout(window.qrScanTimeout);
        window.qrScanTimeout = null;
    }
}

function switchQRMode(mode) {
    if (typeof playSound === 'function') playSound('click');
    
    const showTab = document.getElementById('btn-qr-mode-show');
    const scanTab = document.getElementById('btn-qr-mode-scan');
    const showContent = document.getElementById('qr-content-show');
    const scanContent = document.getElementById('qr-content-scan');
    
    if (!showTab || !scanTab || !showContent || !scanContent) return;
    
    if (mode === 'show') {
        showTab.className = "flex-grow py-2 rounded-lg text-[10.5px] font-bold transition-all shadow-sm bg-white dark:bg-[#1b261f] text-forest-green dark:text-warm-cream";
        scanTab.className = "flex-grow py-2 rounded-lg text-[10.5px] font-bold transition-all text-outline hover:text-forest-green/80 bg-transparent";
        showContent.classList.remove('hidden');
        scanContent.classList.add('hidden');
        
        if (window.qrScanTimeout) {
            clearTimeout(window.qrScanTimeout);
            window.qrScanTimeout = null;
        }
    } else {
        scanTab.className = "flex-grow py-2 rounded-lg text-[10.5px] font-bold transition-all shadow-sm bg-white dark:bg-[#1b261f] text-forest-green dark:text-warm-cream";
        showTab.className = "flex-grow py-2 rounded-lg text-[10.5px] font-bold transition-all text-outline hover:text-forest-green/80 bg-transparent";
        scanContent.classList.remove('hidden');
        showContent.classList.add('hidden');
        
        // Simulate Camera Scanning Success after 2.5 seconds
        if (window.qrScanTimeout) clearTimeout(window.qrScanTimeout);
        window.qrScanTimeout = setTimeout(() => {
            handleQRScanSuccess();
        }, 2500);
    }
}

function handleQRScanSuccess() {
    const conv = state.conversations.find(c => c.id === state.currentConversationId);
    if (!conv) return;
    
    closeQRHandshake();
    
    // 1. Mark negotiation status completed
    conv.negotiation.status = 'completed';
    conv.timeLeft = '';
    
    // Record in swapHistory
    if (!state.swapHistory) state.swapHistory = [];
    state.swapHistory.unshift({
        neighborName: conv.neighborName,
        offeredItem: conv.negotiation.offeredItem || 'Tutoring',
        requestedItem: conv.negotiation.requestedItem || 'Swap',
        date: 'Just now'
    });
    
    // Delete the chat (Disabled per request)
    // state.conversations = state.conversations.filter(c => c.id !== conv.id);
    
    // Save state
    saveState();
    renderConversationsList();
    showView('chat_hub');
    alert("🤝 QR Handshake Verified! Swap marked complete. 🌿");
}

