// proposalCountdownInterval declared globally at the top of app.js
function startProposalCountdownTimer() {
    if (proposalCountdownInterval) clearInterval(proposalCountdownInterval);
    
    function updateClocks() {
        if (!state.conversations) return;
        state.conversations.forEach(conv => {
            if (conv.negotiation && (conv.negotiation.status === 'pending' || conv.negotiation.status === 'received')) {
                const el = document.getElementById(`proposal-countdown-${conv.id}`);
                const elDrawer = document.getElementById(`drawer-proposal-countdown-${conv.id}`);
                const elHeader = document.getElementById(`header-proposal-countdown-${conv.id}`);
                
                if (el || elDrawer || elHeader) {
                    if (!conv.proposalTimestamp) {
                        conv.proposalTimestamp = Date.now();
                    }
                    const elapsed = Date.now() - conv.proposalTimestamp;
                    const expiryHours = (state && state.config && state.config.swapExpiryHours) ? state.config.swapExpiryHours : 24;
                    const totalDuration = expiryHours * 60 * 60 * 1000;
                    const remaining = Math.max(0, totalDuration - elapsed);
                    
                    if (remaining === 0) {
                        conv.negotiation.status = 'expired';
                        saveState();
                        if (state.currentConversationId === conv.id) {
                            renderChatDetail(conv);
                        }
                        renderConversationsList();
                        return;
                    }
                    
                    const hours = Math.floor(remaining / (1000 * 60 * 60));
                    const minutes = Math.floor((remaining % (1000 * 60 * 60)) / (1000 * 60));
                    const seconds = Math.floor((remaining % (1000 * 60)) / 1000);
                    
                    const pad = (num) => String(num).padStart(2, '0');
                    const text = `${pad(hours)}:${pad(minutes)}:${pad(seconds)} left`;
                    if (el) el.innerText = text;
                    if (elDrawer) elDrawer.innerText = text;
                    if (elHeader) elHeader.innerText = text;
                }
            }
        });
    }
    
    updateClocks();
    proposalCountdownInterval = setInterval(updateClocks, 1000);
}

function cancelProposedBarter() {
    const conv = state.conversations.find(c => c.id === state.currentConversationId);
    if (!conv) return;
    if (typeof playSound === 'function') playSound('click');
    conv.negotiation.status = 'none';
    saveState();
    renderConversationsList();
    renderChatDetail(conv);
}
window.cancelProposedBarter = cancelProposedBarter;

function handleAcceptProposalFromList(convId) {
    if (typeof playSound === 'function') playSound('click');
    const conv = state.conversations.find(c => c.id === convId);
    if (!conv) return;

    conv.isRequest = false; // Move to active!
    conv.negotiation.status = 'accepted';
    conv.messages.push({
        sender: 'me',
        text: 'Proposal accepted! Sounds great.',
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    });
    conv.messages.push({
        sender: 'App admin',
        text: 'Click this message to set up a meeting location',
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        isMeetupPrompt: true,
        isAdminMeetupClick: true
    });
    saveState();
    
    if (typeof queueTradeCheckIn === 'function') {
        queueTradeCheckIn(conv.id);
    }
    
    if (typeof showToast === 'function') {
        showToast("Swap request accepted!");
    }
    
    // Logically transition directly to the chat conversation
    if (typeof startChatConversation === 'function') {
        startChatConversation(conv.id);
    } else {
        switchChatSegment('active');
        renderConversationsList();
        showView('chat_detail');
    }
    triggerSuccessConfetti();
}

function handleDeclineProposalFromList(convId) {
    if (typeof playSound === 'function') playSound('click');
    const conv = state.conversations.find(c => c.id === convId);
    if (!conv) return;

    conv.isRequest = false; // Move out of swap requests!
    conv.isOld = true; // Move to archived!
    conv.negotiation.status = 'declined';
    conv.negotiation.declineReason = "Friendly decline";
    
    if (!state.declineLogs) state.declineLogs = [];
    state.declineLogs.push({
        id: 'decline-' + Date.now(),
        neighborName: conv.neighborName,
        reason: "Friendly decline",
        time: new Date().toLocaleString()
    });

    conv.messages.push({
        sender: 'System',
        text: `Proposal declined. Reason: Friendly decline`,
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    });
    saveState();
    
    if (typeof showToast === 'function') {
        showToast("Swap request declined.");
    }
    
    renderConversationsList();
}

