function renderEventRSVPs(event) {
    const avatarsContainer = document.getElementById('event-detail-rsvp-avatars');
    const rsvpCountEl = document.getElementById('event-detail-rsvp-count');
    const rsvpBtn = document.getElementById('event-detail-rsvp-btn');
    
    if (!avatarsContainer || !rsvpCountEl || !rsvpBtn) return;
    
    avatarsContainer.innerHTML = "";
    
    const currentUser = state.currentUser ? (state.currentUser.displayName || `${state.currentUser.firstName} ${state.currentUser.lastName}`) : 'Lily Kaufmann';
    const isUserRsvped = event.rsvps.includes(currentUser);
    const isHost = (event.host === currentUser || event.host.toLowerCase() === 'you' || event.host.toLowerCase().includes('lily kaufmann') || event.host.toLowerCase().includes(currentUser.toLowerCase()));

    rsvpBtn.style.display = '';
    rsvpBtn.classList.remove('hidden');
    rsvpBtn.className = "w-full py-2.5 rounded-xl font-bold text-[11px] active:scale-[0.98] transition-transform flex items-center justify-center gap-1.5 transition-all";

    if (isUserRsvped) {
        rsvpBtn.classList.add('bg-black', 'text-white', 'hover:bg-black/90', 'dark:bg-white', 'dark:text-black', 'dark:hover:bg-white/90');
        rsvpBtn.innerHTML = '<span class="material-symbols-outlined text-xs">cancel</span> cancel rsvp';
    } else {
        rsvpBtn.classList.add('bg-white', 'border', 'border-black/20', 'text-black', 'hover:bg-black/5', 'dark:bg-[#18201a]', 'dark:border-white/20', 'dark:text-white', 'dark:hover:bg-white/5');
        rsvpBtn.innerHTML = '<span class="material-symbols-outlined text-xs">check_circle</span> rsvp to event';
    }

    const count = event.rsvps.length;
    rsvpCountEl.innerText = `${count} ${count === 1 ? 'neighbor is' : 'neighbors are'} going`;

    event.rsvps.forEach(name => {
        let avatarUrl = RSVP_AVATARS[name] || 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?q=60&w=80&auto=format&fit=crop';
        if (state.currentUser && (name === currentUser || name === state.currentUser.displayName || name === (state.currentUser.firstName + ' ' + state.currentUser.lastName).trim())) {
            if (state.currentUser.avatar) {
                avatarUrl = state.currentUser.avatar;
            }
        }
        const ringEl = document.createElement('div');
        ringEl.className = "profile-avatar-no-ring inline-block h-8 w-8 flex-shrink-0 cursor-pointer active:scale-95 transition-transform";
        const imgEl = document.createElement('img');
        imgEl.className = "w-full h-full object-cover rounded-full";
        imgEl.src = avatarUrl;
        imgEl.alt = name;
        imgEl.title = name;
        ringEl.appendChild(imgEl);
        
        ringEl.onclick = () => {
            const isSelf = (name === currentUser || (state.currentUser && (name === state.currentUser.displayName || name === `${state.currentUser.firstName} ${state.currentUser.lastName}`)));
            if (isSelf) {
                showView('profile_settings');
            } else {
                openNeighborProfileModal(name);
            }
        };
        
        avatarsContainer.appendChild(ringEl);
    });
}

function handleEventRSVPToggle() {
    const event = state.events.find(e => e.id === state.activeEventId);
    if (!event) return;

    if (!event.rsvps) {
        event.rsvps = ['Sarah Chen', 'David Kim'];
    }

    const currentUser = state.currentUser ? (state.currentUser.displayName || `${state.currentUser.firstName} ${state.currentUser.lastName}`) : 'Lily Kaufmann';
    const index = event.rsvps.indexOf(currentUser);

    if (index > -1) {
        event.rsvps.splice(index, 1);
        playSound('click');
    } else {
        event.rsvps.push(currentUser);
        playSound('match_success');
        
        // Send a chat confirmation message from host to user
        const hostLower = (event.host || '').toLowerCase();
        let conv = state.conversations.find(c => (c.neighborName && c.neighborName.toLowerCase() === hostLower) || (c.id && c.id === hostLower.replace(' ', '-')));
        if (!conv) {
            conv = {
                id: hostLower.replace(' ', '-'),
                neighborName: event.host,
                unread: true,
                timeLeft: '48 hours left',
                messages: [],
                negotiation: {
                    status: 'none'
                }
            };
            state.conversations.push(conv);
        }
        
        const dateObj = new Date(event.datetime);
        const formattedDate = dateObj.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });
        const formattedTime = dateObj.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
        
        conv.messages.push({
            sender: event.host,
            text: `Hey neighbor! Thanks for RSVPing to my event: "${event.title}"!\n\n📅 Date: ${formattedDate}\n⏰ Time: ${formattedTime}\n📍 Location: ${event.location}\n\nLooking forward to seeing you there! 🌿`,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        });
        conv.unread = true;
        conv.unreadCount = (conv.unreadCount || 0) + 1;
    }

    saveState();
    updateChatNotificationBadge();
    renderEventRSVPs(event);
    renderEventsList();
    renderProfileSettings();
}

