window.handleAcceptSwapRequest = function(convId) {
    playSound('click');
    const conv = state.conversations.find(c => c.id === convId);
    if (!conv) return;
    
    // Move chat to active chats page, delete from swap requests
    conv.isRequest = false;
    if (!conv.negotiation) {
        conv.negotiation = {};
    }
    conv.negotiation.status = 'accepted';
    
    // 1. Add Proposed Swap message (with give & get images) immediately
    conv.messages.push({
        sender: conv.neighborName,
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        isSwapOffer: true,
        offeredItemTitle: conv.negotiation.offeredItem,
        offeredItemImage: getItemImageByTitle(conv.negotiation.offeredItem) || PLACEHOLDER_IMAGE,
        requestedItemTitle: conv.negotiation.requestedItem,
        requestedItemImage: getItemImageByTitle(conv.negotiation.requestedItem) || PLACEHOLDER_IMAGE
    });
    
    saveState();
    switchChatSegment('active');
    renderChatDetail(conv);
    showView('chat_detail');
    
    // 2. After 1 second, simulate "Swap Request accepted!" message
    setTimeout(() => {
        conv.messages.push({
            sender: 'me',
            text: 'Swap Request accepted!',
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        });
        saveState();
        if (state.currentView === 'chat_detail' && state.currentConversationId === conv.id) {
            playSound('message');
            renderChatDetail(conv);
        }
        
        // 3. After another 1.2 seconds, simulate "Click this message to set up a meeting location" admin message
        setTimeout(() => {
            conv.messages.push({
                sender: 'App admin',
                text: 'Click this message to set up a meeting location',
                time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
                isMeetupPrompt: true,
                isAdminMeetupClick: true
            });
            saveState();
            if (state.currentView === 'chat_detail' && state.currentConversationId === conv.id) {
                playSound('message');
                renderChatDetail(conv);
            }
        }, 1200);
    }, 1000);
};

window.handleDeclineSwapRequest = function(convId) {
    playSound('click');
    const conv = state.conversations.find(c => c.id === convId);
    if (!conv) return;
    
    // Send nice message first: "Sorry, I’m not interested in this swap right now!"
    conv.messages.push({
        sender: state.currentUser ? (state.currentUser.displayName || `${state.currentUser.firstName} ${state.currentUser.lastName}`) : 'Me',
        text: "Sorry, I’m not interested in this swap right now!",
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    });
    
    saveState();
    
    // Now delete the chat from local state
    state.conversations = state.conversations.filter(c => c.id !== convId);
    saveState();
    
    switchChatSegment('requests');
    showView('chat_hub');
};

