window.renderCleanupListings = function(filterText = '') {
    const listContainer = document.getElementById('cleanup-listings-list');
    if (!listContainer) return;
    listContainer.innerHTML = "";

    const convId = state.cleanupConversationId;
    const conv = state.conversations.find(c => c.id === convId);
    let offered = '';
    let requested = '';
    if (conv && conv.negotiation) {
        offered = conv.negotiation.offeredItem || '';
        requested = conv.negotiation.requestedItem || '';
    }

    const items = [];
    if (state.userNeeds) {
        state.userNeeds.forEach(need => {
            items.push({
                id: need.id,
                title: need.title,
                type: 'need',
                obj: need
            });
        });
    }
    if (state.userOfferings) {
        state.userOfferings.forEach(off => {
            items.push({
                id: off.id,
                title: off.title,
                type: 'offering',
                obj: off
            });
        });
    }

    const query = filterText.toLowerCase().trim();
    const filtered = items.filter(item => item.title.toLowerCase().includes(query));

    if (filtered.length === 0) {
        listContainer.innerHTML = `
            <div class="flex flex-col items-center justify-center py-8 text-center text-outline">
                <span class="material-symbols-outlined text-3xl opacity-40 mb-1">search_off</span>
                <p class="text-xs font-semibold">No active listings found.</p>
            </div>
        `;
        return;
    }

    filtered.forEach(item => {
        const isMatch = (offered && (item.title.toLowerCase().includes(offered.toLowerCase()) || offered.toLowerCase().includes(item.title.toLowerCase()))) ||
                        (requested && (item.title.toLowerCase().includes(requested.toLowerCase()) || requested.toLowerCase().includes(item.title.toLowerCase())));
        
        const div = document.createElement('div');
        div.className = "flex items-center gap-3 p-3 bg-forest-green/5 dark:bg-white/5 rounded-xl border border-outline-variant/10 shadow-sm cursor-pointer select-none hover:bg-forest-green/10 transition-colors";
        div.onclick = (e) => {
            if (e.target.type !== 'checkbox') {
                const cb = div.querySelector('input[type="checkbox"]');
                if (cb) cb.checked = !cb.checked;
            }
        };

        const badgeBg = item.type === 'need' 
            ? 'bg-rose-100 dark:bg-rose-950/40 text-rose-700 dark:text-rose-400 border border-rose-200/50' 
            : 'bg-emerald-100 dark:bg-emerald-950/40 text-emerald-700 dark:text-emerald-400 border border-emerald-200/50';

        div.innerHTML = `
            <input type="checkbox" class="cleanup-item-checkbox w-4.5 h-4.5 text-forest-green rounded border-outline-variant/35 focus:ring-forest-green cursor-pointer" data-id="${item.id}" data-type="${item.type}" ${isMatch ? 'checked' : ''}>
            <div class="flex-grow min-w-0 flex flex-col gap-0.5">
                <div class="flex items-center gap-2">
                    <span class="text-[9px] px-1.5 py-0.5 rounded-full font-bold uppercase ${badgeBg}">${item.type}</span>
                    ${isMatch ? '<span class="text-[9px] bg-amber-100 text-amber-800 dark:bg-amber-950/40 dark:text-amber-400 px-1.5 py-0.5 rounded-full font-extrabold border border-amber-200/50">MATCHED</span>' : ''}
                </div>
                <span class="text-xs font-semibold text-on-surface truncate">${escapeHTML(item.title)}</span>
            </div>
        `;
        listContainer.appendChild(div);
    });
};

window.handleCleanupSearchInput = function(el) {
    window.renderCleanupListings(el.value);
};

window.closeCleanupListingsModal = function() {
    playSound('click');
    const modal = document.getElementById('cleanup-listings-modal');
    if (modal) {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
    }
    state.cleanupConversationId = null;
    showToast("Swap confirmed!");
    enableMapGestures();
};

window.submitCleanupListings = function() {
    playSound('click');
    const checkboxes = document.querySelectorAll('.cleanup-item-checkbox:checked');
    let deletedCount = 0;

    checkboxes.forEach(cb => {
        const id = cb.getAttribute('data-id');
        const type = cb.getAttribute('data-type');
        if (type === 'need') {
            state.userNeeds = state.userNeeds.filter(n => n.id !== id);
            deletedCount++;
        } else if (type === 'offering') {
            state.userOfferings = state.userOfferings.filter(o => o.id !== id);
            deletedCount++;
        }
    });

    if (deletedCount > 0) {
        saveState();
        renderNeedsBoardView();
        renderProfileSettings();
        showToast(`${deletedCount} listing(s) deleted.`);
    } else {
        showToast("No listings deleted.");
    }

    const modal = document.getElementById('cleanup-listings-modal');
    if (modal) {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
    }
    state.cleanupConversationId = null;
    enableMapGestures();
};

function handleEventDetailBack() {
    showView(state.lastEventView || 'events_hub');
    if (state.lastEventView === 'village') {
        let targetSeg = currentVillageSegment || 'map';
        if (state && state.activeViewMode) {
            if (state.activeViewMode === 'list') {
                const cat = state.activeCategory || 'offerings';
                if (cat === 'offerings') targetSeg = 'list';
                else if (cat === 'needs') targetSeg = 'needs';
                else if (cat === 'events') targetSeg = 'events';
            } else {
                const cat = state.activeCategory || 'offerings';
                if (cat === 'offerings') targetSeg = 'map';
                else if (cat === 'needs') targetSeg = 'needs_map';
                else if (cat === 'events') targetSeg = 'events_map';
            }
        }
        switchVillageSegment(targetSeg);
    }
}

