function handleDismissReport(reportId) {
    playSound('click');
    if (!state.reportedAccounts) return;
    const report = state.reportedAccounts.find(r => r.id === reportId);
    if (report) {
        if (!state.moderationLogs) state.moderationLogs = [];
        state.moderationLogs.unshift({
            time: 'Just now',
            action: 'Dismiss Report',
            detail: `Dismissed safety report on ${report.neighborName}.`,
            type: 'info'
        });
    }
    state.reportedAccounts = state.reportedAccounts.filter(r => r.id !== reportId);
    saveState();
    alert("Report dismissed.");
    renderAdminPanel();
}

function handleRemoveReportContent(reportId) {
    playSound('click');
    if (!state.reportedAccounts) return;
    const report = state.reportedAccounts.find(r => r.id === reportId);
    if (!report) return;
    
    if (!state.moderationLogs) state.moderationLogs = [];
    state.moderationLogs.unshift({
        time: 'Just now',
        action: 'Content Removed',
        detail: `Removed ${report.targetType} from ${report.neighborName}.`,
        type: 'warning'
    });

    if (report.targetType === 'post') {
        const target = report.targetId;
        state.userOfferings = state.userOfferings.filter(o => o.id !== target);
        
        for (const name in state.neighbors) {
            const n = state.neighbors[name];
            if (n && (n.offerTitle === target || name === target || n.offerTitle === report.targetId)) {
                n.offerTitle = "[Content Removed by Moderation]";
                n.offerDesc = "This listing was removed due to a violation of our community safety guidelines.";
                n.offerImg = "https://images.unsplash.com/photo-1594322436404-5a0526db4d13?q=60&w=200&auto=format&fit=crop";
            }
        }
        alert("Listing content has been removed.");
    } else if (report.targetType === 'event') {
        if (state.events) {
            state.events = state.events.filter(e => e.id !== report.targetId);
        }
        alert("Event has been removed.");
    } else {
        alert("No specific listing content to remove for this report type.");
    }
    
    state.reportedAccounts = state.reportedAccounts.filter(r => r.id !== reportId);
    saveState();
    refreshAllLayouts();
    renderAdminPanel();
}

function handleSuspendReportUser(reportId) {
    playSound('click');
    if (!state.reportedAccounts) return;
    const report = state.reportedAccounts.find(r => r.id === reportId);
    if (!report) return;
    
    const neighborName = report.neighborName;
    if (!state.moderationLogs) state.moderationLogs = [];
    state.moderationLogs.unshift({
        time: 'Just now',
        action: 'User Suspended',
        detail: `Permanently suspended account: ${neighborName}.`,
        type: 'security'
    });

    if (!state.suspendedUsers) state.suspendedUsers = [];
    if (!state.suspendedUsers.includes(neighborName)) {
        state.suspendedUsers.push(neighborName);
    }
    
    if (state.neighbors[neighborName]) {
        state.neighbors[neighborName].suspended = true;
    }
    
    if (state.events) {
        state.events = state.events.filter(e => e.host !== neighborName);
    }
    
    state.reportedAccounts = state.reportedAccounts.filter(r => r.id !== reportId);
    saveState();
    
    alert(`${neighborName} has been permanently suspended. All their listings, events, and pins have been removed from the platform.`);
    refreshAllLayouts();
    renderAdminPanel();
}

function handleVerifyNoShowStrike(reportId) {
    playSound('click');
    if (!state.reportedAccounts) return;
    const report = state.reportedAccounts.find(r => r.id === reportId);
    if (!report) return;

    const targetName = report.neighborName;
    const reporter = report.reporterName || 'Anonymous Neighbor';

    // 1. Increment strikes and add to noShowReports
    if (state.neighbors && state.neighbors[targetName]) {
        const neighbor = state.neighbors[targetName];
        if (!neighbor.noShowReports) neighbor.noShowReports = [];
        if (!neighbor.noShowReports.includes(reporter)) {
            neighbor.noShowReports.push(reporter);
        }
        neighbor.strikes = (neighbor.strikes || 0) + 1;

        // Create moderation audit log
        if (!state.moderationLogs) state.moderationLogs = [];
        state.moderationLogs.unshift({
            time: 'Just now',
            action: 'No-Show Verified',
            detail: `Verified No-Show report from ${reporter} against ${targetName}. (Strike #${neighbor.strikes})`,
            type: 'warning'
        });

        // 2. Check threshold for shadow-ban
        if (neighbor.strikes >= 3) {
            neighbor.shadowBanned = true;
            state.moderationLogs.unshift({
                time: 'Just now',
                action: 'Shadow-Banned',
                detail: `${targetName} shadow-banned automatically after reaching ${neighbor.strikes} verified No-Show strikes.`,
                type: 'security'
            });
            alert(`Verified strike #${neighbor.strikes} for ${targetName}.\n\n⚠️ Threshold reached! ${targetName} has been automatically shadow-banned from the platform. Their listings and map pins are now hidden from other neighbors.`);
        } else {
            alert(`Verified strike #${neighbor.strikes} for ${targetName}.\n\nThey currently have ${neighbor.strikes}/3 strikes before being shadow-banned.`);
        }
    } else {
        // If it's Lily Kaufmann (Self-simulation)
        const currentUserDisplayName = state.currentUser ? (state.currentUser.displayName || `${state.currentUser.firstName} ${state.currentUser.lastName}`) : 'Lily Kaufmann';
        if (targetName === currentUserDisplayName || targetName === 'Lily Kaufmann') {
            if (!state.currentUser) state.currentUser = {};
            if (!state.currentUser.noShowReports) state.currentUser.noShowReports = [];
            if (!state.currentUser.noShowReports.includes(reporter)) {
                state.currentUser.noShowReports.push(reporter);
            }
            state.currentUser.strikes = (state.currentUser.strikes || 0) + 1;

            if (!state.moderationLogs) state.moderationLogs = [];
            state.moderationLogs.unshift({
                time: 'Just now',
                action: 'No-Show Verified',
                detail: `Verified No-Show report from ${reporter} against Lily Kaufmann. (Strike #${state.currentUser.strikes})`,
                type: 'warning'
            });

            if (state.currentUser.strikes >= 3) {
                state.currentUser.shadowBanned = true;
                state.moderationLogs.unshift({
                    time: 'Just now',
                    action: 'Shadow-Banned',
                    detail: `Lily Kaufmann shadow-banned automatically after reaching ${state.currentUser.strikes} verified No-Show strikes.`,
                    type: 'security'
                });
                alert(`Verified strike #${state.currentUser.strikes} for Lily Kaufmann.\n\n⚠️ Threshold reached! Lily Kaufmann has been automatically shadow-banned from the platform.`);
            } else {
                alert(`Verified strike #${state.currentUser.strikes} for Lily Kaufmann.\n\nLily Kaufmann currently has ${state.currentUser.strikes}/3 strikes before being shadow-banned.`);
            }
        } else {
            alert(`Could not find neighbor account "${targetName}" to apply strike.`);
        }
    }

    // 3. Remove report from active queue
    state.reportedAccounts = state.reportedAccounts.filter(r => r.id !== reportId);
    saveState();
    refreshAllLayouts();
    renderAdminPanel();
}
window.handleVerifyNoShowStrike = handleVerifyNoShowStrike;

function handleSimulateSelfReport() {
    playSound('click');
    if (!state.reportedAccounts) state.reportedAccounts = [];
    
    // Check if we already have these reports
    const countSelf = state.reportedAccounts.filter(r => r.id && r.id.startsWith('rep-self-noshow')).length;
    if (countSelf >= 3) {
        alert("Self-reports already simulated. Check the Active Moderation Tickets queue.");
        return;
    }

    const reporters = ['Sarah Chen', 'Ava', 'Marcus'];
    for (let i = 0; i < 3; i++) {
        state.reportedAccounts.push({
            id: `rep-self-noshow-${i + 1}`,
            neighborName: 'Lily Kaufmann',
            targetType: 'user',
            reasons: ['No-Show'],
            explanation: `Lily Kaufmann failed to arrive at our agreed meeting spot for the swap. No response received. (Simulated test report #${i + 1})`,
            time: 'Just now',
            reporterName: reporters[i],
            status: 'pending'
        });
    }
    
    saveState();
    alert("3 simulated No-Show reports against yourself have been successfully generated and queued in the reports tab!");
    renderAdminPanel();
}
window.handleSimulateSelfReport = handleSimulateSelfReport;

