// Private Address Directory for Autocomplete & Auto-recognition

function initAddressAutocomplete() {
    const inputAddress = document.getElementById('settings-address');
    const autocompleteList = document.getElementById('address-autocomplete-list');
    const inputLoc = document.getElementById('settings-location');

    if (!inputAddress || !autocompleteList) return;

    inputAddress.addEventListener('input', function() {
        const query = this.value.toLowerCase().trim();
        autocompleteList.innerHTML = '';

        if (!query) {
            autocompleteList.classList.add('hidden');
            return;
        }

        const matches = ADDRESS_DIRECTORY.filter(item => 
            item.address.toLowerCase().includes(query)
        );

        if (matches.length === 0) {
            autocompleteList.classList.add('hidden');
            return;
        }

        matches.forEach(item => {
            const div = document.createElement('div');
            div.className = "autocomplete-item p-3 text-xs hover:bg-black/10 dark:hover:bg-white/10 cursor-pointer text-black dark:text-white border-b border-outline-variant/10 last:border-b-0";
            div.innerText = item.address;
            div.addEventListener('click', function() {
                inputAddress.value = item.address;
                if (inputLoc) inputLoc.value = item.neighborhood;
                
                if (!state.currentUser) state.currentUser = {};
                state.currentUser.address = item.address;
                state.currentUser.lat = item.lat;
                state.currentUser.lng = item.lng;
                
                saveState();
                renderHomeDashboard();
                refreshAllLayouts();
                
                if (leafletMap) {
                    leafletMap.setView([item.lat, item.lng], 14, { animate: true });
                }
                
                autocompleteList.classList.add('hidden');
            });
            autocompleteList.appendChild(div);
        });

        autocompleteList.classList.remove('hidden');
    });

    // Hide when clicking outside
    document.addEventListener('click', function(e) {
        if (e.target !== inputAddress && e.target !== autocompleteList && !autocompleteList.contains(e.target)) {
            autocompleteList.classList.add('hidden');
        }
    });
}

