window.selectLocationConsent = function(mode) {
    if (typeof playSound === 'function') playSound('click');
    const modes = ['approximate', 'precise'];
    modes.forEach(m => {
        const btn = document.getElementById(`consent-btn-${m}`);
        if (btn) {
            if (m === mode) {
                btn.className = "w-full h-12 bg-forest-green text-white border border-forest-green font-bold text-xs rounded-xl active:scale-[0.98] transition-all flex items-center justify-start px-6 gap-3 shadow-md cursor-pointer";
            } else {
                btn.className = "w-full h-12 bg-white border border-forest-green/30 text-forest-green font-bold text-xs rounded-xl active:scale-[0.98] transition-all flex items-center justify-start px-6 gap-3 shadow-sm cursor-pointer hover:bg-forest-green/5";
            }
        }
    });
    setTimeout(() => {
        window.grantLocationConsent(mode);
    }, 1000);
};

window.grantLocationConsent = function(mode) {
    window.closeLocationPrivacyModal();
    if (mode === 'manual') {
        if (state.onboardingLocationRequest) {
            state.onboardingLocationRequest = false;
            saveState();
            showView('profile_step_1');
        } else {
            showView('settings_detail');
            setTimeout(() => {
                const input = document.getElementById('settings-address');
                if (input) {
                    input.focus();
                    input.scrollIntoView({ behavior: 'smooth' });
                }
            }, 300);
        }
        return;
    }

    // If onboarding, show an elegant spinner and status update on the main button
    if (state.onboardingLocationRequest) {
        const textCloud = document.getElementById('text-location-cloud');
        const cloudIcon = document.getElementById('icon-location-cloud');
        if (textCloud) textCloud.innerText = 'Enabling Location...';
        if (cloudIcon) {
            cloudIcon.innerText = 'sync';
            cloudIcon.classList.add('animate-spin');
        }
    }

    state.locationConsent = true;
    if (!state.currentUser) state.currentUser = {};
    state.currentUser.locationAccuracy = mode;

    // Simulate GPS coordinates retrieval (Defaulting close to Fairview)
    let baseLat = 49.2608;
    let baseLng = -123.1368;
    
    // Check if browser supports geolocation and we want actual coordinates
    if (navigator.geolocation) {
        let finished = false;
        
        // Fast 750ms fallback timeout to prevent app freeze/hanging
        const fallbackTimeout = setTimeout(() => {
            if (!finished) {
                finished = true;
                console.log("Location request timed out. Falling back to default coordinates.");
                applyFinalCoords(baseLat, baseLng, mode);
            }
        }, 750);

        try {
            navigator.geolocation.getCurrentPosition((position) => {
                if (!finished) {
                    finished = true;
                    clearTimeout(fallbackTimeout);
                    baseLat = position.coords.latitude;
                    baseLng = position.coords.longitude;
                    applyFinalCoords(baseLat, baseLng, mode);
                }
            }, (error) => {
                if (!finished) {
                    finished = true;
                    clearTimeout(fallbackTimeout);
                    console.warn("GPS failed, using mock coordinates: ", error);
                    applyFinalCoords(baseLat, baseLng, mode);
                }
            }, { 
                timeout: 700, 
                enableHighAccuracy: (mode === 'precise') 
            });
        } catch (err) {
            console.warn("Synchronous geolocation check failed, using fallback:", err);
            if (!finished) {
                finished = true;
                clearTimeout(fallbackTimeout);
                applyFinalCoords(baseLat, baseLng, mode);
            }
        }
    } else {
        applyFinalCoords(baseLat, baseLng, mode);
    }
};

function applyFinalCoords(lat, lng, mode) {
    try {
        let finalLat = parseFloat(lat);
        let finalLng = parseFloat(lng);
        
        // Obfuscation fuzzing formula: only apply to approximate mode
        if (mode === 'approximate') {
            const radius = (state && state.config && state.config.fuzzingRadius) ? state.config.fuzzingRadius : 250;
            const multiplier = radius / 250;
            const latOffset = (Math.random() * 0.0016 + 0.0012) * (Math.random() > 0.5 ? 1 : -1) * multiplier;
            const lngOffset = (Math.random() * 0.0022 + 0.0016) * (Math.random() > 0.5 ? 1 : -1) * multiplier;
            finalLat = parseFloat(lat) + latOffset;
            finalLng = parseFloat(lng) + lngOffset;
        }
        
        if (!state) state = {};
        if (!state.currentUser) state.currentUser = {};
        state.currentUser.lat = finalLat;
        state.currentUser.lng = finalLng;
        state.currentUser.locationAccuracy = mode;
        
        // Update accuracy selector in DOM
        const accuracySelect = document.getElementById('settings-location-accuracy');
        const gpsToggle = document.getElementById('settings-location-gps');
        if (accuracySelect) accuracySelect.value = mode;
        if (gpsToggle) gpsToggle.checked = true;
        
        saveState();
        
        // Update map marker dynamically
        if (leafletMap) {
            refreshAllLayouts();
            leafletMap.setView([finalLat, finalLng], 15, { animate: true });
        }
        
        if (state.onboardingLocationRequest) {
            state.onboardingLocationRequest = false;
            saveState();
            
            const cloudIcon = document.getElementById('icon-location-cloud');
            const textCloud = document.getElementById('text-location-cloud');
            const locationBtn = document.getElementById('btn-onboarding-location-permission');
            
            if (cloudIcon) {
                cloudIcon.innerText = 'cloud_done';
                cloudIcon.classList.remove('animate-spin');
                cloudIcon.classList.remove('text-green-400');
                cloudIcon.classList.add('text-white');
            }
            if (locationBtn) {
                locationBtn.classList.remove('bg-forest-green');
                locationBtn.classList.add('bg-[#15803d]');
            }
            if (textCloud) {
                textCloud.innerHTML = 'Location Permission Enabled <span style="margin-left: 8px; font-weight: bold;">✓</span>';
            }
            if (mode !== 'precise') {
                if (typeof triggerSuccessConfetti === 'function') {
                    triggerSuccessConfetti();
                }
            }
            
            // Auto transition to manual neighborhood selection view after brief delay
            setTimeout(() => {
                showView('profile_step_1');
            }, 2000);
        } else {
            console.log(`Success: Location access enabled using ${mode} accuracy mode.`);
        }
    } catch (err) {
        console.error("Error in applyFinalCoords:", err);
        // Direct fallback to showing profile_step_1 to ensure user is not stuck on a frozen page
        setTimeout(() => {
            showView('profile_step_1');
        }, 1000);
    }
}

