window.handleLeaveReviewFromDropdown = function() {
    window.closeStatusDropdownMenu();
    if (state.currentConversationId) {
        const conv = state.conversations.find(c => c.id === state.currentConversationId);
        if (conv && !conv.isGroup) {
            if (!conv.negotiation || conv.negotiation.status !== 'completed') {
                alert("You can only review after the trade is completed.");
                return;
            }
            if (conv.reviewed) {
                alert("You have already reviewed this trade.");
                return;
            }
            openNeighborReviewModal(conv.neighborName);
        }
    }
};

window.handleCompleteTradeDropdown = function() {
    window.closeConfirmationsDropdownMenu();
    
    // Find active conversation matching the active profile neighbor or current conversation
    let activeConvId = state.currentConversationId;
    if (state.activeProfileNeighborName) {
        const conv = state.conversations.find(c => !c.isGroup && c.neighborName === state.activeProfileNeighborName);
        if (conv) activeConvId = conv.id;
    }
    
    const conv = state.conversations.find(c => c.id === activeConvId);
    if (!conv) return;
    
    conv.negotiation.status = 'completed';
    
    // Record in swapHistory
    if (!state.swapHistory) state.swapHistory = [];
    state.swapHistory.unshift({
        neighborName: conv.neighborName,
        offeredItem: conv.negotiation.offeredItem || 'Tutoring',
        requestedItem: conv.negotiation.requestedItem || 'Swap',
        date: 'Just now'
    });
    
    // Delete the chat (Disabled per request)
    // state.conversations = state.conversations.filter(c => c.id !== conv.id);
    
    state.stats.tradesMade += 1;
    const pts = conv.negotiation.isKarmaSwap ? 10 : 5;
    addKarmaXP(pts);
    saveState();
    
    // Close the profile modal so they see the success celebration!
    closeNeighborProfileModal();
    
    showTradeCelebrationOverlay(conv);
    showView('chat_hub');
    renderConversationsList();
    // Trigger push notification after 5s
    setTimeout(() => {
        triggerPushNotification(
            "Review Reminder",
            `Your swap with ${conv.neighborName} is complete. Leave a review to share your experience!`,
            "rate_review",
            "chat_hub"
        );
    }, 5000);
};

