window.toggleGlobalTheme = function() {
    if (typeof playSound === 'function') playSound('click');
    const html = document.documentElement;
    const isDark = html.classList.contains('dark');
    const checked = !isDark;
    
    // Toggle checkbox in settings if visible
    const settingsCheckbox = document.getElementById('settings-toggle-dark');
    if (settingsCheckbox) settingsCheckbox.checked = checked;

    if (typeof handleToggleDarkMode === 'function') {
        handleToggleDarkMode(checked);
    } else {
        if (checked) {
            html.classList.add('dark');
        } else {
            html.classList.remove('dark');
        }
    }

    // Sync the icon inside desktop-navbar
    const btn = document.getElementById('global-theme-toggle-btn');
    if (btn) {
        const icon = btn.querySelector('.material-symbols-outlined');
        if (icon) {
            icon.textContent = checked ? 'dark_mode' : 'light_mode';
        }
    }
};

