function hideHomeCategory(event, id) {
    if (event) {
        event.stopPropagation();
        event.preventDefault();
    }
    const el = document.getElementById(id);
    if (el) el.classList.add('hidden');
    let hidden = [];
    try {
        const stored = safeLocalStorage.getItem('barterland_hidden_categories');
        if (stored) hidden = JSON.parse(stored);
    } catch(e) {}
    if (!hidden.includes(id)) {
        hidden.push(id);
    }
    safeLocalStorage.setItem('barterland_hidden_categories', JSON.stringify(hidden));
    const resetBtn = document.getElementById('reset-categories-btn');
    if (resetBtn) resetBtn.classList.remove('hidden');
}

function resetCategories() {
    let hidden = [];
    try {
        const stored = safeLocalStorage.getItem('barterland_hidden_categories');
        if (stored) hidden = JSON.parse(stored);
    } catch(e) {}
    hidden.forEach(id => {
        const el = document.getElementById(id);
        if (el) el.classList.remove('hidden');
    });
    safeLocalStorage.removeItem('barterland_hidden_categories');
    const resetBtn = document.getElementById('reset-categories-btn');
    if (resetBtn) resetBtn.classList.add('hidden');
}

function initHomeCategories() {
    let hidden = [];
    try {
        const stored = safeLocalStorage.getItem('barterland_hidden_categories');
        if (stored) hidden = JSON.parse(stored);
    } catch(e) {}
    hidden.forEach(id => {
        const el = document.getElementById(id);
        if (el) el.classList.add('hidden');
    });
    const resetBtn = document.getElementById('reset-categories-btn');
    if (resetBtn) {
        if (hidden.length > 0) {
            resetBtn.classList.remove('hidden');
        } else {
            resetBtn.classList.add('hidden');
        }
    }
}

window.hideHomeCategory = hideHomeCategory;
window.resetCategories = resetCategories;
window.initHomeCategories = initHomeCategories;

