window.selectDynamicSuboption = function(optionName) {
    playSound('click');
    selectedSuboption = optionName;
    
    const presets = document.getElementById('dynamic-suboptions-presets');
    if (presets) {
        presets.querySelectorAll('.dyn-opt-btn').forEach(btn => {
            if (btn.getAttribute('data-option') === optionName) {
                btn.classList.add('bg-forest-green', 'text-warm-cream', 'border-forest-green');
                btn.classList.remove('bg-white', 'text-forest-green', 'border-outline-variant/30');
            } else {
                btn.classList.remove('bg-forest-green', 'text-warm-cream', 'border-forest-green');
                btn.classList.add('bg-white', 'text-forest-green', 'border-outline-variant/30');
            }
        });
    }

    if (optionName === 'Other') {
        const customWritein = document.getElementById('subcategory-custom-writein');
        const customInput = document.getElementById('subcategory-custom-text-input');
        if (customWritein) customWritein.classList.remove('hidden');
        if (customInput) {
            customInput.focus();
            customInput.placeholder = "Specify details for your swap...";
        }
    }
};

const PRESET_LANGUAGES = ['English', 'Spanish', 'French', 'Japanese', 'Mandarin', 'Cantonese', 'German', 'Korean', 'Italian', 'Arabic', 'Portuguese', 'Hindi', 'Russian', 'Turkish', 'Vietnamese', 'Thai', 'Greek', 'Hebrew', 'Swedish', 'Dutch'];
const PRESET_SHOES = ['Running Shoes', 'Hiking Boots', 'Climbing Shoes', 'Sneakers', 'Rain Boots', 'Sandals', 'Flip Flops', 'Dress Shoes', 'High Heels', 'Loafers', 'Slippers', 'Snow Boots', 'Tennis Shoes', 'Canvas Shoes'];
const PRESET_GENERAL = ['Sourdough Starter', 'Homegrown Kale', 'Balcony Tomatoes', 'Fresh Preserves', 'Handmade Jam', 'Bicycle Tuning', 'Furniture Assembly', 'Baking Assistance', 'Guitar Lessons', 'Math Tutoring'];

function selectLanguageOption(lang) {
    playSound('click');
    selectedLanguage = lang;
    document.querySelectorAll('.lang-opt-btn').forEach(btn => {
        const btnText = btn.textContent.trim();
        if (btnText === lang) {
            btn.classList.add('bg-forest-green', 'text-warm-cream', 'border-forest-green');
            btn.classList.remove('bg-white', 'text-forest-green', 'border-outline-variant/30');
        } else {
            btn.classList.remove('bg-forest-green', 'text-warm-cream', 'border-forest-green');
            btn.classList.add('bg-white', 'text-forest-green', 'border-outline-variant/30');
        }
    });
    // Clear custom write-in if preset selected
    const customIn = document.getElementById('language-custom-input');
    if (customIn) customIn.value = '';
    const suggestions = document.getElementById('language-custom-suggestions');
    if (suggestions) suggestions.innerHTML = '';
}
window.selectLanguageOption = selectLanguageOption;

function handleLanguageCustomInput(val) {
    selectedLanguage = val;
    // Unhighlight preset buttons
    document.querySelectorAll('.lang-opt-btn').forEach(btn => {
        btn.classList.remove('bg-forest-green', 'text-warm-cream', 'border-forest-green');
        btn.classList.add('bg-white', 'text-forest-green', 'border-outline-variant/30');
    });

    const suggestions = document.getElementById('language-custom-suggestions');
    if (!suggestions) return;
    suggestions.innerHTML = '';

    if (!val) return;
    const query = val.toLowerCase();
    const matched = PRESET_LANGUAGES.filter(lang => lang.toLowerCase().startsWith(query) && lang.toLowerCase() !== query);
    matched.slice(0, 4).forEach(lang => {
        const badge = document.createElement('span');
        badge.className = 'px-2 py-1 bg-forest-green/10 text-forest-green border border-forest-green/20 rounded-lg text-[10px] font-bold cursor-pointer active:scale-95 transition-transform hover:bg-forest-green/20';
        badge.innerText = lang;
        badge.onclick = () => {
            const customIn = document.getElementById('language-custom-input');
            if (customIn) customIn.value = lang;
            selectLanguageOption(lang);
        };
        suggestions.appendChild(badge);
    });
}
window.handleLanguageCustomInput = handleLanguageCustomInput;

function selectShoesOption(subType, val) {
    playSound('click');
    if (subType === 'type') {
        shoeSelections.type = val;
        document.querySelectorAll('.shoes-opt-btn').forEach(btn => {
            const btnText = btn.textContent.trim();
            if (btnText === val) {
                btn.classList.add('bg-forest-green', 'text-warm-cream', 'border-forest-green');
                btn.classList.remove('bg-white', 'text-forest-green', 'border-outline-variant/30');
            } else {
                btn.classList.remove('bg-forest-green', 'text-warm-cream', 'border-forest-green');
                btn.classList.add('bg-white', 'text-forest-green', 'border-outline-variant/30');
            }
        });
        const container = document.getElementById('shoes-custom-type-container');
        if (container) {
            if (val === 'Other') {
                container.classList.remove('hidden');
            } else {
                container.classList.add('hidden');
                shoeSelections.custom = '';
                const customIn = document.getElementById('shoes-custom-type-input');
                if (customIn) customIn.value = '';
                const sugg = document.getElementById('shoes-custom-suggestions');
                if (sugg) sugg.innerHTML = '';
            }
        }
    } else if (subType === 'size') {
        shoeSelections.size = val;
        document.querySelectorAll('.shoes-size-btn').forEach(btn => {
            const btnText = btn.textContent.trim();
            if (btnText === val || btnText === val.replace('US ', '')) {
                btn.classList.add('bg-forest-green', 'text-warm-cream', 'border-forest-green');
                btn.classList.remove('bg-white', 'text-forest-green', 'border-outline-variant/30');
            } else {
                btn.classList.remove('bg-forest-green', 'text-warm-cream', 'border-forest-green');
                btn.classList.add('bg-white', 'text-forest-green', 'border-outline-variant/30');
            }
        });
    }
}
window.selectShoesOption = selectShoesOption;

window.updateShoeSizes = function() {
    const sizeContainer = document.getElementById('shoes-size-select');
    if (!sizeContainer) return;

    // Check currently selected gender/style
    const gender = clothesSelections.gender || '';
    
    let sizes = [];
    if (gender === 'Kids') {
        sizes = ['Toddler-4', 'Toddler-6', 'Toddler-8', 'Youth-1', 'Youth-3', 'Youth-5'];
    } else if (gender === 'Women') {
        sizes = ['US 5', 'US 6', 'US 7', 'US 8', 'US 9', 'US 10'];
    } else if (gender === 'Men') {
        sizes = ['US 7', 'US 8', 'US 9', 'US 10', 'US 11', 'US 12'];
    } else {
        // Fallback default
        sizes = ['US 5', 'US 6', 'US 7', 'US 8', 'US 9', 'US 10', 'US 11', 'US 12'];
    }

    sizeContainer.innerHTML = '';
    sizes.forEach(sz => {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'shoes-size-btn p-3 bg-white dark:bg-[#18201a] border border-outline-variant/30 dark:border-outline-variant/15 rounded-xl text-forest-green dark:text-[#308A5E] font-semibold text-xs text-center active:scale-95 transition-all cursor-pointer shadow-sm';
        const label = sz.replace('US ', '');
        btn.innerHTML = `<span>${label}</span>`;
        btn.onclick = () => selectShoesOption('size', sz);
        
        // If this size is currently selected, highlight it
        if (shoeSelections.size === sz) {
            btn.classList.add('bg-forest-green', 'text-warm-cream', 'border-forest-green');
            btn.classList.remove('bg-white', 'text-forest-green');
        }
        sizeContainer.appendChild(btn);
    });
};

function handleShoesCustomInput(val) {
    shoeSelections.custom = val;
    const suggestions = document.getElementById('shoes-custom-suggestions');
    if (!suggestions) return;
    suggestions.innerHTML = '';

    if (!val) return;
    const query = val.toLowerCase();
    const matched = PRESET_SHOES.filter(shoe => shoe.toLowerCase().startsWith(query) && shoe.toLowerCase() !== query);
    matched.slice(0, 4).forEach(shoe => {
        const badge = document.createElement('span');
        badge.className = 'px-2 py-1 bg-forest-green/10 text-forest-green border border-forest-green/20 rounded-lg text-[10px] font-bold cursor-pointer active:scale-95 transition-transform hover:bg-forest-green/20';
        badge.innerText = shoe;
        badge.onclick = () => {
            const customIn = document.getElementById('shoes-custom-type-input');
            if (customIn) customIn.value = shoe;
            shoeSelections.custom = shoe;
            suggestions.innerHTML = '';
        };
        suggestions.appendChild(badge);
    });
}
window.handleShoesCustomInput = handleShoesCustomInput;

function handleGeneralCustomInput(val) {
    subcategoryCustomText = val;
    // Unhighlight standard subcategory items
    const optionsContainer = document.getElementById('subcategory-options-container');
    if (optionsContainer) {
        optionsContainer.querySelectorAll('.sub-opt-btn').forEach(btn => {
            btn.classList.remove('bg-forest-green', 'text-warm-cream', 'border-forest-green');
            btn.classList.add('bg-white', 'text-forest-green', 'border-outline-variant/30');
        });
        selectedSubcategoryName = '';
    }

    const suggestions = document.getElementById('subcategory-custom-text-suggestions');
    if (!suggestions) return;
    suggestions.innerHTML = '';

    if (!val) return;
    const query = val.toLowerCase();
    const matched = PRESET_GENERAL.filter(item => item.toLowerCase().startsWith(query) && item.toLowerCase() !== query);
    matched.slice(0, 4).forEach(item => {
        const badge = document.createElement('span');
        badge.className = 'px-2 py-1 bg-forest-green/10 text-forest-green border border-forest-green/20 rounded-lg text-[10px] font-bold cursor-pointer active:scale-95 transition-transform hover:bg-forest-green/20';
        badge.innerText = item;
        badge.onclick = () => {
            const customIn = document.getElementById('subcategory-custom-text-input');
            if (customIn) customIn.value = item;
            subcategoryCustomText = item;
            suggestions.innerHTML = '';
        };
        suggestions.appendChild(badge);
    });
}
window.handleGeneralCustomInput = handleGeneralCustomInput;

function openSubcategoryModal(categoryName) {
    currentSubcategoryCategory = categoryName;
    selectedSubcategoryName = '';
    selectedLanguage = '';
    shoeSelections = { type: '', size: '', custom: '' };
    subcategoryCustomText = '';
    
    // Clear inputs in HTML
    const langIn = document.getElementById('language-custom-input');
    if (langIn) langIn.value = '';
    const langSugg = document.getElementById('language-custom-suggestions');
    if (langSugg) langSugg.innerHTML = '';
    
    const shoeIn = document.getElementById('shoes-custom-type-input');
    if (shoeIn) shoeIn.value = '';
    const shoeSugg = document.getElementById('shoes-custom-suggestions');
    if (shoeSugg) shoeSugg.innerHTML = '';

    const genIn = document.getElementById('subcategory-custom-text-input');
    if (genIn) genIn.value = '';
    const genSugg = document.getElementById('subcategory-custom-text-suggestions');
    if (genSugg) genSugg.innerHTML = '';
    clothesSelections = { type: '', gender: '', age: '' };
    document.querySelectorAll('.clothes-opt-btn').forEach(btn => {
        btn.classList.remove('bg-forest-green', 'text-warm-cream', 'border-forest-green');
        btn.classList.add('bg-white', 'text-forest-green', 'border-outline-variant/30');
    });
    if (typeof updateShoeSizes === 'function') {
        updateShoeSizes();
    }

    document.querySelectorAll('.shoes-opt-btn').forEach(btn => {
        btn.classList.remove('bg-forest-green', 'text-warm-cream', 'border-forest-green');
        btn.classList.add('bg-white', 'text-forest-green', 'border-outline-variant/30');
    });

    document.querySelectorAll('.shoes-size-btn').forEach(btn => {
        btn.classList.remove('bg-forest-green', 'text-warm-cream', 'border-forest-green');
        btn.classList.add('bg-white', 'text-forest-green', 'border-outline-variant/30');
    });

    document.querySelectorAll('.lang-opt-btn').forEach(btn => {
        btn.classList.remove('bg-forest-green', 'text-warm-cream', 'border-forest-green');
        btn.classList.add('bg-white', 'text-forest-green', 'border-outline-variant/30');
    });

    const modal = document.getElementById('subcategory-modal');
    const title = document.getElementById('subcategory-modal-title');
    const desc = document.getElementById('subcategory-modal-desc');
    const optionsContainer = document.getElementById('subcategory-options-container');
    const clothesForm = document.getElementById('clothes-narrow-form');
    const languageForm = document.getElementById('language-narrow-form');
    const shoeSection = document.getElementById('clothes-shoe-details-section');
    const shoesCustomContainer = document.getElementById('shoes-custom-type-container');

    selectedSuboption = '';
    const dynForm = document.getElementById('dynamic-suboptions-narrow-form');
    if (dynForm) dynForm.classList.add('hidden');
    const dynPresets = document.getElementById('dynamic-suboptions-presets');
    if (dynPresets) dynPresets.innerHTML = '';

    if (languageForm) languageForm.classList.add('hidden');
    if (shoeSection) shoeSection.classList.add('hidden');
    if (shoesCustomContainer) shoesCustomContainer.classList.add('hidden');

    if (!modal) return;

    const displayCategoryMap = {
        'Food & Drink': 'Food & Drink',
        'Home and Living': 'Home & Living',
        'Home, Living & Gear': 'Home & Living',
        'Garden & Outdoors': 'Garden & Outdoors',
        'Skills & Education': 'Skills & Education',
        'Handyman & Services': 'Handyman & Services',
        'Creative & Art': 'Creative & Art',
        'Health': 'Health',
        'Clothing & Apparel': 'Clothing & Apparel',
        'Clothes': 'Clothing & Apparel',
        'Books, Games, Entertainment': 'Books & Games',
        'Kids, Puzzles & Books': 'Kids & Books',
        'Kids and Maternity': 'Kids & Maternity',
        'Kids': 'Kids & Maternity',
        'Maternity': 'Kids & Maternity',
        'Event or Meetup': 'Event or Meetup',
        'Language or Info Exchange': 'Language & Info',
        'Other': 'Other'
    };
    const mappedTitleName = displayCategoryMap[categoryName] || categoryName;
    title.innerText = mappedTitleName;
    desc.innerText = `Choose a specific sub-category for your listing.`;

    if (optionsContainer) {
        optionsContainer.innerHTML = '';
        const subs = SUBCATEGORIES_MAP[categoryName] || [];
        subs.forEach(sub => {
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.setAttribute('data-category', categoryName);
            btn.className = 'sub-opt-btn p-3 bg-white dark:bg-[#18201a] border border-outline-variant/30 dark:border-outline-variant/15 rounded-xl text-forest-green dark:text-warm-cream font-semibold text-xs flex items-center gap-2 hover:bg-forest-green/5 active:scale-95 transition-all w-full select-none shadow-sm';
            btn.innerHTML = `
                <span class="material-symbols-outlined text-base flex-shrink-0 sub-icon-${sub.icon}">${sub.icon}</span>
                <span class="leading-tight text-xs text-left">${sub.name}</span>
            `;
            btn.onclick = () => selectSubcategoryItem(sub.name, btn);
            optionsContainer.appendChild(btn);
        });
    }

    if (categoryName === 'Clothing & Apparel' || categoryName === 'Clothes') {
        if (clothesForm) clothesForm.classList.remove('hidden');
        if (optionsContainer) optionsContainer.classList.add('hidden');
    } else {
        if (clothesForm) clothesForm.classList.add('hidden');
        if (optionsContainer) optionsContainer.classList.remove('hidden');
    }

    modal.classList.remove('hidden');
}

function closeSubcategoryModal() {
    playSound('click');
    const modal = document.getElementById('subcategory-modal');
    if (modal) modal.classList.add('hidden');
}

function selectSubcategoryItem(itemName, btnElement) {
    playSound('click');
    selectedSubcategoryName = itemName;
    
    const container = document.getElementById('subcategory-options-container');
    if (container) {
        container.querySelectorAll('.sub-opt-btn').forEach(btn => {
            btn.classList.remove('bg-forest-green', 'text-warm-cream', 'border-forest-green');
            btn.classList.add('bg-white', 'text-forest-green', 'border-outline-variant/30');
        });
    }
    if (btnElement) {
        btnElement.classList.add('bg-forest-green', 'text-warm-cream', 'border-forest-green');
        btnElement.classList.remove('bg-white', 'text-forest-green', 'border-outline-variant/30');
    }

    // Toggle language subform - bypassed for new dynamic suboptions form
    const languageForm = document.getElementById('language-narrow-form');
    if (languageForm) languageForm.classList.add('hidden');

    // Toggle dynamic sub-options presets form if option has suboptions
    const dynForm = document.getElementById('dynamic-suboptions-narrow-form');
    const dynPresets = document.getElementById('dynamic-suboptions-presets');
    const dynLabel = document.getElementById('dynamic-suboptions-label');
    
    selectedSuboption = '';
    
    if (dynForm && dynPresets) {
        const options = SUBOPTIONS_MAP[itemName];
        if (options && options.length > 0) {
            if (dynLabel) dynLabel.innerText = `Select details for ${itemName}`;
            dynPresets.innerHTML = '';
            
            options.forEach(opt => {
                const btn = document.createElement('button');
                btn.type = 'button';
                btn.className = 'dyn-opt-btn p-3 bg-white dark:bg-[#18201a] border border-outline-variant/30 dark:border-outline-variant/15 rounded-xl text-forest-green dark:text-warm-cream font-semibold text-xs text-center active:scale-95 transition-all cursor-pointer shadow-sm';
                btn.setAttribute('data-option', opt);
                btn.innerHTML = `<span>${opt}</span>`;
                btn.onclick = () => selectDynamicSuboption(opt);
                dynPresets.appendChild(btn);
            });

            // Append Other button at the end of presets
            const otherBtn = document.createElement('button');
            otherBtn.type = 'button';
            otherBtn.className = 'dyn-opt-btn p-3 bg-white dark:bg-[#18201a] border border-outline-variant/30 dark:border-outline-variant/15 rounded-xl text-forest-green dark:text-warm-cream font-semibold text-xs text-center active:scale-95 transition-all cursor-pointer shadow-sm';
            otherBtn.setAttribute('data-option', 'Other');
            otherBtn.innerHTML = '<span>Other</span>';
            otherBtn.onclick = () => selectDynamicSuboption('Other');
            dynPresets.appendChild(otherBtn);

            dynForm.classList.remove('hidden');
        } else {
            dynForm.classList.add('hidden');
        }
    }

    if (itemName === 'Other') {
        const customWritein = document.getElementById('subcategory-custom-writein');
        const customInput = document.getElementById('subcategory-custom-text-input');
        if (customWritein) customWritein.classList.remove('hidden');
        if (customInput) {
            customInput.focus();
            customInput.placeholder = "Specify details for your swap...";
        }
    }
}

function selectClothesOption(optionType, value) {
    playSound('click');
    clothesSelections[optionType] = value;

    let groupContainerId = '';
    if (optionType === 'type') groupContainerId = 'clothes-type-select';
    else if (optionType === 'gender') groupContainerId = 'clothes-gender-select';
    else if (optionType === 'age') groupContainerId = 'clothes-age-select';

    const group = document.getElementById(groupContainerId);
    if (group) {
        group.querySelectorAll('.clothes-opt-btn').forEach(btn => {
            const btnText = btn.textContent.trim();
            if (btnText === value) {
                btn.classList.add('bg-forest-green', 'text-warm-cream', 'border-forest-green');
                btn.classList.remove('bg-white', 'text-forest-green', 'border-outline-variant/30');
            } else {
                btn.classList.remove('bg-forest-green', 'text-warm-cream', 'border-forest-green');
                btn.classList.add('bg-white', 'text-forest-green', 'border-outline-variant/30');
            }
        });
    }

    // Show shoes specific section if type is Shoes
    if (optionType === 'type') {
        const shoeSection = document.getElementById('clothes-shoe-details-section');
        if (shoeSection) {
            if (value === 'Shoes') {
                shoeSection.classList.remove('hidden');
            } else {
                shoeSection.classList.add('hidden');
                shoeSelections = { type: '', size: '', custom: '' };
            }
        }
    }

    if (optionType === 'gender') {
        if (typeof updateShoeSizes === 'function') {
            updateShoeSizes();
        }
    }
}

function handleSubcategorySave() {
    playSound('click');
    
    let finalChoice = '';
    
    // Check if Language Practice sub-menu is active
    const isLanguageActive = selectedSubcategoryName === 'Language Practice';
    
    if (currentSubcategoryCategory === 'Clothing & Apparel' || currentSubcategoryCategory === 'Clothes') {
        const parts = [];
        if (clothesSelections.age) parts.push(clothesSelections.age);
        if (clothesSelections.gender) parts.push(clothesSelections.gender);
        
        if (clothesSelections.type === 'Shoes') {
            const shoeType = shoeSelections.type === 'Other' ? (shoeSelections.custom || 'Shoes') : (shoeSelections.type || 'Shoes');
            parts.push(shoeType);
            if (shoeSelections.size) parts.push(`(Size ${shoeSelections.size.replace('US ', '')})`);
        } else {
            if (clothesSelections.type) parts.push(clothesSelections.type);
        }
        
        if (parts.length === 0) {
            alert('Please select at least one clothing detail.');
            return;
        }
        finalChoice = parts.join(' ');
    } else if (selectedSuboption) {
        finalChoice = `${selectedSubcategoryName} (${selectedSuboption})`;
    } else if (subcategoryCustomText) {
        finalChoice = subcategoryCustomText;
    } else {
        if (!selectedSubcategoryName) {
            alert('Please select a sub-category.');
            return;
        }
        finalChoice = selectedSubcategoryName;
    }

    if (currentSubcategoryContext === 'offer') {
        const titleInput = document.getElementById('offer-title');
        if (titleInput) {
            titleInput.value = finalChoice;
        }
        if (typeof renderOfferSelectedDetailsSummary === 'function') {
            renderOfferSelectedDetailsSummary();
        }
    } else if (currentSubcategoryContext === 'wizard-skills') {
        loadWizardCategoryChips('skills', currentSubcategoryCategory);
        const input = document.getElementById('custom-skill-tag-input');
        if (input) {
            input.value = finalChoice;
            addCustomSetupTag('skills');
            input.value = '';
        }
    } else if (currentSubcategoryContext === 'wizard-needs') {
        loadWizardCategoryChips('needs', currentSubcategoryCategory);
        const input = document.getElementById('custom-need-tag-input');
        if (input) {
            input.value = finalChoice;
            addCustomSetupTag('needs');
            input.value = '';
        }
    }

    closeSubcategoryModal();
}

