function handleOfferNeighborNeedDirect(neighborName, needTitle) {
    playSound('click');
    closeNeighborProfileModal();

    let conv = state.conversations.find(c => c.neighborName === neighborName);
    const textMsg = `Hi ${neighborName}! I saw you need "${needTitle}". I'd love to help out with that. Let's trade!`;
    
    if (!conv) {
        conv = {
            id: neighborName.toLowerCase().replace(/\s+/g, '-'),
            neighborName: neighborName,
            unread: false,
            timeLeft: '48 hours left',
            messages: [
                { sender: 'me', text: textMsg, time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) }
            ],
            negotiation: {
                status: 'none',
                offeredItem: null,
                requestedItem: needTitle
            }
        };
        state.conversations.unshift(conv);
    } else {
        conv.messages.push({
            sender: 'me',
            text: textMsg,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        });
        conv.negotiation.requestedItem = needTitle;
        state.conversations = [conv, ...state.conversations.filter(c => c.id !== conv.id)];
    }

    saveState();
    state.currentConversationId = conv.id;
    
    renderChatDetail(conv);
    showView('chat_detail');

    setTimeout(() => {
        openSwapProposalPage();
    }, 450);
}

