function deductKarmaPoints(userName, amount) {
    if (userName === 'me' || userName === (state.currentUser && state.currentUser.email)) {
        if (state.xp === undefined) state.xp = 50;
        if (state.level === undefined) state.level = 1;
        let totalXP = (state.level - 1) * 100 + state.xp;
        totalXP = Math.max(0, totalXP - amount);
        state.level = Math.floor(totalXP / 100) + 1;
        state.xp = totalXP % 100;
        updateProfileXPDisplay();
    } else {
        const neighbor = state.neighbors[userName];
        if (neighbor) {
            if (neighbor.xp === undefined) neighbor.xp = 50;
            if (neighbor.level === undefined) neighbor.level = 1;
            let totalXP = (neighbor.level - 1) * 100 + neighbor.xp;
            totalXP = Math.max(0, totalXP - amount);
            neighbor.level = Math.floor(totalXP / 100) + 1;
            neighbor.xp = totalXP % 100;
        }
    }
    saveState();
}

function suspendUser(userName) {
    if (userName === 'me' || userName === (state.currentUser && state.currentUser.email) || userName === (state.currentUser && state.currentUser.displayName)) {
        if (!state.suspendedUsers) state.suspendedUsers = [];
        const myName = state.currentUser ? state.currentUser.displayName : 'Lily Kaufmann';
        if (!state.suspendedUsers.includes(myName)) {
            state.suspendedUsers.push(myName);
        }
        const myEmail = state.currentUser ? state.currentUser.email : 'lily@community.com';
        if (!state.suspendedUsers.includes(myEmail)) {
            state.suspendedUsers.push(myEmail);
        }
        if (state.currentUser) {
            state.currentUser.suspended = true;
            state.currentUser.strikes = 5;
        }
        state.userOfferings.forEach(off => {
            off.active = false;
        });
        saveState();
        alert("Your account has been suspended for repeated unreliability (5 no-show strikes). An email notification has been sent to your registered address.");
        handleLogout();
    } else {
        if (!state.suspendedUsers) state.suspendedUsers = [];
        if (!state.suspendedUsers.includes(userName)) {
            state.suspendedUsers.push(userName);
        }
        if (state.neighbors[userName]) {
            state.neighbors[userName].suspended = true;
            state.neighbors[userName].strikes = 5;
        }
        saveState();
        console.log(`[EMAIL SERVICE] Automated suspension email sent to ${userName} due to 5 No-Show strikes.`);
    }
}

function addStrikeToUser(userName) {
    if (userName === 'me' || userName === (state.currentUser && state.currentUser.email)) {
        if (!state.currentUser) state.currentUser = {};
        state.currentUser.strikes = (state.currentUser.strikes || 0) + 1;
        saveState();
        if (state.currentUser.strikes >= 5) {
            suspendUser('me');
        }
    } else {
        const neighbor = state.neighbors[userName];
        if (neighbor) {
            neighbor.strikes = (neighbor.strikes || 0) + 1;
            saveState();
            if (neighbor.strikes >= 5) {
                suspendUser(userName);
            }
        }
    }
}

function submitNoShowReport() {
    const conv = state.conversations.find(c => c.id === state.currentConversationId);
    if (!conv) return;
    
    const neighborName = conv.neighborName;
    
    // Log Strike and Deduct 50 Karma
    addStrikeToUser(neighborName);
    deductKarmaPoints(neighborName, 50);
    
    // Revert Trade Status to none
    conv.negotiation.status = 'none';
    
    // Push system logs/messages
    conv.messages.push({
        sender: 'System',
        text: `Trade cancelled. Report filed: ${neighborName} did not arrive. Listing is reverted back to Available.`,
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    });
    
    saveState();
    closeConfirmNoShowModal();
    renderChatDetail(conv);
    playSound('error');
    
    alert(`No-Show report submitted. 1 strike issued against ${neighborName} (-50 Karma). Listing is now Active.`);
}

function confirmCheckIn(convId, btn) {
    const conv = state.conversations.find(c => c.id === convId);
    if (!conv) return;
    
    const checkInMsg = conv.messages.find(m => m.isCheckIn && !m.checkInConfirmed);
    if (checkInMsg) {
        checkInMsg.checkInConfirmed = true;
        saveState();
        playSound('success');
        renderChatDetail(conv);
    }
}

function cancelCheckIn(convId) {
    const conv = state.conversations.find(c => c.id === convId);
    if (!conv) return;
    
    // Dissolve trade safely
    conv.negotiation.status = 'none';
    
    // Record user cancelled trade stats for reliability calculations
    if (!state.currentUser) state.currentUser = {};
    state.currentUser.cancelledTrades = (state.currentUser.cancelledTrades || 0) + 1;
    
    const neighborName = conv.neighborName;
    if (state.neighbors[neighborName]) {
        state.neighbors[neighborName].cancelledTrades = (state.neighbors[neighborName].cancelledTrades || 0) + 1;
    }
    
    conv.messages.push({
        sender: 'System',
        text: 'Trade dissolved. No penalties issued. Listing is reverted back to Available.',
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    });
    
    saveState();
    playSound('click');
    renderChatDetail(conv);
}

