function getActiveSuggestionsInfo() {
    const activeEl = document.activeElement;
    if (activeEl) {
        if (activeEl.id === 'village-search-input') {
            return {
                input: activeEl,
                suggestions: document.getElementById('village-search-suggestions'),
                overlay: document.getElementById('village-search-bar-overlay')
            };
        } else if (activeEl.id === 'village-list-search-input') {
            return {
                input: activeEl,
                suggestions: document.getElementById('village-list-search-suggestions'),
                overlay: null
            };
        } else if (activeEl.id === 'village-needs-search-input') {
            return {
                input: activeEl,
                suggestions: document.getElementById('village-needs-search-suggestions'),
                overlay: null
            };
        } else if (activeEl.id === 'village-events-search-input') {
            return {
                input: activeEl,
                suggestions: document.getElementById('village-events-search-suggestions'),
                overlay: null
            };
        }
    }
    // Fallback based on visible panels
    const listContainer = document.getElementById('village-list-container');
    const needsContainer = document.getElementById('village-needs-container');
    const eventsContainer = document.getElementById('village-events-container');
    
    if (listContainer && !listContainer.classList.contains('hidden')) {
        return {
            input: document.getElementById('village-list-search-input'),
            suggestions: document.getElementById('village-list-search-suggestions'),
            overlay: null
        };
    } else if (needsContainer && !needsContainer.classList.contains('hidden')) {
        return {
            input: document.getElementById('village-needs-search-input'),
            suggestions: document.getElementById('village-needs-search-suggestions'),
            overlay: null
        };
    } else if (eventsContainer && !eventsContainer.classList.contains('hidden')) {
        return {
            input: document.getElementById('village-events-search-input'),
            suggestions: document.getElementById('village-events-search-suggestions'),
            overlay: null
        };
    }
    
    return {
        input: document.getElementById('village-search-input'),
        suggestions: document.getElementById('village-search-suggestions'),
        overlay: document.getElementById('village-search-bar-overlay')
    };
}

// Map search intelligence pill state
window.currentIntelMatches = [];
window.currentIntelIndex = -1;

function updateIntelPillUI(exactCount, similarCount) {
    const intelPill = document.getElementById('village-search-intel-pill');
    if (!intelPill || !window.currentIntelMatches || window.currentIntelMatches.length === 0) return;

    if (exactCount === undefined || similarCount === undefined) {
        exactCount = 0;
        similarCount = 0;
        const q = (document.getElementById('village-search-input')?.value || "").toLowerCase().trim();
        window.currentIntelMatches.forEach(item => {
            const titleClean = (item.title || "").toLowerCase();
            const subtitleClean = (item.subtitle || "").toLowerCase();
            const isExact = titleClean.includes(q) || subtitleClean.includes(q);
            if (isExact) {
                exactCount++;
            } else {
                similarCount++;
            }
        });
    }

    const index = window.currentIntelIndex;
    const item = window.currentIntelMatches[index];
    if (!item) return;

    const titleEl = document.getElementById('intel-match-title');
    const badgeEl = document.getElementById('intel-match-badge');
    const indexEl = document.getElementById('intel-match-index');
    const iconEl = document.getElementById('intel-match-icon');
    const prevBtn = document.getElementById('btn-intel-prev');
    const nextBtn = document.getElementById('btn-intel-next');

    if (titleEl) titleEl.textContent = item.title;
    if (iconEl) iconEl.textContent = item.icon || 'location_on';

    if (badgeEl) {
        badgeEl.style.display = 'inline-block';
        if (item.id === 'special_music_card') {
            badgeEl.textContent = "Music";
            badgeEl.className = "intel-badge text-[9px] font-bold px-1.5 py-0.5 rounded-full ml-1.5 bg-purple-500/10 text-purple-500 dark:bg-purple-500/20 dark:text-purple-300";
        } else {
            const q = (document.getElementById('village-search-input')?.value || "").toLowerCase().trim();
            const titleClean = (item.title || "").toLowerCase();
            const subtitleClean = (item.subtitle || "").toLowerCase();
            const isExact = titleClean.includes(q) || subtitleClean.includes(q);
            if (isExact) {
                badgeEl.textContent = "Exact";
                badgeEl.className = "intel-badge text-[9px] font-bold px-1.5 py-0.5 rounded-full ml-1.5 bg-[#308A5E]/10 text-[#308A5E] dark:bg-[#308A5E]/20 dark:text-[#50C878]";
            } else {
                badgeEl.textContent = "Similar";
                badgeEl.className = "intel-badge text-[9px] font-bold px-1.5 py-0.5 rounded-full ml-1.5 bg-amber-500/10 text-amber-500 dark:bg-amber-500/20 dark:text-amber-300";
            }
        }
    }

    if (indexEl) {
        let breakDown = "";
        if (exactCount > 0 && similarCount > 0) {
            breakDown = ` (${exactCount} Ex, ${similarCount} Sim)`;
        } else if (exactCount > 0) {
            breakDown = ` (${exactCount} Exact)`;
        } else if (similarCount > 0) {
            breakDown = ` (${similarCount} Similar)`;
        }
        indexEl.textContent = `${index + 1} of ${window.currentIntelMatches.length}${breakDown}`;
    }

    if (prevBtn && nextBtn) {
        if (window.currentIntelMatches.length <= 1) {
            prevBtn.style.opacity = '0.3';
            prevBtn.style.pointerEvents = 'none';
            nextBtn.style.opacity = '0.3';
            nextBtn.style.pointerEvents = 'none';
        } else {
            prevBtn.style.opacity = '1';
            prevBtn.style.pointerEvents = 'auto';
            nextBtn.style.opacity = '1';
            nextBtn.style.pointerEvents = 'auto';
        }
    }
}
window.updateIntelPillUI = updateIntelPillUI;

function cycleIntelMatch(offset) {
    if (!window.currentIntelMatches || window.currentIntelMatches.length === 0) return;
    let newIndex = window.currentIntelIndex + offset;
    if (newIndex < 0) {
        newIndex = window.currentIntelMatches.length - 1;
    } else if (newIndex >= window.currentIntelMatches.length) {
        newIndex = 0;
    }
    window.currentIntelIndex = newIndex;
    updateIntelPillUI();
    goToCurrentIntelMatch();
}
window.cycleIntelMatch = cycleIntelMatch;

function goToCurrentIntelMatch() {
    if (!window.currentIntelMatches || window.currentIntelIndex === -1) return;
    const item = window.currentIntelMatches[window.currentIntelIndex];
    if (!item) return;

    if (item.id === 'special_music_card') {
        selectSearchSuggestion(item.id, item.title, null, null);
    } else {
        if (leafletMap && item.lat !== null && item.lng !== null) {
            leafletMap.setView([item.lat, item.lng], 15);
        }
        if (item.id) {
            openMapItemDetail(item.id);
        }
    }
}
window.goToCurrentIntelMatch = goToCurrentIntelMatch;

function adjustSearchSuggestionsVisibility(show, immediate = false) {
    const allSuggestionsIds = [
        'village-search-suggestions',
        'village-list-search-suggestions',
        'village-needs-search-suggestions',
        'village-events-search-suggestions'
    ];
    
    if (window.searchSuggestionsTimeout) {
        clearTimeout(window.searchSuggestionsTimeout);
        window.searchSuggestionsTimeout = null;
    }
    
    const activeInfo = getActiveSuggestionsInfo();
    const intelPill = document.getElementById('village-search-intel-pill');
    if (intelPill) intelPill.classList.add('hidden');
    
    if (show) {
        // First hide others
        allSuggestionsIds.forEach(id => {
            const el = document.getElementById(id);
            if (el && id !== activeInfo.suggestions?.id) {
                el.classList.add('hidden');
            }
        });
        
        if (activeInfo.suggestions) {
            let controlId = 'village-segmented-control';
            if (activeInfo.suggestions.id === 'village-list-search-suggestions') controlId = 'village-list-segmented-control';
            else if (activeInfo.suggestions.id === 'village-needs-search-suggestions') controlId = 'village-needs-segmented-control';
            else if (activeInfo.suggestions.id === 'village-events-search-suggestions') controlId = 'village-events-segmented-control';
            
            const control = document.getElementById(controlId);
            if (control && activeInfo.suggestions.parentElement) {
                const parentRect = activeInfo.suggestions.parentElement.getBoundingClientRect();
                const controlRect = control.getBoundingClientRect();
                const topOffset = controlRect.top - parentRect.top;
                activeInfo.suggestions.style.top = `${topOffset}px`;
            }
            activeInfo.suggestions.classList.remove('hidden');
        }
        if (activeInfo.overlay) {
            activeInfo.overlay.style.height = 'auto';
        }
    } else {
        const mainOverlay = document.getElementById('village-search-bar-overlay');
        if (mainOverlay) {
            mainOverlay.style.height = 'auto';
        }
        
        const isEmpty = activeInfo.input ? activeInfo.input.value.trim() === "" : true;
        if (immediate || isEmpty) {
            allSuggestionsIds.forEach(id => {
                const el = document.getElementById(id);
                if (el) el.classList.add('hidden');
            });
        } else {
            window.searchSuggestionsTimeout = setTimeout(() => {
                allSuggestionsIds.forEach(id => {
                    const el = document.getElementById(id);
                    if (el) el.classList.add('hidden');
                });
            }, 300);
        }
    }
}
window.adjustSearchSuggestionsVisibility = adjustSearchSuggestionsVisibility;

function updateSearchSuggestions(query) {
    const activeInfo = getActiveSuggestionsInfo();
    const container = activeInfo.suggestions;
    if (!container) return;

    const isMapView = activeInfo.input && activeInfo.input.id === 'village-search-input';
    const intelPill = document.getElementById('village-search-intel-pill');

    const q = query.toLowerCase().trim();
    if (!q) {
        const isDark = document.documentElement.classList.contains('dark');
        const bgLight = 'rgba(48, 138, 94, 0.08)';
        const typeBg = isDark ? 'rgba(255, 255, 255, 0.1)' : 'rgba(0, 0, 0, 0.05)';
        const typeColor = isDark ? '#a4a9a0' : '#4b5563';
        
        container.innerHTML = `
            <div class="suggestion-section-title" style="margin-top: 0 !important;"><span>Suggested Searches</span></div>
            <div class="fused-suggestion-item" onclick="selectSearchSuggestion('', 'Tools', null, null)">
                <div class="fused-suggestion-icon-wrapper" style="background-color: ${bgLight} !important; margin-right: 6px !important;">
                    <span class="material-symbols-outlined text-[18px]" style="color: #308A5E !important;">handyman</span>
                </div>
                <div class="fused-suggestion-type-icon-wrapper" style="width: 24px !important; height: 24px !important; border-radius: 50% !important; display: flex !important; align-items: center !important; justify-content: center !important; margin-right: 12px !important; flex-shrink: 0 !important; background-color: ${typeBg} !important;">
                    <span class="material-symbols-outlined text-[14px]" style="color: ${typeColor} !important;">search</span>
                </div>
                <div class="fused-suggestion-info">
                    <div class="fused-suggestion-title">Tools & Handyman</div>
                    <div class="fused-suggestion-subtitle">Search for shared tools or repair help</div>
                </div>
                <span class="material-symbols-outlined text-[18px] quick-create-chevron">chevron_right</span>
            </div>
            
            <div class="fused-suggestion-item" onclick="selectSearchSuggestion('', 'Food', null, null)">
                <div class="fused-suggestion-icon-wrapper" style="background-color: ${bgLight} !important; margin-right: 6px !important;">
                    <span class="material-symbols-outlined text-[18px]" style="color: #308A5E !important;">restaurant</span>
                </div>
                <div class="fused-suggestion-type-icon-wrapper" style="width: 24px !important; height: 24px !important; border-radius: 50% !important; display: flex !important; align-items: center !important; justify-content: center !important; margin-right: 12px !important; flex-shrink: 0 !important; background-color: ${typeBg} !important;">
                    <span class="material-symbols-outlined text-[14px]" style="color: ${typeColor} !important;">search</span>
                </div>
                <div class="fused-suggestion-info">
                    <div class="fused-suggestion-title">Food & Cooking</div>
                    <div class="fused-suggestion-subtitle">Search for food shares, recipes, or kitchen items</div>
                </div>
                <span class="material-symbols-outlined text-[18px] quick-create-chevron">chevron_right</span>
            </div>

            <div class="fused-suggestion-item" onclick="selectSearchSuggestion('', 'Skills', null, null)">
                <div class="fused-suggestion-icon-wrapper" style="background-color: ${bgLight} !important; margin-right: 6px !important;">
                    <span class="material-symbols-outlined text-[18px]" style="color: #308A5E !important;">school</span>
                </div>
                <div class="fused-suggestion-type-icon-wrapper" style="width: 24px !important; height: 24px !important; border-radius: 50% !important; display: flex !important; align-items: center !important; justify-content: center !important; margin-right: 12px !important; flex-shrink: 0 !important; background-color: ${typeBg} !important;">
                    <span class="material-symbols-outlined text-[14px]" style="color: ${typeColor} !important;">search</span>
                </div>
                <div class="fused-suggestion-info">
                    <div class="fused-suggestion-title">Skills & Learning</div>
                    <div class="fused-suggestion-subtitle">Search for language tutors, classes, or mentoring</div>
                </div>
                <span class="material-symbols-outlined text-[18px] quick-create-chevron">chevron_right</span>
            </div>

            <div class="fused-suggestion-item" onclick="selectSearchSuggestion('', 'Garden', null, null)">
                <div class="fused-suggestion-icon-wrapper" style="background-color: ${bgLight} !important; margin-right: 6px !important;">
                    <span class="material-symbols-outlined text-[18px]" style="color: #308A5E !important;">yard</span>
                </div>
                <div class="fused-suggestion-type-icon-wrapper" style="width: 24px !important; height: 24px !important; border-radius: 50% !important; display: flex !important; align-items: center !important; justify-content: center !important; margin-right: 12px !important; flex-shrink: 0 !important; background-color: ${typeBg} !important;">
                    <span class="material-symbols-outlined text-[14px]" style="color: ${typeColor} !important;">search</span>
                </div>
                <div class="fused-suggestion-info">
                    <div class="fused-suggestion-title">Garden & Yard</div>
                    <div class="fused-suggestion-subtitle">Search for seeds, plant sharing, or garden help</div>
                </div>
                <span class="material-symbols-outlined text-[18px] quick-create-chevron">chevron_right</span>
            </div>
        `;
        if (intelPill) {
            intelPill.classList.add('hidden');
        }
        window.currentIntelMatches = [];
        window.currentIntelIndex = -1;
        adjustSearchSuggestionsVisibility(true);
        return;
    }

    let allItems = [];

    // Helper to check for exact substrings or word boundaries
    function checkExactMatch(queryStr, title, subtitle) {
        const queryClean = queryStr.toLowerCase().trim();
        if (!queryClean) return false;
        const titleClean = (title || "").toLowerCase();
        const subtitleClean = (subtitle || "").toLowerCase();
        return titleClean.includes(queryClean) || subtitleClean.includes(queryClean);
    }

    // 1. User Offerings
    if (state.userOfferings) {
        state.userOfferings.forEach(offer => {
            if (typeof getBarterItemStatus === 'function' && getBarterItemStatus(offer.id) === 'Traded') return;
            if (fuzzySearchMatch(q, offer.title, offer.desc || '', offer.category || '')) {
                allItems.push({
                    id: offer.id,
                    title: offer.title,
                    subtitle: `You · ${offer.category}`,
                    icon: offer.icon || getCategoryIcon(offer.category),
                    lat: offer.lat,
                    lng: offer.lng,
                    type: 'user_offer',
                    badge: 'Offer',
                    category: offer.category
                });
            }
        });
    }

    // 2. Neighbor Offerings
    if (state.neighbors) {
        Object.keys(state.neighbors).forEach(key => {
            const neighbor = state.neighbors[key];
            if (neighbor && !neighbor.suspended && !(state.suspendedUsers && state.suspendedUsers.includes(key)) && !(state.blockedUsers && state.blockedUsers.includes(key))) {
                if (fuzzySearchMatch(q, neighbor.offerTitle || '', neighbor.category || '', neighbor.name || '')) {
                    allItems.push({
                        id: key,
                        title: neighbor.offerTitle || 'Offering',
                        subtitle: `${neighbor.name} · ${neighbor.category}`,
                        icon: getCategoryIcon(neighbor.category),
                        lat: neighbor.lat,
                        lng: neighbor.lng,
                        type: 'offer',
                        badge: 'Offer',
                        category: neighbor.category
                    });
                }
            }
        });
    }

    // 3. Needs Board
    if (state.needsBoard) {
        state.needsBoard.forEach(need => {
            if (state.blockedUsers && state.blockedUsers.includes(need.neighborName)) return;
            if (state.suspendedUsers && state.suspendedUsers.includes(need.neighborName)) return;
            if (fuzzySearchMatch(q, need.needTitle || '', need.needDesc || '', need.category || '', need.neighborName || '')) {
                let lat = need.lat;
                let lng = need.lng;
                if (!lat || !lng) {
                    const user = state.currentUser || {};
                    const displayName = user.displayName || `${user.firstName || 'Lily'} ${user.lastName || 'Kaufmann'}`;
                    if (need.neighborName === displayName) {
                        lat = user.lat;
                        lng = user.lng;
                    } else {
                        const neighbor = state.neighbors[need.neighborName];
                        if (neighbor) {
                            lat = neighbor.lat;
                            lng = neighbor.lng;
                        }
                    }
                }
                allItems.push({
                    id: `need_${need.id}`,
                    title: need.needTitle || 'Need Request',
                    subtitle: `${need.neighborName} · Need Help`,
                    icon: getCategoryIcon(need.category) || 'help_outline',
                    lat: lat || 49.2827,
                    lng: lng || -123.1207,
                    type: 'need',
                    badge: 'Need',
                    category: need.category
                });
            }
        });
    }

    // 4. Events
    if (state.events) {
        state.events.forEach(evt => {
            if (!(state.suspendedUsers && state.suspendedUsers.includes(evt.host))) {
                if (fuzzySearchMatch(q, evt.title || '', evt.desc || '', evt.type || '', evt.host || '')) {
                    allItems.push({
                        id: `evt_${evt.id}`,
                        title: evt.title || 'Event',
                        subtitle: `Event · Hosted by ${evt.host || 'Community'}`,
                        icon: 'event',
                        lat: evt.lat,
                        lng: evt.lng,
                        type: 'event',
                        badge: 'Event',
                        category: 'Event or Meetup'
                    });
                }
            }
        });
    }

    // Separate into Exact and Similar matches
    const exactMatches = [];
    const similarMatches = [];

    allItems.forEach(item => {
        if (checkExactMatch(q, item.title, item.subtitle)) {
            exactMatches.push(item);
        } else {
            similarMatches.push(item);
        }
    });

    // Special music query handling
    if (isMusicalQuery(q)) {
        exactMatches.unshift({
            id: 'special_music_card',
            title: 'Explore Community Music Swaps',
            subtitle: `View music instruments, lessons, and gear for "${query}"`,
            icon: 'music_note',
            lat: null,
            lng: null,
            type: 'special_music_card',
            badge: 'Music',
            category: 'Books, Games, Entertainment'
        });
    }

    if (exactMatches.length === 0 && similarMatches.length === 0) {
        container.innerHTML = `<div class="px-3 py-2.5 text-xs text-on-surface-variant text-center">No matching suggestions</div>`;
        adjustSearchSuggestionsVisibility(true);
        return;
    }

    // Highlight helper
    function highlightQuery(title, queryStr) {
        if (!queryStr) return title;
        const escaped = queryStr.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
        const regex = new RegExp(`(${escaped})`, 'gi');
        return title.replace(regex, `<span class="search-highlight">$1</span>`);
    }

    // Hex to RGBA helper for subtle badge/icon wrapper backgrounds
    function hexToRgba(hex, alpha) {
        if (!hex) return 'rgba(0,0,0,0.05)';
        hex = hex.replace('#', '');
        if (hex.length === 3) {
            hex = hex.split('').map(char => char + char).join('');
        }
        const r = parseInt(hex.substring(0, 2), 16);
        const g = parseInt(hex.substring(2, 4), 16);
        const b = parseInt(hex.substring(4, 6), 16);
        return `rgba(${r}, ${g}, ${b}, ${alpha})`;
    }

    container.innerHTML = "";

    // 1. Render Exact Matches
    if (exactMatches.length > 0) {
        const hdr = document.createElement('div');
        hdr.className = "suggestion-section-title exact";
        hdr.innerHTML = `<span>Exact Matches</span>`;
        container.appendChild(hdr);

        exactMatches.slice(0, 5).forEach(item => {
            const div = document.createElement('div');
            div.className = "fused-suggestion-item";
            div.onclick = () => {
                if (item.id === 'special_music_card') {
                    selectSearchSuggestion(item.id, query, null, null);
                } else {
                    selectSearchSuggestion(item.id, item.title, item.lat, item.lng);
                }
            };
            
            const iconColor = getCategoryColor(item.category) || '#308A5E';
            const bgLight = hexToRgba(iconColor, 0.08);
            const isDark = document.documentElement.classList.contains('dark');
            const typeBg = isDark ? 'rgba(255, 255, 255, 0.1)' : 'rgba(0, 0, 0, 0.05)';
            const typeColor = isDark ? '#a4a9a0' : '#4b5563';
            
            let typeIcon = 'local_offer';
            if (item.badge === 'Need') {
                typeIcon = 'help_outline';
            } else if (item.badge === 'Event') {
                typeIcon = 'event';
            } else if (item.badge === 'Music') {
                typeIcon = 'music_note';
            }

            div.innerHTML = `
                <div class="fused-suggestion-icon-wrapper" style="background-color: ${bgLight} !important; margin-right: 6px !important;">
                    <span class="material-symbols-outlined text-[18px]" style="color: ${iconColor} !important;">${item.icon}</span>
                </div>
                <div class="fused-suggestion-type-icon-wrapper" style="width: 24px !important; height: 24px !important; border-radius: 50% !important; display: flex !important; align-items: center !important; justify-content: center !important; margin-right: 12px !important; flex-shrink: 0 !important; background-color: ${typeBg} !important;">
                    <span class="material-symbols-outlined text-[14px]" style="color: ${typeColor} !important;">${typeIcon}</span>
                </div>
                <div class="fused-suggestion-info">
                    <div class="fused-suggestion-title">${highlightQuery(item.title, query)}</div>
                    <div class="fused-suggestion-subtitle">${item.subtitle}</div>
                </div>
                <span class="material-symbols-outlined text-[18px] quick-create-chevron">chevron_right</span>
            `;
            container.appendChild(div);
        });
    }

    // 2. Render Similar Matches
    if (similarMatches.length > 0) {
        const hdr = document.createElement('div');
        hdr.className = "suggestion-section-title similar";
        hdr.innerHTML = `<span>Similar Matches</span>`;
        container.appendChild(hdr);

        similarMatches.slice(0, 5).forEach(item => {
            const div = document.createElement('div');
            div.className = "fused-suggestion-item";
            div.onclick = () => {
                selectSearchSuggestion(item.id, item.title, item.lat, item.lng);
            };
            
            const iconColor = getCategoryColor(item.category) || '#308A5E';
            const bgLight = hexToRgba(iconColor, 0.08);
            const isDark = document.documentElement.classList.contains('dark');
            const typeBg = isDark ? 'rgba(255, 255, 255, 0.1)' : 'rgba(0, 0, 0, 0.05)';
            const typeColor = isDark ? '#a4a9a0' : '#4b5563';
            
            let typeIcon = 'local_offer';
            if (item.badge === 'Need') {
                typeIcon = 'help_outline';
            } else if (item.badge === 'Event') {
                typeIcon = 'event';
            } else if (item.badge === 'Music') {
                typeIcon = 'music_note';
            }

            div.innerHTML = `
                <div class="fused-suggestion-icon-wrapper" style="background-color: ${bgLight} !important; margin-right: 6px !important;">
                    <span class="material-symbols-outlined text-[18px]" style="color: ${iconColor} !important;">${item.icon}</span>
                </div>
                <div class="fused-suggestion-type-icon-wrapper" style="width: 24px !important; height: 24px !important; border-radius: 50% !important; display: flex !important; align-items: center !important; justify-content: center !important; margin-right: 12px !important; flex-shrink: 0 !important; background-color: ${typeBg} !important;">
                    <span class="material-symbols-outlined text-[14px]" style="color: ${typeColor} !important;">${typeIcon}</span>
                </div>
                <div class="fused-suggestion-info">
                    <div class="fused-suggestion-title">${highlightQuery(item.title, query)}</div>
                    <div class="fused-suggestion-subtitle">${item.subtitle}</div>
                </div>
                <span class="material-symbols-outlined text-[18px] quick-create-chevron">chevron_right</span>
            `;
            container.appendChild(div);
        });
    }

    adjustSearchSuggestionsVisibility(true);
}
window.updateSearchSuggestions = updateSearchSuggestions;

function selectSearchSuggestion(id, title, lat, lng) {
    const mainInput = document.getElementById('village-search-input');
    if (mainInput) mainInput.value = title;
    
    // Sync other search bars without infinite loops
    const subInputs = [
        'village-list-search-input',
        'village-needs-search-input',
        'village-events-search-input',
        'village-bulletins-search-input'
    ];
    subInputs.forEach(inputId => {
        const el = document.getElementById(inputId);
        if (el) el.value = title;
    });

    // Hide suggestions container with animation
    adjustSearchSuggestionsVisibility(false);

    if (id === 'special_music_card') {
        // Refresh all list views and map markers filtering
        applyMapFiltering();
        renderVillageListView();
        renderNeedsBoardView();
        renderEventsList();
        renderBulletinsList();

        // Switch to Offerings list view segment to show results and the music guidance banner
        switchVillageSegment('list');
    } else {
        // Refresh map markers filtering and all list views
        applyMapFiltering();
        renderVillageListView();
        renderNeedsBoardView();
        renderEventsList();
        renderBulletinsList();

        // Center map on location
        if (leafletMap && lat !== null && lng !== null) {
            leafletMap.setView([lat, lng], 15);
        }

        // Open detail card directly
        if (id) {
            openMapItemDetail(id);
        }
    }
}
window.selectSearchSuggestion = selectSearchSuggestion;

// Dismiss suggestions when clicking outside
document.addEventListener('click', (e) => {
    const searchIds = [
        'village-search-input',
        'village-list-search-input',
        'village-needs-search-input',
        'village-events-search-input'
    ];
    const suggestionsIds = [
        'village-search-suggestions',
        'village-list-search-suggestions',
        'village-needs-search-suggestions',
        'village-events-search-suggestions'
    ];
    
    let clickedInside = false;
    for (const id of [...searchIds, ...suggestionsIds]) {
        const el = document.getElementById(id);
        if (el && el.contains(e.target)) {
            clickedInside = true;
            break;
        }
    }
    
    const overlay = document.getElementById('village-search-bar-overlay');
    if (overlay && overlay.contains(e.target)) {
        clickedInside = true;
    }
    
    if (!clickedInside) {
        adjustSearchSuggestionsVisibility(false);
    }
});

// Map Page Peek Card and Custom Zoom handlers

function openMapItemPeek(idOrName) {
    if (typeof idOrName !== 'string') {
        console.warn("Invalid idOrName passed to openMapItemPeek:", idOrName);
        return;
    }
    
    // Bypass the bottom peek card entirely and open the full detail overlay
    openMapItemDetail(idOrName);
    return;
    let title = "", authorName = "", rating = "", category = "", image = "", isEvent = false, isUserOffer = false, isUserNeed = false;
    let eventId = "";

    if (idOrName.startsWith('evt_')) {
        eventId = idOrName.replace('evt_', '');
        const event = state.events.find(e => e.id === eventId);
        if (!event) return;
        isEvent = true;
        title = event.title;
        authorName = event.host || 'Community Member';
        category = event.type;
        image = getEventPresetImage(event.type);
        rating = "Community Event";
    } else if (idOrName.startsWith('need_')) {
        const needId = idOrName.replace('need_', '');
        const need = state.needsBoard ? state.needsBoard.find(n => n.id === needId) : null;
        if (!need) return;
        title = need.needTitle;
        category = need.category;
        image = getCategoryPresetImage(need.category);
        
        const currentUser = state.currentUser || {};
        const displayName = currentUser.displayName || `${currentUser.firstName || 'Lily'} ${currentUser.lastName || 'Kaufmann'}`;
        if (need.neighborName === displayName) {
            isUserNeed = true;
            authorName = `${currentUser.firstName || 'Lily'} (You)`;
            rating = "Your Need Request";
        } else {
            const neighbor = state.neighbors[need.neighborName];
            authorName = need.neighborName;
            rating = neighbor ? `Needs help · ${neighbor.vouches || 0} ❤️` : "Community Member";
        }
    } else if (idOrName.startsWith('off_') || idOrName === '1' || idOrName === '2') {
        const offer = state.userOfferings.find(o => o.id === idOrName);
        if (!offer) return;
        isUserOffer = true;
        title = offer.title;
        authorName = state.currentUser ? `${state.currentUser.firstName} (You)` : 'Lily Kaufmann (You)';
        category = offer.category;
        image = offer.image || getCategoryPresetImage(offer.category);
        rating = "100% Reliable";
    } else {
        const neighbor = state.neighbors[idOrName];
        if (!neighbor) return;
        title = neighbor.offerTitle;
        authorName = neighbor.name;
        category = neighbor.category;
        image = neighbor.offerImg || neighbor.avatar || DEFAULT_AVATAR;
        rating = `Appreciated · ${neighbor.vouches || 0} ❤️`;
    }

    playSound('click');

    // Populate peek card DOM elements
    const peekImgContainer = document.getElementById('peek-item-img-container');
    if (peekImgContainer) {
        if (isEvent) {
            const event = state.events.find(e => e.id === eventId);
            peekImgContainer.innerHTML = getEventCardThumbnailHTML(event);
        } else {
            peekImgContainer.innerHTML = `<img id="peek-item-img" src="${image || PLACEHOLDER_IMAGE}" class="w-full h-full object-cover" alt="Item image">`;
            const peekImg = document.getElementById('peek-item-img');
            if (peekImg) {
                peekImg.onerror = () => {
                    peekImg.onerror = null;
                    peekImg.src = PLACEHOLDER_IMAGE;
                };
            }
        }
    }

    const peekCategory = document.getElementById('peek-item-category');
    if (peekCategory) {
        peekCategory.innerText = category;
        peekCategory.style.backgroundColor = getCategoryColor(category);
    }

    const peekTitle = document.getElementById('peek-item-title');
    if (peekTitle) peekTitle.innerText = title;

    const peekUser = document.getElementById('peek-user-name');
    if (peekUser) {
        let formattedAuthorName = authorName;
        if (authorName) {
            if (authorName.endsWith(' (You)')) {
                const cleanName = authorName.replace(' (You)', '');
                const capName = cleanName.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(' ');
                formattedAuthorName = capName + ' (You)';
            } else {
                formattedAuthorName = authorName.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(' ');
            }
        }
        peekUser.innerText = formattedAuthorName;
    }

    const peekRating = document.getElementById('peek-user-rating');
    const peekVerifiedIcon = document.getElementById('peek-verified-icon');
    if (peekRating) {
        peekRating.innerText = rating;
    }
    if (peekVerifiedIcon) {
        if (isEvent || rating.includes('❤️')) {
            peekVerifiedIcon.style.display = 'none';
        } else {
            peekVerifiedIcon.style.display = 'inline-block';
        }
    }

    // Conditionally show/hide verified icon
    let isVerified = false;
    if (idOrName.startsWith('evt_')) {
        isVerified = false;
    } else if (idOrName.startsWith('need_')) {
        const needId = idOrName.replace('need_', '');
        const need = state.needsBoard ? state.needsBoard.find(n => n.id === needId) : null;
        if (need) {
            const neighbor = state.neighbors[need.neighborName];
            isVerified = neighbor ? (neighbor.verified === true) : false;
        }
    } else if (idOrName.startsWith('off_') || idOrName === '1' || idOrName === '2') {
        isVerified = state.currentUser ? !!state.currentUser.verified : false;
    } else {
        const neighbor = state.neighbors[idOrName];
        isVerified = neighbor ? (neighbor.verified === true) : false;
    }
    const verifiedIcon = document.getElementById('peek-verified-icon');
    if (verifiedIcon) {
        verifiedIcon.style.display = isVerified ? 'inline-flex' : 'none';
    }

    // Set up chat button actions
    const chatBtn = document.getElementById('peek-chat-btn');
    if (chatBtn) {
        if (isEvent) {
            chatBtn.innerHTML = `<span class="material-symbols-outlined text-xs">campaign</span> RSVP`;
            chatBtn.onclick = () => {
                closeMapItemPeek();
                openEventDetail(eventId);
            };
        } else if (isUserOffer || isUserNeed) {
            chatBtn.innerHTML = `<span class="material-symbols-outlined text-xs">person</span> Profile`;
            chatBtn.onclick = () => {
                state.profileReferrer = 'map';
                state.lastActiveMapPinId = currentPeekItemId;
                closeMapItemPeek();
                showView('profile_settings');
            };
        } else {
            chatBtn.innerHTML = `<span class="material-symbols-outlined text-xs">chat</span> Chat`;
            chatBtn.onclick = () => {
                state.chatBackReferrer = { type: 'map_detail', id: idOrName };
                closeMapItemPeek();
                if (idOrName.startsWith('need_')) {
                    const needId = idOrName.replace('need_', '');
                    const need = state.needsBoard ? state.needsBoard.find(n => n.id === needId) : null;
                    const authorId = need ? need.neighborName : idOrName;
                    startChatConversation(authorId);
                } else {
                    startChatConversation(idOrName);
                }
            };
        }
    }

    const peekCard = document.getElementById('map-peek-card');
    if (peekCard) {
        peekCard.classList.add('active');
    }
}

