function handlePresetAnnouncement(presetType) {
    playSound('click');
    const titleInput = document.getElementById('admin-announcement-title');
    const contentInput = document.getElementById('admin-announcement-content');
    if (!titleInput || !contentInput) return;
    
    let title = "";
    let content = "";
    
    if (presetType === 'urgent') {
        title = "Urgent System Alert";
        content = "We are currently investigating temporary system latency issues. Our team is actively working to resolve this as quickly as possible. Thank you for your patience!";
    } else if (presetType === 'maintenance') {
        title = "Scheduled Maintenance";
        content = "Corner Swaps will undergo scheduled system maintenance tonight from 2:00 AM to 3:00 AM UTC. Some features may be temporarily offline during this window.";
    } else if (presetType === 'update') {
        title = "New App Update Available";
        content = "A brand new version of Corner Swaps is now available in the App Store! Please download the latest update to access exciting new features and performance improvements.";
    } else if (presetType === 'tips') {
        title = "Community Guidelines Reminder";
        content = "Keep our community friendly and safe! Remember to always meet in public spaces, be respectful, and keep swaps positive.";
    } else if (presetType === 'event') {
        title = "Upcoming Neighbourhood Swap Meet";
        content = "Join us this Saturday for our community swap meet in the central park! Bring items you want to trade and meet your neighbours.";
    } else if (presetType === 'security') {
        title = "Safety & Security Reminder";
        content = "Protect your account! Corner Swaps staff will never ask for your password or verification codes. Report any suspicious behaviour immediately.";
    }
    
    titleInput.value = title;
    contentInput.value = content;
    contentInput.focus();
}

window.handlePresetAnnouncement = handlePresetAnnouncement;

window.setSuSocialInputVisible = function(platform, visible) {
    const container = document.getElementById(`su-social-input-${platform}-container`);
    const btn = document.getElementById(`su-social-btn-${platform}`);
    if (!container) return;
    
    if (visible) {
        container.classList.remove('hidden');
        if (btn) {
            btn.classList.add('bg-forest-green', 'text-white', 'border-forest-green');
            btn.classList.remove('bg-white', 'dark:bg-[#1b261f]', 'border-outline-variant/20');
            const svg = btn.querySelector('svg');
            if (svg) {
                svg.classList.add('text-white');
                svg.classList.remove('text-forest-green');
            }
        }
    } else {
        container.classList.add('hidden');
        if (btn) {
            btn.classList.remove('bg-forest-green', 'text-white', 'border-forest-green');
            btn.classList.add('bg-white', 'dark:bg-[#1b261f]', 'border-outline-variant/20');
            const svg = btn.querySelector('svg');
            if (svg) {
                svg.classList.remove('text-white');
                svg.classList.add('text-forest-green');
            }
        }
    }
};

