window.selectCameraPreset = function(preset) {
    currentCameraPreset = preset;
    const imgEl = document.getElementById('camera-preview-mock-img');
    if (imgEl && CAMERA_PRESETS[preset]) {
        imgEl.src = CAMERA_PRESETS[preset];
    }
    
    ['bike', 'tools', 'books', 'produce'].forEach(p => {
        const btn = document.getElementById(`cam-preset-${p}`);
        if (btn) {
            if (p === preset) {
                btn.className = "px-3 py-1 bg-forest-green text-warm-cream text-[10px] font-bold rounded-full";
            } else {
                btn.className = "px-3 py-1 bg-white/20 text-white text-[10px] font-bold rounded-full";
            }
        }
    });
};

