window.snapMockCameraPhoto = function() {
    const flash = document.getElementById('camera-shutter-flash');
    if (flash) {
        flash.classList.remove('opacity-0');
        flash.classList.add('opacity-100');
        setTimeout(() => {
            flash.classList.remove('opacity-100');
            flash.classList.add('opacity-0');
        }, 100);
    }
    
    playSound('click'); // simulate shutter with click
    
    setTimeout(() => {
        const imgUrl = CAMERA_PRESETS[currentCameraPreset];
        const conv = state.conversations.find(c => c.id === state.currentConversationId);
        if (conv) {
            const time = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
            const msgObj = {
                sender: 'me',
                image: imgUrl,
                time: time,
                status: 'delivered'
            };
            conv.messages.push(msgObj);
            saveState();
            renderChatDetail(conv);
            playSound('message');
            
            if (!conv.isGroup) {
                setTimeout(() => {
                    msgObj.status = 'read';
                    saveState();
                    if (state.currentConversationId === conv.id) {
                        renderChatDetail(conv);
                    }
                }, 1500);
            }
        }
        window.closeChatCameraModal();
    }, 250);
};

