function staggeredInvalidateSize(mapInstance) {
    if (!mapInstance) return;
    mapInstance.invalidateSize();
    setTimeout(() => { if (mapInstance) mapInstance.invalidateSize(); }, 50);
    setTimeout(() => { if (mapInstance) mapInstance.invalidateSize(); }, 150);
    setTimeout(() => { if (mapInstance) mapInstance.invalidateSize(); }, 400);
    setTimeout(() => { if (mapInstance) mapInstance.invalidateSize(); }, 800);
}

// Meetup Location Picker Logic
let tempMeetupCoords = null;
let tempMeetupRadius = 100;

function openMeetupLocationPicker() {
    const modal = document.getElementById('meetup-picker-modal');
    if (!modal) return;
    modal.classList.remove('hidden');
    playSound('click');

    // Initialize map if it doesn't exist
    if (!meetupPickerMap) {
        meetupPickerMap = L.map('meetup-picker-map', {
            zoomControl: false,
            attributionControl: false,
            tap: false,
            bounceAtZoomLimits: false,
            wheelDebounceTime: 150,
            preferCanvas: true,
            fadeAnimation: true,
            zoomAnimation: true,
            markerZoomAnimation: true,
            inertia: true
        });

        const retinaSuffix = '';
        const isDark = state.preferences && state.preferences.darkMode;
        const tileUrl = isDark
            ? 'https://{s}.basemaps.cartocdn.com/rastertiles/dark_all/{z}/{x}/{y}' + retinaSuffix + '.png'
            : 'https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}' + retinaSuffix + '.png';

        L.tileLayer(tileUrl, {
            maxZoom: 19,
            subdomains: 'abcd',
            keepBuffer: 2,
            updateWhenPanning: true,
            updateWhenIdle: false
        }).addTo(meetupPickerMap);

        // Click handler to select coordinates
        meetupPickerMap.on('click', onMeetupMapClick);
    }

    // Determine initial center
    // If we have selected coordinates, center there. Otherwise, use state.currentUser location coords, or Vancouver default.
    let centerCoords = [49.2827, -123.1207];
    if (state.selectedMeetupCoords) {
        centerCoords = [state.selectedMeetupCoords.lat, state.selectedMeetupCoords.lng];
        tempMeetupCoords = { lat: state.selectedMeetupCoords.lat, lng: state.selectedMeetupCoords.lng };
        tempMeetupRadius = state.selectedMeetupRadius || 100;
    } else if (state.currentUser && state.currentUser.lat && state.currentUser.lng) {
        centerCoords = [state.currentUser.lat, state.currentUser.lng];
        tempMeetupCoords = null; // Wait for user tap
        tempMeetupRadius = 100;
    } else {
        tempMeetupCoords = null;
        tempMeetupRadius = 100;
    }

    meetupPickerMap.setView(centerCoords, 15);

    // Invalidate map size to ensure it renders correctly
    staggeredInvalidateSize(meetupPickerMap);

    // Reset controls
    const slider = document.getElementById('meetup-radius-slider');
    if (slider) {
        slider.value = tempMeetupRadius;
    }
    const display = document.getElementById('meetup-radius-display');
    if (display) {
        display.innerText = `${tempMeetupRadius}m`;
    }

    // Set neighborhood name to input
    const neighInput = document.getElementById('meetup-picker-neighborhood');
    const confirmBtn = document.getElementById('meetup-confirm-btn');

    if (tempMeetupCoords) {
        plotMeetupPickerMarker(tempMeetupCoords.lat, tempMeetupCoords.lng, tempMeetupRadius);
        if (neighInput) {
            neighInput.value = document.getElementById('neighborhood-input').value || "";
        }
        if (confirmBtn) confirmBtn.disabled = false;
        
        const instruct = document.getElementById('map-picker-instruction');
        if (instruct) instruct.classList.add('hidden');
    } else {
        if (meetupPickerMarker) {
            meetupPickerMap.removeLayer(meetupPickerMarker);
            meetupPickerMarker = null;
        }
        if (meetupPickerCircle) {
            meetupPickerMap.removeLayer(meetupPickerCircle);
            meetupPickerCircle = null;
        }
        if (neighInput) neighInput.value = "";
        if (confirmBtn) confirmBtn.disabled = true;

        const instruct = document.getElementById('map-picker-instruction');
        if (instruct) {
            instruct.classList.remove('hidden');
            instruct.innerText = "Tap map to set meetup point";
        }
    }
}

function plotMeetupPickerMarker(lat, lng, radius) {
    if (!meetupPickerMap) return;

    const color = '#2563eb'; // Blue
    
    // Create/update marker
    if (meetupPickerMarker) {
        meetupPickerMarker.setLatLng([lat, lng]);
    } else {
        const customIcon = L.divIcon({
            className: 'custom-div-icon',
            html: `<div class="pin-icon overflow-hidden flex items-center justify-center rounded-full" style="border: 2px solid white !important; background-color: ${color} !important; width: 38px; height: 38px; display: flex !important; align-items: center !important; justify-content: center !important; box-shadow: 0 3px 8px rgba(0,0,0,0.2) !important; border-radius: 50% !important;">
                    <span class="material-symbols-outlined text-[20px]" style="color: white !important; font-variation-settings: 'FILL' 1, 'wght' 500;">location_on</span>
                   </div>`,
            iconSize: [38, 38],
            iconAnchor: [19, 19]
        });
        meetupPickerMarker = L.marker([lat, lng], { icon: customIcon }).addTo(meetupPickerMap);
    }

    // Create/update circle
    if (meetupPickerCircle) {
        meetupPickerCircle.setLatLng([lat, lng]);
        meetupPickerCircle.setRadius(radius);
    } else {
        meetupPickerCircle = L.circle([lat, lng], {
            radius: radius,
            color: color,
            fillColor: color,
            fillOpacity: 0.15,
            weight: 1.5,
            dashArray: '4, 4'
        }).addTo(meetupPickerMap);
    }
}

function onMeetupMapClick(e) {
    playSound('click');
    const lat = e.latlng.lat;
    const lng = e.latlng.lng;
    tempMeetupCoords = { lat, lng };

    plotMeetupPickerMarker(lat, lng, tempMeetupRadius);

    // Enable confirm button
    const confirmBtn = document.getElementById('meetup-confirm-btn');
    if (confirmBtn) confirmBtn.disabled = false;

    // Hide overlay instruction
    const instruct = document.getElementById('map-picker-instruction');
    if (instruct) instruct.classList.add('hidden');

    // Perform reverse geocoding via OpenStreetMap Nominatim
    const neighInput = document.getElementById('meetup-picker-neighborhood');
    if (neighInput) neighInput.value = "Resolving location...";

    fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${lat}&lon=${lng}`)
        .then(response => response.json())
        .then(data => {
            if (neighInput && tempMeetupCoords && tempMeetupCoords.lat === lat && tempMeetupCoords.lng === lng) {
                let addressText = "";
                if (data.address) {
                    const road = data.address.road || "";
                    const suburb = data.address.suburb || data.address.neighbourhood || data.address.city_district || "";
                    const city = data.address.city || data.address.town || "";
                    
                    if (road && suburb) {
                        addressText = `${road}, ${suburb}`;
                    } else if (suburb) {
                        addressText = suburb;
                    } else if (road) {
                        addressText = road;
                    } else {
                        addressText = city || "Map Location";
                    }
                } else {
                    addressText = "Selected Location";
                }
                neighInput.value = addressText;
            }
        })
        .catch(err => {
            console.error("Reverse geocode error:", err);
            if (neighInput) {
                let estName = "Oakwood Village";
                if (lat > 49.27 && lat < 49.29 && lng > -123.14 && lng < -123.10) {
                    if (lng < -123.125) estName = "Kitsilano";
                    else if (lat > 49.278) estName = "Downtown";
                    else estName = "Mount Pleasant";
                }
                neighInput.value = estName;
            }
        });
}

function updateMeetupPickerRadius(val) {
    const radius = parseInt(val);
    tempMeetupRadius = radius;

    const display = document.getElementById('meetup-radius-display');
    if (display) {
        display.innerText = `${radius}m`;
    }

    if (meetupPickerCircle) {
        meetupPickerCircle.setRadius(radius);
    }
}

function confirmMeetupLocation() {
    if (!tempMeetupCoords) return;
    playSound('click');

    state.selectedMeetupCoords = { lat: tempMeetupCoords.lat, lng: tempMeetupCoords.lng };
    state.selectedMeetupRadius = tempMeetupRadius;

    // Set value in Create Offering form
    const neighInput = document.getElementById('meetup-picker-neighborhood');
    const mainInput = document.getElementById('neighborhood-input');
    if (mainInput) {
        mainInput.value = neighInput ? neighInput.value : `Map Location (+${tempMeetupRadius}m vicinity)`;
    }

    // Show visual status
    const mapStatus = document.getElementById('meetup-map-status');
    if (mapStatus) {
        mapStatus.classList.remove('hidden');
        mapStatus.innerHTML = `<span class="material-symbols-outlined text-[14px]">check_circle</span> Map set (+${tempMeetupRadius}m)`;
    }

    closeMeetupLocationPicker(true);
}

function closeMeetupLocationPicker(confirm) {
    const modal = document.getElementById('meetup-picker-modal');
    if (modal) modal.classList.add('hidden');
    if (!confirm) {
        playSound('click');
    }
}

window.openMeetupLocationPicker = openMeetupLocationPicker;
window.closeMeetupLocationPicker = closeMeetupLocationPicker;
window.updateMeetupPickerRadius = updateMeetupPickerRadius;
window.confirmMeetupLocation = confirmMeetupLocation;

window.openSwapsPopupModal = function() {
    playSound('click');
    collapseChatMenu();
    
    const modal = document.getElementById('swaps-popup-modal');
    const list = document.getElementById('swaps-popup-list');
    if (!modal || !list) return;

    modal.classList.remove('hidden');

    // Find unique names of neighbors that we have completed a trade with
    // A trade is completed if negotiation status is 'completed'
    const completedPartners = new Set();
    state.conversations.forEach(c => {
        if (c.negotiation && c.negotiation.status === 'completed') {
            if (!c.isGroup && c.neighborName) {
                completedPartners.add(c.neighborName);
            }
        }
    });

    list.innerHTML = '';
    
    if (completedPartners.size === 0) {
        list.innerHTML = `
            <div class="text-center py-12 text-outline space-y-3">
                <span class="material-symbols-outlined text-5xl text-outline-variant">handshake</span>
                <p class="text-sm font-semibold text-on-surface-variant">No Completed Swaps Yet</p>
                <p class="text-xs text-outline max-w-[240px] mx-auto leading-relaxed">Completed swaps with your neighbors will show up here as trusted connections.</p>
            </div>
        `;
        return;
    }

    completedPartners.forEach(name => {
        const neighbor = state.neighbors[name];
        if (!neighbor) return;

        let displayName = name;
        if (displayName === 'Liam Vance' || displayName === 'Liam') {
            displayName = 'Devon';
        } else if (displayName === 'Arthur Pendragon' || displayName === 'Arthur') {
            displayName = 'Artem';
        } else if (displayName === 'Maya Lin' || displayName === 'Emily') {
            displayName = 'Millissa Greenwood';
        } else if (displayName === 'Lily Rose' || displayName === 'Lily') {
            displayName = 'Lily ❤️';
        } else if (displayName === 'Daniel Craig' || displayName === 'Daniel') {
            displayName = 'Danny';
        }

        const avatarUrl = neighbor.avatar || "https://images.unsplash.com/photo-1544005313-94ddf0286df2?q=60&w=80&auto=format&fit=crop";
        const completedCount = neighbor.completedSwaps !== undefined ? neighbor.completedSwaps : 0;
        const karma = neighbor.vouches !== undefined ? neighbor.vouches : 0;

        const card = document.createElement('div');
        card.className = "flex items-center justify-between bg-white dark:bg-[#18201a] p-4 rounded-xl border border-outline-variant/30 shadow-sm mb-3 hover:bg-forest-green/5 transition-colors cursor-pointer";
        card.onclick = () => {
            closeSwapsPopupModal();
            openNeighborProfileModal(name);
        };

        card.innerHTML = `
            <div class="flex items-center gap-3.5">
                <div class="profile-avatar-ring w-12 h-12 flex-shrink-0"><img src="${avatarUrl}" class="w-full h-full object-cover rounded-full" /></div>
                <div>
                    <h4 class="font-bold text-[13.5px] text-on-surface">${displayName}</h4>
                    <p class="text-[10px] text-outline mt-0.5 flex items-center gap-1.5">
                        <span class="flex items-center text-forest-green font-semibold"><span class="material-symbols-outlined text-xs mr-0.5">volunteer_activism</span> ${karma} Karma</span>
                        <span class="text-outline-variant/30">•</span>
                        <span>${completedCount} swaps completed</span>
                    </p>
                </div>
            </div>
            <button class="h-8 bg-forest-green text-warm-cream px-3 font-bold text-[10px] rounded-lg active:scale-95 transition-transform flex items-center gap-1">
                View Profile
            </button>
        `;
        list.appendChild(card);
    });
};

