function setupCarouselScrollListeners() {
    const setups = [
        { carouselId: 'map-detail-carousel', dots: ['map-detail-dot-1', 'map-detail-dot-2', 'map-detail-dot-3'] },
        { carouselId: 'map-event-detail-carousel', dots: ['map-event-detail-dot-1', 'map-event-detail-dot-2', 'map-event-detail-dot-3'] },
        { carouselId: 'event-detail-carousel', dots: ['event-detail-dot-1', 'event-detail-dot-2', 'event-detail-dot-3'] }
    ];

    setups.forEach(setup => {
        const carousel = document.getElementById(setup.carouselId);
        if (!carousel) return;

        carousel.addEventListener('scroll', () => {
            const width = carousel.offsetWidth;
            if (width <= 0) return;
            const scrollLeft = carousel.scrollLeft;
            const activeIndex = Math.round(scrollLeft / width);
            
            setup.dots.forEach((dotId, index) => {
                const dot = document.getElementById(dotId);
                if (dot) {
                    dot.style.opacity = (index === activeIndex) ? '1' : '0.4';
                }
            });
        }, { passive: true });
    });
}

window.requestGPSCentering = function() {
    window.triggerHapticFeedback('medium');
    playSound('click');
    
    if (!navigator.geolocation) {
        alert("Geolocation is not supported by your browser/device.");
        return;
    }
    
    const gpsBtn = document.getElementById('gps-locate-btn');
    const icon = gpsBtn ? gpsBtn.querySelector('span') : null;
    if (icon) {
        icon.innerText = 'sync';
        icon.classList.add('animate-spin');
    }
    
    navigator.geolocation.getCurrentPosition((position) => {
        if (icon) {
            icon.innerText = 'gps_fixed';
            icon.classList.remove('animate-spin');
        }
        
        const lat = position.coords.latitude;
        const lng = position.coords.longitude;
        
        // Save to current user location
        if (!state.currentUser) state.currentUser = {};
        state.currentUser.lat = lat;
        state.currentUser.lng = lng;
        state.locationConsent = true;
        saveState();
        
        // Centering the map
        if (leafletMap) {
            leafletMap.setView([lat, lng], 15, { animate: true });
        }
        
        // Re-plot markers to adjust distance calculations
        plotMapMarkersOnly();
        
        playSound('success');
    }, (error) => {
        if (icon) {
            icon.innerText = 'gps_off';
            icon.classList.remove('animate-spin');
            setTimeout(() => { icon.innerText = 'gps_fixed'; }, 2000);
        }
        alert("Failed to retrieve GPS location: " + error.message);
    }, {
        timeout: 5000,
        enableHighAccuracy: true
    });
};

window.createListingAtCoords = function(lat, lng) {
    window.triggerHapticFeedback('medium');
    playSound('click');
    if (leafletMap) {
        leafletMap.closePopup();
    }
    
    // Switch to offering creation view
    showView('offer');
    
    // Set coordinates
    state.selectedMeetupCoords = { lat: lat, lng: lng };
    state.selectedMeetupRadius = 100;
    
    // Update map status indicator on offering form page
    const statusEl = document.getElementById('meetup-map-status');
    if (statusEl) {
        statusEl.classList.remove('hidden');
        statusEl.innerHTML = `<span class="material-symbols-outlined text-[14px]">check_circle</span> Location preset from map click`;
    }
};

window.createNeedAtCoords = function(lat, lng) {
    window.triggerHapticFeedback('medium');
    playSound('click');
    if (leafletMap) {
        leafletMap.closePopup();
    }
    
    const needTitle = prompt("What is your community need? (e.g., Sourdough starter help)");
    if (!needTitle) return;
    const needDesc = prompt("Provide some details for your need:");
    if (!needDesc) return;
    
    // Add to needs board
    const newNeed = {
        id: 'need-' + Date.now(),
        neighborName: state.currentUser ? ((state.currentUser.firstName || 'Lily') + ' ' + (state.currentUser.lastName || 'Kaufmann')) : 'Lily Kaufmann',
        avatar: state.currentUser ? state.currentUser.avatar : 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?q=60&w=80',
        time: 'Just now',
        location: 'Custom location',
        needTitle: needTitle,
        needDesc: needDesc,
        category: 'Handyman & Services', // default category
        lat: lat,
        lng: lng,
        createdAt: Date.now()
    };
    
    if (!state.needsBoard) state.needsBoard = [];
    state.needsBoard.unshift(newNeed);
    saveState();
    
    // Switch to needs board sub-view
    switchVillageSegment('needs');
    renderNeedsBoardView();

    if (leafletMap) {
        leafletMap.eachLayer(layer => {
            if (layer instanceof L.Marker || layer instanceof L.Circle) {
                leafletMap.removeLayer(layer);
            }
        });
        mapMarkers = [];
        plotMapMarkersOnly();
    }

    triggerSuccessConfetti();
    playSound('success');
};

window.selectCategoryChip = function(cat) {
    window.triggerHapticFeedback('light');
    playSound('click');
    
    if (cat === 'All') {
        activeCategoryFilter = null;
    } else {
        activeCategoryFilter = cat;
    }
    
    // Update all chip styling
    const chipContainers = ['list-category-chips', 'needs-category-chips'];
    chipContainers.forEach(containerId => {
        const container = document.getElementById(containerId);
        if (!container) return;
        
        container.querySelectorAll('button').forEach(btn => {
            const btnCat = btn.getAttribute('data-chip-category');
            if ((cat === 'All' && btnCat === 'All') || (cat !== 'All' && btnCat === cat)) {
                btn.className = "category-chip bg-forest-green border border-forest-green text-warm-cream dark:bg-[#308A5E] dark:border-[#308A5E] dark:text-[#18201a] text-[10px] font-bold px-3 py-1.5 rounded-full shrink-0 active:scale-95 transition-all cursor-pointer";
            } else {
                btn.className = "category-chip bg-white dark:bg-[#18201a] border border-outline-variant/30 text-on-surface-variant dark:text-warm-cream/80 text-[10px] font-bold px-3 py-1.5 rounded-full shrink-0 active:scale-95 transition-all cursor-pointer hover:bg-forest-green/5";
            }
        });
    });
    
    // Sync the bento grid highlights on the map view
    updateCategoryTrayUI();
    
    // Re-render views
    if (currentVillageSegment === 'list') {
        renderVillageListView();
    } else if (currentVillageSegment === 'needs') {
        renderNeedsBoardView();
    } else if (currentVillageSegment === 'events') {
        renderEventsList();
    } else if (currentVillageSegment === 'map' || currentVillageSegment === 'needs_map' || currentVillageSegment === 'gifts_map' || currentVillageSegment === 'events_map') {
        plotMapMarkersOnly();
    }
};

window.handleHashRoute = function() {
    const hash = window.location.hash;
    if (!hash || hash === '#/' || hash === '#') {
        if (state && state.currentView === 'village') return;
        showView('village');
    } else if (hash.startsWith('#/')) {
        const viewId = hash.substring(2).replace(/-/g, '_');
        const viewEl = document.getElementById(`view-${viewId}`);
        if (viewEl) {
            if (state && state.currentView === viewId) {
                if (window.logStartup) window.logStartup("handleHashRoute: already on view " + viewId + ", skipping duplicate showView.");
                return;
            }
            showView(viewId);
        } else {
            console.warn(`Hash view 'view-${viewId}' not found. Falling back to default.`);
            showView('village');
        }
    } else {
        console.warn(`Malformed hash route: ${hash}. Falling back to default.`);
        showView('village');
    }
};

window.addEventListener('hashchange', () => {
    window.handleHashRoute();
});

