function triggerAppStartupCoordination() {
    window.appJSLoaded = true;
    if (window.logStartup) window.logStartup("triggerAppStartupCoordination called. finalLogoRevealTriggered=" + window.finalLogoRevealTriggered + ", appIconShuffleIndex=" + window.appIconShuffleIndex);
    
    // Always start app initialization if the final logo reveal has already been triggered
    if (window.finalLogoRevealTriggered) {
        if (window.startAppInitialization) {
            if (window.logStartup) window.logStartup("triggerAppStartupCoordination calling startAppInitialization (finalLogoRevealTriggered is true)");
            window.startAppInitialization();
        }
        return;
    }
    
    const isTestMode = window.location.search.includes('test=true');
    const minShuffleCount = isTestMode ? 1 : 8;
    // If the inline script already reached the minShuffleCount, reveal logo/title and start app initialization.
    if (window.appIconShuffleIndex >= minShuffleCount) {
        if (window.logStartup) window.logStartup("triggerAppStartupCoordination: appIconShuffleIndex >= minShuffleCount. Triggering reveal & initialization.");
        if (window.revealLogoAndTitle) {
            window.revealLogoAndTitle();
        } else {
            window.finalLogoRevealTriggered = true;
            window.logoRevealTime = Date.now();
        }
        if (window.startAppInitialization) {
            window.startAppInitialization();
        }
    } else {
        if (window.logStartup) window.logStartup("triggerAppStartupCoordination: appIconShuffleIndex (" + window.appIconShuffleIndex + ") < minShuffleCount (" + minShuffleCount + "). Waiting for inline script.");
    }
}

// Execute immediately to prevent timing issues in native app wrappers
triggerAppStartupCoordination();

