function getShortTitle(title) {
    if (!title) return "";
    const words = title.trim().split(/\s+/);
    if (words.length === 0) return "";
    if (words.length === 1) return words[0];
    const twoWords = words.slice(0, 2).join(" ");
    if (twoWords.length > 15) {
        return words[0];
    }
    return twoWords;
}

