function submitOfferSwapProposal(isKarma) {
    if (state.chatLockdownMode) {
        alert("The community chat network is temporarily muted under administrative lockdown.");
        return;
    }
    
    const conv = state.conversations.find(c => c.id === state.currentConversationId);
    if (!conv) return;
    
    let offeredText = "";
    if (isKarma) {
        offeredText = "Karma Points";
    } else {
        const customText = document.getElementById('offer-swap-custom-text')?.value.trim() || "";
        const selectedListingId = state.selectedSwapListingId;
        
        if (selectedListingId) {
            const off = state.userOfferings.find(o => o.id === selectedListingId);
            if (off) {
                offeredText = off.title;
            }
        } else if (customText) {
            offeredText = customText;
        }
    }
    
    if (!offeredText) {
        const grid = document.getElementById('offer-swap-boxes-grid');
        const customText = document.getElementById('offer-swap-custom-text');
        if (grid) {
            grid.querySelectorAll('.swap-listing-box').forEach(btn => {
                btn.classList.add('error-swap-box');
            });
        }
        if (customText) {
            customText.classList.add('error-custom-text');
        }
        return;
    }
    
    // Safety checks
    if (!isKarma) {
        if (checkSafetyPolicy(offeredText)) {
            showSafetyContentViolation();
            return;
        }
        if (checkCashlessPolicy(offeredText)) {
            showSafetyMoneyWarning();
            return;
        }
        if (checkExactAddress(offeredText)) {
            showSafetyAddressWarning();
            return;
        }
    }
    
    // Construct offered message text
    let msgText = "";
    let offeredId = "";
    let offeredImage = PLACEHOLDER_IMAGE;
    let requestedId = "";
    let requestedImage = PLACEHOLDER_IMAGE;

    if (isKarma) {
        const req = conv.negotiation.requestedItem || "item";
        msgText = `Hey! I'm really interested in your "${req}". I don't have anything to trade right now, but would you be open to a Karma Swap? You'd receive +50 Karma Points for helping a neighbor, and it would mean the world to me! 💛✨`;
        conv.negotiation.isKarmaSwap = true;
    } else {
        const req = conv.negotiation.requestedItem || "item";
        msgText = `SWAP OFFER: I would like to swap my "${offeredText}" for your "${req}".`;
        conv.negotiation.isKarmaSwap = false;

        const selectedListingId = state.selectedSwapListingId;
        if (selectedListingId && selectedListingId !== 'custom') {
            const off = state.userOfferings.find(o => o.id === selectedListingId);
            if (off) {
                offeredId = off.id;
                offeredImage = off.image || PLACEHOLDER_IMAGE;
            }
        }
        
        const neighbor = state.neighbors[conv.neighborName];
        if (neighbor) {
            requestedId = conv.neighborName;
            requestedImage = neighbor.offerImg || PLACEHOLDER_IMAGE;
        }
    }
    
    // Send message in thread
    const newMsg = {
        sender: 'me',
        text: msgText,
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };
    if (isKarma) {
        newMsg.isKarmaSwapRequest = true;
        newMsg.requestedItem = conv.negotiation.requestedItem || "item";
    } else {
        newMsg.isSwapOffer = true;
        newMsg.offeredItemTitle = offeredText;
        newMsg.offeredItemImage = offeredImage;
        newMsg.offeredItemId = offeredId;
        newMsg.requestedItemTitle = conv.negotiation.requestedItem || "item";
        newMsg.requestedItemImage = requestedImage;
        newMsg.requestedItemId = requestedId;
    }
    conv.messages.push(newMsg);
    
    // Add admin confirmation message: "Swap proposed! Our team has sent the request to your neighbor. We'll let you know as soon as they respond."
    conv.messages.push({
        sender: 'App admin',
        text: "Swap proposed! Our team has sent the request to your neighbor. We'll let you know as soon as they respond.",
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    });
    
    // Update negotiation state
    conv.negotiation.status = 'pending';
    conv.negotiation.offeredItem = offeredText;
    conv.negotiation.isFromOfferSwapModal = true;
    
    saveState();
    closeOfferSwapModal();
    renderChatDetail(conv);
    if (typeof playSound === 'function') playSound('message');
    
    // Trigger confetti if a regular swap proposal was successfully submitted (not karma, and validation passed)
    if (!isKarma && typeof triggerSuccessConfetti === 'function') {
        triggerSuccessConfetti();
    }
    
    // Trigger partner mock accept after 4 seconds
    if (conv.mockAcceptTimer) {
        clearTimeout(conv.mockAcceptTimer);
    }
    conv.mockAcceptTimer = setTimeout(() => {
        window.simulatePartnerAccept(conv.id);
    }, 4000);
}

function closeChatExpirationBanner(convId) {
    const conv = state.conversations.find(c => c.id === convId);
    if (!conv) return;
    conv.expirationBannerDismissed = true;
    saveState();
    renderChatDetail(conv);
}

function simulateChatExpiration() {
    const conv = state.conversations.find(c => c.id === state.currentConversationId);
    if (!conv) return;
    
    // Force conversation to expire (48h up)
    conv.isOld = true;
    conv.timeLeft = '';
    conv.expirationBannerDismissed = false; // Reset to show banner
    
    // Set locationChosenAt sufficiently in the past to trigger review immediately
    if (conv.negotiation && conv.negotiation.meetupLocation) {
        conv.locationChosenAt = Date.now() - (48 * 60 * 60 * 1000 + 5000);
    }
    
    saveState();
    if (typeof playSound === 'function') playSound('message');
    
    // Trigger push notification with click callback
    triggerPushNotification(
        "Did you swap?",
        `Your conversation with ${conv.neighborName} has expired. Tap to record details.`,
        "question_mark",
        "chat_hub",
        () => openDidYouSwapModal(conv.id)
    );
    
    // Re-render views
    renderChatDetail(conv);
    renderConversationsList();
    alert(`48h expiration simulated for your chat with ${conv.neighborName}! Expired banner has been loaded and push notification sent.`);
}

function openDidYouSwapModal(convId) {
    const conv = state.conversations.find(c => c.id === convId);
    if (!conv) return;
    
    window.currentDidYouSwapConvId = convId;
    
    // Set title
    const titleEl = document.getElementById('did-you-swap-title');
    if (titleEl) titleEl.innerText = `Did you swap with ${conv.neighborName}?`;
    
    // Populate delete list options
    const select = document.getElementById('did-you-swap-delete-select');
    if (select) {
        select.innerHTML = '<option value="">Select a listing/need to delete...</option>';
        
        // Populate user offerings
        if (state.userOfferings && state.userOfferings.length > 0) {
            const group = document.createElement('optgroup');
            group.label = "Your Offerings";
            state.userOfferings.forEach(off => {
                const opt = document.createElement('option');
                opt.value = `offering_${off.id}`;
                opt.innerText = off.title;
                group.appendChild(opt);
            });
            select.appendChild(group);
        }
        
        // Populate user needs
        if (state.userNeeds && state.userNeeds.length > 0) {
            const group = document.createElement('optgroup');
            group.label = "Your Needs";
            state.userNeeds.forEach(need => {
                const opt = document.createElement('option');
                opt.value = `need_${need.id}`;
                opt.innerText = need.title;
                group.appendChild(opt);
            });
            select.appendChild(group);
        }
    }
    
    // Reset modal state fields
    const swapInput = document.getElementById('did-you-swap-input-item');
    if (swapInput) {
        if (conv.negotiation && conv.negotiation.offeredItem) {
            swapInput.value = conv.negotiation.offeredItem;
        } else {
            swapInput.value = "";
        }
    }
    
    const fbText = document.getElementById('did-you-swap-feedback-text');
    if (fbText) fbText.value = "";
    
    const delCheckbox = document.getElementById('did-you-swap-delete-checkbox');
    if (delCheckbox) delCheckbox.checked = false;
    
    const delContainer = document.getElementById('did-you-swap-delete-select-container');
    if (delContainer) delContainer.classList.add('hidden');
    
    setDidYouSwapRating(5);
    
    // Open modal animation classes
    const modal = document.getElementById('did-you-swap-modal');
    const inner = document.getElementById('did-you-swap-container');
    if (modal && inner) {
        modal.classList.remove('opacity-0', 'pointer-events-none');
        modal.classList.add('opacity-100');
        inner.classList.remove('translate-y-full');
        inner.classList.add('translate-y-0');
    }
    if (typeof playSound === 'function') playSound('click');
}

function closeDidYouSwapModal() {
    const modal = document.getElementById('did-you-swap-modal');
    const inner = document.getElementById('did-you-swap-container');
    if (modal && inner) {
        modal.classList.remove('opacity-100');
        modal.classList.add('opacity-0', 'pointer-events-none');
        inner.classList.remove('translate-y-0');
        inner.classList.add('translate-y-full');
    }
    if (typeof playSound === 'function') playSound('click');
}

function setDidYouSwapRating(rating) {
    document.getElementById('did-you-swap-rating-value').value = rating;
    const starsContainer = document.getElementById('did-you-swap-rating-stars');
    if (starsContainer) {
        const stars = starsContainer.children;
        for (let i = 0; i < stars.length; i++) {
            if (i < rating) {
                stars[i].classList.remove('text-gray-300');
                stars[i].classList.add('text-amber-500');
            } else {
                stars[i].classList.remove('text-amber-500');
                stars[i].classList.add('text-gray-300');
            }
        }
    }
}

function toggleDidYouSwapDeleteDropdown(chk) {
    const selectContainer = document.getElementById('did-you-swap-delete-select-container');
    if (selectContainer) {
        if (chk.checked) {
            selectContainer.classList.remove('hidden');
        } else {
            selectContainer.classList.add('hidden');
        }
    }
}

function submitDidYouSwapFeedback() {
    const convId = window.currentDidYouSwapConvId;
    const conv = state.conversations.find(c => c.id === convId);
    if (!conv) return;
    
    const swappedItem = document.getElementById('did-you-swap-input-item')?.value.trim() || "";
    if (!swappedItem) {
        alert("Please specify what you swapped.");
        return;
    }
    
    const feedbackText = document.getElementById('did-you-swap-feedback-text')?.value.trim() || "";
    const ratingValue = parseInt(document.getElementById('did-you-swap-rating-value')?.value) || 5;
    const shouldDelete = document.getElementById('did-you-swap-delete-checkbox')?.checked || false;
    
    // Process profile item deletion if checked
    if (shouldDelete) {
        const deleteSelect = document.getElementById('did-you-swap-delete-select');
        const selectedVal = deleteSelect ? deleteSelect.value : "";
        if (selectedVal) {
            if (selectedVal.startsWith('offering_')) {
                const offId = selectedVal.replace('offering_', '');
                state.userOfferings = state.userOfferings.filter(o => o.id !== offId);
                if (state.savedListings) {
                    state.savedListings = state.savedListings.filter(savedId => savedId !== offId);
                }
            } else if (selectedVal.startsWith('need_')) {
                const needId = selectedVal.replace('need_', '');
                state.userNeeds = state.userNeeds.filter(n => n.id !== needId);
                if (state.savedListings) {
                    state.savedListings = state.savedListings.filter(savedId => !savedId.endsWith(needId));
                }
            }
        }
    }
    
    
    // Record swap history
    if (!state.swapHistory) state.swapHistory = [];
    state.swapHistory.unshift({
        neighborName: conv.neighborName,
        offeredItem: swappedItem,
        requestedItem: conv.negotiation.requestedItem || 'Swap Item',
        date: 'Just now'
    });
    state.stats.tradesMade = (state.stats.tradesMade || 0) + 1;
    
    // Record completed swap details as a system message in the feed
    conv.messages.push({
        sender: 'System',
        text: `Swap complete! Transferred: "${swappedItem}". Rating left: ${ratingValue}★. Feedback: "${feedbackText || 'Smooth swap!'}"`,
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    });
    
    // Archive chat and set status to completed
    conv.isOld = true;
    conv.timeLeft = '';
    conv.negotiation.status = 'completed';
    conv.reviewed = true;
    
    saveState();
    closeDidYouSwapModal();
    
    // Update layout dashboards and listings
    refreshAllLayouts();
    renderProfileSettings();
    
    if (state.currentConversationId === conv.id) {
        renderChatDetail(conv);
    }
    
    if (typeof showTradeCelebrationOverlay === 'function') {
        showTradeCelebrationOverlay(conv);
    }
    
    alert(`Swap recorded! You earned +25 Karma points for completing your trade and leaving feedback! 🌿`);
}

