window.viewMeetupLocationOnMap = function(convId) {
    const conv = state.conversations.find(c => c.id === convId);
    if (!conv || !conv.negotiation || !conv.negotiation.meetupLocation) return;

    let lat = conv.negotiation.meetupLat;
    let lng = conv.negotiation.meetupLng;
    if (!lat || !lng) {
        const msg = conv.messages.find(m => m.isLocationSuggestion && m.locationData);
        if (msg && msg.locationData) {
            lat = msg.locationData.lat;
            lng = msg.locationData.lng;
        }
    }
    
    if (!lat || !lng) {
        lat = 49.2608;
        lng = -123.1368;
    }

    state.meetupMapMode = true;
    state.meetupMapCoords = { lat, lng };
    state.meetupMapName = conv.negotiation.meetupLocation;

    showView('village');
    switchVillageSegment('map');
};

window.exitMeetupMapMode = function() {
    state.meetupMapMode = false;
    state.meetupMapCoords = null;
    state.meetupMapName = null;
    
    const meetupCloseBtn = document.getElementById('meetup-close-btn');
    if (meetupCloseBtn) meetupCloseBtn.classList.add('hidden');
    
    const mapControls = document.getElementById('floating-map-controls');
    if (mapControls) mapControls.classList.remove('hidden');
    
    const navBar = document.getElementById('global-navbar');
    if (navBar) navBar.classList.remove('hidden');
    
    showView('chat_detail');
};

