window.openItemDetailsByTitle = function(title, neighborName) {
    if (!title) return;
    const cleanTitle = title.toLowerCase().trim();
    if (cleanTitle.includes('karma') || cleanTitle.includes('standing') || cleanTitle.includes('free') || cleanTitle.includes('points')) {
        openProfileStatExplanation('karma');
        return;
    }
    // 1. Check user offerings
    if (state && state.userOfferings) {
        const userOffer = state.userOfferings.find(o => o && o.title && (o.title.toLowerCase().includes(cleanTitle) || cleanTitle.includes(o.title.toLowerCase())));
        if (userOffer) {
            openMapItemDetail(userOffer.id);
            return;
        }
    }
    // 2. Check neighborName's offering
    if (neighborName) {
        const n = state.neighbors[neighborName];
        if (n && n.offerTitle && (n.offerTitle.toLowerCase().includes(cleanTitle) || cleanTitle.includes(n.offerTitle.toLowerCase()))) {
            openMapItemDetail(neighborName);
            return;
        }
    }
    // 3. Fallback: Search all neighbors
    if (state && state.neighbors) {
        for (const name in state.neighbors) {
            const n = state.neighbors[name];
            if (n && n.offerTitle && (n.offerTitle.toLowerCase().includes(cleanTitle) || cleanTitle.includes(n.offerTitle.toLowerCase()))) {
                openMapItemDetail(name);
                return;
            }
        }
    }
    alert(`Details for "${title}" are not available.`);
};

function handleChatBackButton() {
    if (typeof playSound === 'function') playSound('click');
    
    // Blur any active text input/textarea to dismiss the virtual keyboard safely
    const activeEl = document.activeElement;
    if (activeEl && (activeEl.tagName === 'INPUT' || activeEl.tagName === 'TEXTAREA')) {
        activeEl.blur();
    }

    if (state.chatBackReferrer && state.chatBackReferrer.type === 'neighbor_profile') {
        const neighborName = state.chatBackReferrer.name;
        const prevView = state.chatBackReferrer.previousView || 'chat_hub';
        state.chatBackReferrer = null; // Clear it to avoid loop
        showView(prevView);
        openNeighborProfileModal(neighborName);
    } else if (state.chatBackReferrer && state.chatBackReferrer.type === 'map_detail') {
        const referrerId = state.chatBackReferrer.id;
        state.chatBackReferrer = null; // Clear it to avoid loop
        openMapItemDetail(referrerId);
    } else {
        showView('chat_hub');
    }
}
window.handleChatBackButton = handleChatBackButton;
window.dismissNewUserChatWarning = function() {
    if (typeof closeSafetyHelpGuideModal === 'function') {
        closeSafetyHelpGuideModal();
    }
};

