function renderReviewsList() {
    const container = document.getElementById('chat-threads-container');
    if (!container) return;
    container.innerHTML = "";

    // Set header bar contents for reviews!
    const headerTitleEl = document.getElementById('chat-hub-title-text');
    const headerBarEl = document.getElementById('chat-hub-title-bar');
    const headerRightEl = document.getElementById('chat-hub-header-right');
    if (headerTitleEl && headerBarEl && headerRightEl) {
        const activeColor = '#ef4444'; // Red color
        headerTitleEl.innerText = 'Reviews';
        headerTitleEl.style.setProperty('color', activeColor, 'important');
        headerBarEl.className = 'w-[8px] h-[22px] rounded-full flex-shrink-0';
        headerBarEl.style.setProperty('background-color', activeColor, 'important');
        headerRightEl.innerHTML = `
            <button onclick="showChatAutoDeleteInfo()" class="w-10 h-10 rounded-full flex items-center justify-center bg-black/5 dark:bg-white/10 hover:bg-black/10 dark:hover:bg-white/20 active:scale-90 transition-all cursor-pointer text-black dark:text-warm-cream border border-black/10 dark:border-white/10 flex-shrink-0 shadow-sm" title="Auto-Delete Info">
                <span class="material-symbols-outlined text-[20px]">info</span>
            </button>
        `;
    }

    const reviews = getPendingReviews().slice(0, 5); // Max 5 people

    if (reviews.length === 0) {
        const div = document.createElement('div');
        div.className = "text-center py-10 text-outline space-y-2 select-none";
        div.innerHTML = `
            <span class="material-symbols-outlined text-4xl text-red-500/50">rate_review</span>
            <p class="text-xs font-semibold">No pending reviews right now.</p>
            <p class="text-[10px] text-outline/60 px-6">Completed swaps will appear here for review immediately after they disappear from active chats.</p>
        `;
        container.appendChild(div);
        return;
    }

    reviews.forEach(rev => {
        const cardWrapper = document.createElement('div');
        cardWrapper.className = "relative overflow-hidden w-full border-b border-outline-variant/10 bg-[#18201a]/5 dark:bg-black/10";

        // Swipe Action (slide to left to delete/opt-out with no popup)
        const buttonsHtml = `
            <div class="absolute inset-0 bg-[#ef4444] flex items-center justify-end pr-8 text-white select-none z-0 cursor-pointer" onclick="event.stopPropagation(); window.handleReviewDelete('${rev.id}')">
                <div class="flex flex-col items-center gap-1 select-none mr-2">
                    <span class="material-symbols-outlined text-[20px] font-bold">delete</span>
                    <span class="text-[10px] font-bold uppercase tracking-wider">Delete</span>
                </div>
            </div>
        `;

        const card = document.createElement('div');
        card.className = "chat-card-slider-content group flex items-center gap-4 py-3.5 px-6 cursor-pointer transition-transform duration-200 relative z-10 bg-white dark:bg-[#18201a]";
        card.style.transform = "translateX(0px)";
        
        card.onclick = (e) => {
            let transformX = 0;
            const transform = card.style.transform;
            if (transform) {
                const match = transform.match(/translateX\(([-\d.]+)px\)/) || transform.match(/translateX\(([-\d.]+)\)/);
                if (match) {
                    transformX = parseFloat(match[1]);
                }
            }
            if (Math.abs(transformX) > 5) {
                e.stopPropagation();
                closeSwipeCard(card);
            } else {
                window.openNeighborReviewModal(rev.id);
            }
        };

        const avatarHtml = `<div class="profile-avatar-ring w-14 h-14 flex-shrink-0"><img alt="${escapeHTML(rev.neighborName)}" class="w-full h-full object-cover rounded-full" src="${rev.avatar}"/></div>`;

        // Calculate time left for the review (it disappears after 48h in review section)
        const elapsed = Date.now() - rev.createdAt;
        const remainingMs = Math.max(0, 48 * 60 * 60 * 1000 - elapsed);
        const remainingHours = Math.round(remainingMs / (60 * 60 * 1000));
        const timeLeftText = `Review Pending • ${remainingHours} hours left`;

        card.innerHTML = `
            <div class="relative flex-shrink-0 select-none w-14 overflow-visible">
                <div class="relative w-14 h-14 overflow-visible">
                    ${avatarHtml}
                </div>
            </div>
            <div class="flex-grow min-w-0 flex flex-col justify-center gap-1">
                <h3 class="font-headline text-base font-bold text-on-surface truncate leading-tight">
                    ${escapeHTML(rev.neighborName)}
                </h3>
                <div class="flex items-center gap-1.5 text-[11px] font-bold leading-tight">
                    <span class="material-symbols-outlined text-[13px] font-bold text-red-600 dark:text-red-400">schedule</span>
                    <span class="text-gray-500 dark:text-gray-400">${remainingHours}h left Review Pending</span>
                </div>
            </div>
        `;

        cardWrapper.innerHTML = buttonsHtml;
        cardWrapper.appendChild(card);
        container.appendChild(cardWrapper);

        // Bind Touch/Mouse slider actions for review card
        setupReviewSwipeGestures(card, rev.id);
    });
}
window.renderReviewsList = renderReviewsList;

function setupReviewSwipeGestures(sliderEl, reviewId) {
    let startX = 0;
    let startY = 0;
    let currentTranslateX = 0;
    let isDragging = false;
    let isVerticalSwipe = false;
    const dragThreshold = 10;

    let hasMoved = false;

    const startDrag = (clientX, clientY) => {
        if (openSwipeCard && openSwipeCard !== sliderEl) {
            closeSwipeCard(openSwipeCard);
        }

        startX = clientX;
        startY = clientY;
        isDragging = true;
        isVerticalSwipe = false;
        hasMoved = false;

        const transformMatrix = window.getComputedStyle(sliderEl).transform;
        if (transformMatrix && transformMatrix !== 'none') {
            const matrixValues = transformMatrix.split('(')[1].split(')')[0].split(',');
            currentTranslateX = parseInt(matrixValues[4]) || 0;
        } else {
            currentTranslateX = 0;
        }

        sliderEl.style.transition = 'none';
    };

    const moveDrag = (clientX, clientY, preventDefaultFn) => {
        if (!isDragging) return;

        const diffX = clientX - startX;
        const diffY = clientY - startY;

        if (Math.abs(diffX) > 5 || Math.abs(diffY) > 5) {
            hasMoved = true;
        }

        if (!isVerticalSwipe) {
            if (Math.abs(diffY) > Math.abs(diffX) && Math.abs(diffY) > dragThreshold) {
                isVerticalSwipe = true;
                isDragging = false;
                sliderEl.style.transition = 'transform 0.25s cubic-bezier(0.16, 1, 0.3, 1)';
                sliderEl.style.transform = 'translateX(0px)';
                return;
            }
        }

        const maxTranslate = -sliderEl.offsetWidth || -360;

        if (Math.abs(diffX) > dragThreshold) {
            if (typeof preventDefaultFn === 'function') preventDefaultFn();
            let newX = currentTranslateX + diffX;
            if (newX > 0) newX = 0;
            if (newX < maxTranslate) {
                newX = maxTranslate;
            }
            sliderEl.style.transform = `translateX(${newX}px)`;
            if (newX < -10) {
                openSwipeCard = sliderEl;
            }
        }
    };

    const endDrag = () => {
        if (!isDragging) return;
        isDragging = false;

        sliderEl.style.transition = 'transform 0.3s cubic-bezier(0.16, 1, 0.3, 1)';
        
        if (!hasMoved) {
            if (Math.abs(currentTranslateX) > 5) {
                closeSwipeCard(sliderEl);
            } else {
                window.openNeighborReviewModal(reviewId);
            }
            return;
        }
        
        const transformMatrix = window.getComputedStyle(sliderEl).transform;
        let finalX = 0;
        if (transformMatrix && transformMatrix !== 'none') {
            const matrixValues = transformMatrix.split('(')[1].split(')')[0].split(',');
            finalX = parseInt(matrixValues[4]) || 0;
        }

        const maxTranslate = -sliderEl.offsetWidth || -360;
        const triggerThreshold = maxTranslate * 0.40;

        if (finalX < triggerThreshold) {
            sliderEl.style.transition = 'transform 0.25s cubic-bezier(0.16, 1, 0.3, 1)';
            sliderEl.style.transform = `translateX(${maxTranslate}px)`;
            if (openSwipeCard === sliderEl) openSwipeCard = null;
            setTimeout(() => {
                window.handleReviewDelete(reviewId);
            }, 250);
        } else {
            sliderEl.style.transform = 'translateX(0px)';
            if (openSwipeCard === sliderEl) openSwipeCard = null;
        }
    };

    sliderEl.addEventListener('touchstart', (e) => {
        startDrag(e.touches[0].clientX, e.touches[0].clientY);
    }, { passive: true });

    sliderEl.addEventListener('touchmove', (e) => {
        moveDrag(e.touches[0].clientX, e.touches[0].clientY, () => {
            if (e.cancelable) e.preventDefault();
        });
    }, { passive: false });

    sliderEl.addEventListener('touchend', () => {
        endDrag();
    }, { passive: true });

    sliderEl.addEventListener('mousedown', (e) => {
        startDrag(e.clientX, e.clientY);
        
        const mouseMoveHandler = (moveEvt) => {
            moveDrag(moveEvt.clientX, moveEvt.clientY);
        };
        
        const mouseUpHandler = () => {
            endDrag();
            document.removeEventListener('mousemove', mouseMoveHandler);
            document.removeEventListener('mouseup', mouseUpHandler);
        };
        
        document.addEventListener('mousemove', mouseMoveHandler);
        document.addEventListener('mouseup', mouseUpHandler);
    });
}
window.setupReviewSwipeGestures = setupReviewSwipeGestures;

window.handleReviewDelete = function(reviewId) {
    if (openSwipeCard) {
        closeSwipeCard(openSwipeCard);
    }

    if (typeof playSound === 'function') playSound('click');

    // 1. Check if fictitious review
    if (state.fictitiousReviews) {
        const fakeIndex = state.fictitiousReviews.findIndex(r => r.id === reviewId);
        if (fakeIndex !== -1) {
            state.fictitiousReviews.splice(fakeIndex, 1);
            saveState();
            renderReviewsList();
            updateChatNotificationBadge();
            showToast("Review removed.");
            return;
        }
    }

    // 2. Check if real review
    if (reviewId.startsWith('rev-')) {
        const convId = reviewId.replace('rev-', '');
        const conv = state.conversations.find(c => c.id === convId);
        if (conv) {
            conv.reviewDeleted = true;
            saveState();
            renderReviewsList();
            updateChatNotificationBadge();
            showToast("Review removed.");
        }
    }
};



let fusedReviewTargetId = null;
let fusedReviewTargetType = null;
let fusedReviewVote = null;
let fusedReviewFriend = false;
let fusedReviewBlock = false;
let fusedReviewTags = [];

window.openFusedReviewModal = function(neighborName, convId, reviewId) {
    if (typeof playSound === 'function') playSound('click');
    
    // Clear and reset state variables
    fusedReviewTargetId = convId || reviewId;
    fusedReviewTargetType = convId ? 'conversation' : 'review';
    fusedReviewVote = null;
    fusedReviewFriend = false;
    fusedReviewBlock = false;
    fusedReviewTags = [];

    // Find neighbor
    let neighbor = state.neighbors[neighborName];
    if (!neighbor) {
        const lowerName = neighborName.trim().toLowerCase();
        const foundKey = Object.keys(state.neighbors).find(k => k.toLowerCase() === lowerName);
        if (foundKey) neighbor = state.neighbors[foundKey];
    }
    
    // Header data: Name
    const nameEl = document.getElementById('confirm-swap-neighbor-name');
    if (nameEl) nameEl.innerText = neighborName;

    // Avatar
    const avatarEl = document.getElementById('confirm-swap-avatar');
    if (avatarEl) {
        avatarEl.src = neighbor ? neighbor.avatar : "https://images.unsplash.com/photo-1544005313-94ddf0286df2?q=60&w=80&auto=format&fit=crop";
    }

    // Karma points
    const karmaEl = document.getElementById('confirm-swap-karma-points');
    if (karmaEl) {
        const nKarma = neighbor ? (neighbor.karmaPoints !== undefined ? neighbor.karmaPoints : ((neighbor.vouches || 0) * 12 + 30)) : 50;
        karmaEl.innerText = nKarma;
    }

    // Details of items being swapped
    const detailsEl = document.getElementById('confirm-swap-items-details');
    if (detailsEl) {
        let detailsText = "No active swap proposal found.";
        if (convId) {
            const conv = state.conversations.find(c => c.id === convId);
            if (conv && conv.negotiation) {
                const offered = conv.negotiation.offeredItem || 'Swap Item';
                const requested = conv.negotiation.requestedItem || 'Swap Item';
                if (conv.negotiation.isKarmaSwap || offered === 'Karma Points') {
                    detailsText = `${requested} (for Karma Points)`;
                } else {
                    detailsText = `${offered} ⇄ ${requested}`;
                }
            }
        } else if (reviewId) {
            let rev = null;
            if (state.fictitiousReviews) {
                rev = state.fictitiousReviews.find(r => r.id === reviewId);
            }
            if (!rev && reviewId.startsWith('rev-')) {
                const cId = reviewId.replace('rev-', '');
                const conv = state.conversations.find(c => c.id === cId);
                if (conv && conv.negotiation) {
                    rev = {
                        offeredItem: conv.negotiation.offeredItem,
                        requestedItem: conv.negotiation.requestedItem
                    };
                }
            }
            if (rev) {
                const offered = rev.offeredItem || 'Swap Item';
                const requested = rev.requestedItem || 'Swap Item';
                detailsText = `${offered} ⇄ ${requested}`;
            } else {
                detailsText = "Completed swap";
            }
        }
        detailsEl.innerText = detailsText;
    }

    // Written review text label and placeholder
    const feedbackLabel = document.getElementById('confirm-swap-written-feedback-label');
    if (feedbackLabel) {
        feedbackLabel.innerText = `Write a public review for ${neighborName}:`;
    }
    const feedbackTextarea = document.getElementById('confirm-swap-written-feedback');
    if (feedbackTextarea) {
        feedbackTextarea.value = "";
        feedbackTextarea.placeholder = `Tell us more details about your swap with ${neighborName} (optional)...`;
    }

    // Reset tag buttons styling
    document.querySelectorAll('.fused-tag-btn').forEach(btn => {
        btn.className = "fused-tag-btn px-2.5 py-1.5 bg-white dark:bg-[#1b261f] border border-outline-variant/20 rounded-lg text-[10px] font-bold hover:border-red-500 cursor-pointer text-black dark:text-white";
    });

    // Update UI buttons and negative menu visibility
    updateFusedReviewUI();

    // Show modal
    const modal = document.getElementById('confirm-swap-rating-modal');
    if (modal) {
        modal.classList.remove('hidden');
        modal.classList.add('flex');
    }
};

window.openFusedReviewModalFromChat = function() {
    if (state.currentConversationId) {
        window.openConfirmSwapRatingModal(state.currentConversationId);
    }
};

window.toggleFusedRating = function(choice) {
    if (typeof playSound === 'function') playSound('click');

    if (choice === 'up') {
        fusedReviewVote = (fusedReviewVote === 'up') ? null : 'up';
        fusedReviewTags = [];
    } else if (choice === 'down') {
        fusedReviewVote = (fusedReviewVote === 'down') ? null : 'down';
    } else if (choice === 'friend') {
        fusedReviewFriend = !fusedReviewFriend;
        if (fusedReviewFriend) {
            fusedReviewBlock = false;
            fusedReviewTags = [];
            if (fusedReviewVote === 'down') {
                fusedReviewVote = null;
            }
        }
    } else if (choice === 'block') {
        fusedReviewBlock = !fusedReviewBlock;
        if (fusedReviewBlock) {
            fusedReviewFriend = false;
            if (fusedReviewVote === 'up') {
                fusedReviewVote = null;
            }
        }
    }

    updateFusedReviewUI();
};

window.toggleFusedTag = function(btn, tag) {
    if (typeof playSound === 'function') playSound('click');
    const index = fusedReviewTags.indexOf(tag);
    if (index !== -1) {
        fusedReviewTags.splice(index, 1);
        btn.className = "fused-tag-btn px-2.5 py-1.5 bg-white dark:bg-[#1b261f] border border-outline-variant/20 rounded-lg text-[10px] font-bold hover:border-red-500 cursor-pointer text-black dark:text-white";
    } else {
        fusedReviewTags.push(tag);
        btn.className = "fused-tag-btn px-2.5 py-1.5 bg-red-500/10 dark:bg-red-500/20 border border-red-500 text-red-500 font-bold rounded-lg text-[10px] cursor-pointer";
    }
};

window.updateFusedReviewUI = function() {
    const upBtn = document.getElementById('fused-btn-up');
    const friendBtn = document.getElementById('fused-btn-friend');
    const downBtn = document.getElementById('fused-btn-down');
    const blockBtn = document.getElementById('fused-btn-block');
    const negativeMenu = document.getElementById('confirm-swap-negative-menu');

    // Vote Up
    if (upBtn) {
        if (fusedReviewVote === 'up') {
            upBtn.className = "h-12 rounded-xl bg-[#22c55e] border border-[#22c55e] text-white active:scale-95 transition-all flex flex-col items-center justify-center cursor-pointer shadow-sm";
        } else {
            upBtn.className = "h-12 rounded-xl bg-white dark:bg-[#1b261f] border border-outline-variant/20 text-[#22c55e] active:scale-95 transition-all flex flex-col items-center justify-center cursor-pointer shadow-sm hover:border-[#22c55e]";
        }
    }

    // Friend
    if (friendBtn) {
        if (fusedReviewFriend) {
            friendBtn.className = "h-12 rounded-xl bg-[#22c55e] border border-[#22c55e] text-white active:scale-95 transition-all flex flex-col items-center justify-center cursor-pointer shadow-sm";
        } else {
            friendBtn.className = "h-12 rounded-xl bg-white dark:bg-[#1b261f] border border-outline-variant/20 text-[#22c55e] active:scale-95 transition-all flex flex-col items-center justify-center cursor-pointer shadow-sm hover:border-[#22c55e]";
        }
    }

    // Vote Down
    if (downBtn) {
        if (fusedReviewVote === 'down') {
            downBtn.className = "h-12 rounded-xl bg-[#ef4444] border border-[#ef4444] text-white active:scale-95 transition-all flex flex-col items-center justify-center cursor-pointer shadow-sm";
        } else {
            downBtn.className = "h-12 rounded-xl bg-white dark:bg-[#1b261f] border border-outline-variant/20 text-[#ef4444] active:scale-95 transition-all flex flex-col items-center justify-center cursor-pointer shadow-sm hover:border-[#ef4444]";
        }
    }

    // Block
    if (blockBtn) {
        if (fusedReviewBlock) {
            blockBtn.className = "h-12 rounded-xl bg-[#ef4444] border border-[#ef4444] text-white active:scale-95 transition-all flex flex-col items-center justify-center cursor-pointer shadow-sm";
        } else {
            blockBtn.className = "h-12 rounded-xl bg-white dark:bg-[#1b261f] border border-outline-variant/20 text-[#ef4444] active:scale-95 transition-all flex flex-col items-center justify-center cursor-pointer shadow-sm hover:border-[#ef4444]";
        }
    }

    // Negative Menu Visibility
    if (negativeMenu) {
        if (fusedReviewVote === 'down') {
            negativeMenu.classList.remove('hidden');
            negativeMenu.classList.add('flex');
        } else {
            negativeMenu.classList.add('hidden');
            negativeMenu.classList.remove('flex');
        }
    }
};

window.submitFusedReview = function() {
    if (!fusedReviewTargetId) return;
    
    const neighborName = document.getElementById('confirm-swap-neighbor-name').innerText.trim();
    const commentEl = document.getElementById('confirm-swap-written-feedback');
    const comment = commentEl ? commentEl.value.trim() : "";

    // 1. Adjust neighbor's karma
    const targetNeighbor = state.neighbors[neighborName];
    if (targetNeighbor) {
        if (targetNeighbor.karmaPoints === undefined) {
            targetNeighbor.karmaPoints = targetNeighbor.vouches ? targetNeighbor.vouches * 10 : 50;
        }
        if (fusedReviewVote === 'up') {
            targetNeighbor.karmaPoints = (targetNeighbor.karmaPoints || 0) + 10;
        } else if (fusedReviewVote === 'down') {
            targetNeighbor.karmaPoints = Math.max(0, (targetNeighbor.karmaPoints || 0) - 10);
        }
    }

    // 2. Add Friend
    if (fusedReviewFriend) {
        if (!state.friends) state.friends = [];
        const alreadyFriend = state.friends.some(f => f.name.toLowerCase() === neighborName.toLowerCase());
        if (!alreadyFriend) {
            const neighbor = state.neighbors[neighborName];
            state.friends.push({
                name: neighbor ? neighbor.name : neighborName,
                avatar: neighbor ? neighbor.avatar : "https://images.unsplash.com/photo-1544005313-94ddf0286df2?q=60&w=80&auto=format&fit=crop",
                phone: neighbor ? (neighbor.phone || '+1 (604) 555-0199') : '+1 (604) 555-0199'
            });
        }
    }

    // 3. Block User
    if (fusedReviewBlock) {
        if (!state.blockedUsers) state.blockedUsers = [];
        if (!state.blockedUsers.includes(neighborName)) {
            state.blockedUsers.push(neighborName);
        }
    }

    // 4. Submit report/feedback to reportedAccounts admin backend
    if (fusedReviewTags.length > 0 || comment !== "" || fusedReviewBlock) {
        if (!state.reportedAccounts) state.reportedAccounts = [];
        let explanation = `Vote: ${fusedReviewVote === 'up' ? 'Thumbs Up 👍' : (fusedReviewVote === 'down' ? 'Thumbs Down 👎' : 'None')}`;
        if (fusedReviewFriend) explanation += ` | Action: Add Friend`;
        if (fusedReviewBlock) explanation += ` | Action: Block User`;
        if (comment) explanation += ` | Message: "${comment}"`;
        
        const reportObj = {
            id: 'report-' + Date.now(),
            neighborName: neighborName,
            targetType: 'review',
            reasons: fusedReviewTags.length > 0 ? fusedReviewTags : ['Feedback Given'],
            explanation: explanation,
            time: new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit' })
        };
        state.reportedAccounts.push(reportObj);
    }

    // 5. Update Conversation or Fictitious Review list
    let showListingCleanup = false;
    let cleanupConvId = null;

    if (fusedReviewTargetType === 'conversation') {
        const conv = state.conversations.find(c => c.id === fusedReviewTargetId);
        if (conv) {
            if (conv.negotiation) {
                conv.negotiation.status = 'completed';
                conv.negotiation.rating = fusedReviewVote === 'up' ? 5 : (fusedReviewVote === 'down' ? 1 : 3);
                conv.negotiation.ratingText = comment || (fusedReviewVote === 'up' ? 'great, thank you!' : 'poor experience');
            }
            conv.reviewed = true;
            conv.reviewSubmitted = true;
            
            // Push system message
            conv.messages.push({
                sender: 'System',
                text: `Swap verified! Trade is officially completed. Rating left: "${fusedReviewVote === 'up' ? 'Thumbs Up 👍' : (fusedReviewVote === 'down' ? 'Thumbs Down 👎' : 'No rating left')}". Congratulations! 🎉`,
                time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
            });

            // Trigger confetti
            if (typeof triggerSuccessConfetti === 'function') {
                triggerSuccessConfetti();
            }

            showListingCleanup = true;
            cleanupConvId = conv.id;
        }
    } else if (fusedReviewTargetType === 'review') {
        if (state.fictitiousReviews) {
            state.fictitiousReviews = state.fictitiousReviews.filter(r => r.id !== fusedReviewTargetId && r.neighborName !== neighborName);
        }
    }

    // 6. Award XP (+10)
    addKarmaXP(10);

    saveState();
    closeConfirmSwapRatingModal();
    updateChatNotificationBadge();

    if (state.currentView === 'chat_detail' && fusedReviewTargetType === 'conversation') {
        const conv = state.conversations.find(c => c.id === fusedReviewTargetId);
        if (conv) renderChatDetail(conv);
    }
    renderConversationsList();

    showToast("Review submitted successfully!");

    // Open Listing Cleanup modal if it was a real conversation
    if (showListingCleanup && cleanupConvId) {
        setTimeout(() => {
            window.openCleanupListingsModal(cleanupConvId);
        }, 300);
    }
};

window.skipFusedReview = function() {
    if (typeof playSound === 'function') playSound('click');
    
    const neighborName = document.getElementById('confirm-swap-neighbor-name').innerText.trim();

    if (fusedReviewTargetType === 'conversation') {
        const conv = state.conversations.find(c => c.id === fusedReviewTargetId);
        if (conv) {
            if (conv.negotiation) {
                conv.negotiation.status = 'completed';
                conv.negotiation.rating = 3;
                conv.negotiation.ratingText = 'skipped';
            }
            conv.reviewed = true;
            conv.reviewSubmitted = true;
            conv.messages.push({
                sender: 'System',
                text: `Swap marked as complete without rating.`,
                time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
            });
        }
    } else if (fusedReviewTargetType === 'review') {
        if (state.fictitiousReviews) {
            state.fictitiousReviews = state.fictitiousReviews.filter(r => r.id !== fusedReviewTargetId && r.neighborName !== neighborName);
        }
    }

    saveState();
    closeConfirmSwapRatingModal();
    updateChatNotificationBadge();
    
    if (state.currentView === 'chat_detail' && fusedReviewTargetType === 'conversation') {
        const conv = state.conversations.find(c => c.id === fusedReviewTargetId);
        if (conv) renderChatDetail(conv);
    }
    renderConversationsList();
};

window.notCompletedFusedReview = function() {
    if (typeof playSound === 'function') playSound('click');

    if (fusedReviewTargetType === 'conversation') {
        const conv = state.conversations.find(c => c.id === fusedReviewTargetId);
        if (conv) {
            if (conv.negotiation) {
                conv.negotiation.status = 'failed';
            }
            conv.reviewed = true;
            conv.reviewSubmitted = true;
            conv.messages.push({
                sender: 'System',
                text: `Swap marked as not completed. Negotiation failed.`,
                time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
            });
        }
    }

    saveState();
    closeConfirmSwapRatingModal();
    showToast("Swap marked as not completed.");
    updateChatNotificationBadge();

    if (state.currentView === 'chat_detail' && fusedReviewTargetType === 'conversation') {
        const conv = state.conversations.find(c => c.id === fusedReviewTargetId);
        if (conv) renderChatDetail(conv);
    }
    renderConversationsList();
};

window.openNeighborReviewModal = function(reviewId) {
    let rev = null;
    let isRealConv = false;
    let convId = null;

    if (state.fictitiousReviews) {
        rev = state.fictitiousReviews.find(r => r.id === reviewId);
    }
    if (!rev && reviewId && typeof reviewId === 'string' && reviewId.startsWith('rev-')) {
        convId = reviewId.replace('rev-', '');
        const conv = state.conversations.find(c => c.id === convId);
        if (conv) {
            isRealConv = true;
            rev = {
                id: reviewId,
                neighborName: conv.neighborName
            };
        }
    }
    if (!rev) {
        if (state.fictitiousReviews) {
            rev = state.fictitiousReviews.find(r => r.neighborName === reviewId || r.id === reviewId);
        }
        if (!rev && state.conversations) {
            const conv = state.conversations.find(c => c.neighborName === reviewId);
            if (conv) {
                isRealConv = true;
                convId = conv.id;
                rev = { id: 'rev-' + conv.id, neighborName: conv.neighborName };
            }
        }
        if (!rev && reviewId) {
            rev = { id: 'temp-' + Date.now(), neighborName: reviewId };
        }
    }
    if (!rev) return;

    if (isRealConv) {
        window.openFusedReviewModal(rev.neighborName, convId, null);
    } else {
        window.openFusedReviewModal(rev.neighborName, null, rev.id);
    }
};

window.openConfirmSwapRatingModal = function(convId) {
    const conv = state.conversations.find(c => c.id === convId);
    if (!conv) return;
    window.openFusedReviewModal(conv.neighborName, convId, null);
};

window.openDidYouSwapModal = function(convId) {
    const conv = state.conversations.find(c => c.id === convId);
    if (!conv) return;
    window.openFusedReviewModal(conv.neighborName, convId, null);
};

// Automatically update --chat-input-height based on the actual height of the chat action center container
const initChatInputHeightObserver = () => {
    const actionCenter = document.getElementById('chat-action-center');
    const feed = document.getElementById('chat-message-feed');
    if (!actionCenter || !feed) return;
    
    const observer = new ResizeObserver((entries) => {
        for (let entry of entries) {
            const height = actionCenter.offsetHeight;
            if (height > 0) {
                feed.style.setProperty('--chat-input-height', `${height}px`);
            }
        }
    });
    observer.observe(actionCenter);
};
document.addEventListener('DOMContentLoaded', initChatInputHeightObserver);

window.handleChatInputWrapperClick = function(event, wrapper) {
    if (event.target.closest('button') || event.target.closest('input[type="file"]') || event.target.tagName.toLowerCase() === 'input') {
        return;
    }
    const input = wrapper.querySelector('input[type="text"]');
    if (input) {
        input.focus();
    }
};
// Unified Swap/Karma Request Modal Lifecycle (State A & State B)
