window.submitLifecycleSwap = function(isKarma) {
    if (state.chatLockdownMode) {
        alert("The community chat network is temporarily muted under administrative lockdown.");
        return;
    }
    const conv = state.conversations.find(c => c.id === state.currentConversationId);
    if (!conv) return;
    
    let offeredText = "";
    if (isKarma) {
        offeredText = "Karma Points";
    } else {
        const customText = document.getElementById('lifecycle-custom-text')?.value.trim() || "";
        const selectedListingId = state.selectedSwapListingId;
        if (selectedListingId) {
            const off = state.userOfferings.find(o => o.id === selectedListingId);
            if (off) {
                offeredText = off.title;
            }
        } else if (customText) {
            offeredText = customText;
        }
    }
    
    if (!offeredText) {
        // Highlight errors
        const input = document.getElementById('lifecycle-custom-text');
        if (input) {
            input.classList.add('border-red-500', 'focus:ring-red-500');
            setTimeout(() => input.classList.remove('border-red-500', 'focus:ring-red-500'), 1500);
        }
        return;
    }
    
    // Safety checks
    if (!isKarma) {
        if (checkSafetyPolicy(offeredText)) {
            showSafetyContentViolation();
            return;
        }
        if (checkCashlessPolicy(offeredText)) {
            showSafetyMoneyWarning();
            return;
        }
        if (checkExactAddress(offeredText)) {
            showSafetyAddressWarning();
            return;
        }
    }
    
    let msgText = "";
    let offeredId = "";
    let offeredImage = PLACEHOLDER_IMAGE;
    let requestedId = "";
    let requestedImage = PLACEHOLDER_IMAGE;
    
    if (isKarma) {
        const req = conv.negotiation?.requestedItem || "item";
        msgText = `Hey! I'm really interested in your "${req}". I don't have anything to trade right now, but would you be open to a Karma Swap? You'd receive +50 Karma Points for helping a neighbor, and it would mean the world to me! 💛✨`;
        if (!conv.negotiation) conv.negotiation = {};
        conv.negotiation.isKarmaSwap = true;
    } else {
        const req = conv.negotiation?.requestedItem || "item";
        msgText = `SWAP OFFER: I would like to swap my "${offeredText}" for your "${req}".`;
        if (!conv.negotiation) conv.negotiation = {};
        conv.negotiation.isKarmaSwap = false;
        
        const selectedListingId = state.selectedSwapListingId;
        if (selectedListingId && selectedListingId !== 'custom') {
            const off = state.userOfferings.find(o => o.id === selectedListingId);
            if (off) {
                offeredId = off.id;
                offeredImage = off.image || PLACEHOLDER_IMAGE;
            }
        }
        
        const neighbor = state.neighbors[conv.neighborName];
        if (neighbor) {
            requestedId = conv.neighborName;
            requestedImage = neighbor.offerImg || PLACEHOLDER_IMAGE;
        }
    }
    
    const newMsg = {
        sender: 'me',
        text: msgText,
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };
    if (isKarma) {
        newMsg.isKarmaSwapRequest = true;
        newMsg.requestedItem = conv.negotiation.requestedItem || "item";
    } else {
        newMsg.isSwapOffer = true;
        newMsg.offeredItemTitle = offeredText;
        newMsg.offeredItemImage = offeredImage;
        newMsg.offeredItemId = offeredId;
        newMsg.requestedItemTitle = conv.negotiation.requestedItem || "item";
        newMsg.requestedItemImage = requestedImage;
        newMsg.requestedItemId = requestedId;
    }
    conv.messages.push(newMsg);
    
    // Add admin confirmation
    conv.messages.push({
        sender: 'App admin',
        text: "Swap proposed! Our team has sent the request to your neighbor. We'll let you know as soon as they respond.",
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    });
    
    conv.negotiation.status = 'pending';
    conv.negotiation.offeredItem = offeredText;
    conv.negotiation.isFromOfferSwapModal = true;
    
    saveState();
    window.closeSwapLifecycleModal();
    renderChatDetail(conv);
    if (typeof playSound === 'function') playSound('message');
    
    if (!isKarma && typeof triggerSuccessConfetti === 'function') {
        triggerSuccessConfetti();
    }
    
    if (conv.mockAcceptTimer) {
        clearTimeout(conv.mockAcceptTimer);
    }
    conv.mockAcceptTimer = setTimeout(() => {
        window.simulatePartnerAccept(conv.id);
    }, 4000);
};

function updateVillageViewFromState() {
    const category = state.activeCategory || 'offerings';
    const viewMode = state.activeViewMode || 'map';
    
    let targetSegment = 'map';
    if (viewMode === 'map') {
        if (category === 'offerings') {
            targetSegment = 'map';
        } else if (category === 'needs') {
            targetSegment = 'needs_map';
        } else if (category === 'events') {
            targetSegment = 'events_map';
        }
    } else { // viewMode === 'list'
        if (category === 'offerings') {
            targetSegment = 'list';
        } else if (category === 'needs') {
            targetSegment = 'needs';
        } else if (category === 'events') {
            targetSegment = 'events';
        }
    }
    
    if (typeof switchVillageSegment === 'function') {
        switchVillageSegment(targetSegment);
    }
    
    updateTopSegmentedControlUI(category);
}
window.updateVillageViewFromState = updateVillageViewFromState;

function handleCategorySegmentTap(category) {
    if (typeof playSound === 'function') playSound('click');
    state.activeCategory = category;
    saveState();
    updateVillageViewFromState();
}
window.handleCategorySegmentTap = handleCategorySegmentTap;

function updateTopSegmentedControlUI(category) {
    const controls = [
        { containerId: 'village-segmented-control', pillId: 'village-active-pill-bg' },
        { containerId: 'village-list-segmented-control', pillId: 'village-list-active-pill-bg' },
        { containerId: 'village-needs-segmented-control', pillId: 'village-needs-active-pill-bg' },
        { containerId: 'village-events-segmented-control', pillId: 'village-events-active-pill-bg' }
    ];

    controls.forEach(ctrl => {
        const container = document.getElementById(ctrl.containerId);
        const pill = document.getElementById(ctrl.pillId);
        if (!container || !pill) return;

        const targetBtn = container.querySelector(`button[data-category="${category}"]`);
        const btns = container.querySelectorAll('button[data-category]');

        // Use 'active-tab' class — the CSS uses this with !important color overrides
        btns.forEach(btn => {
            if (btn === targetBtn) {
                btn.classList.add('active-tab');
            } else {
                btn.classList.remove('active-tab');
            }
        });

        // Position the sliding pill
        if (targetBtn) {
            const updatePosition = () => {
                if (targetBtn.offsetWidth > 0) {
                    pill.style.width = `${targetBtn.offsetWidth}px`;
                    pill.style.left = `${targetBtn.offsetLeft}px`;
                }
            };
            // Run immediately
            updatePosition();
            // Also schedule on next ticks in case layout properties are updating
            requestAnimationFrame(updatePosition);
            setTimeout(updatePosition, 50);
            setTimeout(updatePosition, 150);
        }
    });
}
window.updateTopSegmentedControlUI = updateTopSegmentedControlUI;

// Search Behavior and Navbar Toggling on keyboard/search focus
function initSearchBehavior() {
    const searchInputs = [
        { inputId: 'village-search-input', clearBtnId: 'btn-map-search-clear' },
        { inputId: 'village-list-search-input', clearBtnId: 'btn-list-search-clear' },
        { inputId: 'village-needs-search-input', clearBtnId: 'btn-needs-search-clear' },
        { inputId: 'village-events-search-input', clearBtnId: 'btn-events-search-clear' },
        { inputId: 'village-bulletins-search-input', clearBtnId: 'btn-bulletins-search-clear' },
        { inputId: 'chat-search-input', clearBtnId: 'btn-clear-chat-search' }
    ];

    searchInputs.forEach(({ inputId, clearBtnId }) => {
        const input = document.getElementById(inputId);
        const clearBtn = document.getElementById(clearBtnId);
        if (!input) return;

        // On Focus (Tapped search bar)
        input.addEventListener('focus', () => {
            closeAllListDropdowns();
            closeMapCategoryDropdown();
            closeAllQuickCreateDropdowns();
            // Hide bottom navbar
            const navbar = document.getElementById('global-navbar');
            if (navbar) {
                navbar.classList.add('hidden');
            }
            // Hide floating segment stack on map or lists
            const floatingContainer = document.getElementById('village-segment-floating-buttons');
            if (floatingContainer) {
                floatingContainer.style.display = 'none';
            }
            // Show clear button (X) only if input is not empty
            if (clearBtn) {
                if (input.value.trim() !== "") {
                    clearBtn.classList.remove('hidden');
                } else {
                    clearBtn.classList.add('hidden');
                }
            }
            // Trigger suggestions on search input focus
            const suggestionInputIds = [
                'village-search-input',
                'village-list-search-input',
                'village-needs-search-input',
                'village-events-search-input'
            ];
            if (suggestionInputIds.includes(inputId)) {
                updateSearchSuggestions(input.value);
            }
        });

        // On Blur (Keyboard dismissed / tapped outside)
        input.addEventListener('blur', () => {
            // Restore bottom navbar and floating segment stack after a small delay
            // to allow clear button clicks or suggestion selection tap events to process first
            setTimeout(() => {
                const navbar = document.getElementById('global-navbar');
                if (navbar) {
                    navbar.classList.remove('hidden');
                }
                const floatingContainer = document.getElementById('village-segment-floating-buttons');
                if (floatingContainer && state.currentView === 'village') {
                    const isMapSegment = currentVillageSegment === 'map' || currentVillageSegment === 'needs_map' || currentVillageSegment === 'gifts_map' || currentVillageSegment === 'events_map';
                    if (!state.meetupMapMode) {
                        floatingContainer.style.display = 'flex';
                    }
                }
                if (typeof adjustSearchSuggestionsVisibility === 'function') {
                    adjustSearchSuggestionsVisibility(false, true);
                }
            }, 200);
        });

        // Ensure X button visibility matches whether there is text in the input
        input.addEventListener('input', () => {
            if (clearBtn) {
                if (input.value.trim() !== "") {
                    clearBtn.classList.remove('hidden');
                } else {
                    clearBtn.classList.add('hidden');
                }
            }
        });
    });

    // Global listener to prevent clicking on listings when dismissing search/keyboard
    const handleOutsideClick = (e) => {
        const activeEl = document.activeElement;
        if (!activeEl) return;

        const searchInputIds = [
            'village-search-input',
            'village-list-search-input',
            'village-needs-search-input',
            'village-events-search-input',
            'village-bulletins-search-input',
            'chat-search-input'
        ];

        if (searchInputIds.includes(activeEl.id)) {
            // Check if user clicked inside the active search input, its clear button, or its suggestions dropdown
            const isClickOnInput = activeEl.contains(e.target) || e.target === activeEl;
            
            // Check clear buttons
            const isClickOnClearBtn = e.target.closest('#btn-map-search-clear') ||
                                      e.target.closest('#btn-list-search-clear') ||
                                      e.target.closest('#btn-needs-search-clear') ||
                                      e.target.closest('#btn-events-search-clear') ||
                                      e.target.closest('#btn-bulletins-search-clear') ||
                                      e.target.closest('#btn-clear-chat-search');

            // Check suggestions containers
            const suggestionsIds = [
                'village-search-suggestions',
                'village-list-search-suggestions',
                'village-needs-search-suggestions',
                'village-events-search-suggestions'
            ];
            const isClickOnSuggestions = suggestionsIds.some(id => {
                const el = document.getElementById(id);
                return el && (el.contains(e.target) || el === e.target);
            });

            // If clicked outside all of these, dismiss search and allow click/touchstart through
            if (!isClickOnInput && !isClickOnClearBtn && !isClickOnSuggestions) {
                // Blur active input to pull down keyboard
                activeEl.blur();
            }
        }
    };

    // Use capturing phase (true) so we intercept events before they reach cards
    document.addEventListener('touchstart', handleOutsideClick, { capture: true, passive: false });
    document.addEventListener('mousedown', handleOutsideClick, { capture: true });
    document.addEventListener('click', handleOutsideClick, { capture: true });
}

// Global function to clear search and exit search mode
function clearSearchInput(inputId) {
    const input = document.getElementById(inputId);
    if (!input) return;

    // Clear value
    input.value = "";
    
    // Trigger input event to clear filter/results
    input.dispatchEvent(new Event('input', { bubbles: true }));

    // Force blur to hide keyboard
    input.blur();

    // Hide clear buttons
    const clearBtnIds = [
        'btn-map-search-clear',
        'btn-list-search-clear',
        'btn-needs-search-clear',
        'btn-events-search-clear',
        'btn-bulletins-search-clear'
    ];
    clearBtnIds.forEach(id => {
        const btn = document.getElementById(id);
        if (btn) btn.classList.add('hidden');
    });

    // Restore bottom navbar and floating segment stack
    const navbar = document.getElementById('global-navbar');
    if (navbar) {
        navbar.classList.remove('hidden');
    }
    const floatingContainer = document.getElementById('village-segment-floating-buttons');
    if (floatingContainer && state.currentView === 'village') {
        const isMapSegment = currentVillageSegment === 'map' || currentVillageSegment === 'needs_map' || currentVillageSegment === 'gifts_map' || currentVillageSegment === 'events_map';
        if (!state.meetupMapMode) {
            floatingContainer.style.display = 'flex';
        }
    }
    
    // Hide search suggestions immediately
    if (typeof adjustSearchSuggestionsVisibility === 'function') {
        adjustSearchSuggestionsVisibility(false, true);
    }
    
    // Synchronize all search bars
    if (typeof syncVillageSearch === 'function') {
        syncVillageSearch("");
    }
}
window.clearSearchInput = clearSearchInput;

// Keyboard transparency and positioning using Visual Viewport API
function initKeyboardLayoutHandler() {
    if (!window.visualViewport) return;

    let prevOffset = -1;
    let prevKeyboardVisible = null;

    const handleViewportChange = () => {
        const keyboardHeight = window.innerHeight - window.visualViewport.height;
        const offset = Math.max(0, keyboardHeight);

        if (offset !== prevOffset) {
            document.documentElement.style.setProperty('--keyboard-offset', `${offset}px`);
            prevOffset = offset;
        }

        // Support both viewport resize height differences and focused input tags (for SwiftUI webview keyboard avoidance resizing)
        const isFocused = document.activeElement && (document.activeElement.tagName === 'INPUT' || document.activeElement.tagName === 'TEXTAREA');
        const isVisible = (offset > 10) || isFocused;
        
        if (isVisible !== prevKeyboardVisible) {
            if (isVisible) {
                document.body.classList.add('keyboard-visible');
                
                // Auto-scroll chat feed to bottom ONLY when keyboard first appears
                if (state && state.currentView === 'chat_detail') {
                    const feed = document.getElementById('chat-message-feed');
                    if (feed) {
                        feed.scrollTop = feed.scrollHeight;
                        setTimeout(() => {
                            feed.scrollTop = feed.scrollHeight;
                        }, 50);
                        setTimeout(() => {
                            feed.scrollTop = feed.scrollHeight;
                        }, 150);
                    }
                }
            } else {
                document.body.classList.remove('keyboard-visible');
            }
            prevKeyboardVisible = isVisible;
        }
    };

    window.visualViewport.addEventListener('resize', handleViewportChange);
    
    // Add event listeners for focusin/focusout to catch keyboard state transitions instantly
    document.addEventListener('focusin', () => {
        setTimeout(handleViewportChange, 50);
        setTimeout(handleViewportChange, 150);
    });
    document.addEventListener('focusout', () => {
        setTimeout(handleViewportChange, 50);
        setTimeout(handleViewportChange, 150);
    });
    
    // Initial run
    handleViewportChange();
}

// Initialize on DOM loaded
document.addEventListener('DOMContentLoaded', () => {
    initSearchBehavior();
    initKeyboardLayoutHandler();
    initQuickCreateSheet();
});
if (document.readyState === 'complete' || document.readyState === 'interactive') {
    initSearchBehavior();
    initKeyboardLayoutHandler();
    initQuickCreateSheet();
}

function initQuickCreateSheet() {
    const sheet = document.getElementById('global-navbar');
    if (!sheet) return;

    // Fixed height for static navbar capsule
    const STATIC_HEIGHT = 56;

    function setSheetHeight() {
        sheet.style.setProperty('height', `${STATIC_HEIGHT}px`, 'important');
        
        // Calculate bottom offset to avoid WebKit calc() custom property bugs
        const isNative = document.documentElement.classList.contains('native-app-env');
        const isSimulator = document.body && document.body.classList.contains('show-simulator');
        const detector = document.getElementById('safe-area-detector');
        const safeArea = (isNative && detector) ? detector.offsetHeight : 0;
        
        let collapsedBottom;
        if (isNative) {
            collapsedBottom = Math.max(20, 12 + safeArea);
        } else if (isSimulator) {
            collapsedBottom = 20;
        } else {
            collapsedBottom = 20;
        }
        
        // Keep bottom margin floating and static so it sits nicely above safe area
        sheet.style.setProperty('bottom', `${collapsedBottom}px`, 'important');

        // Fixed Width: Never expand the section wider than the initial floating capsule size
        const screenWidth = window.innerWidth;
        const pillWidth = Math.min(380, screenWidth - 48);
        sheet.style.setProperty('width', `${pillWidth}px`, 'important');
        sheet.style.setProperty('max-width', '380px', 'important');

        // Keep corners fully rounded to preserve the "floating card" aesthetic
        sheet.style.setProperty('border-radius', '32px', 'important');

        const isDark = document.documentElement.classList.contains('dark');
        const bgAlpha = 0.45;
        const borderAlpha = 0.35;
        const shadowAlpha = 0.06;
        const blurAmount = 24;
        const saturateAmount = 200;

        sheet.style.setProperty('background', isDark ? `rgba(20, 28, 22, ${bgAlpha})` : `rgba(255, 255, 255, ${bgAlpha})`, 'important');
        sheet.style.setProperty('border-color', isDark ? `rgba(255, 255, 255, ${borderAlpha})` : `rgba(0, 0, 0, ${borderAlpha})`, 'important');
        sheet.style.setProperty('box-shadow', `0 -8px 32px rgba(0, 0, 0, ${shadowAlpha})`, 'important');
        sheet.style.setProperty('backdrop-filter', `blur(${blurAmount}px) saturate(${saturateAmount}%)`, 'important');
        sheet.style.setProperty('-webkit-backdrop-filter', `blur(${blurAmount}px) saturate(${saturateAmount}%)`, 'important');
    }
    
    window.updateQuickCreateSheetHeight = function(h) {
        // Noop to prevent other code trying to expand the sheet
        setSheetHeight();
    };

    // Observe when native-app-env class is dynamically added on documentElement by native app wrapper
    const observer = new MutationObserver(() => {
        setSheetHeight();
    });
    observer.observe(document.documentElement, { attributes: true, attributeFilter: ['class'] });

    // Fallback load event listener to ensure safe area inset dimensions have been parsed and applied
    window.addEventListener('load', () => {
        setSheetHeight();
    });

    setSheetHeight();
}

window.closeAllQuickCreateDropdowns = function() {
    ['village-quick-create-dropdown', 'list-quick-create-dropdown', 'needs-quick-create-dropdown', 'events-quick-create-dropdown'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.classList.add('hidden');
    });
};

window.deactivateSearchMode = function() {
    const searchInputIds = [
        'village-search-input',
        'village-list-search-input',
        'village-needs-search-input',
        'village-events-search-input'
    ];
    searchInputIds.forEach(id => {
        const el = document.getElementById(id);
        if (el && document.activeElement === el) {
            el.blur();
        }
    });

    const suggestionIds = [
        'village-search-suggestions',
        'village-list-search-suggestions',
        'village-needs-search-suggestions',
        'village-events-search-suggestions',
        'fused-search-suggestions'
    ];
    suggestionIds.forEach(id => {
        const el = document.getElementById(id);
        if (el) el.classList.add('hidden');
    });

    const navbar = document.getElementById('global-navbar');
    if (navbar) {
        navbar.classList.remove('hidden');
    }
    const floatingContainer = document.getElementById('village-segment-floating-buttons');
    if (floatingContainer && state.currentView === 'village') {
        floatingContainer.style.display = 'flex';
    }
};

window.toggleQuickCreateDropdown = function(event, type) {
    if (event) event.stopPropagation();
    
    let dropdownId = 'village-quick-create-dropdown';
    if (type === 'list') dropdownId = 'list-quick-create-dropdown';
    else if (type === 'needs') dropdownId = 'needs-quick-create-dropdown';
    else if (type === 'events') dropdownId = 'events-quick-create-dropdown';
    
    const dropdown = document.getElementById(dropdownId);
    if (!dropdown) return;
    
    const isHidden = dropdown.classList.contains('hidden');
    
    // Close all other quick-create dropdowns first
    ['village-quick-create-dropdown', 'list-quick-create-dropdown', 'needs-quick-create-dropdown', 'events-quick-create-dropdown'].forEach(id => {
        if (id !== dropdownId) {
            const other = document.getElementById(id);
            if (other) other.classList.add('hidden');
        }
    });
    
    // Close other overlays (like search suggestions if any)
    const suggestions = document.getElementById('fused-search-suggestions');
    if (suggestions) suggestions.classList.add('hidden');
    const listSuggestions = document.getElementById('village-list-search-suggestions');
    if (listSuggestions) listSuggestions.classList.add('hidden');
    const needsSuggestions = document.getElementById('village-needs-search-suggestions');
    if (needsSuggestions) needsSuggestions.classList.add('hidden');
    const eventsSuggestions = document.getElementById('village-events-search-suggestions');
    if (eventsSuggestions) eventsSuggestions.classList.add('hidden');
    
    if (isHidden) {
        closeAllListDropdowns();
        closeMapCategoryDropdown();
        deactivateSearchMode();
        
        let controlId = 'village-segmented-control';
        if (type === 'list') controlId = 'village-list-segmented-control';
        else if (type === 'needs') controlId = 'village-needs-segmented-control';
        else if (type === 'events') controlId = 'village-events-segmented-control';
        
        const control = document.getElementById(controlId);
        if (control && dropdown.parentElement) {
            const parentRect = dropdown.parentElement.getBoundingClientRect();
            const controlRect = control.getBoundingClientRect();
            const topOffset = controlRect.top - parentRect.top;
            dropdown.style.top = `${topOffset}px`;
        }
        
        dropdown.classList.remove('hidden');
        if (typeof playSound === 'function') playSound('click');
        window.triggerHapticFeedback('light');
    } else {
        dropdown.classList.add('hidden');
    }
};

document.addEventListener('click', function(e) {
    const dropdowns = [
        { id: 'village-quick-create-dropdown', btnId: 'btn-integrated-quick-create' },
        { id: 'list-quick-create-dropdown', btnId: 'btn-list-quick-create' },
        { id: 'needs-quick-create-dropdown', btnId: 'btn-needs-quick-create' },
        { id: 'events-quick-create-dropdown', btnId: 'btn-events-quick-create' }
    ];
    
    dropdowns.forEach(item => {
        const dropdown = document.getElementById(item.id);
        const plusBtn = document.getElementById(item.btnId);
        if (dropdown && !dropdown.classList.contains('hidden')) {
            if (!dropdown.contains(e.target) && (!plusBtn || !plusBtn.contains(e.target))) {
                dropdown.classList.add('hidden');
            }
        }
    });
});

window.triggerQuickCreate = function(mode) {
    if (typeof playSound === 'function') playSound('click');
    window.triggerHapticFeedback('medium');
    
    // Close all quick-create dropdowns
    ['village-quick-create-dropdown', 'list-quick-create-dropdown', 'needs-quick-create-dropdown', 'events-quick-create-dropdown'].forEach(id => {
        const dropdown = document.getElementById(id);
        if (dropdown) {
            dropdown.classList.add('hidden');
        }
    });

    // Launch full listing creation form
    showView('offer');
    selectOfferMode(mode);
};

